  \centering
  \includegraphics[width=0.6\linewidth]{phase1.png}
 \caption{The projections $\gamma_1$ (left) and $\gamma_2$ (right) of $\gamma(t)$}
 \label{fig:phase}
\end{figure}
\end{enumerate}
\end{lemma}
\begin{proof}  See, for instance, \cite[Section 4]{Ver14} or \cite[Section 3]{WDR04}.
\end{proof}


If $\gamma$ is a brake-brake orbit or a brake-collision orbit, then there exists $t_0$ such that $(\lambda(t_0), \nu(t_0) )  $ lies on the boundary of Hill's region.  Equivalently, this means that $p_\lambda( t_0) = p_\nu( t_0)=0$. However, the previous lemma tells us that for lemniscate motions $p_\nu$ never vanishes. Therefore, we obtain the following assertion. 

\begin{corollary}\label{cor:nobrake}
A lemniscate motion does not admit braking points. Hence,   brake-brake orbits and brake-collision orbits cannot be realized as lemniscate motions. 
\end{corollary}



We now turn to study of collision-collision orbits that arise as lemniscate motions. 



\begin{lemma}\label{lem:Lregion}
     On each $T_{k,l}$-torus corresponding to lemniscate motions, there exist precisely two collision-collision orbits, denoted by $K_1, K_2$. If $l$ is odd, then both orbits are of type II and related by reflection  with respect to  the $q_1$-axis.   
 If $l$ is even, then each orbit involves collisions with a single primary and is symmetric under reflection  with respect to  the $q_1$-axis.  See Figure \ref{fig:cc}.
 \begin{figure}[h]
  \centering
  \includegraphics[width=0.75\linewidth]{collisionorbits.png}
 \caption{Examples of  collision-collision orbits in the Euler problem. (top left) $k=7, \; l=5$; (top right) $k=7,\;  l=6$; (bottom left) $k=10, \;  l=3$; (bottom right) $k=9,\; l=4$}
 \label{fig:cc}
\end{figure}

\end{lemma}
\begin{proof} 

We follow the arguments given in \cite[Proposition 3.5]{KimSZ} and \cite[Section 5]{Ver14}.  


  Let $\gamma(t)$ be a $T$-periodic Hamiltonian trajectory corresponding to a lemniscate motion, lying on a $T_{k,l}$-torus.   Since the rotation number satisfies $R=k/l  $ (see the introduction for the definition of $R$), the projections $\gamma_1$ and $\gamma_2$ complete $k$ and $l$ full cycles, respectively. Consequently, the period $T$ satisfies $T = k T_\lambda= l T_\nu$.



Suppose that $\gamma(t)$ admits a collision. Without loss of generality, we may assume that the collision occurs at  $E$,  and reparametrize $\gamma(t)$   so that $\gamma(0)=  (0, -\pi, p_\lambda^0, p_\nu^0) $ with  $p_\lambda^0, p_\nu^0>0$. Because of Corollary \ref{cor:nobrake}, $\gamma$ is a collision-collision orbit. The  second collision then occurs at time $t=T/2$, and  there are  four possible configurations, illustrated   in Figure \ref{fig:four}.
\begin{figure}[h]
  \centering
  \includegraphics[width=0.9\linewidth]{fourcases.png}
 \caption{Four possible configurations for the second collision. The first case is excluded, as it contradicts the assumption gcd$(k,l)=1$.  The second and last  cases  correspond to simple covered collision-collision orbits of type II. The third case indicates a double covered collision-collision orbit of type I}
 \label{fig:four}
\end{figure}
The first case is excluded since $k$ and $l$ are assumed to be relatively prime. 

In the second case, we have $k$ is even and $l$ is odd, and the trajectory $\gamma$ collides with $M$ at time $t =T/2$. Hence, $\gamma$ is a simple covered $T$-periodic collision-collision orbit of type II. Since the Hamiltonian $F_{\mu,c}$ is invariant under the anti-symplectic involution $\mathcal{R} \colon (\lambda, \nu, p_\lambda, p_\nu) \mapsto (-\lambda, \nu, p_\lambda, -p_\nu)$, which corresponds to reflection in the  $q_1$-axis,  it follows that $\mathcal{R}(\gamma)$ is also a simple covered $T$-periodic collision-collision orbit of type II.   

In the third case, $k$ is odd and $l$ is even, and $\gamma$ collides again with $E$ at time $t =T/2$. This implies that $\gamma$ is a double-covered $T$-periodic collision-collision orbit of type I. Moreover, this orbit is invariant under the involution $\mathcal{R}$. A similar argument applies if the initial condition is assumed to occur at $M$ instead of $E$.  

In the last case, where both $k$ and $l$ are odd, the situation is equivalent to the second case. 
This completes the proof.  
 \end{proof}
















