 \subsection{The invariant  $(\mathcal{J}_{E,M}, n)$}\label{subsec:EM}


 We normalize the positions of the two primaries to $E=(-1,0)$ and $M=(1,0)$ and denote by $(\lambda,\nu)$ the associated elliptic coordinates as before.  


The coordinate line $\lambda = \lambda_0 >0 $  corresponds to an ellipse given by 
\begin{equation}\label{eq:ell} 
\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1, \quad \text{where }\; a = \cosh \lambda_0  \; \text{ and } \; b = \sinh \lambda_0 ,
\end{equation} 
while the cooordinate line $\nu =\nu_0 \in (-\pi, 0)$ corresponds to a hyperbola given by 
\begin{equation}\label{eq:hyper} 
\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1, \quad \text{where } \; a = \cos \nu_0 \;  \text{ and } \; b = \sin \nu_0  ,  
\end{equation}
provided that $\nu_0 \neq -\pi/2$. In the case  $\nu_0=-\pi/2$, the coordinate line coincides with the $y$-axis.   


Let $B \colon \C \setminus \{ 0 \} \to \C$ denote the Birkhoff regularization map as defined in \eqref{eq:Birkhoff}. We extend it to a branched double covering $B \colon  \C \cup \{ \infty \}  \to \C \cup \{ \infty\} $ by defining it to send both $0$ and $\infty$ to $\infty$. In the following lemma, we collect some basic properties of this extended map. The proofs are straightforward and omitted.



%Below we list some   properties of the Birkhoff regularization mapping 
%\[
%B \colon \C \cup \{\infty\} \to \C \cup \{ \infty\}, \quad B(z) = \frac{1}{2} \left( z + \frac{1}{z} \right)= \frac{1}{2}\left( x + \frac{x}{x^2 +y^2} \right) + i \frac{1}{2}\left( y - \frac{y}{x^2+y^2}\right)\] 
%whose proofs are straightforward.
\begin{lemma}\label{lem:propofB} The Birkhoff regularization map $B \colon \C \cup \{\infty\} \to \C \cup \{ \infty \}$ satisfies the following properties:  

\begin{enumerate}
%\item $B$ is a 2-to-1 covering branched at $E,M$.
%\item $B(0) = B(\infty)=   \infty$.
\item  The arcs $(0,1) \times \{ 0 \}$ and $(1,\infty) \times \{0\}$ are bijectively mapped onto $(1, \infty) \times \{0\}$, with the former reversing and the latter preserving it.   In a similar way, the arcs $(-\infty, -1) \times \{ 0 \}$ and $(-1, 0) \times \{ 0 \}$ are bijectively mapped onto $(-\infty, -1) \times \{ 0 \}$,   preserving and reversing the orientations, respectively. 



\item  The preimage of an ellipse of the form \eqref{eq:ell} is the union of the two circles  of radii $a \pm b$, centered at the origin. In particular, the preimage of the coordinate line $\lambda =0$ is the unit circle.

\item Let $\nu=\nu_0$ be a coordinate line corresponding to a hyperbola of the form \eqref{eq:hyper}. If $\nu_0 \in (-\pi/2, 0)$, then its preimage is given by the pair of rays $\{ y = \pm (b/a)x \mid x >0 \}$. If $\nu_0 \in (-\pi, -\pi/2)$, then the preimage is $\{ y = \pm (b/a)x \mid x < 0 \}$. 
The preimage of $\nu=-\pi/2$, i.e.~the $q_2$-axis, is the $y$-axis, see Figure \ref{fig:ex11} for illustrations. 





