Based on the properties described in the preceding lemma, we now investigate the preimage of a collision-collision orbit under the Birkhoff regularization map. 




\begin{lemma}\label{lem:Bcoll}
Let $K$ be a collision-collision orbit lying on a $T_{k,l}$-torus. Then the following assertions hold:

  \begin{enumerate}
  \item The preimage $B^{-1}(K)$ consists of a single arc whose endpoints lie at $(\pm 1,0)$, depending on the parity of $l$. We denote this arc by  $\tilde K = B^{-1}(K)$.
  Moreover, $\tilde K$ is invariant under the map $\phi(z)=1/z. $   % See Figure \ref{fig:ex12}.

  %\begin{figure}[h]
  %\centering
  %\includegraphics[width=0.6\linewidth]{ex12.jpeg}
%\caption{The map $\phi$ {\color{red}DELETE LATER}}
%\label{fig:ex12}
 %   \end{figure}

\item Suppose that  $l$ is  even and that $K$ collides twice with $E$,  so that $\tilde K$ passes through the point $(-1,0)$.  Then the intersections of $\tilde K$ with the arc $(1,\infty) \times \{ 0 \}$ consist of $l/4$ double points if $l \in 4 \N$ and $(l-2)/4$ double points and a single point if $l \in 4 \N_0+2$.



%\begin{align*}
 %{  \text{s, $l/4 -1$ d's, $(-1,0)$, $l/4-1$ d's, s, $l/2$ d's}} & \quad  \text{ if } \;  l \in 4\N, \\
%{\text{ $(l-2)/4 $ d's, $(-1,0)$, $(l-2)/4 $ d's, s, $l/2-1$ d's, s}}  & \quad  \text{ if } \;  l \in 4\N_0+2,
%\end{align*}
%where $s$ indicates a single point, and $d$ indicates a double point.  Note that $(-1,0)$ is a double point. 



  \item Suppose that $l$ is odd, so that $K$ collides with both primaries. Then both points $(\pm1, 0)$ are single points of $\tilde{K}$, and $\tilde{K}$ intersects the arc $(1,\infty) \times \{ 0 \}$ at $(l-1)/2$ single points.



  \end{enumerate}

\end{lemma}
\begin{proof}
  Since the map $B$ fixes two points $(\pm 1,0)$, it is immediate that each component of $B^{-1}(K)$ must start and end at either  $(-1,0)$ or $(1,0)$. The rest of the first assertion follows from a similar argument as in  Lemma \ref{lem:simgleLE}, replacing the $\pi$-rotation with the symmetry under the map $\phi$. This proves the first assertion.
  The second and third assertions follow from Lemma \ref{lem:propofB}(1), together with   Fact(1e) and Fact(1o) in   Remark \ref{rmk:useful}. This completes the proof of the lemma.
\end{proof}





 We are in a position to determine the quantity $n(K)$.


\begin{proposition}\label{prop:leavf} For any $T_{k,l}$-type orbit $K$, we have   $n(K)=l$.
\end{proposition}
\begin{proof} As before, we may assume that $K$ is a collision-collision orbit. Set $\tilde K=B^{-1}(K)$ as in Lemma \ref{lem:Bcoll}(1).  By definition, $n(K)$ is the absolute value of the winding number $w_0(\tilde K)$, which in our setting equals the signed count of the intersection points of $\tilde K$  with the arc $(0,\infty)\times\{0\}. $  


%(here we might have a sign issues but it does not matter since anyway we are going to take absolute value in the end) 


% Recall that the arcs $(0, 1 ) \times \{ 0 \}$ and $(1, \infty) \times \{ 0 \}$ are switched under the map $\phi. $
Let $z(t)=( x(t), y(t))$ be a parametrization of $\tilde K$ and suppose that $\dot y(t)>0$ at some point $(x(t),0)$, where $x(t)>1$. We evaluate the image under the map $\phi(z) = 1/z$, see Lemma \ref{lem:Bcoll}(1). Then 
 \begin{align*}
\frac{d}{dt} {\rm Im} \phi (z(t)) = \frac{d}{dt}  \frac{ -y(t)}{x(t)^2 + y(t)^2}     = - \frac{y'(t)}{x(t)^2} <0.
 \end{align*}
Since $\phi$ reverses orientation, this implies that the corresponding intersection points on $(0,1) \times \{0\}$ and $(1, \infty) \times \{ 0 \}$ that are related via the $\phi$-symmetry contribute the same sign to the winding number.  
 The case $\dot{y}(t)<0$  is analogous. Thus, it suffices to consider only the intersections of $\tilde K$ with the arc $[1, \infty) \times \{ 0 \}$.



We first claim that every intersection point of $\tilde K$ with $(1, \infty) \times \{ 0 \}$  contributes  the same sign to the winding number.  To prove this, let $(q_1(t),q_2(t))$ be a parametrization of $K$ and let $(q_1(t_0), 0), (q_1(t_1), 0)$  be two consecutive intersection points of $K$ with $(1,\infty) \times \{0\}$. That is,   there exists no $t _2\in (t_0, t_1)$ such that $K$ intersects $(1,\infty) \times \{0\}$ at time $t=t_2$.
Recall that in the elliptic coordinates $(\lambda, \nu)$  the arc $(1,\infty) \times \{0\}$ corresponds to the coordinate line $\nu=0$. Since $p_\nu = \dot{\nu}$ is nonvanishing along lemniscate motions, see Lemma \ref{lem:phaseportrait}(1), evaluating the time derivative of $q_2 = \sinh \lambda \sin \nu$ at $\nu=0$ gives rise to 
 %Differentiating $q_2 =  \sinh \lambda\sin \nu$ with respect $t$ and plugging $\nu=0$, we obtain that
$\dot{q}_2  =\sinh \lambda \cdot \dot{\nu}$, so that $\dot{q}_2(t_0)$ and $\dot{q}_2(t_1)$ have opposite (resp. same) signs if and only if
the part of $K$ over the interval $  (t_0, t_1)$   intersects the coordinate line $\lambda=0$, that is, the arc $(0,1) \times \{ 0 \}$,  an odd (resp. even) number of times.
Moreover, along the arc $(1,\infty) \times \{ 0 \}$ we have
\[
 \dot{q}_2 (t) = \frac{ \dot{y}(t)}{2} \left( 1 - \frac{1}{x (t)^2} \right),
\]
from which it follows that 
\begin{equation}\label{eq:q2y}
{\text{$\dot{y}(t)$ and $\dot{q}_2 (t)$ have } } \begin{cases} {\text{ same sign }} \\ {\text{ opposite sign }} \end{cases}  { \text{ if and only if }} \;\; \begin{cases} x>1 \\ 0<x<1 .\end{cases}
\end{equation}






We now write $B^{-1}( q_1(t_0), 0)=\{ a_1, a_2\}$ and $B^{-1}(q_1(t_1), 0) = \{ b_1, b_2\}$. By Lemma \ref{lem:propofB}(1) the four points $a_1, a_2, b_1, b_2$ lie on $\left( (0,\infty) \setminus \{ 1 \} \right) \times \{ 0 \}$. Recall that each pair $(a_1, a_2)$ and $(b_1, b_2)$ consists of intersection points of the same sign.   
Let $a_i, b_j$ be consecutive intersection points of $\tilde K$. They belong to the same connected component of $\left( (0,\infty) \setminus \{ 1 \} \right) \times \{ 0 \}$   if and only if $\tilde K$ intersects the unit circle an even number of times between $a_i$ and $b_j$. Due to Lemma \ref{lem:propofB}(2), this is equivalent to the condition that the part of $K$ over the interval $  \in (t_0, t_1)$  intersects the coordinate line $\lambda =0$ an even number of times, which, as shown earlier, is in turn equivalent to $\dot q_2(t_0)$ and $\dot q_2(t_1)$ having the same sign as intersection points. 
Therefore, by equation \eqref{eq:q2y} the two points $a_i, b_j$ have the same sign as the intersection points. 

Similarly, if $a_i$ and $b_j$ are in different components of $\left( (0,1) \cup ( 1, \infty) \right) \times \{0 \}$, then $\dot q_2(t_0)$ and $\dot q_2(t_1)$ have opposite signs, and again \eqref{eq:q2y} implies that $a_i, b_j$ still have the same sign.   

Consequently, all points $a_1 , a_2, b_1, b_2$   have the same sign, and hence all intersection points of $\tilde K$ with $\left( (0,1) \cup (1, \infty)\right)\times \{0 \}$ contribute  the same sign to the winding number.  This proves the claim. 



Assume first that $l$ is even, so that $K$ collides twice with $E$.    Hence, $\tilde K$ does not pass the point $(1,0). $ In view of Lemma \ref{lem:Bcoll}(2),  we see that $\tilde K$ intersects the positive $x$-axis precisely $l$ times. By the preceding argument, all these intersection points contribute  the same sign. Therefore, we conclude that $w_0(\tilde K) = \pm l$ when $l$ is even.


Now consider the case where $l$ is odd, so that the point $(1,0)$ is a single point of $\tilde K$. Note that the argument above concerning the sign of intersection points applies to any $T_{k,l}$-type orbit, regardless of whether it is a collision-collision orbit or not. Since $K$ belongs to a $T_{k,l}$-torus, which is a smooth one-parameter family of $T_{k,l}$-type orbits, the intersection point $(1,0)$ must have the same sign as the other intersection points of $\tilde K$   with the arc $(1,\infty) \times \{ 0 \}$. Therefore, by Lemma \ref{lem:Bcoll}(3),  $\tilde K$ again intersects the positive $x$-axis precisely $l$ times, and all intersections contribute  the same sign. It follows that $w_0(\tilde K)= \pm l $ also in this case.  


To conclude, we have $n(K) = \lvert w_0(\tilde K)\rvert = l $, which completes the proof of the proposition.
\end{proof}





It remains to determine the quantity $\mathcal{J}_{E,M}$. By definition, it suffices to determine $J^+(\widetilde{K})$. 
 Given a collision-collision orbit $K$, choose any parametrization $\gamma(t)$ of $K$. Then it gives rise to a parametrization $\tilde{\gamma}(t)$ of the preimage $\tilde K = B^{-1}(K)$. 




\begin{lemma} 
The curve  $\tilde{\gamma}$  rotates in the same direction at every point. 
\end{lemma}
\begin{proof}  By the proof of Proposition \ref{prop:leavf}, it is enough to show that every ray emanating from the origin intersects $\tilde K$ precisely $l$ times.  
Recall from the proof of Proposition \ref{prop:quadruple}   that for any fixed value $\bar{\nu} \in (0, \pi)$, the corresponding hyperbola $\nu = \bar{\nu}$ intersects the orbit $K$  at exactly $l$ points. Since the map $B$ is a  $2$-to-$1$ branched covering, it follows that $\tilde K$ intersects the preimage of the hyperbola $\nu=\bar{\nu}$  exactly $2l$ times. According to Lemma \ref{lem:propofB}(3), the preimage of the hyperbola consists of two rays given by $\theta = \pm \bar{\theta}$ for some angle $\bar{\theta} \in \R$. Therefore,   each ray intersects $\tilde K$ exactly $l$ times, from which the lemma is proved. 
\end{proof}



The previous lemma enables us to provide an algorithm for drawing a loop homotopic to $\tilde K$ without encountering any disaster, following the approach of \cite[Section 3]{KKJplus}.  
For the readers' convenience, we include such an algorithm below for the case $l \in 4 \N$,   obtained by Fact(4e) in Remark \ref{rmk:useful}.  Let $K$ be a collision-collision orbit at $E$. 
\begin{enumerate}[(i)]
\item Choose real numbers $0< r_{-l/2} <  \cdots < r_{-1} < r_0=1 < r_1 < \cdots <   r_{l/2}$ and draw circles $C_{ j} $ centered at the origin with radius $r_j$. The two circles $C_{\pm l/2}$ correspond to the preimage of the ellipse $\lambda = \lambda_{\max}$ under the Birkhoff  map $B$.
Similarly, choose angular values $-\pi=\theta_0 < \theta_1 < \cdots <\theta_{k-1} < \theta_k = 0$ and draw rays emanating from the origin at angles $\theta = \pm \theta_i$.
\item On each circle $C_j$,   mark $k$ points according to the following rule: 

\begin{itemize}
    \item if  $j$ is odd, then mark the   intersections of $C_j$ with   rays at angles $\theta = \pm  \theta_1, \pm \theta_3, \ldots,   \theta_{k }$; 

  \item if $j$ is even, then mark  the intersections of $C_j$ with $\theta = \theta_0, \pm \theta_2, \ldots, \pm \theta_{k-1}$. 
\end{itemize}
Each marked point is denoted by $a_{i,j} =  C_i \cap \{ \theta =\theta_j \}$.  All points $a_{i,j}$ with $i   \neq \pm l/2$ correspond to   double points of $\tilde{K}$. Note that  $a_{0, 0} = (-1,0)$.



\item Starting from   $a_{-l/2, 0}$,    connect the points $a_{i,j}$ in the following order using straight line segments: 
\begin{align*}
& \qquad \qquad   a_{- { l}/{2} , 0}, \;  a_{- { l}/{2}+1, 1}, \; a_{-l/2+2,2}, \;  \ldots, \;    a_{  {l}/{2}, l  }, \; a_{{l}/{2}-1, l+1 }, \; \ldots, \; a_{- {l}/{2}, 2l} ,\\
& \qquad \qquad  a_{- {l}/{2}+1, 2l+1}, \;  \ldots, \; a_{l/2, 3l}, \; a_{l/2-1, 3l+1}, \;, \ldots, \; a_{-l/2, 4l}, \;   \ldots,     \\
& \qquad \qquad  a_{l/2, 5l}, \; \ldots,\; a_{-l/2, 6l},  \; \ldots, \; a_{l/2, (k-2)l}
  \;\ldots,  \;a_{- {l}/{2}, (k-1)l } = a_{- {l}/{2}, 0}.
\end{align*}
Here, all second sub-indices of $a_{i,j}$ are considered modulo $k$.

\item Finally, smooth out the corners of the resulting piecewise-linear arc to obtain  a smooth loop that is homotopic to   $\tilde{K}$ without encountering any disasters.
See Figure \ref{motionsd}. 

