\subsection{Decomposition of $\widehat{R}(\tilde\tau;\hat\eta)$} \label{app:decomposition}
We have that
\begin{align*}
     \widehat{R}(\tilde\tau;\hat\eta) &= \frac{1}{n_1} \sum_{i:S_i=1} \left(\widehat{\psi}_i - \tilde\tau(X_i)\right)^2 \\
     &= \frac{1}{n_1} \sum_{i:S_i=1} \left(\widehat{\psi}_i - \tau(X_i) + \tau(X_i) - \tilde\tau(X_i)\right)^2 \\
     &= \frac{1}{n_1}\sum_{i: S_i=1} \Bigg\{ \left( \tau(X_i) - \tilde\tau\left(X_i\right) \right)^2- 2\left( \tau(X_i) - \tilde\tau\left(X_i\right) \right) \left( \widehat{\psi}_i - \tau(X_i)\right)+ \left( \widehat{\psi}_i - \tau(X_i) \right)^2\Bigg\}~.
\end{align*}

\subsection{Proof of Theorem~\ref{thm:robustness_pseudo_outcome}}\label{app:robustness_proof}




\begin{proof}
    We write $\psi_{\text{fixed}}=\psi(O;\eta_{\text{fixed}})$.

    First, we need to prove conditional unbiasedness, $\E[\psi_{\text{fixed}} \mid X=x, S=1] = \tau(x)$, as follows:
\begin{align*}
        \E[\psi_{\text{fixed}} \mid X=x] &= \E\Bigg[ \frac{A}{e(X)}(Y-h_1(X)) - \frac{1-A}{1-e(X)}(Y-h_0(X)) + h_1(X) - h_0(X) 
        \mid X=x,S=1\Bigg] \\
        & = \E\Bigg[ \frac{A}{e(X)}(Y^1-h_1(X)) - \frac{1-A}{1-e(X)}(Y^0-h_0(X)) 
        \mid X=x, S=1\Bigg] + h_1(x) - h_0(x)
\end{align*}
where the second equality follows from consistency in Condition~\ref{asmp:consistency}.
Next, we inspect the first term inside the above expectation, which can be rewritten as follows
\begin{align*}
    \E\Bigg[ \frac{A}{e(X)}(Y^1-h_1(X))\mid X=x, S=1\Bigg] &= \E\Bigg[ \frac{A}{e(X)} \mid X=x, S=1\Bigg] \Bigg(\E\Big[Y^1\mid X=x, S=1\Big] - h_1(x)\Bigg) \\ 
    & = \frac{e(x)}{e(x)}\Bigg(\E\Big[Y^1\mid X=x, S=1\Big] - h_1(X)\Bigg) \\
    & = \E\Big[Y^1\mid X=x, S=1\Big] - h_1(X)
\end{align*}
where the first equality follows from conditional exchangeability in the trial population, $Y^a\indep A \mid X, S=1$, in Condition~\ref{asmp:strong_ignorability_trial} and the second equality follows from that $\E[A\mid X=x, S=1]=e(x)$. Similarly, we can show that 
\begin{equation*}
     \E\Bigg[ \frac{1-A}{1-e(X)}(Y^0-h_0(X))\mid X=x, S=1\Bigg] = \E\Big[Y^0\mid X=x, S=1\Big] - h_0(X)~.
\end{equation*}
Putting all of the above together, we see that 
\begin{align*}
    \E[\psi_{\text{fixed}}\mid X=x] & = \E\Big[Y^1 - Y^0\mid X=x, S=1\Big] = \tau(x)
\end{align*}

Next, we show that $\tau = \argmin_{\tilde\tau \in \mathcal{F}} R(\tilde\tau;\eta_{\text{fixed}})$ when $\tau\in\mathcal{F}$. By adding and subtracting $\tau(X)$ inside $R(\tilde\tau;\eta_{\text{fixed}})$, we can decompose it as
\begin{align*}
    \underbrace{\E\left[(\tau(X) - \tilde\tau(X))^2 \mid S=1\right]}_{(a)} -  \underbrace{\E\left[\left( \tau(X) - \tilde\tau\left(X\right) \right) \left( \psi_{\text{fixed}} - \tau(X)\right) \mid S=1\right]}_{(b)} + \underbrace{\E\left[ \left( \psi_{\text{fixed}}  - \tau(X) \right)^2 \mid S=1\right]}_{(c)}
\end{align*}
First, we see that $(a) = R^*(\tilde\tau)$. Next, we have that $(b)=0$ because
\begin{align*}
    \E&\left[\left(\tau(X) - \tilde\tau\left(X\right) \right) \left( \psi_{\text{fixed}}  - \tau(X)\right) \mid S=1\right] = \\
    & =  \E\left[\E\left[\left(\tau(X) - \tilde\tau\left(X\right) \right) \left( \psi_{\text{fixed}}  - \tau(X)\right) \mid X, S=1 \right]\mid S=1\right] \\
    &=  \E\left[\left(\tau(X) - \tilde\tau\left(X\right) \right) \E\left[ \left( \psi_{\text{fixed}}  - \tau(X)\right) \mid X, S=1 \right]\mid S=1\right] \\
    &= 0
\end{align*}
where the last equality follows from conditional unbiasedness such that $\E\left[ \left( \psi_{\text{fixed}}  - \tau(X)\right) \mid X, S=1 \right]=0$.
Finally, $(c)=C$ is a real-valued constant $C\geq 0$ independent of $\tilde\tau$. Thus, we can write that
\begin{equation*}
    R(\tilde\tau;\eta_{\text{fixed}}) = R^*(\tilde\tau) + C
\end{equation*}
which implies that
\begin{equation*}
\argmin_{\tilde\tau\in\mathcal{F}}R(\tilde\tau;\eta_{\text{fixed}}) = \argmin_{\tilde\tau\in\mathcal{F}} \{R^*(\tilde\tau) + C\} = \argmin_{\tilde\tau\in\mathcal{F}} R^*(\tilde\tau) = \tau~.
\end{equation*}
\end{proof}



\subsection{Proof of Theorem~\ref{thm:variance_bound}}\label{app:variance_bound}

\begin{proof}
    To make it more explicit that the estimated nuisance models $\hat\eta$ are obtained independently of the observations used to compute the pseudo-outcomes, we denote it as $\eta_{\text{fixed}}=\{h_1,h_0\}$. Moreover, we write $\psi_{\text{fixed}}=\psi(O;\eta_{\text{fixed}})$. 

    Defining $\epsilon:=\left( \tau(X) - \tilde\tau\left(X\right) \right) \left( \psi_{\text{fixed}} - \tau(X)\right)$, we then have that $\E[\epsilon\mid S=1] = 0$ which we showed in the proof of Theorem~\ref{thm:robustness_pseudo_outcome}. Next, we note that 
    \begin{align*}
        \V(\epsilon \mid S=1) &= \E\left[ \epsilon^2 \mid S=1 \right] \\ 
        & = \E\left[\left( \tau(X) - \tilde\tau\left(X\right) \right)^2 \left( \psi_{\text{fixed}} - \tau(X)\right)^2 \mid S=1 \right]  \\
        &= \E\left[ \E\left[\left( \tau(X) - \tilde\tau\left(X\right) \right)^2 \left( \psi_{\text{fixed}} - \tau(X)\right)^2 \mid X, S=1 \right] \mid S=1 \right] \\
        &= \E\left[ \left( \tau(X) - \tilde\tau\left(X\right) \right)^2  \E\left[\left( \psi_{\text{fixed}} - \tau(X)\right)^2 \mid X, S=1 \right] \mid S=1 \right] \\
        & = \E\left[ \left( \tau(X) - \tilde\tau\left(X\right) \right)^2  \V\left( \psi_{\text{fixed}} \mid X, S=1 \right)\mid S=1 \right]
    \end{align*}
    where the first equality follows from that $\E[\epsilon\mid S=1]=0$ and the last from the conditional unbiasedness of the pseudo-outcome, $\E[\psi_{\text{fixed}} \mid X=x, S=1] = \tau(x)$, which we derived in the proof of Theorem~\ref{thm:robustness_pseudo_outcome}.

    Next, we show how to upper-bound $\V(\epsilon\mid S=1)$ as follows:
    \begin{align*}
        \V(\epsilon\mid S=1) & = \E\left[ \left( \tau(X) -\tilde\tau\left(X\right) \right)^2  \V\left( \widehat{\psi} \mid X, S=1 \right)\mid S=1 \right] \\
        & \leq C_{\tilde\tau} \cdot \E\left[\V\left(\psi_{\text{fixed}} \mid X, S=1\right) \mid S=1\right]
    \end{align*}
    where the inequality holds if define the constant $\tilde{C}=\max_{x\in\mathcal{X}}(\tau(x) - \tilde\tau(x))^2 \geq 0$ . Next, we have from the law of total variance that 
    \begin{align*}
    \E\left[\V\left(\psi_{\text{fixed}} \mid X, S=1\right) \mid S=1\right] &= \V(\psi_{\text{fixed}} \mid S=1) -  \V\left(\E\left[ \psi_{\text{fixed}} \mid X, S=1 \right]\mid S=1\right) \\
    & = \V(\psi_{\text{fixed}} \mid S=1) -  \V\left(\tau\left(X\right) \mid S=1\right)~.
    \end{align*}
    where the second equality follows from the conditional unbiasedness of the pseudo-outcomes. Thus, so far, we have $\V(\epsilon\mid S=1) \lesssim \V(\psi_{\text{fixed}} \mid S=1) -  \V\left(\tau\left(X\right) \mid S=1\right)$.

    Next, we inspect the variance $\V(\psi_{\text{fixed}} \mid S=1)$, which we rewrite using the law of total variance:
    \begin{align*}
       \V(\psi_{\text{fixed}} \mid S=1) &= \E\left[ \V\left( \psi_{\text{fixed}} \mid Y^1, Y^0, X, S=1 \right)\mid S=1 \right] + \V\left(\E\left[\psi_{\text{fixed}} \mid Y^1, Y^0, X, S=1 \right]\mid S=1 \right) \\
        & = \E\left[ \V\left( \psi_{\text{fixed}} \mid Y^1, Y^0, X, S=1 \right)\mid S=1 \right] + \V\left(Y^1-Y^0\mid S=1 \right)
    \end{align*}
    where the second inequality follows from that 
    \begin{equation*}
    \E\left[\psi_{\text{fixed}} \mid Y^1, Y^0, X, S=1 \right] = \E\left[Y^1-Y^0\mid Y^1, Y^0, X, S=1 \right] = Y^1-Y^0
    \end{equation*} where the first equality stems from the conditional unbiasedness of the pseudo-outcomes.

    We next write $\psi_{\text{fixed}}=\psi_{1,\text{fixed}}-\psi_{0,\text{fixed}}$ where   $\psi_{a,\text{fixed}}=\frac{\mathbf{1}(A=a)}{\mathbf{1}(A=1)e(X) + \mathbf{1}(A=0)(1-e(X))}(Y-h_a(X)) + h_a(X)$. This will help us simplify the expression for the above inner conditional variance as follows,
    \begin{align*}
        \V&\left(\psi_{\text{fixed}} \mid Y^1, Y^0, X, S=1 \right) = \V\left( \psi_{1,\text{fixed}}-\psi_{0,\text{fixed}} \mid Y^1, Y^0, X, S=1 \right) \\
        & = \E\left[ \left\{\psi_{1,\text{fixed}}-\psi_{0,\text{fixed}} - \underbrace{\E\left[\psi_{1,\text{fixed}}-\psi_{0,\text{fixed}} \mid Y^1, Y^0, X, S=1\right]}_{=Y^1-Y^0}\right\}^2\mid Y^1, Y^0, X, S=1 \right]  \\
        & = \E\left[\left\{\left(\psi_{1,\text{fixed}} - Y^1\right) -\left(\psi_{0,\text{fixed}}  - Y^0\right) \right\}^2\mid Y^1, Y^0, X, S=1 \right] \\
        & \leq 2 \E\left[\left(\psi_{1,\text{fixed}}-Y^1\right)^2 +\left(\psi_{0,\text{fixed}} - Y^0\right)^2 \mid Y^1, Y^0, X, S=1 \right]
    \end{align*}
    where the third inequality follows again from the conditional unbiasedness of the pseudo-outcomes and the final inequality from that $(a-b)^2\leq 2(a^2+b^2)$ for any real numbers $a$ and $b$.
    At last, we note that 
    \begin{align*}
        \E&\left[\left(\psi_{1,\text{fixed}}-Y^1\right)^2 \mid Y^1, Y^0, X, S=1 \right] = \\
        &=\E\left[\left(\frac{A}{e(X)}(Y-h_1(X)) + h_1(X)-Y^1\right)^2 \mid Y^1, Y^0, X, S=1 \right] \\
        &=\E\left[\left(\frac{A}{e(X)}(Y^1-h_1(X)) + h_1(X)-Y^1\right)^2 \mid Y^1, Y^0, X, S=1 \right] \\
        & = \E\left[\left(\frac{A}{e(X)} - 1 \right)^2\mid X, S=1 \right] (Y^1-h_1(X))^2  \\
        & = \frac{1-e(X)}{e(X)}(Y^1-h_1(X))^2
    \end{align*}
    where the second equality follows from consistency (Condition~\ref{asmp:consistency}) and the third equality from conditional exchangeability in the trial population (Condition~\ref{asmp:strong_ignorability_trial}). Similarly, we have that 
    \begin{align*}
         \E&\left[\left(\psi_{0,\text{fixed}}-Y^0\right)^2 \mid Y^1, Y^0, X, S=1 \right] = \frac{e(X)}{1-e(X)}(Y^0-h_0(X))^2~.
    \end{align*}
    At last, plugging the above expressions back into our original expression for $\V(\psi_{\text{fixed}} \mid S=1)$, we obtain the inequality
    \begin{align*}
         \V(\epsilon \mid S=1)  &\lesssim 2\E\left[\frac{1-e(X)}{e(X)}(Y^1-h_1(X))^2 \mid S=1\right] + 2\E\left[\frac{e(X)}{1-e(X)}(Y^0-h_0(X))^2\mid S=1\right] \\
        &\quad + \V\left( Y^1-Y^0\mid X, S=1 \right) - \V\left(\tau\left(X\right)\mid S=1\right)  \\
        &= 2\E\left[\frac{1-e(X)}{e(X)}(Y-h_1(X))^2\mid X, A=1, S=1\right] + 2\E\left[ \frac{e(X)}{1-e(X)}(Y-h_0(X))^2\mid  X, A=0, S=1 \right] \\
        &\quad + \V\left( Y^1-Y^0\mid S=1 \right)  - \V\left(\tau\left(X\right)\mid S=1\right) 
    \end{align*}
    where the equality follows from consistency and conditional exchangeability in the trial population again (Condition~\ref{asmp:consistency} and~\ref{asmp:strong_ignorability_trial}).
\end{proof}

\subsection{Proof of Theorem~\ref{thm:variance_rewritten}} \label{app:variance_rewritten}
\begin{proof}
    We begin by writing
    \begin{align*}
        L_a(h) & = \E\left[\left\{\frac{1-e(X)}{e(X)}\right\}^{2a-1}\left(Y-h\left(X\right)\right)^2 \mid A=a, S=1\right] \\
        &= \E\left[ \frac{S}{\Pr(S=1\mid A=a)}\left\{\frac{1-e(X)}{e(X)}\right\}^{2a-1}\left(Y-h\left(X\right)\right)^2 \mid A=a\right]\\
        &= \E\left[ \E\left[ \frac{S}{\Pr(S=1\mid A=a)}\left\{\frac{1-e(X)}{e(X)}\right\}^{2a-1}\left(Y-h\left(X\right)\right)^2 \mid X, A=a \right] \mid A=a\right]\\
        &= \E\left[\frac{1}{\Pr(S=1\mid A=a)}\left\{\frac{1-e(X)}{e(X)}\right\}^{2a-1} \E\left[S \left(Y-h\left(X\right)\right)^2 \mid X, A=a \right] \mid A=a\right]~.
    \end{align*}
    We inspect the inner conditional expectation, $\E\left[S \left(Y-h\left(X\right)\right)^2 \mid X, A=a \right]$, and note that 
    \begin{align*}
        \E\left[S \left(Y-h\left(X\right)\right)^2 \mid X, A=a \right] &= \E[S\mid X, A=a] \E[\left(Y-h\left(X\right)\right)^2 \mid X, A=a] \\
        &=\Pr(S=1\mid X, A=a) \E[\left(Y-h\left(X\right)\right)^2 \mid X, A=a] 
    \end{align*}
    where the first equality follows from that $Y\indep S\mid (X, A)$ holds under Conditions~\ref{asmp:consistency}-\ref{asmp:transportability}. To show this, we note that the conditional independencies $Y^a\indep A\mid (X, S=1)$ (Condition~\ref{asmp:strong_ignorability_trial}) and $Y^a\indep A\mid (X, S=0)$ (Condition~\ref{asmp:strong_ignorability_external}) jointly imply that $Y^a\indep A \mid (X,S)$. Combining this conditional independence statement with $Y^a\indep S\mid X$ from Condition~\ref{asmp:transportability}, they together imply $Y^a \indep (A,S)\mid X$. Thus, from the weak union of conditional independence, we have that $Y^a\indep S\mid (X,A)\Rightarrow Y\indep S\mid (X,A)$ where the final implication follows from consistency (Condition~\ref{asmp:consistency}).

    Combining all of the above, we finally obtain the following expression,
    \begin{equation*}
        L_a(h) = \E\left[\frac{\Pr(S=1\mid X, A=a)}{\Pr(S=1\mid A=a)}\left\{\frac{1-e(X)}{e(X)}\right\}^{2a-1} \left(Y-h\left(X\right)\right)^2\mid A=a\right]
    \end{equation*}
\end{proof}

\subsection{Proof of Lemma~\ref{lem:oracle_weight_combined}}\label{app:oracle_weight_combined}

\begin{proof}
The inequality $R^*(\lambda^{\star}) \le \min\{R^*_{QR}, R^*_{DR}\}$ follows directly from the definition of $\lambda^{\star}$ as the minimizer of $R^*(\lambda)$ over the set $\Lambda$. Since both $\lambda=0$ and $\lambda=1$ are in this set, the minimum value $R^*(\lambda^{\star})$ cannot be greater than the value at either endpoint: $R^*(\lambda^{\star}) \le R^*(0) = R^*_{DR}$ and $R^*(\lambda^{\star}) \le R^*(1) = R^*_{QR}$. Therefore, $R^*(\lambda^{\star}) \le \min\{R^*_{DR}, R^*_{QR}\}$.

For uniqueness, we note that the risk $R^*(\lambda)$ can be expanded as
\begin{align*}
  R^*(\lambda) &= \E\bigl[ (V+\lambda(U-V))^{2} \mid S=1 \bigr] \\
             &= \E[(U-V)^2] \lambda^2 + 2\E[V(U-V)] \lambda + \E[V^2] \\
             &= A\lambda^2 + B\lambda + C,
\end{align*}
where $U=\hattauQR(X)-\cate(X)$, $V=\hattauDR(X)-\cate(X)$, $A=\E[(U-V)^2]$, $B=2\E[V(U-V)]$, and $C=\E[V^2]$. If $A > 0$, the risk function $R^*(\lambda)$ is a strictly convex quadratic function. A strictly convex function has a unique minimum over any convex set, including the set $\Lambda$. Therefore, if $A>0$, the minimizing weight $\lambda^{\star}$ is unique.
\end{proof}


\subsection{Proof of Theorem~\ref{thm:cv_risk_combined}}

\begin{proof}
   % TODO: Define the risk \widetilde R(\lambda) and justify its relation to R^*(\lambda), possibly via a Proposition like the original proof mentioned.
   Let $\widetilde R(\lambda)$ be the expectation of the cross-validated loss term.
Since the squared loss is bounded in $[0,B]$,  $\Lambda:=[0,1]$ is a compact subset of $\mathbb R$, the uniform law of large numbers gives
   \[
\sup_{\lambda\in \Lambda}\bigl|\widehat R_{CV}(\lambda)-\widetilde R(\lambda)\bigr|
     \;=\;o_p(1).
   \]
Further, by definition $\widehat R_{CV}(\hat\lambda^\star)\le\widehat R_{CV}(\lambda^\star)$, hence
   \[
     \widetilde R(\hat\lambda^\star)
     =\widehat R_{CV}(\hat\lambda^\star)+o_p(1)
     \;\le\;
     \widehat R_{CV}(\lambda^\star)+o_p(1)
     =\widetilde R(\lambda^\star)+o_p(1).
   \]
Finally, it follows from the proof in Theorem~\ref{thm:variance_bound} that $\widetilde R(\lambda)=R^*(\lambda)+C$ for some constant $C$ 
   \[
     R^*(\hat\lambda^\star)+C
     \;\le\;
     R^*(\lambda^\star)+C
     +o_p(1)
     \quad\Longrightarrow\quad
     R^*(\hat\lambda^\star)\;\le\;R^*(\lambda^\star)+o_p(1).
   \]
Finally, Lemma~\ref{lem:oracle_weight_combined} yields
   \[
     R^*(\lambda^\star) 
     \;\le\;\min\{R^*_{DR}, R^*_{QR}\},
   \]
   completing the chain:
   \[
     R^*(\hat\lambda^\star)
     \;\le\;
     R^*(\lambda^\star)
     \;+\;o_p(1)
     \;\le\;
     \min\{R^*_{DR}, R^*_{QR}\}
     \;+\;o_p(1).
   \]
\end{proof}


\section{Statistical inference with QR-learner}
\label{app:QR_learner_guarantees}

In this section, we discuss when statistical inference is feasible for the estimated CATE function $\hat\tau(x)$ produced by the QR-learner. Although a full theoretical analysis is beyond the scope of this work, we outline key conditions under which inference is expected to be valid.

Under standard regularity conditions and with the use of cross-fitting (as described in the main text), inference on $\hat\tau(x)$ becomes possible when the regression of pseudo-outcomes $\widehat{\psi}$ on covariates $X$ is performed using a low-dimensional model~\citep[Chapter 14]{chernozhukov2024}. This is enabled by the Neyman orthogonality of the pseudo-outcomes~\eqref{eq:pseudo_outcome}, which ensures that the impact of nuisance estimation errors on $\hat\tau(x)$ is second-order~\citep{foster2023orthogonal}.

Moreover, \citet{kennedy2023towards} show that if a ``stable regressor'' is used to estimate $\tau(x)$ in the DR-learner (see their definition), statistical inference may also be guaranteed. Examples of such regressors include linear regression, smoothing splines, and kernel ridge regression. Importantly, this remains feasible even if the nuisance components $\hat\eta$ converge at slower rates than $\hat\tau(x)$, since their influence appears as a product of estimation errors -- specifically, those from $\hat\eta$ and the estimated propensity score (if one were to estimate it). In randomized trials, where the true propensity score is known, we could expect this product to vanish rapidly, making the impact of nuisance estimation asymptotically negligible on the final CATE estimate $\hat\tau(x)$. In this case, asymptotically valid inference for $\hat\tau(x)$ may be warranted as long as the regressor used for the final stage regressor has inferential guarantees~\citep{kennedy2023towards}.

\section{Experimental details} \label{app:experiment}

\subsection{Data-generating process in simulation studies}

We simulate data as follows: We set $S_i=1$ for $i=1,\dots,n_1$, and for $S_i=0$ for $i=n_1+1,\dots, n_1+n_0$, and sampled a Normal $d$-dimensional covariate according to $X_i\sim N(\mu_{S_i}, \frac{1}{\sqrt{d}}\Sigma)$ with the mean $\mu_1=\mathbf{0}$ or $\mu_0=0.2\cdot \mathbf{1}$ and the covariance matrix $\Sigma$ of shape $d\times d$ had its diagonal elements set to $1$ and its off-diagonal elements set to $0.1$. 
Thereafter, we sampled the treatment $T_i\sim\text{Bern}(e(X_i,S_i))$ according to the Bernoulli probability 
\begin{equation*}
    e(X_i,S_i) = 
    \begin{cases}
        0.5,& \text{ if }S_i=1 \\
        \frac{1}{1+\exp{\{-(\alpha_0+\alpha^\top X_i)}\}}, & \text{otherwise}
    \end{cases}
\end{equation*}
Finally, we computed outcomes $Y_i=b(X_i)+A_i\cdot \tau(X_i)+\varepsilon_i$ where the noise variables was sampled according to $\varepsilon_i\sim N(0,\sigma^2=1/4)$. 

For the experiment in Section~\ref{sec:simulation_rmse}, we modeled a highly non-linear baseline risk together with a linear CATE, which as done by defining:
\begin{align*}
    b(X_i) &= \sum_{j=1}^d \frac{3}{d}\cos \left(\frac{3}{2}X_{ij}\right) + \sum_{j=1}^d \sum_{j'=1}^d \frac{1}{d}X_{ij}X_{ij'}, \\
    \tau(X_i) &= \sum_{j=1}^d  \frac{1}{d}X_{ij}.
\end{align*}
In the scenario where Conditions~\ref{asmp:strong_ignorability_external} and~\ref{asmp:transportability} held, we set the covariate dimension to $d=5$. To simulate violations of these assumptions, we increased the covariate dimension to $d=7$ but masked the last two dimensions, so that only 5 covariates remained observed. 

For the experiment in Section~\ref{sec:simulation_power}, we considered a setting with a linear baseline outcome and a sparse linear CATE that depended only on a single covariate. To violate transportability (Condition~\ref{asmp:transportability}), this time we encoded different functions $\tau(X)$ for the trial and external population. Specifically, we defined:
\begin{align*}
b(X_i) &= \sum_{j=1}^d \frac{1}{d} X_{ij}, \\
\tau(X_i) &= \begin{cases}
    \beta \cdot d \cdot X_{i1}, &\text{ if }S_i=1\\
    \left(\beta + \frac{1}{20}\right) \cdot d \cdot X_{i1}, & \text{ otherwise}
\end{cases}
\end{align*}
where $\beta$ was a tunable parameter that controlled the size of the interaction effect between the treatment $A_i$ and the first covariate $X_{i1}$. As before, we set $d=5$. 


\subsection{Implementation details for CATE learners}
For the experiments in Section~\ref{sec:simulation_rmse} and~\ref{sec:star}, we implemented the CATE learners as follows.

For the estimators used inside the CATE learners we used implementations from the \textit{scikit-learn} Python package~\citep{scikit-learn} . For the DR-learner, T-learner, pooled T-learner, the method from \citet{asiaee2023leveraging}, and QR-learner, we used histogram-based gradient boosting regression tree using default hyperparameter. As the final CATE regressor in the two-stage CATE learners (all of the above except the T-learner variants), we used a linear regression model. For estimating $\pi_a(X)=\Pr(S=1\mid X,A=a)$, we used a cross-validated logistic regression with ridge penalty. For the additive correction model in~\citet{kallus2018removing}, we fitted the DR-learner on the external dataset and then used a linear regression to estimate the bias model. We applied crossfitting to all two-stage CATE learners using two folds consistently. For cross-fold validation in the combined QR- and DR-learner, we used three folds. 

To predict with the average treatment effect (ATE), we used the difference-in-means estimate $$\hat\tau_{DM}=\frac{\sum_{i=1}^{n_1} A_iY_i}{\sum_{i=1}^{n_1} A_i} - \frac{\sum_{i=1}^{n_1} (1-A_i)Y_i}{\sum_{i=1}^{n_1} 1-A_i}$$ as a constant CATE prediction $\hat\tau(x)=\hat\tau_{DM}$ for all $x$.

\subsection{Statistical tests for treatment effect heterogeneity} \label{app:statistical_tests}

Below we describe our implementations for the statistical tests used to detect treatment effect modification in the experiment in Section~\ref{sec:simulation_power}.

For covariate adjustment, we fit a linear regression model of $Y$ on the covariates $(A, X_1, A \cdot X_1)$ using the trial data. We then estimated 95\% confidence intervals for the coefficient of $A \cdot X_1$ to assess whether it was significantly different from zero. For the pooled covariate adjustment, we followed the same approach but fit the linear regression model on the combined dataset consisting of both the trial data and the external data.

For the DR-learner, QR-learner, and the method proposed by~\citet{asiaee2023leveraging}, we split the data into two folds (stratified by the study population $S$). We used the first fold to estimate the nuisance components in $\eta$ via linear regression using their respective strategies as outlined in the main paper, then computed pseudo-outcomes on the second fold. These pseudo-outcomes were regressed on the feature $X_1$ using another linear regression model, resulting in the first CATE estimate $\hat{\tau}(X_1) = \hat{\alpha}^{(1)} \cdot X_1$. To utilize the entire dataset efficiently, we repeated the process by swapping the folds, obtaining a second CATE estimate $\hat{\tau}(X_1) = \hat{\alpha}^{(2)} \cdot X_1$. We then computed 95\% confidence intervals to test the null hypothesis that $\alpha=0$ as follows:
$$\left[\bar{\alpha} - 1.96 \cdot \text{se}(\bar{\alpha}), \; \bar{\alpha} + 1.96 \cdot \text{se}(\bar{\alpha})\right],$$
where $\bar{\alpha} = \frac{1}{2}(\hat{\alpha}^{(1)} + \hat{\alpha}^{(2)})$ and using the individual standard errors $\text{se}(\hat{\alpha}^{(1)})$ and $\text{se}(\hat{\alpha}^{(2)})$ to compute
$$
\text{se}(\bar{\alpha}) = \sqrt{\frac{1}{4} \left( \text{se}(\hat{\alpha}^{(1)})^2 + \text{se}(\hat{\alpha}^{(2)})^2 \right)},
$$
assuming normality and that the covariance between $\hat{\alpha}^{(1)}$ and $\hat{\alpha}^{(2)}$ to be negligible.



\subsection{Tenneesse STAR Dataset}\label{app:star}

The data from the STAR study consists of 4218 students: 2811 from rural schools and 1407 from urban schools. The treatment is class size: small ($A = 0$) versus regular ($A = 1$), and the continuous outcome $Y$ is the student's average test score. Our observed covariates include gender, race, birth date, teacher ID, and free lunch eligibility. After applying one-hot encoding to these variables, which are either binary or categorical, we obtain a 310-dimensional feature vector. 

To construct a partially overlapping randomized trial and confounded observational study, we begin by evenly splitting the rural students into two groups: one assigned to a randomized trial and the other to an observational cohort. All students from urban schools are then added to the observational dataset. To induce confounding in the observational study, we selectively remove treated students with above-median outcomes separately within the rural and urban subsets. This process creates a dependence between school location, treatment assignment, and outcomes. Crucially, school location is excluded from the observed covariates, ensuring that this confounding remains unmeasured. For this reason, we can be certain that there is a violation of strong ignorability in the observational data (Condition~\ref{asmp:strong_ignorability_external}) due to this omitted confounder. In the experiment, we would randomly resample from this data without replacement for each repeated run, sampling $n_1$ and $n_0$ observations each from the trial and external data.

Moreover, we evaluate if also transportability (Condition~\ref{asmp:transportability}) is violated between the two constructed populations in this data. We test for transportability using a conditional independence test, $Y \perp S \mid X, A$, which should hold if Conditions~\ref{asmp:consistency} through~\ref{asmp:transportability} are valid~\citep{dahabreh2024using}. We tested this conditional independence using the partial Pearson correlation test while including the school location in $X$, meaning that we expect strong ignorability in the external population (Condition~\ref{asmp:strong_ignorability_external}) to hold, in addition to Condition~\ref{asmp:consistency} and~\ref{asmp:strong_ignorability_trial} which are supported by the randomization in the trial partition. Still, the test rejected the null hypothesis of the conditional independence holding, suggesting that there also is a transportability violation in the data.

Finally, we visualized the overlap between the trial and observational populations. We first plotted a histogram of the estimated probabilities  $\Pr(S=1\mid X)$ obtained using cross-validated logistic regression. Additionally, we applied t-SNE for dimensionality reduction to visualize the distribution of covariates across the two populations. These visualizations, shown in Figure~\ref{fig:star_visualization}, reveal limited overlap in certain regions of the observational data. However, importantly, the covariate support of the trial population appears to be contained within that of the observational population.

Overall, the above analysis of the data indicates that in our experiments, the external observational study is misaligned with the trial data because both strong ignorability in the external population (Condition~\ref{asmp:strong_ignorability_external}) and transportability (Condition~\ref{asmp:transportability}) are violated.

\begin{figure}[ht]
    \centering
    \begin{subfigure}[b]{0.45\linewidth}
        \centering
        \includegraphics[width=\linewidth]{figures/propensity_score_hist.pdf}
        \caption{}
        \label{fig:star_histogram}
    \end{subfigure}
    ~
    \begin{subfigure}[b]{0.45\linewidth}
        \centering    \includegraphics[width=\linewidth]{figures/tsne.pdf}
        \caption{}
        \label{fig:star_tsne}
    \end{subfigure}
    \caption{\textbf{(a)}: Histograms of estimated probabilities for trial study participation $\Pr(S=1\mid X)$ using a cross-validated logistic regression on STAR dataset. \textbf{(b)} TSNE plot over features in Tennessee STAR dataset, colored by study population. In both plots, we observe significant lack of overlap between populations, though the trial is a subset of the external data as expected.
    }
    \label{fig:star_visualization}
\end{figure}



\subsection{Compute resources used for experiment} \label{app:compute_resources} 

All experiments were run on a CPU machine. The simulations in Sections~\ref{sec:experiment} and~\ref{sec:star} each completed in under 72 hours on a laptop with a 2 GHz Quad-Core Intel Core i5 processor and 16GB of RAM. Including preliminary experiments not shown in the paper, no single run exceeded this runtime.

\end{document}

