\begin{thm}\label{r+ trace preserving}
		For all $n\geq 0$, the reflection operator $r^+_{2n+1}$ is trace preserving.
	\end{thm}
\begin{prf}
	We will first do it for $r^+_{1}$.
	Let $x \in B^\prime \cap A_1$. Then,
	\begin{eqnarray}\nonumber
	\tr(r^+_{1}(x))&=& \tr(\tau^{-1}\sum_i E_1(e_1\lambda_ix)e_1\lambda_i^*) \\\nonumber
	&=& \tau^{-1}\sum_i E_0\circ E_1(E_1(e_1\lambda_ix)e_1\lambda_i^*)\\\nonumber
	&=& \sum_iE_0\circ E_1(e_1\lambda_ix\lambda_i^*)\\\nonumber&=& \tau^{-1}E_0\circ E_1(e_1E^{B^\prime \cap A_1}_{A^\prime \cap A_1}(x))\\\nonumber
	&=& \tr(E^{B^\prime \cap A_1}_{A^\prime \cap A_1}(x))\quad\quad (\text{by  \Cref{tracelemma}})\\\nonumber
