\begin{ppsn}\label{reln r- r A A_1} For each $n\geq 0$,
    $r^-_{2n+1}=(r^+_{2n+1})^{A\subset A_1}$.
\end{ppsn}
 \begin{prf}
 Using \Cref{rho+relnrho-} we can observe that,

     \begin{eqnarray}\nonumber
      r^-_{2n+1}(w)&=&({\rho^-_{2n+1}})^{n+1}(w)\\\nonumber
          &=&i\circ \big(({\rho^{+}_{2n+1}})^{A\subset A_1}\big)^{(n+1)}\circ i(w)\\\nonumber
          &=&i\circ (r^+_{2n+1})^{A\subset A_1}\circ i(w)\\\nonumber
     &=&(r^+_{2n+1})^{A\subset A_1}(w).
