 \begin{thm}\label{r- every property}
      For $n\geq 0$, the reflection operator $r^-_{2n+1}: A^\prime \cap A_{2n+2} \to A^\prime \cap A_{2n+2}$, is a unital, involutive, $*$-preserving anti-homomorphism. It also preserves the trace.
 \end{thm}
 \begin{prf}
     Using \Cref{reln r- r A A_1}, \Cref{antihomo} and \Cref{r+ trace preserving} the proof is straightforward. \qed
