The following result will be used later crucially to improve the constant of the  Young's inequality as given in \cite{BGS2022}.
\begin{thm}\label{pnormequality}
	For $x \in B^\prime\cap A_{2n+1}$ and $w \in A^\prime \cap A_{2n+2}$, we have the following
	\begin{center}
		$\|x\|_p=\|r^+_{2n+1}(x)\|_p\quad\quad\text{and}\quad \quad\|w\|_p =\|r^-_{2n+1}(w)\|_p\,$
	\end{center}
where $1\leq p \leq \infty$.
\end{thm}
\begin{prf}
Let us do the case $p=2$.	Let $x \in B^\prime\cap A_{2n+1}$.  Then,
	\begin{eqnarray}\nonumber
	\|r^+_{2n+1}(x)\|_2^2 &=& \tr(|r^+_{2n+1}(x)|^2)\\\nonumber
	&=& \tr(r^+_{2n+1}(x^*)r^+_{2n+1}(x))\\\nonumber
	&=& \tr(r^+_{2n+1}(xx^*))\quad \quad
    (\text{by \Cref{antihomo}} )\\\nonumber
	&=& \tr(xx^*)\quad \quad
    (\text{by \Cref{r+ trace preserving}} )\\\nonumber
	&=& \tr(|x|^2)\\\nonumber
	&=& \|x\|_2^2.
	\end{eqnarray}
We know that the reflection operator $r^-_{2n+1}$ is also an anti-homomorphism and trace preserving by \Cref{r- every property}. Now doing same as above for the reflection operator $r^-_{2n+1}$, we will get
	$\|r^-_{2n+1}(w)\|_2=\|w\|_2 $. Once the result is established for $p=2$, it follows  that it is also true for all $1\leq p \leq \infty$, thanks to the interpolation technique.
\end{prf}

\subsection{Canonical shift}\label{Canonical shift}
Motivated by the classification of subfactors of the hyperfinite $II_1$ factor $R$ with finite Jones index, Ocneanu had introduced a certain $*$-endomorphism which he called the canonical shift on the $n$-box spaces of the subfactor. This resembles Longo's canonical endomorphism for infinite factors which plays a significant role in the index theory for infinite factors. Analogous to the subfactor theory, we  introduce canonical shift for an inclusion of simple $C^*$-algebras with a conditional  expectation of index-finite type, as a vast generalization of canonical shift for both type $II$ and type $III$ subfactors and examine its key properties which will be instrumental in establishing a relationship between Watatani index and the Connes-St{\o}rmer relative entropy of the shift in the final section. A key difference is that unlike subfactors with finite Jones index, we do not have modular conjugation operators in our case. We exploit quasi-basis and minimal conditional expectation and use the reflection operators as the key technical tool to establish this theory. To begin, we discuss certain shift operators (see \cite{O} for $II_1$ subfactor case) on the $n$-box spaces.

We begin with the following lemma, which will be useful in our subsequent analysis. The straightforward proof is omitted.
\begin{lmma}\label{shift 10}
For every $n\geq 1$, we have $$v_{n+2}\lambda_{i_{1}}\cdots v_{2n+1}\lambda_{i_{n}} \,v_{2n}\lambda_{i_{n+1}}v_{2n+1}  \lambda_{i_{n+2}}=\tau^{2n}\lambda_{i_{1}}e_{1}\lambda_{i_{2}} \,v_{n+2}\lambda_{i_{3}}v_{n+3}  \lambda_{i_{4}}\cdots v_{2n+1}  \lambda_{i_{n+2}} .$$
\end{lmma}
The following two results are well known in the context of $II_1$ factors (for instance see \cite{David}) and will be instrumental in defining the canonical shift in our setting.

\begin{ppsn}\label{shift 1}
    For every $n\geq 0$ and $x \in B' \cap A_{2n+1}$, we have $$r^+_{2n+3}(x)= \tau^{-(2n+2)}\sum_{i_1} \lambda_{i_1} v^*_{2n+2}\,r^{+}_{2n+1}(x) \,v_{2n+3}\lambda^*_{i_1}.$$
 Moreover, $r^+_{2n+3}(x) \in A^{'}_1 \cap A_{2n+3}$.
\end{ppsn}	
\begin{prf}
Let us first treat the case when $n=0$. For any $x \in B' \cap A_{1}$, applying \Cref{eqn for r+} gives the following expression.
\begin{eqnarray}\nonumber
r^+_{3}(x)
      &=& c^{2}_{3}\sum_{i_1,i_{2}}  E_2 \circ E_{{3}}(v_{2}\lambda_{i_{1}}v_{3}\lambda_{i_{2}}x)v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber
    %&=& c^{2}_{3}\sum_{i_1,i_{2}}  E_2 \big(v_{2}\lambda_{i_{1}} E_3(v_{3}\lambda_{i_{2}}x)\big)v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber 
    &=& c^{2}_{3}\tau \sum_{i_1,i_{2}}  E_2 (v_{2}\lambda_{i_{1}} v_{2}\lambda_{i_{2}}x)v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber 
     &=& c^{2}_{3}\tau^2 \sum_{i_1,i_{2}}  E_2 (e_{2}\lambda_{i_{1}} e_{1}\lambda_{i_{2}}x)v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber 
      &=& c^{2}_{3}\tau^3 \sum_{i_1,i_{2}}   \lambda_{i_{1}} e_{1}\lambda_{i_{2}}x\,v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber
      %&=& c^{2}_{3}\tau^2 \sum_{i_1,i_{2}}   \lambda_{i_{1}} e_{1}e_2e_1\lambda_{i_{2}}x\,v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber
      &=& c^{2}_{3}\tau^2 \sum_{i_1,i_{2}}   \lambda_{i_{1}} e_{1}E_1(e_1\lambda_{i_{2}}x)v_{2}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber
      &=& c^{2}_{3}\tau^2 \sum_{i_1,i_{2}}   \lambda_{i_{1}} e_1e_2E_1(e_1\lambda_{i_{2}}x)e_{1}\lambda^{*}_{i_{2}}v_{3}\lambda^{*}_{i_{1}}\\\nonumber
      &=& \tau^{-2} \sum_{i_1}   \lambda_{i_{1}} v^*_2\,r^+_1(x)\,v_{3}\lambda^{*}_{i_{1}}.
\end{eqnarray}
Now, let $n\geq 1$ and consider an element $x \in B' \cap A_{2n+1}$. By applying \Cref{eqn for r+} we obtain the following: 
     \begin{eqnarray}\label{imp shifttt}
      && r^+_{2n+3}(x)
      = c^{n+2}_{2n+3}\sum_{i_1, \cdots, i_{n+2}}  E^{{2n+3}}_{{n+2}} (v_{n+2}\lambda_{i_{1}}\cdots v_{2n+3}\lambda_{i_{n+2}}x)v_{n+2}\lambda^{*}_{i_{n+2}} \cdots v_{2n+3}\lambda^{*}_{i_{1}}.
    \end{eqnarray}
Consequently, we now obtain: 
    \begin{eqnarray}\nonumber
    &&E^{{2n+3}}_{{n+2}} (v_{n+2}\lambda_{i_{1}}\cdots v_{2n+3}\lambda_{i_{n+2}}x)\\\nonumber
    &=&E^{{2n+2}}_{{n+2}}\big( v_{n+2}\lambda_{i_{1}}\cdots v_{2n+2}\lambda_{i_{n+1}}\,  E_{2n+3}(v_{2n+3}\lambda_{i_{n+2}}x)\big)\\\nonumber
    &=& \tau E^{{2n+2}}_{{n+2}}( v_{n+2}\lambda_{i_{1}}\cdots v_{2n+2}\lambda_{i_{n+1}}v_{2n+2}  \lambda_{i_{n+2}}x)\\\nonumber
     &=& \tau^2 E^{{2n+2}}_{{n+2}}( v_{n+2}\lambda_{i_{1}}\cdots v_{2n+1}\lambda_{i_{n}} e_{2n+2}\,v_{2n}\lambda_{i_{n+1}}v_{2n+1}  \lambda_{i_{n+2}}x)\\\nonumber
    &=& \tau^2 E^{{2n+1}}_{{n+2}}\big( v_{n+2}\lambda_{i_{1}}\cdots v_{2n+1}\lambda_{i_{n}}\,  E_{2n+2}(e_{2n+2}\,v_{2n}\lambda_{i_{n+1}}v_{2n+1}  \lambda_{i_{n+2}}x )\big)\\\nonumber
    &=& \tau^3 E^{{2n+1}}_{{n+2}}( v_{n+2}\lambda_{i_{1}}\cdots v_{2n+1}\lambda_{i_{n}} \,v_{2n}\lambda_{i_{n+1}}v_{2n+1}  \lambda_{i_{n+2}}x)\\\nonumber
   &=& \tau^{2n+3} E^{{2n+1}}_{{n+2}}(\lambda_{i_{1}}e_{1}\lambda_{i_{2}} \,v_{n+2}\lambda_{i_{3}}v_{n+3}  \lambda_{i_{4}}\cdots v_{2n+1}  \lambda_{i_{n+2}}).
\end{eqnarray}
The last line follows from \Cref{shift 10}. Thus, from \Cref{imp shifttt}, we obtain:
 \begin{eqnarray}\nonumber
      && r^+_{2n+3}(x)\\\nonumber
      &=& c^{n+2}_{2n+3}\tau^{2n+3}\sum_{i_1, \cdots, i_{n+2}}  E^{{2n+1}}_{{n+2}} (\lambda_{i_{1}}e_{1}\lambda_{i_{2}} \,v_{n+2}\lambda_{i_{3}}v_{n+3}  \lambda_{i_{4}}\cdots v_{2n+1}  \lambda_{i_{n+2}})v_{n+2}\lambda^{*}_{i_{n+2}} \cdots v_{2n+3}\lambda^{*}_{i_{1}}.
    \end{eqnarray}
Furthermore, by applying \Cref{eqn for r+}, we have
\begin{eqnarray}\nonumber
&&\sum_{i_1} \lambda_{i_1} v^*_{2n+2}\,r^{+}_{2n+1}(x) \,v_{2n+3}\lambda^*_{i_1}\\\nonumber
&=&c^{n+1}_{2n+1}\sum_{i_1, \cdots, i_{n+2}} \lambda_{i_1} v^*_{2n+2}\, E^{{2n+1}}_{{n+1}} (v_{n+1}\lambda_{i_{2}}\cdots v_{2n+1}\lambda_{i_{n+2}}x)v_{n+1}\lambda^{*}_{i_{n+2}} \cdots v_{2n+1}\lambda^{*}_{i_{2}}v_{2n+3}\lambda^*_{i_1}\\\nonumber
&=&c^{n+1}_{2n+1}\sum_{i_1, \cdots, i_{n+2}} \lambda_{i_1} v^*_{n+1}\, E^{{2n+1}}_{{n+1}} (v_{n+1}\lambda_{i_{2}}\cdots v_{2n+1}\lambda_{i_{n+2}}x)(v^{(n+2)}_{2n+2})^*\,v_{n+1}\lambda^{*}_{i_{n+2}} \cdots v_{2n+1}\lambda^{*}_{i_{2}}v_{2n+3}\lambda^*_{i_1}\\\nonumber
&=&c^{n+1}_{2n+1}\sum_{i_1, \cdots, i_{n+2}} \lambda_{i_1} v^*_{n+1}\, E^{{2n+1}}_{{n+1}} (v_{n+1}\lambda_{i_{2}}\cdots v_{2n+1}\lambda_{i_{n+2}}x)v_{n+2}\lambda^{*}_{i_{n+2}} \cdots v_{2n+2}\lambda^{*}_{i_{2}}v_{2n+3}\lambda^*_{i_1}\\\nonumber
&=&c^{n+1}_{2n+1}\sum_{i_1, \cdots, i_{n+2}} \lambda_{i_1} v^*_{n+1}\, E_{n+1}\big(v_{n+1}\lambda_{i_{2}} \, E^{{2n+1}}_{{n+2}} (v_{n+2}\lambda_{i_{3}}\cdots v_{2n+1}\lambda_{i_{n+2}}x)\big)v_{n+2}\lambda^{*}_{i_{n+2}} \cdots v_{2n+3}\lambda^*_{i_1}\\\nonumber
&=&c^{n+1}_{2n+1}\tau \sum_{i_1, \cdots, i_{n+2}} \lambda_{i_1} v^*_{n+1}v_{n}\lambda_{i_{2}} \, E^{{2n+1}}_{{n+2}} (v_{n+2}\lambda_{i_{3}}\cdots v_{2n+1}\lambda_{i_{n+2}}x)v_{n+2}\lambda^{*}_{i_{n+2}} \cdots v_{2n+3}\lambda^*_{i_1}\\\nonumber
&=&c^{n+1}_{2n+1}\tau^{n+1} \sum_{i_1, \cdots, i_{n+2}} \lambda_{i_1} e_1\lambda_{i_{2}} \, E^{{2n+1}}_{{n+2}} (v_{n+2}\lambda_{i_{3}}\cdots v_{2n+1}\lambda_{i_{n+2}}x)v_{n+2}\lambda^{*}_{i_{n+2}} \cdots v_{2n+3}\lambda^*_{i_1}.
\end{eqnarray}
The last two equalities follow from \Cref{pushdown} and \cite{BakshiVedlattice}[Equation 3.2] respectively. Since $c^{n+1}_{2n+1}\tau^{n+1}\tau^{-(2n+2)}=c^{n+2}_{2n+3}\tau^{2n+3}$, so the first part is done. Once the first part is done, by proceeding in the same manner as in the proof of \cite{Bi94}[Theorem 2.13(ii)] (or by [lemma 2.23]\cite{BakshiVedlattice}), we get the other part.
 \qed
\end{prf}

Using \Cref{shift 1} we will get the following consequences whose easy proofs are same as in \cite{David}.
\begin{crlre}\label{shift 2}
\begin{itemize}
For every $n\geq 0$ and $x \in B' \cap A_{2n+1}$, we have 
   $$r^+_{2n+3}\circ r^+_{2n+1}(x)= \tau^{-(2n+2)}\sum_{i} \lambda_i v^*_{2n+2}\,x \,v_{2n+3}\lambda^*_i $$ \text{and} 
    $$ r^+_{2n+5}\circ r^+_{2n+3}(x)=r^+_{2n+3} \circ r^+_{2n+1}(x).$$
    \end{itemize}
 \end{crlre}


Now we set $S^{+}_n= r^+_{2n+3} \circ r^+_{2n+1}$, for each $n\geq 0$. Then using the above results and doing same as in the proof of \cite{Bi94}[Theorem 2.13], we will get the following observations which will be extremely crucial in the sequel.
\begin{thm} \label{shift operator}
    For each $n\geq 0$, we have
    \begin{enumerate}
        \item  $S^+_n:B' \cap A_{2n+1} \to A^{\prime}_1 \cap A_{2n+3}$ is a unital trace preserving $*$-isomorphism.
        \item $S^+_n|_{B' \cap A_{2n}} : B' \cap A_{2n} \to A^{\prime}_1 \cap A_{2n+2}$ is also a unital trace preserving $*$-isomorphism.
        \item $S^+_{n+1}|_{B'\cap A_{2n+1}}=S^+_n$.
       \item We have
 $S^{+}_n(A^{\prime}_k \cap A_{2n+1})= A^{\prime}_{k+2} \cap A_{2n+3}$ and 
$S^{+}_n(A^{\prime}_k \cap A_{2n})= A^{\prime}_{k+2} \cap A_{2n+2}$.
    \end{enumerate}
\end{thm}

By \Cref{reln r- r A A_1}, we know that $r^-_{2n+1}=(r^+_{2n+1})^{A\subset A_1}$. Now if we set $S^{-}_n= r^-_{2n+3} \circ r^-_{2n+1}$, for each $n\geq 0$. Thus, we get the following results for  $S^-_{n}$.
\begin{thm} \label{shift 3}
    For each $n\geq 0$, we have
    \begin{enumerate}
        \item  $S^-_n:A' \cap A_{2n+2} \to A^{\prime}_2 \cap A_{2n+4}$ is a unital trace preserving $*$-isomorphism.
        \item $S^-_n|_{A' \cap A_{2n+1}} : A' \cap A_{2n+1} \to A^{\prime}_2 \cap A_{2n+3}$ is also a unital trace preserving $*$-isomorphism.
        \item $S^-_{n+1}|_{A'\cap A_{2n+2}}=S^-_n$. 
       \item We have
$S^{-}_n(A^{\prime}_{k+1} \cap A_{2n+2})= A^{\prime}_{k+3} \cap A_{2n+4}$ and
$S^{-}_n(A^{\prime}_k \cap A_{2n+1})= A^{\prime}_{k+2} \cap A_{2n+3}.$
    \end{enumerate} 
\end{thm}



As discussed in \Cref{preliminaries}, starting from an inclusion $B\subset A$ of simple unital $C^*$-algebras with a conditional expectation of finite Watatani index, we obtain a tower $\{A_j\}_j$ of simple unital $C^*$-algebras, by iterating the $C^*$-basic construction with respect to the minimal conditional expectations. This yields an increasing sequence of finite dimensional von Neumann algebras as follows:
\begin{center}
		$A'\cap A_1 \subset A' \cap A_2 \subset A'\cap A_3 \subset \cdots \subset A'\cap A_n \subset \cdots$
	\end{center}
	Recall further that the maps $\mathrm{tr}_n:=( E_1\circ E_2 \circ \cdots\circ E_n)_{|_{A^{\prime}\cap A_n}}$ define faithful tracial states on $A^{\prime}\cap A_n$. We set $P_0 = \bigcup_{n\geq 1} A'\cap A_n$. There is a natural trace on $P_0$ defined by $\tr(w)=\tr_n(w)$, where $n$ is such that $w \in A' \cap A_n$. Let $\mathcal{H}$ is the completion of $P_0$ with respect to the inner product $\langle w_1, w_2\rangle = \tr(w^*_1w_2)$. An element $w\in P_0$ when viewed as a vector in $\mathcal{H}$ will be written as $\widehat{w}$. For $w_1, w_2 \in P_0$, we set $\pi(w_1)\widehat{w}_2= \widehat{w_1w_2}$. It is easy to check that $\pi : P_0 \rightarrow B(\mathcal{H})$ is an injective $*$-homomorphism and we will write $w$ for $\pi(w)$. We denote by  $P$ the SOT closure of $P_0$ in $B(\mathcal{H})$.


 In view of \Cref{shift 3}, the trace preserving $*$-endomorphism $\Gamma$ on $\bigcup_{n\geq 1} A'\cap A_n$ can be defined by $$\Gamma(w)= S^-_n(w), \quad \text{ for } w\in A' \cap A_{2n+2}.$$ We can extend $\Gamma$ (will denote it by the same $\Gamma$) to a trace preserving endomorphism of the von Neumann algebra $P$. Motivated by Ocneanu, we  call this endormphism $\Gamma$ the \textit{canonical shift of the inclusion $B\subset A$}. The following observations are well-known in the context of an inclusion of factors $N\subset M$, with a conditional expectation from $M$ onto $N$ (see \cite{CH}, for instance).
\begin{ppsn}\label{shiftnew}For all natural number $j$ and $k$,
    \begin{enumerate}


        \item $\Gamma^k(A'\cap A_j)= A^{\prime}_{2k} \cap A_{j+2k}$.
        \item $\Gamma(A'\cap A_{2j})= r^-_{2j+1}(A'\cap A_{2j})$.
        \end{enumerate}
\end{ppsn}
\begin{prf}
\begin{enumerate}[wide=0pt, listparindent=1.25em, parsep=0pt]
\item It is an easy consequence of \Cref{shift 3} item(4).
\item Using \Cref{shift 3}, we have
$$\Gamma(A'\cap A_{2j})=S^-_{j-1}(A'\cap A_{2j})= A^{\prime}_2 \cap A_{2j+2}.$$
Moreover, by \Cref{reln r- r A A_1}, we know that $r^-_{2j+1}=(r^+_{2j+1})^{A\subset A_1}$. Let $w \in A' \cap A_{2j}$. Then, by \Cref{shift 1}, we have $r^-_{2j+1}(w) \in A^{\prime}_2 \cap A_{2j+2}$. Therefore, $ r^-_{2j+1}(A'\cap A_{2j})\subset A^{\prime}_2 \cap A_{2j+2}. $


Now let $\tilde{w}\in A^{\prime}_2 \cap A_{2j+2}.$ Since $S^-_{j-1}$ is an isomorphism, there exists $w\in A'\cap A_{2j}$ such that $$\tilde{w}=S^-_{j-1}(w)=r^-_{2j+1} \circ r^-_{2j-1}(w)= r^-_{2j+1}(w_1)$$ where $w_1= r^-_{2j-1}(w) \in A'\cap A_{2j}$. This shows that $A^{\prime}_2 \cap A_{2j+2} \subset r^-_{2j+1}(A'\cap A_{2j}) $. Combining this with the inclusion obtained earlier, we conclude that $r^-_{2j+1}(A'\cap A_{2j})=A^{\prime}_2 \cap A_{2j+2}=\Gamma(A'\cap A_{2j}).$
\end{enumerate}
\end{prf}

\begin{ppsn}\label{shift5} Let $E_Q$ denote the conditional expectation of $P$ onto a von Neumann subalgebra $Q$ of $A$. For $j\geq 2$, we have the relation $E_{A' \cap A_j}E_{\Gamma(A' \cap A_j)}= E_{\Gamma(A' \cap A_{j-2})}$, that is, the following is a commuting square:
 \[\begin{matrix}
A' \cap A_j&\subset & P\\
\cup & &\cup\\
 \Gamma(A' \cap A_{j-2}) &\subset & \Gamma(A' \cap A_j).
 \end{matrix}\]

\end{ppsn}
\begin{prf} First, observe that by applying item (1) of \Cref{shiftnew}, we have $\Gamma(A' \cap A_{j-2})=A^{\prime}_2 \cap A_{j}$ and $\Gamma(A' \cap A_{j})=A^{\prime}_2 \cap A_{j+2}$. Thus we have to show that the following is a commuting square:
 \[\begin{matrix}
A' \cap A_j&\subset & P\\
\cup & &\cup\\
 A^{\prime}_2 \cap A_{j} &\subset & A^{\prime}_2 \cap A_{j+2}.
 \end{matrix}\]
To complete the argument, it suffices to show that $E_{A' \cap A_j}(A^{\prime}_2 \cap A_{j+2})=A^{\prime}_2 \cap A_{j}$. First, note that for $w \in A^{\prime}_2 \cap A_{j+2}$ and $w'\in {A^{\prime} \cap A_{j}} $, we have $$\tr\big(E^{j+2}_{j+1}(w)w')=\tr(ww').$$  Moreover, for any $w \in A^{\prime}_2 \cap A_{j+2}$ and $a \in A_2$, the following commutation relation holds: $$E^{j+2}_{j+1}(w)a=aE^{j+2}_{j+1}(w).$$
This implies that $E_{A' \cap A_j}(A^{\prime}_2 \cap A_{j+2})\subset A^{\prime}_2 \cap A_{j}$. The reverse inclusion is immediate, hence the desired equality follows.
\qed

\end{prf}


Now we will demonstrate that the canonical shift $\Gamma$ is a $2$-shift in the sense of \cite{Choda}. We begin by recalling the definitions of $n$-shift. 
 \begin{dfn}[\cite{Choda}]\label{nshift}
 Let $Q$ be an injective finite von Neumann algebra equipped with a faithful normal trace $\tr$ such that $\tr(1)=1$. Suppose that $Q_1 \subset Q_2 \subset Q_3 \subset \cdots \subset Q_n \subset \cdots$ is an increasing sequence of finite dimensional von Neumann algebras for which $Q$ is the SOT closure of $\bigcup_j Q_j$. For a natural number $n$, a $\tr$ preserving $*$-endomorphism $\sigma$ of $Q$ is called an $n$-shift on the tower $Q_1 \subset Q_2 \subset Q_2 \subset \cdots \subset Q_n \subset \cdots$ for $Q$, if the following conditions are satisfied:
 \begin{enumerate}
 \item For all $j,m \in \bbn$, the von Neumann algebra $\{Q_j, \sigma(Q_j), \cdots, \sigma^m(Q_j)\}''$ is contained in $Q_{j+nm}$.
 \item There exists a sequence $(k_j)_{j\in \bbn}$ of integers satisfying $\lim_{j\rightarrow \infty }\frac{nk_j -j}{j}=0$ such that the following properties hold, $w_1\sigma^m(w_2)=\sigma^m(w_2)w_1$ and $\tr(w_3\sigma^{lk_j}(w_1))=\tr(w_3)\tr(w_1)$, for all $l\in \bbn$ and $w_1, w_2 \in Q_j, m\in k_j\bbn$ and $w_3\in \{Q_j, \sigma^{k_j}(Q_j), \cdots, \sigma^{(l-1)k_j}(Q_j)\}''$.
 \item Let $E_R$ denote the conditional expectation of $Q$ onto a von Neumann subalgebra $R$ of $Q$. Then for all $j\in \bbn$, we have  $E_{Q_j}E_{\sigma( Q_j)}= E_{\sigma(Q_{j-n})}$, i.e. the following is a commuting square:
 \[\begin{matrix}
Q_j&\subset & Q\\
\cup & &\cup\\
 \sigma(Q_{j-n}) &\subset & \sigma( Q_j).
\end{matrix}\]
 \item For all $j\geq n$, there exists a $\tr$-preserving $*$-automorphism or anti-automorphism $\beta$ of $Q_{nj+n}$ such that $\sigma(Q_{nj})= \beta(Q_{nj})$.
 \end{enumerate}
 \end{dfn}
\begin{ppsn}\label{ppsn for 2 shift}
The canonical shift $\Gamma$ for the inclusion $B\subset A$ is a $2$-shift on the tower $(A'\cap A_j)_j$.
 \end{ppsn} 
 \begin{prf}
  Using item (1) of \Cref{shiftnew}, we obtain that for each $j ,m \in \bbn$, the following identity holds: $$\Gamma^m(A'\cap A_j)= A^{\prime}_{2k} \cap A_{j+2k}.$$ From this, it follows immediately that $\{A' \cap A_j , \,\Gamma(A' \cap A_j ), \,\cdots , \,\Gamma^{m}(A' \cap A_j )\}^{\prime \prime} \subset A' \cap A_{j+2m}$.  Hence, the first condition of \Cref{nshift} is verified in this case for $n=2$.

  If we take $k_j= [\frac{j}{2}]+1$, then it is straightforward to verify that $$\lim_{j\rightarrow \infty }\frac{nk_j -j}{j}=0.$$ Moreover, for any $m\in k_j\bbn$ we have $\Gamma^m(A'\cap A_j)= A^{\prime}_{2m} \cap A_{j+2m}\subset A^{\prime}_j$. Hence, we obtain the following commuting relation for any $w_1, w_2 \in (A'\cap A_j)$: $$w_1\Gamma^m(w_2)=\Gamma^m(w_2)w_1.$$ It is also worth noting, by \Cref{shiftnew} item (1), that we have $\Gamma^{lk_j}(A' \cap A_j)= A^{\prime}_{2lk_j}\cap A_{j+2lk_j}$ for all $l\in \bbn$. Assume that $w \in A' \cap A_j$ and $y \in \{A' \cap A_j , \,\Gamma(A' \cap A_j ), \,\cdots , \,\Gamma^{(l-1)k_j}(A' \cap A_j )\}$. Then we have $y\,\Gamma^{lk_j}(w)\in  A^{\prime}\cap A_{j+2lk_j}$, and hence we obtain the following:
\begin{eqnarray}\nonumber
\tr\big(y\,\Gamma^{lk_j}(w)\big)&=& E^{j+2lk_j}_0(y\,\Gamma^{lk_j}(w)\big)\\\nonumber
&=& E^{2lk_j}_0E^{j+2lk_j}_{2lk_j+1}(y\,\Gamma^{lk_j}(w)\big)\\\nonumber
&=& E^{2lk_j}_0\big(y\,E^{j+2lk_j}_{2lk_j+1}\big(\Gamma^{lk_j}(w)\big)\big).
\end{eqnarray}
Note that $E^{j+2lk_j}_{2lk_j+1}\big(\Gamma^{lk_j}(w)\big)$ belongs to $ A^{\prime}_{2lk_j}\cap A_{2lk_j}=\bbc$. Hence, we conclude: 
\begin{eqnarray}\nonumber
\tr\big(y\,\Gamma^{lk_j}(w)\big)&=& E^{2lk_j}_0\big(y\,E^{j+2lk_j}_{2lk_j+1}\big(\Gamma^{lk_j}(w)\big)\big)\\\nonumber
&=& E^{2lk_j}_0(y) E^{j+2lk_j}_{2lk_j+1}\big(\Gamma^{lk_j}(w)\big)\\\nonumber
&=& E^{2lk_j}_0(y) E^{j+2lk_j}_{0}\big(\Gamma^{lk_j}(w)\big)\\\nonumber
&=& \tr(y) \,\tr\big(\Gamma^{lk_j}(w)\big)\\\nonumber
&=& \tr(y) \,\tr(w).
\end{eqnarray}
As the above relation holds for any $w \in A' \cap A_j$ and any $y \in \{A' \cap A_j , \,\Gamma(A' \cap A_j ), \,\cdots , \,\Gamma^{(l-1)k_j}(A' \cap A_j )\}$, it follows that $$\tr\big(y\,\Gamma^{lk_j}(w)\big)=\tr(y) \,\tr(w)$$ for any $w \in A' \cap A_j$ and $y \in \{A' \cap A_j , \,\Gamma(A' \cap A_j ), \,\cdots , \,\Gamma^{(l-1)k_j}(A' \cap A_j )\}^{\prime \prime}$. Consequently, this establishes that the second condition in \Cref{nshift} is also fulfilled here for the case $n=2$.

By applying \Cref{shift5}, it readily follows that the third condition in \Cref{nshift} is satisfied in this case for $n=2$.

 Since $r^{-}_{2j+1}$ is a $\tr$ preserving $*$-anti-automorphism of ${A'\cap A_{2j+2}}$ by \Cref{r- every property}, the third condition for the \Cref{nshift} is also satisfied once we apply \Cref{shiftnew} item (2). Therefore, $\Gamma$ is a $2$-shift on the tower $(A'\cap A_j)_j$.
 \qed
 \end{prf}

\section{Convolution product and Fourier theoretic inequalities}\label{Fourier transforms revisited}

Given an inclusion of simple $C^*$-algebras $B\subset A$ with ${[A:B]}_0<\infty$, in  \cite{BakshiVedlattice} we had defined a convolution product on $B^\prime \cap A_1$ and proved that the rotation operator $\rho_1$ is an anti-multiplicative with respect to this new product (see also [Proposition 3.9]\cite{BGS2022}). In this section we discuss the convolution product on the $n$-box spaces $B^{\prime}\cap A_n$ and $A^\prime \cap A_{n+1}$. The key ingredient  is the higher order Fourier transform. We also obtain various Fourier theoretic inequalities generalizing \cite{BakshiVedlattice}. Furthermore, we improve the constant of the Young's inequality given in \cite{BakshiVedlattice}.
	\begin{dfn}\label{convolution}(Convolution)
		The convolution product of two elements $x$ and $y$ in $B^{\prime}\cap A_n$, denoted by $x*y$, is defined as
		\begin{center}
			$x* y=\mathcal{F}_n^{-1}\big(\mathcal{F}_n(y)\mathcal{F}_n(x)\big).$
		\end{center}
	Similarly, for any two elements $w,z \in A^\prime \cap A_{n+1}$ we define
	\begin{center}
		$w*z=\mathcal{F}_n\big(\mathcal{F}_n^{-1}(z){\mathcal{F}_n}^{-1}(w)\big).$
	\end{center}
	\end{dfn}
It was already shown in \cite{BakshiVedlattice}[Lemma 3.20] that the convolution $`*$' is associative. It was also shown in \cite{BGS2022} that the rotation operator $\rho_1^+=\rho_+$ and $\rho_1^-=\rho_-$(notations given in \cite{BGS2022}) are anti-multiplicative with respect to the convolution. But the higher rotation operator $\rho_n$ for $n\geq$ are no longer anti-multiplicative. %({\color{red} Lemma 3.2 in \cite{BGS2022} was instrumental in proving that $\rho_1=\rho_{+}$ is an anti- homomorphism with respect to the convolution and is no longer true for $n>2$}). 
However, we show that reflection operators are anti-multiplicative with respect to the convolution as seen below.
	\begin{ppsn}\label{convolutionantihomo}
		For $x,y\in B^\prime\cap A_{2n+1}$, we have $r^+_{2n+1}(x\,*\,y)=r^+_{2n+1}(y)\,*\, r^+_{2n+1}(x)$. Similarly, for $w,z\in A^{\prime}\cap A_{2n+2}$ one has $\,r^-_{2n+1}(w\, *\, z)=r^-_{2n+1}(z)\,* \,r^-_{2n+1}(w)$.
	\end{ppsn}
\begin{prf}
By \Cref{convolution} and \Cref{reflectionmaplemma}, we can easily observe that,
\begin{eqnarray}\nonumber
    r^+_{2n+1}(y)\,*\, r^+_{2n+1}(x)&=& \mathcal{F}_{2n+1}^{-1}\big(\mathcal{F}_{2n+1}(r^+_{2n+1}(x))\mathcal{F}_{2n+1}(r^+_{2n+1}(y))\big)\\\nonumber
    &=& \mathcal{F}_{2n+1}^{-1}\big(r^-_{2n+1}(\mathcal{F}_{2n+1}(x))r^-_{2n+1}(\mathcal{F}_{2n+1}(y))\big).
    \end{eqnarray}
    It is known from \Cref{r- every property}, that the reflection operator $r^-_{2n+1}$ is an anti-homomorphism. Therefore, we obtain:

    \begin{eqnarray}\nonumber
    r^+_{2n+1}(y)\,*\, r^+_{2n+1}(x) &=& \mathcal{F}_{2n+1}^{-1}\big(r^-_{2n+1}(\mathcal{F}_{2n+1}(y)\mathcal{F}_{2n+1}(x))\big).
    \end{eqnarray}
Now using once again \Cref{reflectionmaplemma} and \Cref{convolution}, we get
    \begin{eqnarray}\nonumber
    r^+_{2n+1}(y)\,*\, r^+_{2n+1}(x) &=& r^+_{2n+1}\big(\mathcal{F}_{2n+1}^{-1}(\mathcal{F}_{2n+1}(y)\mathcal{F}_{2n+1}(x))\big)\\\nonumber
      &=& r^+_{2n+1}(x* y).
\end{eqnarray}
Similarly, we can show that $\,r^-_{2n+1}(w\, *\, z)=r^-_{2n+1}(z)\,* \,r^-_{2n+1}(w)$.
	\end{prf}\qed


\begin{rmrk} By \cite{BGS2022}[Proposition 3.8], we have $\,(x* y)^*=(x^*)* (y^*)$, for any $\,x,y\in B^\prime \cap A_{1}$ and similarly, $\,(w* z)^*=(w^*)* (z^*)$ for any $w, z\in A^{\prime}\cap A_{2}$.  However, the above result does not hold for all $(2n+2)$-box spaces $B'\cap A_{2n+1}$ and $A'\cap A_{2n+2}$. For instance,  if we take $n=2$ and $x=y=e_1 \in B'\cap A_5$, then by \Cref{fourier}, we can observe that
$$\mathcal{F}_5(e_1) = \tau^{-\frac{7}{2}}E^{B^{\prime}\cap A_{6}}_{A^{\prime}\cap A_{6}}(e_1v_{6})= \tau^{-\frac{3}{2}}e_{6}e_5e_4e_3.$$
Thus, by applying \Cref{convolution} and \Cref{fourier}, we obtain:
$$e_1* e_1 ={\mathcal{F}_5}^{-1}\big(\mathcal{F}_5(e_1)\mathcal{F}_5(e_1)\big)=\tau^{-1}{\mathcal{F}_5}^{-1}(e_{6}e_4e_5e_3)=\tau^{-\frac{9}{2}} E_6(e_{6}e_4e_5e_3v^*_6)=\tau^{-\frac{1}{2}} e_4e_1e_3.$$
As a result, we get, $(e^*_1)* (e^*_1)= e_1 * e_1=\tau^{-\frac{1}{2}} e_4e_1e_3 \text{  and  }
(e_1 * e_1)^*=\tau^{-\frac{1}{2}} e_3e_1e_4.$
If the mentioned result is true then we will get  $\tau^{-\frac{1}{2}} e_4e_1e_3=\tau^{-\frac{1}{2}} e_3e_1e_4$. That implies $E^{B^{\prime}\cap A_{6}}_{A^{\prime}\cap A_{6}}(e_4e_1e_3)=E^{B^{\prime}\cap A_{6}}_{A^{\prime}\cap A_{6}}(e_3e_1e_4)$, which gives $e_4e_3=e_3e_4$. This  is not possible since $e_4e_3=e_3e_4$ implies $e_3 \in \{e_4\}'$ and so, it would imply $B=A$.
\end{rmrk}
\medskip



Instead of the inclusion of simple $C^*$-algebras $B\subset A$, considering the inclusion $A \subset A_1$ we obtain similarly Fourier transformation, inverse Fourier transform and the convolution product for the corresponding relative commutants. We fix the notations $\mathcal{F}^{A\subset A_1}_{n}$ and $*_1$ for the above Fourier transformation from $A'\cap A_{n+1}$ onto $A^{\prime}_1 \cap A_{n+2}$ and the corresponding convolution product of two elements in $A' \cap A_{n+1}$ respectively. Below we establish that the Fourier transforms $\mathcal{F}^{B\subset A}_{n}$ and $\mathcal{F}^{A\subset A_1}_{n}$ are closely related.

\begin{thm}\label{shift odd}
For every $n \geq 0$, we have the following:
     $$S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w)\big)=\big(\mathcal{F}^{A\subset A_1}_{n}(w^*)\big)^*, \quad \text{ for all } w\in A'\cap A_{n+1}.$$ In other words, if we denote the conjugate map from a  $C^*$-algebra to itself by $i$, then the following diagram commutes.

    \begin{center}
    \begin{tikzcd}
{B' \cap A_{n}} \arrow[r, "\mathcal{F}_{n}" ] \arrow[dr, "S_{[\frac{n}{2}]}" ' ]
& {A'\cap A_{n+1}} \arrow[d, "i \circ \mathcal{F}^{A\subset A_1}_{n}\circ i"]\\
& {A^{\prime}_1 \cap A_{n+2}}
\end{tikzcd}
\end{center}
\end{thm}
\begin{prf}
First, consider the case when $n$ is odd, i.e., $n=2k+1$ for some $k\geq 0$. Then using \Cref{shift operator} and \Cref{fourier}, we can easily notice that 
  \begin{eqnarray}\nonumber
    S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w)\big)
    &=& S_k\big(\mathcal{F}^{-1}_{2k+1}(w)\big)\\\nonumber
    &=& \tau^{-(2k+2)}\sum_{i} \lambda_i v^*_{2k+2}\, \mathcal{F}^{-1}_{2k+1}(w) \,v_{2k+3}\lambda^*_i \\\nonumber
     &=& \tau^{-(2k+2)} \tau^{-\frac{(2k+3)}{2}}\sum_{i} \lambda_i v^*_{2k+2}\, E_{2k+2}(w\, v^*_{2k+2}) \,v_{2k+3}\lambda^*_i .
    \end{eqnarray}
Since $e_{m+1} \in A^\prime_{m-1}$, for all $m\geq 0$, thus using \Cref{pushdown} and [Equation 3.2]\cite{BakshiVedlattice}, we get
    \begin{eqnarray}\nonumber
     S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w)\big) &=&  \tau^{-(2k+2)} \tau^{-\frac{(2k+3)}{2}}\sum_{i} \lambda_i v^*_{2k+3}\, E_{2k+2}(w\, v^*_{2k+2}) \,v_{2k+2}\lambda^*_i \\\nonumber
       &=&  \tau^{-(2k+1)} \tau^{-\frac{(2k+3)}{2}}\sum_{i} \lambda_i v^*_{2k+3}\, w\, v^*_{2k+2} \,v_{2k+1}\lambda^*_i \\\label{forAsubsetA1}
       &=&  \tau^{-\frac{(2k+3)}{2}}\sum_{i} \lambda_i v^*_{2k+3}\, w\, v_{1}\lambda^*_i. 
    \end{eqnarray} 
 Now, by applying \Cref{fourier}, we can easily observe that for all $w\in A' \cap A_{2k+2}$,
 $$\mathcal{F}^{A\subset A_1}_{n}(w^*)=\mathcal{F}^{A\subset A_1}_{2k+1}(w^*)=\tau^{-\frac{(2k+3)}{2}}\,E^{A^{\prime}\cap A_{2k+3}}_{A^{\prime}_1\cap A_{2k+3}}(w^* \,e_{2k+3}e_{2k+2} \cdots e_2).$$
Since $\{ \lambda_i : i\in I\}$ is a quasi-basis for the conditional expectation $E_0$. It is easy to check that, $\{\tau^{-\frac{1}{2}}\lambda_i e_1:  i \in I \}$ is a quasi-basis for the conditional expectation $E_1$, thus we have from \Cref{f2},


 \begin{eqnarray}\nonumber
  \mathcal{F}^{A\subset A_1}_{n}(w^*)&=&\tau^{-\frac{(2k+3)}{2}}\sum_i \lambda_i e_1 w^* \,e_{2k+3}e_{2k+2} \cdots e_2 e_1 \lambda^*_i \\\nonumber
  &=& \tau^{-\frac{(2k+3)}{2}}\sum_i \lambda_i v^*_1 w^* \,v_{2k+3} \lambda^*_i.
\end{eqnarray}
This yields:
\begin{equation}\label{AsubsetA1}
    \big(\mathcal{F}^{A\subset A_1}_{n}(w^*)\big)^*=\tau^{-\frac{(2k+3)}{2}}\sum_i \lambda_i v^*_{2k+3} w \,v_{1} \lambda^*_i.
\end{equation}
Comparing \Cref{AsubsetA1} and \Cref{forAsubsetA1}, we are done for $n=2k+1$. Now assume $n=2k$ for some $k\geq 0$. Since $e_{m+1} \in A^\prime_{m-1}$, for all $m\geq 0$, then from \Cref{shift operator}, we have for all $ x\in B' \cap A_{2k}$,
   \begin{eqnarray}\nonumber
       S_{[\frac{n}{2}]}(x)&=& S_k(x)\\\nonumber
       &=& \tau^{-(2k+2)}\sum_{i} \lambda_i v^*_{2k+2}\, x \,v_{2k+3}\lambda^*_i \\\nonumber
        &=& \tau^{-(2k+2)}\sum_{i} \lambda_i v^*_{2k+1}\, x \,e_{2k+2}e_{2k+3}e_{2k+2}\cdots e_1\lambda^*_i \\\nonumber
         &=& \tau^{-(2k+1)}\sum_{i} \lambda_i v^*_{2k+1}\, x \,v_{2k+2}\lambda^*_i.
   \end{eqnarray}
Using the same line of argument as above $n=2k+1$ case, here we will get
   \begin{eqnarray}\nonumber
       S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w)\big) 
       &=& \tau^{-(2k+1)}\sum_{i} \lambda_i v^*_{2k+1}\, \mathcal{F}^{-1}_{2k}(w)\,v_{2k+2}\lambda^*_i\\\nonumber
        &=&  \tau^{-\frac{(2k+2)}{2}}\sum_{i} \lambda_i v^*_{2k+2}\, w\, v_{1}\lambda^*_i.
       \end{eqnarray}
In a similar manner as in the $n=2k+1$ case, here also we can observe that 
       \begin{equation*}
  \big(\mathcal{F}^{A\subset A_1}_{n}(w^*)\big)^*=   \big(\mathcal{F}^{A\subset A_1}_{2k}(w^*)\big)^*=\tau^{-\frac{(2k+2)}{2}}\sum_i \lambda_i v^*_{2k+2} w \,v_{1} \lambda^*_i.
\end{equation*}
Hence we are done.
    \qed
\end{prf}


 Now we are ready to obtain the higher dimensional Fourier theoretic inequalities in the sense of \cite{Liunoncommutative}. Jiang, Liu and Wu provided a non-commutative version of the Hausdorff-Young inequality, the Young’s inequality and uncertainty principles for  $\mathscr{P}_{2,\pm}$ exploiting the planar algebraic formulation of the standard invariant  in \cite{Liunoncommutative}. Subsequently in \cite{ BGS2022}, we have established those inequalities for $B^{\prime}\cap A_1$ for an inclusion of simple $C^*$-algebras $B\subset A$. Motivated by the subfactor theory we denote the vector spaces $B'\cap A_{n-1}$ and $A'\cap A_{n}$ by $\mathscr{P}_{n,+}$ and $\mathscr{P}_{n,-}$ respectively. Our goal of this subsection is to establish various Fourier theoretic inequalities for the $n$-box spaces $\mathscr{P}_{n,\pm}$, $n\geq 2$ of  $B \subset A$. This naturally generalizes some of the results in section 4 of \cite{BGS2022}. \\

	\textbf{Notation}: 
		\[{\kappa}^{+}_n(B\subset A) = \text{min}\big\{ \tr(p): p\in \mathcal{P}(B^{\prime}\cap A_n)\big\},\] 
	\[{\kappa}^{-}_n (B\subset A)= \text{min}\big\{ \tr(q): q\in \mathcal{P}(A^{\prime}\cap A_{n+1})\big\}\] and 
	\[{\kappa}_n(B\subset A) =\sqrt{{\kappa}^{+}_n(B\subset A) {\kappa}^{-}_n(B\subset A)}.\]
	If there is no danger of confusion, we often write ${\kappa}^{\pm}_n$ and $\kappa_n$ in place of ${\kappa}^{\pm}_n(B\subset A)$ and ${\kappa}_n(B\subset A)$, for brevity.

	\medskip

	We now list a few important results whose easy proofs are similar to \cite{BGS2022} and  omitted.
	\begin{ppsn}\label{constant}
		For any element $x\in B^{\prime}\cap A_n$, we have the following: $$\mathcal{F}_n(x){\mathcal{F}_n(x)}^*=\tau^{-1}\,E^{B^{\prime}\cap A_{n+1}}_{A^{\prime}\cap A_{n+1}}(xe_{n+1}x^*).$$
	\end{ppsn}

 \begin{ppsn}\label{Fn trace preserving}
     Both $\fn $ and $\fn^{-1}$ are isometries with respect to the norm given by $\|x\|_2=(\tr(x^*x))^{\frac{1}{2}}.$
 \end{ppsn}
 We now proceed to prove the Hausdorff-Young inequality for the $n$-box spaces.  The proof strategy is similar to that of \cite{BGS2022}. Recall that $\delta=\sqrt{{[A:B]}_0}$. In the subsequent theorem, we will use the Kadison–Schwarz inequality, which states that for a positive linear functional $f$ on a $C^*$-algebra $Q$, and for $x,y\in Q$, we have:
 $$|f(y^*x)|^2 \leq f(x^*x)f(y^*y).$$


	\begin{thm}[Hausdorff-Young inequality]\label{HY}
		Let $B\subset A$ be an inclusion of simple $C^*$-algebras with a conditional expectation of index-finite type.
		\begin{enumerate}[label=(\roman*)]
		\item For any $x \in B^\prime \cap A_n$, we have
			$\Vert x \rVert_q \leq \lVert \mathcal{F}_n(x)\rVert_p\leq \Big(\dfrac{\delta}{\kappa_{n-1}}\Big)^{1-\frac{2}{p}}~\lVert x\rVert_q$,
		where $2 \leq p \leq \infty$ and $\frac{1}{p}+\frac{1}{q}=1$.
		\item For any $w \in A^\prime \cap A_{n+1}$, we have
			$\Vert w \rVert_q \leq \lVert \mathcal{F}^{-1}_n(w)\rVert_p\leq \Big(\dfrac{\delta}{\kappa_{n-1}}\Big)^{1-\frac{2}{p}}~\lVert w\rVert_q$, where $2 \leq p \leq \infty$ and $\frac{1}{p}+\frac{1}{q}=1$.
\end{enumerate}	

	\end{thm}

	\begin{prf}
	\begin{enumerate}[label=(\roman*), wide=0pt, listparindent=1.25em, parsep=0pt]
	\item
	Following [Theorem 4.1] \cite{BGS2022}, it sufficient to show 
	\begin{equation}\label{maintheorem}
	\,\lVert x\rVert _1\leq {\lVert \mathcal{F}_n (x)\rVert}_{\infty} \leq \dfrac{\delta}{\kappa_{n-1}} {\lVert x\rVert}_1.
	\end{equation}
	Using the Kadison-Schwarz inequality, we obtain the estimate $||x||_1\leq ||x||_{2}$. Additionally, it holds that $||x||_2\leq ||x||_{\infty}$. Since $\mathcal{F}_n$ preserves $||.||_2$, i.e., $|| \mathcal{F}_n (x)||_{2}=||x||_2$, we conclude that $\,\lVert x\rVert _1\leq {\lVert \mathcal{F}_n (x)\rVert}_{\infty}$. We will first prove the remaining part of the inequality for a partial isometry. Then, by applying a rank-one decomposition, we will extend the result to the general case. Similar to  \cite{BGS2022}[Lemma 4.4], we can show that for a partial isometry $v \in B^\prime \cap A_n$, the following properties hold, $E_n(v^*v)\leq \dfrac{1}{{\kappa}_{n-1}^{+}} {\lVert v\rVert}_1$ and $E^{B^{\prime}\cap A_n}_{A^{\prime}\cap A_n}(vv^*)\leq \dfrac{1}{{\kappa}_{n-1}^{-}}{\lVert v\rVert}_1$. Thus, we derive $v e_{n+1} v ^* \leq \dfrac{{\lVert v \rVert}_1}{{\kappa}_{n-1}^{+}} ~v v^*$. Furthermore, as a consequence of \Cref{constant} and the results established above, we obtain the following:
		$$\mathcal{F}_n (v){\mathcal{F}_n (v)}^*=\delta^2 \,E^{B^{\prime}\cap A_{n+1}}_{A^{\prime}\cap A_{n+1}}(ve_{n+1}v^*)\leq\dfrac{{\lVert v \rVert}_1}{{\kappa}_{n-1}^{+}}\delta^2 \,E^{B^{\prime}\cap A_{n+1}}_{A^{\prime}\cap A_{n+1}}(vv^*)\leq \dfrac{{\delta}^2{\lVert v \rVert}^2_1}{\kappa^2_{n-1}}.$$
		Applying $||.||_{\infty}$ to both sides leads us to the desired inequality.
		\item
		Using the Kadison–Schwarz inequality and proceeding as in (1), we obtain the following $\Vert w \rVert_1 \leq \lVert \mathcal{F}^{-1}_n(w)\rVert_\infty $. Now, we will show that ${\lVert \mathcal{F}^{-1}_n (w)\rVert}_{\infty} \leq \dfrac{\delta}{\kappa_{n-1}} {\lVert w\rVert}_1.$ It is enough to show the inequality for a partial isometry. Now, by \Cref{maintheorem}, we have for a partial isometry $v\in A' \cap A_{n+1}$,
     $$\lVert \mathcal{F}^{A\subset A_1}_n(v^*)\rVert_\infty\leq \dfrac{\delta} {{{\kappa}}_{n-1}(A \subset A_1)} {\lVert v^*\rVert}_1.$$
 Here 
  ${{\kappa}}_{n-1}(A \subset A_1)=\sqrt{{{\kappa}}^{+}_{n-1}(A \subset A_1){{\kappa}}^{-}_{n-1}(A \subset A_1)}$. By definition ${{\kappa}}^{+}_{n-1}(A \subset A_1)={\kappa}^{-}_{n-1}$. Also by \Cref{shift operator}, we know that $A^{\prime}_1\cap A_{n+1}$ is isomorphic to $B' \cap A_{n-1}$. Hence ${{\kappa}}^{-}_{n-1}(A \subset A_1)={\kappa}^{+}_{n-1}$. So we get ${{\kappa}}_{n-1}(A \subset A_1)={\kappa}_{n-1}$ and 
  $$\lVert \mathcal{F}^{A\subset A_1}_n(v^*)\rVert_\infty\leq \dfrac{\delta} {{\kappa}_{n-1}} {\lVert v^*\rVert}_1.$$
Since $v$ is a partial isometry, one can observe that, $${\lVert v^*\rVert}_1= \tr(|v^*|)=\tr((vv^*)^{\frac{1}{2}})=\tr(vv^*)=\tr(v^*v)=\tr((v^*v)^{\frac{1}{2}})=\tr(|v|)={\lVert v\rVert}_1 .$$
As a consequence of \Cref{shift odd}, we have 
  $$S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w)\big)=\big(\mathcal{F}^{A\subset A_1}_{n}(w^*)\big)^*, \quad \text{ for all } w\in A'\cap A_{n+1}.$$
This leads to:
   $$\lVert \mathcal{F}^{A\subset A_1}_n(v^*)\rVert_\infty=\lVert \big(\mathcal{F}^{A\subset A_1}_n(v^*)\big)^*\rVert_\infty=\lVert S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(v)\big)\rVert_\infty=\lVert \mathcal{F}^{-1}_{n}(v)\rVert_\infty.$$
Putting everything together, we get:
   $${\lVert \mathcal{F}^{-1}_n (v)\rVert}_{\infty} \leq \dfrac{\delta}{\kappa_{n-1}} {\lVert v\rVert}_1.$$
Thus, by applying rank-one decomposition of any $w\in A' \cap A_{n+1}$, we get
   \begin{equation}\label{-nbox imp}
       \,\lVert w\rVert _1\leq {\lVert \mathcal{F}^{-1}_n (w)\rVert}_{\infty} \leq \dfrac{\delta}{\kappa_{n-1}} {\lVert w\rVert}_1.
   \end{equation}
Since both $\mathcal{F}^{-1}_n$ and $\mathcal{F}_n$ are isometries with respect to the norm given by $\|x\|_2=(\tr(x^*x))^{\frac{1}{2}}$, then using the same kind of interpolation as in proof of \cite{BGS2022}[Theorem 4.1], we are done.\qed


		\end{enumerate}

	\end{prf}

\begin{rmrk}
 This is an appropriate place to mention that, by applying \Cref{HY}, the quintuple $(\mathscr{P}_{n,+}$, $\mathscr{P}_{n,-},\tr_n, \tr_n, d^+_n\mathcal{F}_n)$ forms a von Neumann $\big(d^+_n\big)^2$-bi-algebra (see \cite{HLJ}), while the quintuple $(\mathscr{P}_{n,-}$, $\mathscr{P}_{n,+},\tr_n, \tr_n, d^-_n \mathcal{F}^{-1}_n)$ forms a von Neumann $\big(d^-_n\big)^2$-bi-algebra, where $d^+_n= \sup\{||\mathcal{F}_n(x)||_{\infty}: x\in \mathscr{P}_{n,+}, ||x||_1=1$\} and $d^-_n= \sup\{||\mathcal{F}^{-1}_n(w)||_{\infty}: w\in \mathscr{P}_{n,-}, ||w||_1=1$\}.
	\end{rmrk}
	As a consequence of \Cref{HY}, we have the Donoho-Stark uncertainty principle and the Hirschman-Beckner uncertainty principle for the $n$-box spaces as follows (proof is similar to \cite{BGS2022,Liunoncommutative}). 
	\begin{thm}[Donoho-Stark uncertainty principle]\label{DS}
		Consider an inclusion of simple $C^*$-algebras $B\subset A$ with a conditional expectation of index-finite type. 
		\begin{enumerate}[label=(\roman*)]
		\item 
		For any non zero $x \in B^\prime \cap A_n$, we have $
		\mathcal{S}(x)\mathcal{S}(\fn(x))\geq \dfrac{\kappa^2_{n-1}
		}{{[A:B]}_0}\,.$
		\item For any non zero $w \in A^\prime \cap A_{n+1}$, we have $
		\mathcal{S}(w)\mathcal{S}(\fn^{-1}(w))\geq \dfrac{\kappa^2_{n-1}
		}{{[A:B]}_0}\,.$
		\end{enumerate}
	\end{thm}
	\begin{thm}[Hirschman-Beckner uncertainty principle]\label{HBuncertainty}
		Let $B\subset A$ be an inclusion of simple $C^*$-algebras with a conditional expectation of index-finite type. 
		\begin{enumerate}[label=(\roman*)]
		\item
		For any $x \in B^\prime \cap A_n$,
		$\frac{1}{2}\big(H(|\fn(x)|^2)+H(|x|^2)\big)\geq -\|x\|_2^2\,\Big(\log\bigg(\dfrac{\delta}{\kappa_{n-1}}\bigg) +\log \|x\|_2^2\Big)\,.$
		\item For any $w \in A^\prime \cap A_{n+1}$,
		$\frac{1}{2}\big(H(|\fn^{-1}(w)|^2)+H(|w|^2)\big)\geq -\|w\|_2^2\,\Big(\log\bigg(\dfrac{\delta}{\kappa_{n-1}}\bigg) +\log \|w\|_2^2\Big)\,.$

		\end{enumerate}
	\end{thm}


 As a further application, we  improve the constant of the Young's inequality for $\mathscr{P}_{2,+}$ as proved in \cite{BGS2022}. We also prove the Young's inequality  for  $\mathscr{P}_{2,-}$. First we need a Lemma. 
\begin{lmma}\label{new convolution}
    For $w,z \in A' \cap A_{n+1}$, we have,
    $ w*_1 z = (z^* * w^*)^*.$
\end{lmma}
\begin{prf}
Using \Cref{convolution}, we can easily observe that
   \begin{eqnarray}\label{new convolution 1}
    w*_1 z=   \big(\mathcal{F}^{A\subset A_1}_{n}\big)^{-1}\big( \mathcal{F}^{A\subset A_1}_{n}(z)\mathcal{F}^{A\subset A_1}_{n}(w)\big)
   \end{eqnarray} 
By applying \Cref{shift odd}, we get the following: 
   $$\mathcal{F}^{A\subset A_1}_{2k}(w)=\big(S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w^*)\big)\big)^*=S_{[\frac{n}{2}]}\big(\big(\mathcal{F}^{-1}_{n}(w^*)\big)^*\big), \quad \text{ for all } w\in A'\cap A_{2k+1}.$$
The last equality follows since $S_{[\frac{n}{2}]}$ is $*$-preseving. Also since $S_{[\frac{n}{2}]}$ is a homomorphism we get
   \begin{eqnarray}\nonumber
      \mathcal{F}^{A\subset A_1}_{n}(z)\mathcal{F}^{A\subset A_1}_{n}(w)&=& S_{[\frac{n}{2}]}\big(\big(\mathcal{F}^{-1}_{n}(z^*)\big)^*\big)S_{[\frac{n}{2}]}\big(\big(\mathcal{F}^{-1}_{n}(w^*)\big)^*\big)\\\nonumber
      &=&S_{[\frac{n}{2}]}\big(\big(\mathcal{F}^{-1}_{n}(z^*)\big)^*\big(\mathcal{F}^{-1}_{n}(w^*)\big)^*\big)\\\label{new convolution 2}
      &=&\big(S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w^*)\mathcal{F}^{-1}_{n}(z^*)\big)\big)^*.
      \end{eqnarray}
       Using \Cref{shift odd}, we have for $y \in A^{\prime}_1 \cap A_{n+2}$, 
     $$\big(\mathcal{F}^{A\subset A_1}_{n}\big)^{-1}(y)=i\circ \mathcal{F}_{n} \circ S_{[\frac{n}{2}]}^{-1} \circ i (y).$$
Therefore, by applying \Cref{new convolution 1} and \Cref{new convolution 2}, we ultimately obtain:
\begin{eqnarray}\nonumber
    w*_1 z&=&i\circ \mathcal{F}_{n} \circ S_{[\frac{n}{2}]}^{-1} \circ i \big(\mathcal{F}^{A\subset A_1}_{n}(z)\mathcal{F}^{A\subset A_1}_{n}(w)\big)\\\nonumber
    &=&i\circ \mathcal{F}_{n} \circ S_{[\frac{n}{2}]}^{-1} \circ i \big(\big(S_{[\frac{n}{2}]}\big(\mathcal{F}^{-1}_{n}(w^*)\mathcal{F}^{-1}_{n}(z^*)\big)\big)^*\big)\\\nonumber
     &=&i\circ \mathcal{F}_{n} \big(\mathcal{F}^{-1}_{n}(w^*)\mathcal{F}^{-1}_{n}(z^*)\big)\\\nonumber
     &=& (z^* * w^*)^*.
\end{eqnarray}
\qed
\end{prf}


We now prove Young's inequality for $\mathscr{P}_{2,-}$ and also improve the constant appearing in the Young's inequality  for $\mathscr{P}_{2,+}$ as in \cite{BGS2022}.
\begin{thm}[Young's inequality]\label{Young}
     Suppose $B\subset A $ is an inclusion of simple $C^*$-algebras with a conditional expectation of index-finite type. 
     \begin{enumerate}[label=(\roman*)]
     \item For any $x,y \in B' \cap A_1$, we have
     $\,\lVert x * y\rVert _r \leq\dfrac{\delta}{\kappa^{+}_{0}}\lVert x \rVert _p \lVert  y\rVert _q$,
     where $1\leq p,q,r\leq \infty$ and $\frac{1}{p}+\frac{1}{q}= \frac{1}{r}+1$.
     \item For any $w,z \in A' \cap A_2$, we have
     $\,\lVert w * z\rVert _r \leq\dfrac{\delta}{\kappa^{-}_{0}}\lVert w \rVert _p \lVert  z\rVert _q$,
     where $1\leq p,q,r\leq \infty$ and $\frac{1}{p}+\frac{1}{q}= \frac{1}{r}+1$.
     \end{enumerate}
 \end{thm}
 \begin{prf}
 \begin{enumerate}[label=(\roman*), wide=0pt, listparindent=1.25em, parsep=0pt]
\item This follows from \cite{BGS2022}[Theorem 4.12] and \Cref{pnormequality}.
\item 
 From \Cref{new convolution} and \cite{BGS2022}[Proposition 3.8], it follows that for all $w,z \in A' \cap A_2$, we have:
     $$z*_1w=(w^* * z^*)^*= w * z.$$
     It is known that ${{\kappa}}^{+}_{0}(A \subset A_1)={\kappa}^{-}_{0}$. Hence, by \cite{BGS2022}[Lemma 4.21] and \Cref{pnormequality}, we obtain, for all $1\leq p \leq \infty$, the following:
$${\lVert w*z\rVert}_{p} ={\lVert z*_1w\rVert}_{p}\leq \dfrac{\delta}{\kappa^-_{0}} {\lVert z\rVert}_{p}{\lVert w\rVert}_1 \quad \text{ and }\quad{\lVert z*w\rVert}_{p} ={\lVert w*_1z\rVert}_{p}\leq \dfrac{\delta}{\kappa^-_{0}} {\lVert z\rVert}_{p}{\lVert w\rVert}_1 .$$
Now, using \cite{BGS2022}[Lemma 4.22], \Cref{convolutionantihomo}  and \Cref{pnormequality}, we will get for $1\leq p \leq q$ and $\frac{1}{p}+\frac{1}{q}=1$, 
$${\lVert w*z\rVert}_{\infty} \leq \dfrac{\delta}{\kappa^-_{0}} {\lVert w\rVert}_{p}{\lVert z\rVert}_q .$$
Finally doing the same kind of interpolation as in the Proof of \cite{BGS2022}[Theorem 4.12], we are done.
\qed
     \end{enumerate}
 \end{prf}

 We end this section with the following question.
 \smallskip

 \noindent\textbf{Question:} What is the Young's inequality for the higher $n$-box spaces $\mathscr{P}_{n,\pm}$?

 \section{Connes-St{\o}rmer entropy of the Canonical shift}\label{final section}


In this short section, we will establish a relationship between Watatani index and the Connes-St{\o}rmer entropy of the canonical shift canonically associated with a unital inclusion $B \subset A $ of simple $C^*$-algebras of finite depth \cite{JOPT}. Recall, a unital inclusion $B \subset A $ of $C^*$-algebras is said to be of finite depth if there exist a $n_0 \in \bbn$ such that $(B' \cap A_n) e_{n+1} (B'\cap A_{n})= B'\cap A_{n+1}$ for all $n\geq n_0$. The smallest such $n$ is called the depth of the inclusion. In this case it is worth noting that $\sup_n \dim Z(A' \cap A_{2n})< \infty$ and there exist a $k_0 \in \bbn$ such that $(A' \cap A_{n}) e_{n+1} (A'\cap A_{n})= A'\cap A_{n+1}$ for all $n\geq 2k_0$. Since $E_{n+1}$ is the trace preserving conditional expectation from $A'\cap A_{n+1}$ onto $A'\cap A_{n}$, then doing same as in the proof of \cite{GHJ}[Theorem 4.6.3] we get that if $G$ denotes the inclusion matrix for $A' \cap A_{2k_{0}} \subset A' \cap A_{2k_{0}+1} $ then $G$ is connected and the inclusion matrix for $A' \cap A_{2k_{0}+1} \subset A' \cap A_{2k_{0}+2}$ is $G^t$. Thereby the inclusion matrix $GG^t$ for the inclusion $A' \cap A_{2k_{0}} \subset A' \cap A_{2k_{0}+2}$ is primitive by \cite{GHJ}[Lemma 1.3.2]. Furthermore if $s^{2k_{0}}$ denotes the trace vector for the $\tr$ on $A' \cap A_{2k_0}$, then $GG^t s^{2k_0}=[A:B]_0 s^{2k_0}$. Moreover it is also easy to observe that the $GG^t$ is the inclusion matrix for the inclusions $A' \cap A_{2k} \subset A' \cap A_{2k+2}$ for all $k\geq k_0$. Recall that, as defined in \Cref{Canonical shift}, $P$ denotes the von Neumann algebra generated by $\bigcup_{n\geq 1} A'\cap A_n$. Our main objective in this subsection is to establish the following result:

\begin{thm}\label{entropy 2}
Let  $B \subset A $ be a unital inclusion simple $C^*$-algebras with a conditional expectation of finite Watatani index and of finite depth. Then 
$$\frac{1}{2}H_{\tr}(P| \Gamma(P))= H_{\tr}(\Gamma)= \log[A:B]_0 .$$
\end{thm}

In proving \Cref{entropy 2}, we will need the following results.



\begin{thm}[\cite{Choda}]\label{nshiftthm}
 If $Q$, $\{Q_j:j\in \bbn\}$, $\sigma$and $\tr$ are as in \Cref{nshift} furthermore if $\sigma$ satisfies conditions (1) and (2) in \Cref{nshift}, then $H_{\tr}(\sigma)= \lim_{k\rightarrow \infty} \frac{H_{\tr}(Q_{nk})}{k}$.
 \end{thm}
As established earlier in \Cref{ppsn for 2 shift}, the map $\Gamma$ satisfies the conditions (1) and (2) of \Cref{nshift}. A straightforward consequence of \Cref{nshiftthm} is the following useful fact. \begin{ppsn}\label{2shift}
The canonical shift $\Gamma$ for the inclusion $B\subset A$ has the property that $H_{\tr}(\Gamma)={\lim}_{n\rightarrow \infty} \frac{H_{\tr}(A' \cap A_{2n})}{n}$.
\end{ppsn}

At this point, we recall the following result (considered as folklore) will play a crucial role in proving \Cref{entropy 2}.


\begin{ppsn}[\cite{NS}, Proposition 10.4.9]\label{imp lma for entropy}
Let $Q={\lim}_{\rightarrow} Q_k$ be an AF algebra for which the inclusion matrices for the inclusions $Q_k \subset Q_{k+1}$ for every $k$ are given by a fixed primitive matrix $\Lambda$. Then there exists a unique tracial state on $Q$ and
$$\lim_{n\rightarrow \infty}\frac{1}{n}H_{\tr}(Q_n)=\log\beta,$$
where $\beta$ is the Perron-Frobenious eigen value of $\Lambda$.
\end{ppsn}


\noindent\textbf{Proof of \Cref{entropy 2}: } As already discussed at the beginning of this section, for a finite-depth inclusion $B\subset A$ of simple unital $C^*$-algebras with a conditional expectation of finite Watatani index, there exists $k_0 \in \bbn$ such that the inclusion matrices for the inclusions $A' \cap A_{2k} \subset A' \cap A_{2k+2}$ for all $k\geq k_0$ are same, more precisely the inclusion matrix is $GG^t$, where $G$ is the inclusion matrix for $A' \cap A_{2k_{0}} \subset A' \cap A_{2k_{0}+1} $. Furthermore if $s^{2k_{0}}$ denotes the trace vector for the $\tr$ on $A' \cap A_{2k_0}$, then $GG^t s^{2k_0}=[A:B]_0 s^{2k_0}$. Observe that $s^{2k_{0}}$ is a Perron-Frobenius eigen vector of $GG^t$ with Perron-Frobenius eigen value $[A:B]_0$. Then, by applying \Cref{imp lma for entropy} to $Q_n=A'\cap A_{2n}$, and subsequently using \Cref{2shift}, we obtain $$ H_{\tr}(\Gamma)=\lim_{n\rightarrow \infty}\frac{1}{n}H_{\tr}(A' \cap A_{2n})=\log[A:B]_0.$$
Using \Cref{shiftnew} item(1) and \Cref{2shift}, we observe that $\{A' \cap A_{2n}\}_n$ is a generating sequence (see  \Cref{generatingdfn}) for the canonical shift $\Gamma$. Furthermore, by applying \Cref{shift5}, we see that it satisfies the commuting square condition. 
Thanks to \Cref{Stormerthm}, $\lim_{n\rightarrow \infty}\frac{1}{n}H_{\tr}(Z(A' \cap A_{2n}))$ exists in this setting, and we obtain the following equation.
\begin{equation}\nonumber
H_{\tr}(\Gamma)=\frac{1}{2}H_{\tr}(P| \Gamma(P))+ \lim_{n\rightarrow \infty}\frac{1}{2n}H_{\tr}(Z(A' \cap A_{2n})).
\end{equation}
For finite depth inclusion $B \subset A $ we obviously have $\lim_{n\rightarrow \infty}\frac{1}{2n}H_{\tr}(Z(A' \cap A_{2n}))=0.$ Accordingly, the preceding analysis lead us to conclude the following:

 $$\frac{1}{2}H_{\tr}(P| \Gamma(P))= H_{\tr}(\Gamma)= \log[A:B]_0 .$$
This completes the proof.
\qed
