% Section 3.2 Grammar
\subsection{Grammar}
We provide two complementary flavors of T-CPDL because real‐world data comes in wildly different forms of temporal detail. In some domains—say, when mining natural‐language texts or noisy sensor streams—you often know only that “event A happened before event B” or “these two processes overlap,” but you have no reliable clock‐time to pin them to. The Allen‐relational variant lets you capture and reason about those interval‐orderings directly, yielding crisp causal inferences purely from ordering constraints. In contrast, when you do have precise timestamps—e.g. log files, clinical records, financial trades—you can use the timestamped variant to anchor every causal link to a concrete instant (and still refine it with Allen relations if you like). Offering both ensures that T-CPDL can gracefully degrade to the level of temporal information you actually possess, while preserving the same core causal machinery.

\subsubsection{Allen-Relational only T-CPDL ($T\text{-CPDL}_A$)}
A lightweight variant where causal edges carry no global timestamp; instead, cause and effect intervals are related purely via Allen constraints.

\begin{equation}
\begin{aligned}
T\text{-Concept } C &::= E \\
                   &\mid C \sqcap D \\
                   &\mid C[Y]@X \\
                   &\mid \exists (X)\,\Phi .\,C
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
E\text{-Concept } E &::= A \\
                   &\mid \top \\
                   &\mid \bot \\
                   &\mid \neg E \\
                   &\mid E \sqcap F \\
                   &\mid E \sqcup F \\
                   &\mid \exists R.E \\
                   &\mid \forall R.E \\
                   &\mid \ge n\,R.E \\
                   &\mid \le n\,R.E
\end{aligned}
\end{equation}

Allen relations are drawn from:
\begin{equation}
\{b,\,m,\,o,\,s,\,d,\,f,\,=,\,bi,\,mi,\,oi,\,si,\,di,\,fi\}.
\end{equation}

Temporal constraint networks are formed by:
\begin{equation}
\begin{aligned}
\Phi &::= X\,(\mathrm{Rel})\,Y \\
      &\mid \Phi\,\wedge\,\Phi \\
      &\mid \Phi\,\vee\,\Phi
\end{aligned}
\end{equation}

Causal statements in $T\text{-CPDL}_A$ take the form:
\begin{equation}
\begin{aligned}
\varphi(C,D)[P=p]
&\\
\exists(X,Y)\,\Phi .\,\varphi(C@X,D@Y)[P=p]
\end{aligned}
\end{equation}

In the first form, ``$\varphi(C,D)[P=p]$'' asserts a causal link without any temporal qualifier.  In the second form, fresh intervals $X$ (cause) and $Y$ (effect) are constrained by an Allen network $\Phi$, yielding ``$\varphi(C@X,D@Y)[P=p]$."  

\subsubsection{Timestamped T-CPDL ($T\text{-CPDL}_T$)}
The full variant retains explicit timestamps on causal edges, while still allowing auxiliary Allen constraints.

Causal statements in $T\text{-CPDL}_T$:
\begin{equation}
\begin{aligned}
\varphi(C,D)@\tau[P=p\mid X]
&\\
\exists(X,Y)\,\Phi .\,\varphi(C@X,D@Y)@\tau[P=p\mid Z]
\end{aligned}
\end{equation}

Here, ``$\varphi(C,D)@\tau[P=p|X]$'' is the original timestamped form (optionally conditioned on context $X$). The second form binds helper intervals $X,Y$, applies constraints $\Phi$, and attaches both $@\tau$ and probability tag.

% Section 3.3 Running Examples
\subsection{Running Examples}\label{sec:running-example}
We illustrate both variants on the same healthcare scenario.

\subsubsection{Allen-Relational Example ($T\text{-CPDL}_A$)}

\paragraph{TBox causal rules (no global $@\tau$):}
\begin{equation}
\begin{aligned}
&\exists(X,Y)\,(X\,b\,Y) .\,\varphi(\mathsf{Smoking}@X,\,\mathsf{Hypertension}@Y)[P=0.5]\\
&\exists(U,V)\,(U\,b\,V) .\,\varphi(\mathsf{Hypertension}@U,\,\mathsf{Stroke}@V)[P=0.67]
\end{aligned}
\end{equation}

\paragraph{ABox evidence (grounded events):}
\begin{equation}
\mathsf{Smoking}\;b\;\mathsf{Hypertension}
\end{equation}
meaning that Smoking occurs before Hypertension.

\paragraph{Chaining:}
Since
\begin{equation}
\varphi(\mathsf{Smoking},\,\mathsf{Hypertension})[0.5]
\quad\text{and}\quad
\varphi(\mathsf{Hypertension},\,\mathsf{Stroke})[0.67],
\end{equation}
we derive (via weighted likelihood)
\begin{equation}
\varphi(\mathsf{Smoking},\,\mathsf{Stroke})[\approx0.335].
\end{equation}

\paragraph{Relational projection:}
\begin{equation}
\exists(X,Z)\,(X\,b\,Z) .\,\varphi(\mathsf{Smoking}@X,\,\mathsf{Stroke}@Z)[P\approx0.335]
\end{equation}
placing inferred stroke interval $Z$ strictly after smoking interval $X$.

\subsubsection{Timestamped Example ($T\text{-CPDL}_T$)}

Aircraft Maintenance Incident example:

\paragraph{Maintenance Ontology}
\begin{equation*}
\begin{aligned}
&\varphi(\mathsf{Wear},\mathsf{Crack})@\tau_{1}\;[P=0.6],\\
&\varphi(\mathsf{Crack},\mathsf{Incident})\;[P=0.8],\\
&\exists(U,V)\,(U\,b\,V)\;.\;\mathsf{Inspection}@U\;\sqsubseteq\;\neg\mathsf{Incident}@V.
\end{aligned}
\end{equation*}

\paragraph{Observed Evidence}
\[
\mathsf{Wear}@2025\text{--}01\text{--}10,\quad
\text{No inspection recorded.}
\]

\paragraph{Reasoning Steps}
\begin{enumerate}
  \item \textbf{Causal chaining.} 
    \[
      P(\mathsf{Incident}\mid \mathsf{Wear})
      =0.6\times0.8=0.48
      \quad(\text{48\% risk}).
    \]
  \item \textbf{Temporal projection.} 
    The plausible incident interval $V$ must satisfy 
    \(\tau_{1}\,bi\,V\) (i.e.\ occur after $\tau_{1}$).
  \item \textbf{Preventive rule check.} 
    No interval $U$ with $\mathsf{Inspection}@U$ and $U\,b\,V$ exists,
    so the subsumption axiom cannot block the incident.
\end{enumerate}

\noindent
The maintenance module therefore issues a 48\% incident‐risk alert and recommends scheduling
an inspection interval $U$ that \emph{meets} ($m$) or \emph{before} ($b$) $V$, which would satisfy
the preventive axiom and drive $P(\mathsf{Incident})$ toward 0.

%------------------------------------------------------
% 4  Semantics and Fundamental Theorems of T-CPDL
%------------------------------------------------------
\section{Fundamental Theorems}
\label{sec:theorems}

%-----------------------------
\subsection{Finite-Model Property}
\begin{theorem}[Finite Model]\label{thm:fmp}
If a T\texttt{--}CPDL knowledge base $\mathcal{K}$ is satisfiable, then it has
a model whose domain size is $2^{O(|\mathcal{K}|)}$
and whose temporal structure contains only the
intervals explicitly mentioned in $\mathcal{K}$ plus at most
$O(|\mathcal{K}|)$ fresh points.
\end{theorem}

\begin{proof}
Take the tableau for the ALCQI fragment of $\mathcal{K}$
and apply standard loop blocking to obtain a finite
completion tree (cf.\ \citeauthor{artale1994}~\citeyear{artale1994}).
For every existential temporal binder
$\exists(X)\Phi.\,C$ create at most
$|\Phi|$ fresh interval variables satisfying $\Phi$; path-consistency of
Allen networks guarantees that a finite assignment exists.
Because causal rules are global TBox statements,
their transitive closure adds at most
$|\mathcal{K}|$ additional edges and no new individuals.
Probability values are copied verbatim from $\mathcal{K}$;
there are finitely many such numbers, so the resulting structure is finite.
\end{proof}

%-----------------------------
\subsection{Complexity}
\begin{theorem}[EXPTIME Completeness]\label{thm:exptime}
KB consistency, concept satisfiability, and instance checking in
T\texttt{--}CPDL are EXPTIME-complete.
\end{theorem}

\begin{proof}
Hardness inherits from ALCQI.
For membership: the tableau expands at most exponentially many
individual nodes (ALCQI bound).  For each node,
temporal propagation invokes cubic path-consistency,
and causal propagation adds at most
$|\mathcal{T}|$ deterministic edges with constant-time probability
multiplication (Theorem~\ref{thm:prob-comp} below).
Thus the overall procedure is bounded by $2^{p(|\mathcal{K}|)}$
for some polynomial~$p$.
\end{proof}

%-----------------------------
\subsection{Tableau Soundness and Completeness}
\begin{theorem}[Soundness \& Completeness]\label{thm:sound-complete}
The extended tableau calculus
(temporal rules + causal transitivity + probability update)
is sound and complete for the semantics in~\S\ref{sec:theorems}.
\end{theorem}

\begin{proof}
\emph{Soundness}: every rule is locally truth-preserving.
E.g.\ the causal-transitivity rule adds $\varphi(C,E)$ only if
$\varphi(C,D)$ and $\varphi(D,E)$ already hold; by definition of $\varphi$
the new edge is entailed in every model that satisfied the premises.

\emph{Completeness}: run the tableau with fair rule
application.  If expansion halts without clash,
each branch induces a Hintikka structure that
satisfies all syntactic conditions.
By Theorem~\ref{thm:fmp} this structure can be
turned into a finite model of $\mathcal{K}$.
Conversely, any model yields a clash-free branch.
\end{proof}

%-----------------------------
\subsection{Probabilistic Composition}
\begin{theorem}[Probability of Composed Cause]\label{thm:prob-comp}
Let $\varphi(C,D)[P=p_{12}]$ and $\varphi(D,E)[P=p_{23}]$
be the only causal paths from $C$ to $E$.
Then T--CPDL must annotate the derived edge
$\varphi(C,E)$ with $p_{13}=p_{12}\!\cdot\!p_{23}$.
\end{theorem}

\begin{proof}
By definition
$P(E\!\mid\!C)=\sum_{d} P(E\!\mid\!d)\,P(d\!\mid\!C)$.
Since $D$ is the sole mediator, the sum has one term:
$P(E\!\mid\!C)=p_{23}\cdot p_{12}$.
Assigning any other weight to $\varphi(C,E)$ would violate
Bayes coherence or probabilistic soundness.
\end{proof}

%-----------------------------
\subsection{Temporal Acyclicity}
\begin{theorem}[Temporal–Causal Consistency]\label{thm:acyclic}
If every causal rule is stamped so that its cause interval is
\textbf{b}efore or \textbf{m}eets its effect interval,
the transitive closure of $\varphi$ is acyclic.
\end{theorem}

\begin{proof}
Assume a cycle
$X_1<X_2<\\dots<X_n<X_1$ in the timeline.
Linear order $<$ is irreflexive, so $X_1<X_1$ is impossible.
Hence no such cycle exists; transitive closure is a DAG.
\end{proof}

\vspace{1ex}
Together, Theorems~\ref{thm:fmp}–\ref{thm:acyclic} provide the theoretical
guarantees required for deploying T--CPDL as a sound, complete,
and decidable reasoning substrate under real-world LLM pipelines.

