\section{Preliminaries \& Problem Definitions}
% \input{sections/prelim-prob-def.tex}
In this section, we first provide formal definitions relevant to our proposed methods. We then proceed to formulate the problem of multimodal information retrieval for unconstrained data for property-specific information needs, and the problem of object-property identification from text.

% https://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&arnumber=6313232
\begin{definition}[Attributed relational graph]
\label{defn:arg}
An attributed relational graph (ARG) is a graph whose nodes and edges have assigned attributes (single value or vectors of values). 
% For the sake of simplicity, we denote the node and edge attributes by labels. %, as labels are specific types of attributes. 
Although we focus our methodology only on directed and labeled graphs, it is designed to handle any form of graphs. 
An ARG is defined as:
$g = (N, E, l)$
where
\begin{enumerate}
    \item $N$ is the finite set of nodes, 
    \item $E \subseteq N \times N$ is the set of edges,
    \item  $l : N(g) \cup E(g) \rightarrow \Sigma$ is a labeling function that assigns labels to each vertex and edge from $\Sigma$. 
    % Specifically, $l(u)$ and $l(u, u')$ are the label of node $u$ and the label of edge $(u, u')$, respectively,
    \item $\Sigma$ is a % finite or infinite 
    set of unconstrained labels. $A \in \Sigma$ represents labels enumerating the node-type.
\end{enumerate}

\end{definition}
%
%
\cbd{
\begin{definition} [Graph Edit Distance]
\label{defn:ged}
Formally, the edit distance between $g_1$ and $g_2$, denoted by
GED ($g_1, g_2$), is the number of edit operations in the optimal alignments that transform $g_1$ into $g_2$, where an edit operation on a graph $g$ is an insertion or deletion of a node/edge or relabelling of a node/edge. Intuitively, if two graphs are identical (isomorphic), their GED is 0. 
\end{definition}
%
\begin{definition}[Parts-of-Speech]
\label{defn:pos}
Parts-of-Speech (POS) is a category to which a word or phrase is assigned in accordance with its syntactic functions. 
A syntactic function is the grammatical relationship \footnote{https://glossary.sil.org/term/grammatical-relation} (i.e., subject, object) of one constituent to another within a syntactic construction.
\end{definition}
}
%
\begin{definition}[Wu-Palmer Distance]%[Wordnet Synsets]
\label{defn:wordnets}
Wordnet \cite{wordnet98} is a lexical knowledge base where words are organized in a hypernym tree based on their origin. 
% Words are grouped into Synsets based on their synonyms.
Wu-Palmer distance calculates the similarity between word meanings based on the similarity between the word senses and the location of the synsets relative to each other in the hypernym tree. 
Given the synsets of two strings $s_{t_1}$ and $s_{t_2}$, and the LCS (Least Common Subsumer) between them, the Wu-Palmer distance is:
\begin{equation}
    wpdist(s_{t_1}, s_{t_2}) = 2 * \frac{depth(lcs(s_{t_1}, s_{t_2}))}{depth(s_{t_1}) + depth(s_{t_2})}
\end{equation}
\end{definition}
%
\begin{definition}[Natural Language Inference]
\label{defn:nli}
Given a hypothesis $h$ and a premise $p$, 
natural language inference (NLI) is the task of determining the probability $Pr$ of the hypothesis being true (entailment $E$), false (contradiction $C$), or undetermined (neutral $N$). NLI determines the best label $l$: 
\begin{equation} \arg\max_{l \in \{E, C, N\}} Pr(l ~|~ h, p) \end{equation}
% the task of determining whether a "hypothesis" is true (entailment), false (contradiction), or undetermined (neutral) given a "premise".
\end{definition}

