% \paragraph{Observations} 
We make the following observations for property-specific multimodal queries:
%
%
\begin{enumerate}[label=\textbf{O\thesection.\arabic*}, topsep=0pt, leftmargin=*, series=obsmmir]%, leftmargin=2 pt, [series=theoremconditions]
\item The number of object properties between two data samples is finite, and the values of the properties are mostly categorical values. 
\item A data sample can describe a large number of objects and object properties, but for system-specific similarity comparison, a user is only interested in a finite number of properties.
\item Data samples are special objects with different properties such as metadata, topics, and events. 
% \textit{Entities} are specific types of objects described in a data sample with their own properties.
\item \label{itm:mmir-relationship} \textit{Relationships between objects} are specific types of object properties that belong to all participating objects. The set of values corresponding to the objects would be complementary to each other.
Value for relation-name can be different for the same relationship through different data samples. For example, different text would describe the same action in different forms: \textit{wearing, wear, has}. 
%
\item \label{itm:mmir-single-multi-value-zp} Some properties in $z_p$ have single and fixed value-set i.e., \textattrname{gender, race, height}, while other properties have multiple values in their value-set i.e., \textattrname{clothes}.
%
\item \label{itm:mmir-different-valued-zp}
% The multi-value 
Some object properties such as, \textattrname{clothes-color} have different values for different data samples. For example, in Figure~\ref{fig:qg-and-cg}, \textattrvalue{UPPER-WEAR-COLOR,  SHIRT-COLOR, COLOR} all refer to the color of clothes. 
\end{enumerate}

Our intuition here is that entities, relationships, and object properties in a data sample have an inter-connected structure, and if we can capture the number of changes to convert one structure to another, then we can capture the differences between these samples. 
Based on this intuition, \system\ starts by constructing a \textit{hierarchical attributed relational graph}, called (\harg), with a common hierarchy for all data samples. The choice of graph as a representation was influenced by the need for 
% \begin{enumerate*}
%     \item graph being the best data structure to capture information from connected structures,
%     \item based on observations~\ref{itm:mmir-relationship} and \ref{itm:mmir-different-valued-zp}, 
    a data structure with representation-invariant encoding mechanisms that can capture the syntactic similarities between different values.
    % was necessary.
% \end{enumerate*}

\begin{definition}[Hierarchical Attributed Relational Graph] % (\harg)
\label{defn:harg}
\harg~ is a specific type of ARG in the form of a multi-level tree with $|h|$ levels. It consists of a root node, multiple levels of nodes and edges emanating from it, and specific type of leaf nodes. Nodes at level $h$ are denoted by $N^h$.
\end{definition}

%
\newcommand{\non}{N} %normalNodes
\paragraph{\textbf{CONSTRUCT-\harg}}
Each data sample is represented as \harg, following the steps:
\begin{enumerate}[leftmargin=*, topsep=0pt] % 
    \item The graph starts with a single node at level 0 $(h = 0)$ containing a common label across all data samples in the same application domain: $l(\non^0)=\{ROOT\}$. % \alt{term} (\textsc{content/ object/ root})
    \item Level 1 nodes constitute the object-properties of the data sample itself where the property name is the edge label, and the property value is the node label: 
    \[l(\non^0, \non^1) = \smallOP_p, l(\non^1) = z_{p}.\]
    With the exception of $o_p$ being an entity,  $\non^1$ would be a leaf node. For entities, we define the edge label as $l(\non^0, \non^1) = \{hasEntity\}$.
    %
    \item In case a set of $\smallOP_p$ describes the attributes of an entity, $\non^k (k \geq 1)$ will be a pointer to 
    % another object
    the attribute properties of that entity, whereas $l(\non^k)$ = \{\emph{entity-type}\}. 
    %
    \item We categorize entities in two groups for each data sample: \textit{primary}, and \textit{secondary}. 
    %
    Level 1 of \harg~ only contains primary entities. 
    % (Definition~\ref{defn:primary-entity}).
    %
    \item Level 2 and subsequent levels contain the attribute values of the entities in the previous level with 
    \[l(\non^k, \non^{k+1}) = \smallOP_p (k \geq 1),  and\] \[l(\non^k) = z_p (k \geq 2).\]
    From Definition~\ref{defn:reln}, for \textattrname{relation} properties,  %$\smallOP_p = 
    $\langle R, S, Arg \rangle$ where entity-pointer $S$ is at level-$k$ and entity-pointer $Arg$ is at level-$(k+1)$, 
    \[l(\non^k, \non^{k+1})=R, l(\non^k)= {S}, l(\non^{k+1})={Arg}.\]
    %
    \item There can be edges between entities in the same level with 
    % property-name as the edge label. 
    \textattrname{relation} properties, $R$.
    With nodes $\non^k$ and $\non^r$,\\ $l(\non^k, \non^r) = R$, where $l(\non^k) \neq l(\non^r)$ but $k=r$.
    \item The leaf nodes of \harg~ always contain a property-value or a NULL value for $z_p = \{\phi\}$.
\end{enumerate}
%

