%                 }       \label{algo:line:multi-name:end}
%                 \lElse{\result.\APPEND ($[N, D]$)}   
%                         \label{algo:line:insert-to-results}
%                 %
%                 %
%                 % \tcc*{re-initialize Lists of name-index and values}
%                 $\nid \longleftarrow \emptyset$,   
%                 $\desc \gets \emptyset$ \tcp*[h]{re-initialize Lists} \;    
%             }
%             \lElse{
%                 \Break
%             }
%         }
%     }
%     \KwRet{\result}\;
% %
% \caption{\posalgo}
% \label{algo:cloths-name-value}
% \end{algorithm}

\begin{algorithm}[!htb] %\footnotesize
\begin{algorithmic}[1]
\Require{Collection of Sentences, $T_s$}
\Ensure{Collection of $\langle name, values \rangle$ pairs, $\langle\langle \smallOP_p, z_p \rangle\rangle$}, \result
%
\State \finiteValuedProp $\gets \{ \textattrname{gender, race, height}\}$ \;
\State \colour $\gets$ \syn{``color'', \Noun}[0]\;
\State $C_s \gets$ \cands {$T_s~, Q_H$} \;  \label{algo:line:cand-start}
\If{$C_s$ is $\phi$}
    \State $C_s \gets$ \candsModel {$T_s~, Q_H$}   \label{algo:line:cand-end}
\EndIf
\State \result $\longleftarrow \emptyset$
\mysamelinecomment{Collection of $\langle o_p, z_p \rangle \equiv \langle name, values \rangle$ pairs}
\ForEach{$s$ in $C_s$}                      \label{algo:line:posid-8}
    \ForEach{$o$ in \finiteValuedProp}      \label{algo:line:regex-for-value-start}
        % \tcc*[r]{\tempzp is last token in $s$ which is a property-value}
        \State \tempzp = \reForFiniteValuedProp{$s, \smallOP_p$} 
        \State \result.\APPEND  ($\smallOP_p$, \tempzp) \; \label{algo:line:regex-for-value-end}
    \EndFor
    \State $s_p$ = \reForFiniteValuedProp {$s$, \textattrname{Clothes}} \; \label{algo:line:regex-for-clothes}
    \If{$s_p$ is $\phi$}
            $s_p \gets s \setminus$ \tempzp \label{algo:line:no-wearing-for-clothes}
        \EndIf           
        %%%%%%%%%%
        \State \nid $\longleftarrow \emptyset$\   \mysamelinecomment{Index-List for property-name}
        \State \desc $\gets \emptyset$            \mysamelinecomment{List for property-values}
        % \tcc{set of tokens}
        \State \tokens $\leftarrow$ \TOK{$s_p$}    \mysamelinecomment{List of tokens from $s_p$}   % \TOK{$s$}
        % \tcc{set of POS tags}
        \State \tags $\leftarrow$ \POS{\tokens}  \mysamelinecomment{List of $\langle  \text{token, POS-tag} \rangle$ from tokens}
        %
        % \BlankLine
        \mynewlinecomment{\word\ and $\postag_i$ is token and POS-tag at $i^{th}$ index in \tags}
        %
        \For{($w$, \postag) in \tags}
            \If{$\postag_1$ is \emph{VBD}}           \label{algo:line:first_verbs:start}
                \Continue
            \EndIf
            \If{$\postag_2$ is \emph{VBG} and $\postag_1$ is \emph{VBD}}
                \Continue                   \label{algo:line:first_verbs:end}
            \EndIf
            \If{$\postag_{i} \in$ \SetOne $~\cup~$ \SetTwo}   \label{algo:line:property-name-decribe-start} 
                \If{$\postag_{i} ~\in$ \SetTwo\ and $\postag_{i-1} \in$ \SetThree}
                    \State \Break  \label{algo:line:wearing-not-found} 
                \EndIf
                \State \nid.\APPEND (i)\;           \label{algo:line:property-name-decribe-end}
            \ElsIf{$\postag_{i}$ is \adj}           \label{algo:line:adj:start}
                \State \nid $\longleftarrow \emptyset$   \mysamelinecomment{re-initialize name index-list}
                    \State \desc.\APPEND (\word) \;   \label{algo:line:adj:end}
            \ElsIf{$\postag_{i}$ is \Noun}      \label{algo:line:noun:start}
                \State \wm $\gets$ \syn{\word, \Noun}                                 \label{algo:line:noun-color:start} \;
                %
                \State \nid, \desc, \descColor = \newline \null \hfill \fndmtch{\wm, \nid, \desc} \;
                % \lIf{match found with \colour}{\Continue} 
                \If{\descColor}
                    \Continue  \label{algo:line:noun-color:end} 
                \EndIf
                %
                \State \names $\gets$ \word \;      \label{algo:line:multi-name:start}
                %
                \State $\names \gets$ \popopn{\nid, \names, \tags}                               \label{algo:line:multi-name:middle} 
                %
                % \BlankLine
                \mynewlinecomment{finalize property-name \& assign the values}
                \If{$\postag_{i-1}$ is \Noun\ and \newline \null \hfill
                \result[-1].name == $\wordWithoutIdx_{i-1}$} 
                    \State \CONCAT(\result[-1].name, \word, " ")      \label{algo:line:multi-name:end}
                \Else
                    \State \result.\APPEND ($[N, D]$)           \label{algo:line:insert-to-results}
                \EndIf
                %
                %
                % \tcc*{re-initialize Lists of name-index and values}
                \State \nid $\longleftarrow \emptyset$,   
                        \desc $\gets \emptyset$ \mysamelinecomment{re-initialize Lists} \;    
            \Else
                \State \Break
            \EndIf
        \EndFor
\EndFor
% \Return \result \;
\end{algorithmic}
\caption{\posalgo}
\label{algo:cloths-name-value}
\end{algorithm}

%
%
%%%%%%%%%%%%%%%%

%
Algorithm \ref{algo:cloths-name-value} presents the pseudocode of the search technique \posalgo, which takes the sentences in a 
document $T_s$ as input and returns the \textit{collection} of object-properties and their set of values, $\langle\langle o_p, z_p \rangle\rangle$ as output. 
%
In case of an implicit mention of clothes, we made an assumption that description of \textattrname{clothes} are always followed by descriptions of \textattrname{gender, race}, and/or \textattrname{height}. \\
% Algorithm \ref{algo:functions-in-posid} describes the function definitions in \posalgo.\\
%
\noindent \textbf{Lines \ref{algo:line:cand-start} - \ref{algo:line:cand-end}} Extract the candidate sentences with the \textsc{RE-search}. If results are empty, extract them with semantic or classification models. 
Set of key-phrases $Q_H$ is provided by the system.
% Each system defines its own key-phrases $Q_H$.
\\
%
\textbf{Lines \ref{algo:line:regex-for-value-start} - \ref{algo:line:regex-for-value-end}}  
Iteratively search for all the finite-valued properties \{\textattrname{gender, race, height}\} in each $C_s$ and append them to output.\\
\texttt{\repropvalues}~ is a regular expression matching function that takes sentence $s$ and property-name $o_p$ as input, and outputs 
\begin{enumerate*}
    \item property-value $z_p$, if $o_p$ is a finite-valued property, or 
    \item partial sentence $s_p$, if $o_p$ is a variable-valued property.
\end{enumerate*}
Each $o_p$ is mapped to a search-string pattern, $s_R$ in $T$.\\
% In Section~ \ref{subsec:attr-extrac-experiment}, we define the object-property and search-string mapping, $T$ for \texttt{\repropvalues}.\\
%
\textbf{Lines \ref{algo:line:regex-for-clothes} - \ref{algo:line:no-wearing-for-clothes}} For \textattrname{clothes}, \texttt{\repropvalues}~ returns 
either a partial sentence $s_p$ starting with \texttt{wearing}, or an empty string. In case of an empty string, keep the remaining string from $L_z$ after discarding the extracted values from lines \ref{algo:line:regex-for-value-start} - \ref{algo:line:regex-for-value-end}.\\
% after the last value from 
% fixed-valued properties. \\
%
\textbf{Lines \ref{algo:line:first_verbs:start} - \ref{algo:line:first_verbs:end}} If first and second token is verb\cbd{in past or present tense in third person singular, or in gerund form}, it is the start for the \textattrname{Relation} property. Following \ref{obs:first_verbs}, ignore consecutive verbs until another tag is encountered. \\
% between the person and the clothes. \\
%
\textbf{Lines~ \ref{algo:line:property-name-decribe-start} - \ref{algo:line:property-name-decribe-end}} 
% Since property names for variable-valued properties like clothes, can span from first mention of VERB to \{DET, CONJ, PREP, PTCP, ADV\} until PRONOUN or no-tag is encountered, capture them as property-name.\\
Following \ref{obs:property-name-decribe}, capture tokens from a VERB until any pronoun or non-tag as a free-form property value for \textattrname{clothes}.\\
%
%
% When candidate sentences do not have the usual pattern for Clothes (Line \ref{algo:line:no-wearing-for-clothes}), 
% cloth names (such as shirt, jeans, etc.) are identified by ignoring pronouns and non-tagged tokens.
%
\textbf{Lines \ref{algo:line:adj:start} - \ref{algo:line:adj:end}} 
% Since adjectives are used for characterizing a property or used with a noun phrase to modify it, adjective phrases in candidate sentences are considered as clothes descriptions.
Capture the adjectives as clothes descriptions, and initialize the next property.
% When an adjective is encountered, the previous property-name has been completed, so re-initialize the name-index list.
\\
%
\textbf{Lines~\ref{algo:line:noun-color:start}-\ref{algo:line:noun-color:end}} For noun descriptors in the value i.e., grey {\bf{dress}} pants, compare the wordnet-synset meaning for \texttt{color} 
% as noun 
($COLOR_{syn}$) to the noun-token meaning. 
% If the distance between the synset-meaning of a token $w$ and $COLOR_{meaning}$ is greater than the desired threshold, consider $w$ to be a color and add as property-value. % is already described in func.
Since a description is encountered, name-index is re-initialized for the next property-name. \\
% After a color description, ignore looking for other descriptions and advance to the next token. This captures multi-token values i.e., \textit{red and green shirt}. \\
%
\textbf{Lines~\ref{algo:line:multi-name:start}-\ref{algo:line:multi-name:middle}}
If a noun-phrase is not a color, it is considered as cloth-name with multiple tokens i.e., \textit{dress pants, tank top, dark clothing}. Populate the property-name by backtracking the name-index list.\\
% if token in $P_{PAV}$
%
\textbf{Line~\ref{algo:line:insert-to-results}} 
% Perform an additional check for the noun-tokens as property-name to mitigate errors propagated from the part-of-speech tagger. 
If the previous token is NOUN and does not match the last token of the previous property-name, we consider the end of the current property description. Finalize the current property name and value by appending it to the result.
Otherwise, in line~\ref{algo:line:multi-name:end}, amend the last inserted property-name by appending the current token to it.
%
%
\paragraph{Generalization}
Algorithm~\ref{algo:cloths-name-value} assumes that the property identifier is intended for human-properties. \posalgo~ can be generalized to any object-properties in the text as long as the property names and type of values are known.
The search string for fixed-valued properties has to be re-designed.
Variable-valued properties following some degree of grammatical structure would be covered by the iterative search pattern in \posalgo. \textsc{Color} will be replaced by the phrase that describes the properties in the corresponding system.
% We tried different query phrases such as entity types, entity names or types of clothes.
$Q_H$'s are highly non-restrictive phrases and can be constructed from entity types or entity names. 

