\usepackage{tikz, ytableau}
\usepackage[backend=bibtex,natbib=true,style=alphabetic,maxnames=99]{biblatex}
\addbibresource{refs.bib}

\title{Maximal transitivity of the cactus group on standard Young tableaux}
\author{Sophia Liao and Leonid Rybnikov}

\newcommand{\syt}{\text{SYT}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\LL}{\mathcal{L}}

\newtheorem{thm}{Theorem}[section]
\newtheorem{prop}{Proposition}[section]
\newtheorem{cor}{Corollary}[section]
\newtheorem{conj}{Conjecture}[section]
\newtheorem{lemma}{Lemma}[section]
