\section{Cactus group and its action on standard Young tableaux}\label{se:prelim}

\subsection{Sch\"utzenberger involutions} 
The \emph{Schützenberger involution} \( \xi \) is an involution on the set $\syt(\lambda)$ of all standard Young tableaux of the shape $\lambda$. 

The algorithm makes use of \emph{jeu de taquin} slides and is as follows  (see, e.g. \cite{LY} for the details):

\begin{enumerate}
    \item Remove the box in the first row and first column of the tableau. Record the value \( m \) of this box.
    \item Perform a \emph{jeu de taquin} slide to fill the empty position.
    \item Place a new box in the last position to be emptied in the slide, labeled \( -m \).
    \item Repeat the process until all of the original boxes of \( T \) have been removed. 
\end{enumerate}

After all boxes of the original tableau have been removed in this way, the result is a tableau of the same shape, but with all negative entries. Adding a constant equal to the number of boxes in \( T \) plus one to each entry will yield the standard tableau \( \xi(T) \).

\subsection{Cactus group action on $\syt(\lambda)$} From the defining relations of $C_n$, it is seen that the involutions $s_{[1i]}$ for $i=2,\ldots,n$ generate $C_n$. The following is well-known (see, e.g. \cite{LY}):

\begin{prop}\label{pr:Schutzenberger}\begin{enumerate}
    \item For any $\lambda\vdash n$, there is an action of $C_n$ on $\syt(\lambda)$ taking $s_{[1i]}$ to the Sch\"utzenberger involution of the subtableau formed by the boxes that contain the numbers from $1$ to $i$.
    \item Under the above $C_n$-action on $\syt(\lambda)$, the involution $s_{[ij]}$ changes only the (skew) subtableau formed by the boxes containing the numbers from $i$ to $j$.
\end{enumerate}
\end{prop}

\subsection{Bender--Knuth Involutions}
For any $i=1,\ldots,n-1$, the \emph{Bender-Knuth involution} $t_i$ on $\syt(\lambda)$ interchanges the occurrences of $i$ and $i+1$ the resulting table is a valid standard Young tableau (and does nothing otherwise).

There is an explicit correspondence between Sch\"utzenberger involutions and Bender–Knuth involutions, given by the identity
$$s_{[1,i]}=t_1(t_2t_1)(t_3t_2t_1)\cdots (t_i\cdots t_1).$$ This relation is described in ~\cite{Berenstein_Kirillov_1996,Chmutov_Glick_Pylyavskyy_2020}, and it can be checked that the Bender--Knuth involutions generate the image of $C_n$ in the permutation group of $\syt(\lambda)$. 

\subsection{Notation}

A partition $\lambda$ of $n$ is written as $(a_1,a_2,\cdots,a_k)$ where $a_1\geq a_2\geq \cdots \geq a_k$ and $a_1+a_2+\cdots+a_k=n$. We denote by $r_i(\lambda)$ the number of boxes in row $i$ and by $c_j(\lambda)$ the number of boxes in column $j$ of the Young diagram of $\lambda$. Let $\mathcal{I}:=\{(i,j)\mid i\in [1,c_1(\lambda)], j\in [1,r_i(\lambda)]\}$ be the set of indices of $\lambda$. We view an element $A$ of $\syt(\lambda)$ as a bijection $A:\mathcal{I}\rightarrow[1,n]$ where for all $(i_1,j_1)\neq(i_2,j_2)\in \mathcal{I}$ with $i_1\leq i_2$ and $j_1\leq j_2$, we have $A(i_1,j_1)<A(i_2,j_2)$.

We call a box $(i,j)$ of $\lambda$ a \emph{corner} if there exists a standard Young tableau $A$ of this shape such that $A^{-1}(n)=(i,j)$. We additionally call $(i,j)$ an \emph{extended corner} if there exists a standard Young tableau $A$ of shape $\lambda$ such that $A^{-1}(n)=(i,j)$ and either $A^{-1}(n-1)=(i-1,j)$ or $A^{-1}(n-1)=(i,j-1)$. If $(a,b)$ is a corner of $\lambda$, we denote $\lambda\setminus (a,b)$ as $\lambda$ with the box at $(a,b)$ removed, a partition of $n-1$. We also define $A\setminus n$ to be the standard Young tableau of $\lambda\setminus A^{-1}(n)$ such that $(A\setminus n)^{-1}(k)=A^{-1}(k)$ for all $k\in[1,n-1]$.

Finally, we denote by $\lambda^T$ the transpose partition of $\lambda$, and $A^T\in\syt(\lambda^T)$ the transpose tableau of $A$.

\subsection{Single tableaux are transitive}
\begin{thm} \label{1-trans}
    Let $\lambda$ be a partition of $n$. Then, $\syt(\lambda)$ is transitive under $C_n$.
\end{thm}

\begin{proof}
    Let $A\in\syt(\lambda)$. It suffices to show there exists some $g\in C_n$ such that $g(A)=T$, where $T$ is the fixed tableau with $T(i,j)=j+r_1(\lambda)+r_2(\lambda)+\cdots +r_{i-1}(\lambda)$. Suppose $(i,j)$ be the first coordinate (ordered lexicographically) where $A(i,j)\neq T(i,j)$. Then we can always find some $h\in C_n$ such that the first coordinate that $h(A)$ and $T$ do not agree on is greater than $(i,j)$ (or $h(A)=T$). Observe that $A(i,j)>T(i,j)$ and so $t_{T(i,j)}\cdots t_{A(i,j)-2}t_{A(i,j)-1}(A)$ agrees with $T$ at the coordinate $(i,j)$, but leaves all previous coordinates untouched, so either $h(A)=T$ or the first coordinate they do not agree on must be greater than $(i,j)$).
\end{proof}

Pairs of standard Young tableaux are transitive for all shapes except hook-shaped and self-transpose partitions. In these cases, they are transitive with the exception of a few obvious invariants, which we describe in the next section.

\section{Hook-shaped tableaux and self-transpose tableaux}\label{se:hook-and-symmetric}
\subsection{Hook-shaped tableaux}

\begin{defn*}
     A partition $\lambda$ is \emph{hook-shaped} if it does not include a box at (2,2).
\end{defn*}

\begin{example} \label{ex: H, AH}
    The partition on the left is hook-shaped, whereas the partition on the right is not since it contains the box at $(2,2)$.
    \begin{center}
    $$\begin{ytableau}
        \color{white}0 &  &  & & \\
         \\
        \\
        \color{white}0
    \end{ytableau}\quad\quad\quad \quad \begin{ytableau}
        \color{white}0 &  &  & & \\
         & \\
        \\
        \color{white}0
    \end{ytableau}$$
    \end{center}
\end{example}
\vspace{0.25cm}

Throughout this section, assume $\lambda_1$ and $\lambda_2$ are hook-shaped partitions with $A\in\syt(\lambda_1)$ and $B\in\syt(\lambda_2)$.

\begin{defn*}
    We denote by $S_{A,B}=\{k \mid A^{-1}(k)=(1,a), B^{-1}(k)=(1,b) \text{ for some }a,b\}$ the set of shared values in the first rows of $A$ and $B$.
\end{defn*}

\begin{lemma} \label{invariant}
    The value $|S_{A,B}|$ is invariant under $C_n$.
\end{lemma}

\begin{proof}
    It suffices to show that $I:=|S_{A,B}|$ is invariant under any $t_k$. If $A$ and $B$ are both fixed under $t_k$, clearly $I$ is fixed. If neither $A$ nor $B$ are fixed under $t_k$, then it must be the case that $k$ and $k+1$ are swapped between the first row and the first column: If either $k$ or $k+1$ are shared in the first row, then which of $k$ or $k+1$ is shared is simply swapped in $t_k(A)$ and $t_k(B)$; if neither $k$ nor $k+1$ are shared in the first row, then $t_k$ preserves that neither are shared. If $A$ is fixed under $t_k$ and $B$ is not, then either $k$ and $k+1$ are both in the first row of $A$ or both in the first column of $A$. In the former case, $t_k$ maintains that one of $k$ or $k+1$ is shared in the first row, and in the latter case, $t_k$ maintains that neither are shared in the first row. The proof is symmetric for if $B$ is fixed and $A$ is not.
\end{proof}

\begin{lemma} \label{inc shared in hook}
    The value $m(A,B):=\max(S_{A,B})$ exists and is not equal to $n$ if and only if there exists some $g\in C_n$ such that $m(g(A),g(B))>m(A,B)$.
\end{lemma}
\begin{proof}
The reverse direction follows directly. Now, let $k=m(A,B)$. Clearly, $k+1$ is not in the first row of both $A$ and $B$. If $k+1$ is not in the first row of either, then $m(t_k(A),t_k(B))=k+1$, since $k+1$ is swapped to the first row of both. Otherwise, if $k+1$ is in the first row of either $A$ or $B$ but not the other, then $t_k$ leaves fixed the standard Young tableau with $k$ and $k+1$ in the first row and swaps $k+1$ to the first row of the other, and hence, $m(t_k(A),t_k(B))=k+1$.
\end{proof}
We are now in a position to describe the orbits of pairs standard Young tableaux of hook-shaped partitions under $C_n$.

\begin{prop} \label{2-trans hook}
    There are $\min(r_1(\lambda_1), c_1(\lambda_1), r_1(\lambda_2), c_1(\lambda_2))$ orbits of $C_n$ on the set of pairs $\syt(\lambda_1) \times \syt(\lambda_2)$.
\end{prop}

\begin{proof}
We proceed by induction. Suppose without loss of generality that $r_1(\lambda_1)\leq c_1(\lambda_1),$ $ r_1(\lambda_2),c_1(\lambda_2)$. Let $I_{r}$ denote the number of shared values in the first row of $A$ and the first row of $B$, and let $I_{c}$ denote the number of shared values in the first row of $A$ and the first column of $B$. Observe that $I_r$ and $I_c$ are both invariants by Lemma~\ref{invariant} with $I_r+I_c=r_1(\lambda_1)$. Also, there exist pairs of standard Young tableaux for which $I_r$ and $I_c$ attain values from 1 to $r_1(\lambda_1)$. It suffices to show that $I_r$ is a complete invariant (i.e., given a fixed value of $I_r$, any two pairs of standard Young tableaux in $\syt(\lambda_1) \times \syt(\lambda_2)$ with this value are in the same orbit).

Without loss of generality, we assume $I_r>1$ (otherwise, we do a symmetric proof on the row of $A$ and the column of $B$, as $I_c>1$). If $r_1(\lambda_1)=1$, then observe that $A$ is fixed under any action of $C_n$, and so by Theorem~\ref{1-trans}, there is indeed 1 orbit. Now, suppose $r_1(\lambda_1)>1$. By Lemma~\ref{inc shared in hook}, there exists $g\in C_n$ such that $(g(A))^{-1}(n)=(1,r_1(\lambda_1))$ and $(g(B))^{-1}(n)=(1,r_1(\lambda_2))$. Observe that the number of values shared in the first row of $A\setminus n$ and the first row of $B\setminus n$ is $I_r-1$, and since this is a complete invariant for the shapes $\lambda_1\setminus (1,r_1(\lambda_1))$ and $\lambda_2\setminus (1,r_1(\lambda_2))$, we have that $I_r$ is also a complete invariant.
\end{proof}

When $\lambda_1=\lambda_2$, we can deduce the sizes of the orbits purely combinatorially, since the orbits are defined by the number of shared entries in the first rows of both standard Young tableaux:

\medskip

\begin{cor}
     Hook-shaped tableaux are not 2-transitive, but the number of entries shared in the first row of the two tableaux is a complete invariant. Let $\lambda$ be a hook-shaped partition of $n$. Then the lengths of the orbits of pairs of elements of $\syt(\lambda)$ under the group $C_n$ are $N\cdot {k-1\choose 0}{l-1\choose 0},N\cdot{k-1\choose 1}{l-1\choose 1},\ldots,N\cdot{k-1\choose k-1}{l-1\choose l-k}$, where $k:=\min(r_1(\lambda),c_1(\lambda))$, $l:=\max(r_1(\lambda),c_1(\lambda))$, and $N:=|\syt(\lambda)|$.
\end{cor} 

\subsection{Self-transpose tableaux}
\begin{defn*}
    A partition $\lambda$ is \emph{self-transpose} if it is fixed under transposition (in other words, $\lambda=\lambda^T$).
\end{defn*}

\begin{prop} \label{prop: self-transpose invariant}
    Let $\lambda$ be a self-transpose partition of $n$. The set of pairs $\syt(\lambda)\times \syt(\lambda)$ has at least 3 orbits under $C_n$.
\end{prop}

\begin{proof}
    This follows from the fact that a transposed pair of tableaux stays transposed under $C_n$ (i.e., there are two trivial orbits).
\end{proof}

In the next section, we will prove that there are exactly 3 orbits; that is, we will see that transposition is the only invariant.

\section{2-transitivity}\label{se:2-trans}
The strategy to prove in general that pairs of standard Young tableaux are transitive is by induction on the number of boxes in the diagram, as removing the box containing $n$ yields a tableau on $n-1$ boxes. Since our proof does not depend on the two diagrams being the same shape we actually prove the stronger statement: given a fixed $n$, any pair of not necessarily the same partitions of $n$ is transitive under $C_n$ (excluding hook-shaped and self-transpose invariants).

First, let us be precise about which pairs of tableaux are transitive. If both partitions are hook-shaped, there is no chance that the pair of tableaux will be transitive.
\begin{defn*}
    Let $\lambda_1,\lambda_2$ be partitions of $n$. We say that the pair of partitions $(\lambda_1,\lambda_2)$ is \emph{viable} if at most one partition $\lambda_1$ or $\lambda_2$ is hook-shaped.
\end{defn*}

On the other hand, if both partitions are the same or transposed to each other, the pair of tableaux will still be transitive as long as the standard Young tableaux are not exactly the same or transposed.

\begin{defn*}
    Let $A\in\syt(\lambda_1)$ and $B\in\syt(\lambda_2)$. We say that the pair of tableaux $(A,B)$ is \emph{viable} if $(\lambda_1,\lambda_2)$ is viable and $A\neq B$ and $A^T\neq B$.
\end{defn*}

Since pairs of hook-shaped tableaux are not transitive, our base case should be those pairs where it is possible to remove a box from both and end up with hook-shaped partitions. As such, we have the following base case, where an almost hook-shaped partition is a hook-shaped partition plus the box at $(2,2)$ (for example, the partition on the right in Example~\ref{ex: H, AH}).

\begin{defn*}
   We say that the pair $(\lambda_1,\lambda_2)$ is \emph{base case} if it is viable and either $\lambda_1$ and $\lambda_2$ are both almost hook-shaped or one of $\lambda_1$ and $\lambda_2$ is almost hook-shaped and the other is hook-shaped.
\end{defn*}

\subsection{Proof outline} Given two pairs of tableaux $(A,B)$ and $(C,D)$ (where $A$ and $C$ are of the same partition and $B$ and $D$ are of the same partition), if we can find a group element which takes $n$ to the same box in $A$ and $C$ and the same box in $B$ and $D$, in theory we can use our inductive hypothesis to find a path between these two pairs. More rigorously, we'd like to find some $g\in C_n$ such that $(g(A))^{-1}(n)=C^{-1}(n)$ and $(g(B))^{-1}(n)=D^{-1}(n)$. Our strategy for doing this is as follows: If the partition has more than 3 corners, we can find a box in which neither tableaux, say $A$ or $C$, contains $n$. Then, we can use induction to move $n-1$ to this third box in both $A$ and $C$, and consequently, applying $t_{n-1}$ to $A$ and $C$ moves $n$ into the desired box. By simultaneously performing this maneuver on $B$ and $D$, we can find a way to move $n$ into the same box in the second partition as well. (If there are fewer corners, we can do a similar trick.)

However, there's a catch. In order to use our inductive hypothesis, we also need to ensure that when the boxes containing $n$ in $(g(A),g(B))$ and $(C,D)$ are removed (as well as $(t_{n-1}g(A),t_{n-1}g(B))$ and $(t_{n-1}(C),t_{n-1}(D))$), the $(n-1)$-box partitions fall into our inductive case. Even when the two partitions are the same shape, this may not always be true.

\begin{example}
    This pair of tableaux is viable, but if we remove the boxes containing 9, the tableaux are transposed to each other and are no longer fully transitive.
    \begin{center}
    $$\begin{ytableau}
        1 & 2 & 3 & 9\\
        4 & 5 & 6\\
        7 & 8
    \end{ytableau}\quad\quad\quad \quad \begin{ytableau}
        1 & 4 & 7 & 9\\
        2 & 5 & 8\\
        3 & 6
    \end{ytableau}$$
    \end{center}
\end{example}

To ensure that we never run into this problem, we need \Cref{pre-move 2-trans}.

\subsection{Proof of 2-transitivity}

\begin{lemma} \label{pre-move 2-trans}
    Let $(\lambda_1,\lambda_2)$ be a viable pair of partitions of $n$ which is not base case, and let $A\in\syt(\lambda_1)$ and $B \in\syt(\lambda_2)$. If $(A,B)$ is viable, then there exists $g\in C_n$ such that $(g(A)\setminus n,g(B)\setminus n)$ is also viable.
\end{lemma}

\begin{proof}
\textbf{Case 1:} $\lambda_1=\lambda_2$ or $\lambda_1^T=\lambda_2$. If $A\setminus n=B\setminus n$, then clearly $A=B$, and if $(A\setminus n)^T= B\setminus n$, then clearly $A^T=B$, so we have that $A\setminus n\neq B\setminus n$ and $(A\setminus n)^T\neq B\setminus n$, and we are done.

\textbf{Case 2:} $\lambda_1\neq\lambda_2$ and $\lambda_1\neq\lambda_2^T$. Observe that either $\lambda_1$ or $\lambda_2$ must have at least 2 corners---without loss of generality, suppose it is $\lambda_1$. By Theorem~\ref{1-trans}, there exists some $h\in C_n$ such that $(h(A))^{-1}(n-1)$ is a corner. Let $\lambda_1^*$ be the shape $\lambda_1$ with the box at $(h(A))^{-1}(n)$ removed, and let $\lambda_2^*$ be the shape $\lambda_2$ with the box at $(h(B))^{-1}(n)$ removed. If $\lambda_1^*\neq\lambda_2^*$ and $(\lambda_1^*)^T\neq\lambda_2^*$, then we are done, as clearly $h(A)\setminus n\neq h(B)\setminus n$ and $(h(A)\setminus n)^T\neq h(B)\setminus n$. If $\lambda_1^*=\lambda_2^*$ and $(\lambda_1^*)^T=\lambda_2^*$, then observe that $\lambda_1$ with the box $(t_{n-1}h(A))^{-1}(n)$ taken away cannot be the same or transposed shape as $\lambda_2$ with the box $(t_{n-1}h(B))^{-1}(n)$ taken away, so we are done. If $\lambda_1^*=\lambda_2^*$ and $(\lambda_1^*)^T\neq\lambda_2^*$, and if $h(A)\setminus n\neq h(B)\setminus n$, we are done since $(h(A)\setminus n)^T\neq h(B)\setminus n$. However, if $h(A)\setminus n = h(B)\setminus n$, then observe that $(t_{n-1}h(A)\setminus n)^T\neq t_{n-1}h(B)\setminus n$ and $t_{n-1}h(A)\setminus n\neq t_{n-1}h(B)\setminus n$ because $\lambda_1$ with the box $(t_{n-1}h(A))^{-1}(n)$ taken away is not the same shape as $\lambda_2$ with the box $(t_{n-1}h(B))^{-1}(n)$ taken away, so we are also done.
\end{proof}

\begin{thm} \label{2-trans}
    Let $(\lambda_1,\lambda_2)$ be a viable pair of partitions of $n$. The set of pairs $\{(A,B)\in \syt(\lambda_1)\times \syt(\lambda_2)\mid (A,B) \text{ is viable}\}$ is transitive under $C_n$.
\end{thm}

\begin{proof}
\textbf{Base case:} Our base case is pairs of partitions $(\lambda_1,\lambda_2)$ as specified above. To show the base case, we also use induction on the number of boxes. Let's assume that $\lambda_1$ is almost hook-shaped and $\lambda_2$ is either almost hook-shaped or hook-shaped. If we have $\lambda_1=\lambda_2=(2,2)$, or we have $\lambda_1=(3,2)$ and $\lambda_2=(3,2)$, $\lambda_2=(3,1,1)$, $\lambda_2=(2,1,1,1)$, or $\lambda_2=(1,1,1,1,1)$, or we have $\lambda_1=(3,2,1)$ and $\lambda_2=(4,2)$, $\lambda_2=(4,1,1)$, $\lambda_2=(3,2,1)$, $\lambda_2=(3,1,1,1)$, $\lambda_2=(2,2,1,1)$, $\lambda_2=(2,1,1,1,1)$, or $\lambda_2=(1,1,1,1,1,1)$, we can manually verify that the theorem holds.

Otherwise, observe that $\max(r_1(\lambda_1),c_1(\lambda_1))>3$, and suppose that the theorem holds for base case pairs with $n-1$ boxes. Let $A\in\syt(\lambda_1)$ and $B\in\syt(\lambda_2)$, and without loss of generality, suppose $r_1(\lambda_1)\geq c_1(\lambda_1)$ and $r_1(\lambda_2)\geq c_1(\lambda_2)$. It suffices to show that there exists some $g\in C_n$ such that $(g(A))^{-1}(n)=(1,r_1(\lambda_1))$ and $(g(B))^{-1}(n)=(1,r_1(\lambda_2))$. By Theorem~\ref{1-trans}, there exists some $h\in C_n$ such that $(h(A))^{-1}(n)=(1,r_1(\lambda_1))$. If $(h(B))^{-1}(n)=(1,r_1(\lambda_2))$, we are done. Otherwise, observe that since $r_1(\lambda_1)>3$, it follows that $\lambda_1$ with the box $(h(A))^{-1}(n)$ taken away is either a hook-shaped partition or an almost-hook-shaped partition with $\max(r_1(\lambda_1),c_1(\lambda_1))\geq 3$ and $\lambda_2$ with the box $(h(B))^{-1}(n)$ taken away is hook-shaped, so there exists some $h'\in C_n$ such that $(h'h(A))^{-1}(n-1)=(1,r_1(\lambda_1)-1)$ and $(h'h(B))^{-1}(n-1)=(1,r_1(\lambda_2))$. Then, $(t_{n-1}h'h(A))^{-1}(n)=(1,r_1(\lambda_1))$ and $(t_{n-1}h'h(B))^{-1}(n)=(1,r_2(\lambda_1))$, as desired.

\textbf{Inductive step:} Now, assume $(\lambda_1,\lambda_2)$ is not base case, and let $A\in\syt(\lambda_1)$ and $B\in\syt(\lambda_2)$. We know the theorem holds for all pairs of partitions of $n-1$. We now show that for any $C\in\syt(\lambda_1)$ and $D\in\syt(\lambda_2)$ where $A\neq B,B^T$ and $C\neq D,D^T$, there exists some $g\in C_n$ such that $g(A)=C,g(B)=D$.

By \Cref{pre-move 2-trans}, we can find $g_1,g_2\in C_n$ such that the pairs $(g_1(A)\setminus n, g_1(B)\setminus n$ and $(g_2(C)\setminus n, g_2(D)\setminus n)$ are both viable. We now select a position to move $n-1$ to in $\lambda_1$ for $g_1(A)$ and $g_2(C)$.

If $\lambda_1$ has more than two corners, we choose the corner $(i,j)$ for both $g_1(A)$ and $g_2(C)$ such that $(i,j)\neq (g_1(A))^{-1}(n)$ and $(i,j)\neq (g_2(C))^{-1}(n)$. If $\lambda_1$ has two corners or fewer, then observe that $\lambda_1$ has an extended corner $(k,l)$. Without loss of generality, suppose $(k,l)=(g_1A)^{-1}(n)$. For $g_1(A)$, we select $(k,l-1)$ or $(k-1,l)$ (whichever it is possible to place $n-1$ in by the definition of an extended corner), and for $g_2(C)$, we select $(k,l)$.

We do the same process to select a position to move $n-1$ to in $\lambda_2$ for $g_1(B)$ and $g_2(D)$.
Since $(g_1(A)\setminus n,g_1(B)\setminus n)$ and $(g_2(C)\setminus n,g_2(D)\setminus n)$ are viable pairs on $n-1$ boxes, we can use our inductive hypothesis to find $h_1,h_2\in C_n$ such that $(h_1g_1(A))^{-1}(n-1),(h_1g_1(B))^{-1}(n-1),(h_2g_2(C))^{-1}(n-1),$ and $(h_2g_2(D))^{-1}(n-1)$ are in the specified positions as given above (so that after applying $t_{n-1}$ to both pairs, the position of $n$ is the same in the $A$ and $C$ as well as the $B$ and $D$ tableaux). Since we want to apply $t_{n-1}$ to both pairs and then use our inductive hypothesis yet again, we also need to ensure the pairs restricted to $n-1$ boxes will still be viable after applying $t_{n-1}$. Since a viable pair remains viable even after adding a box to any position, this is true as long as the $(n-2)$-box subdiagrams of both pairs are viable. Since all $(n-2)$-box subdiagrams have at least 3 standard Young tableaux, we can require $h_1$ and $h_2$ to also keep both $(n-2)$-box subdiagrams viable. Hence, our choice of $h_1$ and $h_2$ is such that $(h_1g_1(A)\setminus (n,n-1),(h_1g_1(B)\setminus (n,n-1))$ and $(h_2g_2(C)\setminus (n,n-1),(h_2g_2(D)\setminus (n,n-1))$ are viable; and $(t_{n-1}h_1g_1(A))^{-1}(n)=(t_{n-1}h_2g_2(C))^{-1}(n)$ and $(t_{n-1}h_1g_1(B))^{-1}(n)=(t_{n-1}h_2g_2(D))^{-1}(n)$). 

Thus, we have that the pairs $(t_{n-1}h_1g_1(A)\setminus n, t_{n-1}h_1g_1(B)\setminus n)$ and $(t_{n-1}h_2g_2(C)\setminus n, t_{n-1}h_2g_2(D)\setminus n)$ are both viable. Hence, we can use our inductive hypothesis once again to find $f_1,f_2\in C_n$ such that $f_1t_{n-1}h_1g_1(A)=f_2t_{n-1}h_2g_2(C)$ and $f_1t_{n-1}h_1g_1(B)=f_2t_{n-1}h_2g_2(D)$, so the group element $(f_2t_{n-1}h_2g_2)^{-1}f_1t_{n-1}h_1g_1$ transforms the pair $(A,B)$ into $(C,D)$, as desired.

\end{proof}

\begin{cor}\label{co:2-trans}
     Let $\lambda$ be a non hook-shaped partition of $n$. If $\lambda$ is self-transpose, the set of pairs $\syt(\lambda)\times \syt(\lambda)$ has 3 orbits under $C_n$; otherwise, there are 2 orbits.
\end{cor}

\begin{proof}
    This follows from \Cref{prop: self-transpose invariant}.
\end{proof}

\section{3-transitivity}\label{se:3-trans}
The proof structure is the same as for 2-transitivity, with a little more casework. We also need to update our inductive case and base case as follows:

\begin{defn*}
    Let $\lambda_1,\lambda_2,\lambda_3$ be partitions of $n$. We say that the triple of partitions $(\lambda_1,\lambda_2,\lambda_3)$ is \emph{viable} if at most one partition $\lambda_1,\lambda_2,\lambda_3$ is hook-shaped.
\end{defn*}

\begin{defn*}
    Let $A\in\syt(\lambda_1),B\in\syt(\lambda_2),C\in\syt(\lambda_3)$. We say that the triple of tableaux $(A,B,C)$ is \emph{viable} if $(\lambda_1,\lambda_2,\lambda_3)$ is viable and the following conditions are satisfied:
    \begin{enumerate}
        \item No two tableaux $A,B,C$ are the same.
        \item No two tableaux $A,B,C$ are transpositions of each other.
    \end{enumerate}
\end{defn*}

\begin{defn*}
    We say that the triple $(\lambda_1,\lambda_2,\lambda_3)$ is \emph{base case} if it is viable and satisfies one of the following conditions:
    \begin{enumerate}
        \item Two partitions of $\lambda_1,\lambda_2,\lambda_3$ are almost hook-shaped.
        \item One partition of $\lambda_1,\lambda_2,\lambda_3$ is almost hook-shaped and one is hook-shaped.
    \end{enumerate}
\end{defn*}

\begin{lemma} \label{pre-move}
    Let $(\lambda_1,\lambda_2,\lambda_3)$ be a viable triple of partitions of $n$ (each with at least two corners) that are not base case, and let $A\in\syt(\lambda_1)$, $B \in\syt(\lambda_2)$, and $C\in\syt(\lambda_3)$. If $(A,B,C)$ is viable, then there exists $g\in C_n$ such that $(gA\setminus n,gB\setminus n,gC\setminus n)$ is also viable.
\end{lemma}

\begin{proof}
\textbf{Case 1:} $\lambda_1=\lambda_2$ or $\lambda_1=\lambda_2^T$. Without loss of generality, suppose $\lambda_1=\lambda_2$. Using \Cref{2-trans}, let $g\in C_n$ such that $n-1$ is in a corner of $g(C)$; $g(A)\setminus n$ and $g(C)\setminus n$ are not the same as or transposed to each other; and $t_{n-1}g(A)\setminus n$ and $t_{n-1}g(C)\setminus n$ are not the same as or transposed to each other. If $g(A)\setminus n=g(B)\setminus n$ (resp., $g(A)\setminus n=(g(B)\setminus n)^T$), then $A=B$ (resp., $A=B^T$) since $\lambda_1=\lambda_2$, which contradicts that $(A,B,C)$ is viable. So, $g(A)\setminus n$ cannot be the same as or transposed to $g(B)\setminus n$. Finally, if $g(B)\setminus n\neq g(C)\setminus n$ and $g(B)\setminus n\neq (g(C)\setminus n)^T$, we are done. Otherwise, since $n-1$ is in a corner of $g(C)$, we have that $t_{n-1}g(B)\setminus n\neq t_{n-1}g(C)\setminus n$ and $t_{n-1}g(B)\setminus n\neq (t_{n-1}g(C)\setminus n)^T$, and we are also done.

\textbf{Case 2:} No two partitions of $\lambda_1,\lambda_2,\lambda_3$ are the same as or transposed to each other. There exists some box $(k,l)$ such that $\lambda_1\setminus (k,l)$ is a subshape of $\lambda_2$, and there exists some box $(k',l')$ such that $\lambda_1\setminus (k',l')$ is a subshape of $\lambda_2^T$. If $(k,l)$ and $(k',l')$ are the only corners of $\lambda_1$, then $\lambda_1=\lambda_2$ or $\lambda_1=\lambda_2^T$, and we may refer to Case 1.

Otherwise, there is some corner $(i,j)\in\lambda_1$ such that $\lambda_1\setminus(i,j)\notin \lambda_2$ and $\lambda_1\setminus(i,j)\not\subset \lambda_2^T$. Using \Cref{2-trans}, let $g\in C_n$ such that $(g(A))^{-1}(n)=(i,j)$, $n-1$ is in a corner of $g(C)$, $g(A)\setminus n$ and $g(C)\setminus n$ are not the same as or transposed to each other, and $t_{n-1}g(A)\setminus n$ and $t_{n-1}g(C)\setminus n$ are not the same as or transposed to each other. Since the shape of $g(A)\setminus n$ contains a box which is not in $\lambda_2$, it cannot be the case that $g(A)\setminus n$ is the same as or transposed to $g(B)\setminus n$. If $g(B)\setminus n\neq g(C)\setminus n$ and $g(B)\setminus n\neq (g(C)\setminus n)^T$, we are done. Otherwise, since $n-1$ is in a corner of $g(C)$, we have that $t_{n-1}g(B)\setminus n\neq t_{n-1}g(C)\setminus n$ and $t_{n-1}g(B)\setminus n\neq (t_{n-1}g(C)\setminus n)^T$, and we are also done.
\end{proof}


\begin{thm}\label{th:3-trans}
    Let $\lambda_1,\lambda_2,\lambda_3$ be partitions of $n$. Then the set of viable triples $A\in\syt(\lambda_1),B\in\syt(\lambda_2),C\in\syt(\lambda_3)$ is transitive under $C_n$.
\end{thm}

\begin{proof}
\textbf{Base Case:} We also use induction to show the base case. Let's assume that $\lambda_1$ is almost hook-shaped, $\lambda_2$ is either almost hook-shaped or hook-shaped, and $\lambda_3$ is any partition (which is not hook-shaped). (Throughout the proof, we  assume that partitions have at least two corners, as otherwise, the position of $n$ in is fixed in the only corner, and we are done by \Cref{2-trans}.)

\begin{table}
\centering
\begin{tabular}{l|l|l|l}
 & $\lambda_1$ & $\lambda_2$ & $\lambda_3$  \\\hline
 $n=4$ & $(2,2)$                          & all                           & all            \\\hline
 $n=5$ & $(3,2)$                           & all                         & all                \\
 & $(2,2,1)$                         & all                          & all          \\\hline
 $n=6$ & $(3,2,1)$                         & all                          & all           \\
 & $(4,2)$                          & all                       & all        \\
 & $(2,2,1,1)$                      & all                 &  all     
\end{tabular}
\caption{The 3-transitive cases we check by hand. Note: ``all" refers to all hook-shaped and almost hook-shaped partitions (of $n$ boxes) in the $\lambda_2$ column and all non-hook-shaped partitions in the $\lambda_3$ column. \label{table}}
\end{table}

We manually verify that the theorem holds for the cases in \Cref{table}. Otherwise, observe that $\max(r_1(\lambda_1),c_1(\lambda_1))>3$ and $\max(r_1(\lambda_2),c_1(\lambda_2))>3$, and suppose that the theorem holds for base case triples of partitions of $n-1$. Let $A\in\syt(\lambda_1),B\in\syt(\lambda_2),C\in\syt(\lambda_3)$, and without loss of generality, suppose the first column is not longer than the first row in $\lambda_1$ and $\lambda_2$ (that is, $r_1(\lambda_1)\geq c_1(\lambda_1)$ and $r_1(\lambda_2)\geq c_1(\lambda_2)$). Fix $(k,l)$ to be any corner of $\lambda_3$. We now show there is a way to move $n$ into $(k,l)$ of $\lambda_3$ and the first row of $\lambda_1$ and $\lambda_2$.

Using \Cref{2-trans}, let $g\in C_n$ such that $(g(A))^{-1}(n)=(1,r_1(\lambda_1))$ and $(g(C))^{-1}(n)\neq (k,l)$. Observe that $(g(A)\setminus n,g(B)\setminus n,g(C)\setminus n)$ is base case. Since $r_1(\lambda_1)>3$, we use induction to find some $h\in C_n$ such that $(hg(A))^{-1}(n-1)=(1,r_1(\lambda_1)-1)$, $(hg(C))^{-1}(n-1)=(k,l)$, and lastly, $(hg(B))^{-1}(n-1)=(1,r_1(\lambda_2)-1)$ if $(g(B))^{-1}(n)=(1,r_1(\lambda_2)$ or otherwise $(hg(B))^{-1}(n-1)=(1,r_1(\lambda_2))$ (while maintaining the positions of $n$ in all three tableaux). Because $n-1$ and $n$ are adjacent in $hg(A)$ and $r_1(\lambda_2)>2$, the box $(k,l)$ of $t_{n-1}hg(C)$ and the first rows of $t_{n-1}hgA$ and $t_{n-1}hg(B)$ contain $n$, as desired.


\textbf{Inductive step:} Now, assume the theorem holds for partitions of $n-1$. Let $A,D\in\syt(\lambda_1)$, $B,E \in\syt(\lambda_2)$, and $C,F\in\syt(\lambda_3)$ such that $(A,B,C)$ and $(D,E,F)$ be viable triples. Use \Cref{pre-move} to find $g_1,g_2\in C_n$ such that $(g_1(A)\setminus n,g_1(B)\setminus n,g_1(C)\setminus n)$ and $(g_2(D)\setminus n,g_2(E)\setminus n,g_2(F)\setminus n)$ are viable.

Our goal is to move $n$ into the same position in $g_1(A)$ and $g_2(D)$ (resp., $g_1(B)$ and $g_2(E)$, $g_1(C)$ and $g_2(F)$). We do this by selecting a location to move $n-1$ to in both tableaux of each partition. Recall that we can assume that $\lambda_1,\lambda_2,\lambda_3$ all have at least two corners.

Let us consider $\lambda_1$ (the process is the same for $\lambda_2$ and $\lambda_3)$. If $\lambda_1$ has more than two corners, let $(i_A,j_A)$ and $(i_D,j_D)$ be the same corner which is not equal to $g_1(A)^{-1}(n)$ or $g_2(D)^{-1}(n)$. Otherwise, if $\lambda_1$ has exactly two corners, one such corner must be an extended corner. Without loss of generality, suppose $(k,l):=g_1(A)^{-1}(n)$ is the extended corner and $g_2(D)^{-1}(n)$ is the other corner. Then, let $(i_A,j_A):=(k-1,l)$ or $(i_A,j_A):=(k,l-1)$ (whichever box is possible to place $n-1$ in), and let $(i_D,j_D):=(k,l)$.

Now, repeat this process for $\lambda_2$ and $\lambda_3$ to find positions $(i_B,j_B),(i_E,j_E)$ and $(i_C,j_C),(i_F,j_F)$ to move $n-1$ into. By induction, there exist $h_1,h_2\in C_n$ such that $n-1$ is in the specified positions in the triples $(h_1g_1(A),h_1g_1(B),h_1g_1(C))$ and $(h_2g_2(D),h_2g_2(E),h_2g_2(F))$ such that when they are restricted to $n-2$ boxes, both triples are still viable. Finally, we have that $n$ is in the same position in $t_{n-1}h_1g_1(A)$ and $t_{n-1}h_2g_2(D)$ (resp., $t_{n-1}h_1g_1(B)$ and $t_{n-1}h_2g_2(E)$, $t_{n-1}h_1g_1(C)$ and $t_{n-1}h_2g_2(F)$). Using the same argument as in \Cref{2-trans}, both triples $(t_{n-1}h_1g_1(A)\setminus n, t_{n-1}h_1g_1(B)\setminus n,t_{n-1}h_1g_1(C)\setminus n)$ and $(t_{n-1}h_2g_2(D)\setminus n, t_{n-1}h_2g_2(E)\setminus n,t_{n-1}h_2g_2(F)\setminus n)$ are viable. Hence, we can find $f_1,f_2\in C_n$ such that $f_1t_{n-1}h_1g_1(A)=f_2t_{n-1}h_2g_2(C)$, $f_1t_{n-1}h_1g_1(B)=f_2t_{n-1}h_2g_2(D)$, and $f_1t_{n-1}h_1g_1(C)=f_2t_{n-1}h_2g_2(F)$. Thus, the group element $(f_2t_{n-1}h_2g_2)^{-1}f_1t_{n-1}h_1g_1$ transforms the triple $(A,B,C)$ into $(D,E,F)$, as desired.
\end{proof}

As a consequence, we get the following (Theorem~B in the Introduction):
\begin{cor}\label{co:3-trans}
    Suppose that $\lambda$ is not hook-shaped and not self-transpose. Let $N$ be the cardinality of $\syt(\lambda)$. Then the action of $C_n$ on the set $\syt(\lambda)$ is $3$-transitive.
\end{cor}


\section{Proof of Theorem B}\label{se:thm-B}

In this section, we deduce the following statement (Theorem~B in the Introduction) from Corollary~\ref{co:3-trans}:
\begin{thm}\label{th:B}
    Suppose that $\lambda$ is not hook-shaped and not self-transpose. Let $N$ be the cardinality of $\syt(\lambda)$. Then the image of $C_n$ in the permutation group $S_N$ of the set $\syt(\lambda)$ is either the whole $S_N$ or the alternating group $A_N$.
\end{thm}

\begin{proof}

$3$-transitive actions apart from the standard actions of $S_N$ and $A_N$ are classified as follows, see e.g. \cite[Chapter 7]{Cameron_book}:

