%\centering

\medskip

\begin{tabular}{|l|l|c|}
\hline
\textbf{Group} & \textbf{Set Acted Upon} & \textbf{Degree of Transitivity} \\
\hline
$M_{11}$ & 11 points & 4-transitive \\
$M_{11}$ & 12 points & 3-transitive \\
$M_{12}$ & 12 points & 5-transitive \\
$M_{22}$ or $M_{22}.2$ & 22 points & 3-transitive \\
$M_{23}$ & 23 points & 4-transitive \\
$M_{24}$ & 24 points & 5-transitive \\
\hline
$\mathrm{PSL}(2,q)\subset G\subset\mathrm{P\Gamma L}(2,q)$, $q\ge5$ & $\mathbb{P}^1(\mathbb{F}_q)$ (q+1 points) & 3-transitive \\
