%a_{i_1i_2\dots i_l}\leq Mp_{i_1}a_{i_2\dots i_l}, 
%\end{equation}
%since there are $M$ initial edges from the root of the $M$-ary tree, each of which has probability $p_{i_1}$ of being labeled $i_1$, labels of edges are independent, and the labeling of the subtree below any vertex has the same probability law as the labeling of the entire tree. Iterating \eqref{eq:upper-recursion}, we conclude that for any word $\ii\in\Gamma_n(k_1,\dots,k_N)$,
