We next sketch the proof of the lower bound.  Adapting a technique of Liu and Wu \cite{Liu-Wu}, we first construct a sequence $\{F_n\}$ of (random) subsets of $F$ such that for each $n$, $F_n$ is the limit set of a Mauldin-Williams random recursive construction (see \cite{Mauldin-Williams}) and satisfies
\begin{equation} %\label{eq:subset-dimension}
\dim_H F_n\sim\frac{\log \EE(\#\tilde{\Gamma}_n)}{n}.
\end{equation}
%(This is where the regularity condition (O3) on the open set $U$ comes in.) 
The details of this construction are given in Section \ref{sec:stopping-set}.
Letting $n\to\infty$ then yields
\[
\dim_H F\geq \liminf_{n\to\infty} \frac{\log \EE(\#\tilde{\Gamma}_n)}{n}.
\]
Since $\EE(\#\tilde{\Gamma}_n)=\sum_{\ii\in\Gamma_n}a_\ii$, the task then turns to estimating the probabilities $a_{\mathbf{i}}$ from below.  This would be easy if the paths in the tree were completely independent, as $a_{\mathbf{i}}$ would then be constant on $\Gamma_n(k_1, \dots, k_N)$,  but the cross-dependence of the different paths due to shared edges can make some of the $a_{\mathbf{i}}$ exponentially small.  For example,  if $p_1$ is such that $Mp_1<1$ and $\ii$ is such that $i_1=\dots=i_{k_1}=1$, then by reasoning analogous to what we used for the upper bound,
\[
a_\ii\leq (Mp_1)^{k_1},
\]
and since each $k_i$ is of order $n$ for the tuple $(k_1,\dots,k_N)$ maximizing the expression in \eqref{eq:discrete-maximum}, this shows that $\min_{\ii\in\Gamma_n}a_\ii\to 0$ exponentially fast. Thus, in order to estimate $\sum_{\ii\in\Gamma_n}a_\ii$ from below, we need to exclude highly ordered words as in the above example. This motivates the definition of the special subset $D_n\subset\Gamma_n$ in the proof (see Section \ref{sec:lower-bound}),  which roughly speaking consists of the sufficiently ``random-looking" sequences $\mathbf{i}$.  Via standard estimates we can show that the number of these ``random-looking" sequences is not much smaller than the cardinality of $\Gamma_n(k_1,\dots,k_N)$, and for elements in $D_n$,  we are able to show a sufficient lower bound on $a_{\mathbf{i}}$ via an iteration.



\section{The random stopping set} \label{sec:stopping-set}

For each finite word $\ii\in\{1,\dots,N\}^*$, let $J_\ii:=f_\ii(\bar{U})$, where we write $f_\ii=f_{i_1}\circ\dots\circ f_{i_n}$ for $\ii=(i_1,\dots,i_n)$. We also let $\mathcal{P}_l$ denote the set of all paths of length $l$ in the $M$-ary tree starting from the root, for $l\in\NN$. To simplify the presentation somewhat, we assume without loss of generality that $|U|=1$. Denote
\[
r_{\min}:=\min_{1\leq i\leq N}r_i \qquad\mbox{and}\qquad r_{\max}:=\max_{1\leq i\leq N}r_i.
\]
For each $n\in\NN$, we define the stopping set
\begin{equation} \label{eq:stopping-set}
\Gamma_n:=\{\ii=i_1\dots i_l\in\{1,\dots,N\}^*: r_{i_1}\dots r_{i_l}\leq e^{-n}<r_{i_1}\dots r_{i_l-1}\}.
\end{equation}
Observe that the collection $\{J_\ii: \ii\in\Gamma_n\}$ is an $e^{-n}$-cover of $\Lambda$, hence of $F$. However, not all of these sets are needed to cover $F$, so we define also the smaller (random) set
\begin{equation} \label{eq:stopping-subset}
\tilde{\Gamma}_n:=\{\ii\in\Gamma_n:\ \mbox{at least one path in $\mathcal{P}_{|\ii|}$ is labeled $\ii$}\}.
\end{equation}
Then $\{J_\ii: \ii\in\tilde{\Gamma}_n\}$ is a more efficient $e^{-n}$-cover of $F$. Since the sets in this cover are roughly the same size, we need to estimate their number. In fact, as the next proposition shows, it is sufficient to determine the exponential growth rate of the {\em expected} cardinality of $\tilde{\Gamma}_n$. Let $\EE$ denote the expectation operator associated with the probability measure $\PP$.

\begin{proposition} \label{prop:growth-rate}
We have, $\PP$-almost surely,
\[
\liminf_{n\to\infty} \frac{\log \EE(\#\tilde{\Gamma}_n)}{n}\leq \dim_H F\leq \overline{\dim}_B F\leq \limsup_{n\to\infty} \frac{\log \EE(\#\tilde{\Gamma}_n)}{n}.
\]
\end{proposition}

\begin{proof}
We first prove the upper bound. Let
\[
\lambda:=\limsup_{n\to\infty} \frac{\log \EE(\#\tilde{\Gamma}_n)}{n}.
\]
Fix $\eps>0$. Put $Z_n:=\#\tilde{\Gamma}_n$. Then, for all large enough $n$,
\[
\PP\big(Z_n>e^{(\lambda+2\eps)n}\big)\leq \frac{\EE(Z_n)}{e^{(\lambda+2\eps)n}}\leq \frac{e^{(\lambda+\eps)n}}{e^{(\lambda+2\eps)n}}=e^{-\eps n}.
\]
As the series $\sum_{n=1}^\infty \PP\big(Z_n>e^{(\lambda+2\eps)n}\big)$ converges,  by the Borel-Cantelli lemma, $Z_n\leq e^{(\lambda+2\eps)n}$ for all sufficiently large $n$ with probability one. Therefore, since $f_{\ii}(U)$ has diameter approximately $e^{-n}$ for any $\ii\in\Gamma_n$,
\[
\overline{\dim}_B F\leq \lambda+2\eps \qquad\mbox{$\PP$-almost surely},
\]
and letting $\eps\to 0$ along a discrete sequence gives
$\overline{\dim}_B F\leq \lambda$, $\PP$-almost surely.

For the lower bound, we borrow a technique of Liu and Wu \cite{Liu-Wu}. The idea is to construct a sequence $\{F_n\}$ of (random) subsets of $F$ such that for each $n$, $F_n$ is the limit set of a Mauldin-Williams random recursive construction and satisfies
\begin{equation} \label{eq:subset-dimension}
\dim_H F_n\sim\frac{\log \EE(Z_n)}{n}.
\end{equation}
Letting $n\to\infty$ then yields the desired lower bound.

For the remainder of this proof, let $\CP^*$ be the set of all finite paths in $\mathcal{T}_M$ that start at the root.
Fix $n\in\NN$. For $\omega\in\Omega$, let $\CL_1=\CL_1(\omega)=\tilde{\Gamma}_n$. Let $\CB_1=\CB_1(\omega)$ be the set of finite paths $P=(P(1),\dots,P(l))\in\CP^*$ which receive a label sequence from $\CL_1(\omega)$ and such that no path of the same length as $P$ which is lexicographically smaller than (i.e. to the left of) $P$ receives the same label sequence as $P$. Thus, $\#\CB_1=\#\CL_1$. Observe also that no path in $\CB_1$ extends any other, because no word in $\CL_1$ extends any other. (In terms of the branching random walk, if there are two or more particles occupying the same interval of length approximately $e^{-n}$, we remove all but one of them before continuing the process.)

Next, we proceed inductively. For $k=1,2,\dots$, assume $\CB_k$ and $\CL_k$ have been constructed. 	Let $\CB_{k+1}$ be the set of paths $P=P'P''$ in $\CP^*$ such that $P'\in\CB_k$ and $P''$ receives a label sequence in $\Gamma_n$, and furthermore, no path of the same length as $P$ which is lexicographically smaller than $P$ receives the same label sequence as $P$. (We continue to remove ``duplicate" particles in the branching random walk.)

Let $\CL_{k+1}$ be the set of all label sequences of paths in $\CB_{k+1}$. Thus (by induction), $\#\CB_{k+1}=\#\CL_{k+1}$. For each $\ii\in\CL_k$, let $Y_\ii$ be the number of words in $\CL_{k+1}$ that begin with $\ii$.

For each $k$, by construction, the sets $J_\ii:=f_\ii(\bar{U}): \ii\in\CL_k$, are non-overlapping since the IFS $\{f_1,\dots,f_N\}$ satisfies the open set condition. Furthermore, for $\ii\in\CL_k$,
\[
\#\{\ii'\in\CL_{k+1}: J_{\ii'}\subset J_\ii\}=Y_\ii.
\]
Note that the random variables $Y_\ii: \ii\in\bigcup_{k=1}^\infty \CL_k$ are i.i.d. with the same distribution as $Z_n$. Hence, the set
\[
F_n:=\bigcap_{k=1}^\infty \bigcup_{\ii\in\CL_k}J_\ii
\]
is the limit set of a Mauldin-Williams random recursive construction (see \cite{Mauldin-Williams}). Clearly, $F_n\subset F$. Since $\PP(Z_n\geq 1)=1$, $F_n$ is nonempty with probability one. By the main theorem of \cite{Mauldin-Williams}, the Hausdorff dimension of $F_n$ is the unique number $s_n$ satisfying
\[
\EE\left(\sum_{\ii\in\tilde{\Gamma}_n}(r_{i_1}\dots r_{i_{|\ii|}})^{s_n}\right)=1.
\]
(By condition (O3), the set $K:=\bar{U}$ satisfies the assumption of Mauldin and Williams that $K$ is the closure of its interior.)
By the definition of $\Gamma_n$, this implies
\[
\frac{\log \EE(Z_n)}{n-\log r_{\min}}\leq\dim_H F_n=s_n\leq \frac{\log \EE(Z_n)}{n},
\]
from which \eqref{eq:subset-dimension} follows.
\end{proof}

In view of Proposition \ref{prop:growth-rate},  to complete the proof of Theorem \ref{thm:variational}, it remains to show that
\begin{equation} \label{eq:liminf-limsup-sandwich}
\limsup_{n\to\infty} \frac{\log \EE(\#\tilde{\Gamma}_n)}{n}\leq s^*\leq \liminf_{n\to\infty} \frac{\log \EE(\#\tilde{\Gamma}_n)}{n}
\end{equation}
(and hence, the limit of $n^{-1}\log \EE(\#\tilde{\Gamma}_n)$ actually exists),
where $s^*$ is the right-hand side of \eqref{eq:variational-principle}, i.e. 
\[
s^*:=\max\big\{\psi(\xx)+\min\{0,\phi(\xx)\}: \xx\in[0,\infty)^N,\ h(\xx)=1\big\},
\]
where $\psi$, $\phi$ and $h$ were defined in \eqref{eq:psi}, \eqref{eq:phi} and \eqref{eq:h}, respectively.
Our proofs of these inequalities are mostly combinatorial and necessarily somewhat technical. We prove the first inequality in Section \ref{sec:upper-bound}, and the second inequality in Section \ref{sec:lower-bound}.


\section{Proof of the upper bound} \label{sec:upper-bound}

In this section we prove the first inequality in \eqref{eq:liminf-limsup-sandwich}:

\begin{proposition} \label{prop:key-upper-estimate}
We have
\[
\limsup_{n\to\infty}\frac{\log \EE(\#\tilde{\Gamma}_n)}{n}\leq s^*.
%E(\#\tilde{\Gamma}_n)\geq (s^*-\eps)^n.
\]
\end{proposition}

We use the following estimate for multinomial coefficients, which is an easy consequence of Stirling's approximation.

\begin{lemma}[{\cite[Lemma 7.4]{Allaart}}] \label{lem:multinomial-estimate}
Let $m\in\NN$, and let $k_1,\dots,k_N$ be nonnegative integers with $\sum_{i=1}^N k_i=m$. Put $\alpha_i:=k_i/N$ for $i=1,\dots,N$. Then
\begin{equation*}
\binom{m}{k_1,\dots,k_N}\leq 2\sqrt{m}\left(\prod_{i=1}^N \alpha_i^{-\alpha_i}\right)^m,
\end{equation*}
where we use the convention $0^0\equiv 1$.
\end{lemma}

\begin{proof}[Proof of Proposition \ref{prop:key-upper-estimate}]
For $\ii\in\{1,\dots,N\}^*$, let
\[
k_j(\ii):=\#\{\nu\leq|\ii|: i_\nu=j\}, \qquad j=1,\dots,N.
\]
Then
\begin{equation} \label{eq:first-mean-estimate}
\EE(\#\tilde{\Gamma}_n)=\sum_{\ii\in\Gamma_n}\PP(\ii\in\tilde{\Gamma}_n)\leq \sum_{\ii\in\Gamma_n}\min\left\{\prod_{j=1}^N(Mp_j)^{k_j(\ii)},1\right\},
\end{equation}
where the inequality was established in \eqref{eq:a_i-pointwise}.
If $\ii\in\Gamma_n$ and $k_j(\ii)=k_j$ for $j=1,\dots,N$, then
\begin{equation} \label{eq:product-sandwich}
\prod_{j=1}^N r_i^{k_i}\leq e^{-n}<r_{\min}^{-1}\prod_{j=1}^N r_j^{k_j}.
\end{equation}
Let $B_n$ denote the set of $N$-tuples $(k_1,\dots,k_N)$ for which these inequalities hold. By the rightmost inequality in \eqref{eq:product-sandwich},
\[
\sum_{j=1}^N k_j\log r_j>\log r_{\min}-n,
\]
and so (since $\log r_j<0$) certainly $k_j\log r_j>\log r_{\min}-n$ for each $j$. Hence
\begin{equation} \label{eq:k-bound}
k_j\leq \frac{\log r_{\min}-n}{\log r_j}\leq \frac{n+|\log r_{\min}|}{|\log r_{\max}|}, \qquad j=1,\dots,N,
\end{equation}
so there is a constant $C>0$ such that $\#B_n\leq Cn^N$ for all $n\in\NN$. Thus, from \eqref{eq:first-mean-estimate}, we obtain
\begin{align*}
\EE(\#\tilde{\Gamma}_n)&\leq \sum_{(k_1,\dots,k_N)\in B_n}\binom{k_1+\dots+k_N}{k_1,\dots,k_N}\min\left\{\prod_{j=1}^N(Mp_j)^{k_j},1\right\}\\
&\leq Cn^N\max_{(k_1,\dots,k_N)\in B_n}\binom{k_1+\dots+k_N}{k_1,\dots,k_N}\min\left\{\prod_{j=1}^N(Mp_j)^{k_j},1\right\}.
\end{align*}

Put $\beta_i:=k_i/n$; then $\beta_i\geq 0$ and \eqref{eq:product-sandwich} is equivalent to
\begin{equation} \label{eq:beta-sandwich}
\sum_{i=1}^N \beta_i \log r_i\leq -1<\sum_{i=1}^N \beta_i \log r_i-\frac{1}{n}\log r_{\min}.
\end{equation}
Let $B_n'$ denote the set of $N$-tuples $\boldsymbol{\beta}=(\beta_1,\dots,\beta_N)\in[0,\infty)^N$ satisfying these inequalities. Let
\[
\alpha_i:=\frac{k_i}{k_1+\dots+k_N}=\frac{\beta_i}{\beta_1+\dots+\beta_N}, \qquad i=1,\dots,N.
\]
By Lemma \ref{lem:multinomial-estimate}, we have
\[
\binom{k_1+\dots+k_N}{k_1,\dots,k_N}\leq 2(k_1+\dots+k_N)^{1/2}\left(\prod_{i=1}^N \alpha_i^{-\alpha_i}\right)^{k_1+\dots+k_N}.
\]
Note that $k_1+\dots+k_N\leq C'n$ for a suitable constant $C'$, by \eqref{eq:k-bound}. On the other hand, we can write $\alpha_i(k_1+\dots+k_N)=\alpha_i(\sum_j\beta_j)n=\beta_i n$. Thus,
\begin{align*}
\left(\prod_{i=1}^N \alpha_i^{-\alpha_i}\right)^{k_1+\dots+k_N}& \cdot \min\left\{\prod_{i=1}^N(Mp_i)^{k_i},1\right\}\\
&=\left[\left(\sum_i\beta_i\right)^{\sum_i\beta_i}\prod_i \beta_i^{-\beta_i}\cdot \min\left\{\prod_{i=1}^N(Mp_i)^{\beta_i},1\right\}\right]^n\\
&=\exp\big(n\{\psi(\boldsymbol{\beta})+\min\{0,\phi(\boldsymbol{\beta})\}\big).
\end{align*}
It follows that, for a suitable constant $C''$,
\begin{equation} \label{eq:Gamma-bound}
\EE(\#\tilde{\Gamma}_n) \leq 2C''n^N\sqrt{n}\sup_{\boldsymbol{\beta}\in B_n'} \exp\left(n\{\psi(\boldsymbol{\beta})+\min\{0,\phi(\boldsymbol{\beta})\}\right).
\end{equation}

Since the extra term $(1/n)\log r_{\min}$ in \eqref{eq:beta-sandwich} goes to zero as $n\to\infty$, we can replace the condition of $\boldsymbol{\beta}$ satisfying \eqref{eq:beta-sandwich} by $h(\boldsymbol{\beta})=-\sum\beta_i\log r_i=1$ without changing the last estimate by much. Specifically, we show:

\bigskip
{\bf Claim:} For each $\eps>0$ there exists an integer $n_0$ such that for each $n\geq n_0$ and each $\boldsymbol{\beta}\in B_n'$, there exists a vector $\boldsymbol{\beta}'\in[0,\infty)^N$ such that $h(\boldsymbol{\beta}')=1$ and
\[
\psi(\boldsymbol{\beta})+\min\{0,\phi(\boldsymbol{\beta})\}\leq \psi(\boldsymbol{\beta}')+\min\{0,\phi(\boldsymbol{\beta}')\}+2\eps.
\]

{\bf Proof of Claim:} Let $\eps>0$ be given. For any $\boldsymbol{\beta}\in B_n$, we have, as in \eqref{eq:k-bound},
\[
0\leq\beta_i\leq \frac{n\log r_{\min}-1}{n\log r_i}\leq \frac{\log r_{\min}-1}{\log r_i}\leq \frac{1+|\log r_{\min}|}{|\log r_{\max}|}=:K \qquad \forall i\in\{1,\dots,N\},
\]
by the second half of \eqref{eq:beta-sandwich}.
Recalling our convention that $0\log 0=0$, $\psi$ is continuous on $[0,K]^N$, hence it is uniformly continuous on this set. So there exists $\delta>0$ such that, whenever $|\beta_i-\beta_i'|<\delta$ for all $i$, we have $|\psi(\boldsymbol{\beta})-\psi(\boldsymbol{\beta}')|<\eps$. Let
\[
b:=\frac{\log r_{\min}}{\log r_{\max}}, \qquad \tilde{b}:=b\max_i|\log(Mp_i)|,
\]
and choose $n_0\in\NN$ so large that 
\begin{equation} \label{eq:n-must-be-large}
\frac{b}{n_0}<\delta, \qquad \frac{\tilde{b}}{n_0}<\eps \qquad\mbox{and} \qquad n_0\geq (N-1)|\log r_{\min}|.
\end{equation}
Given $n\geq n_0$ and $\boldsymbol{\beta}\in B_n'$, we construct a suitable vector $\boldsymbol{\beta}'$ as follows.
By the second half of \eqref{eq:beta-sandwich}, there is an index $j$ such that
\begin{equation} \label{eq:excluding-sum}
\sum_{i\neq j}\beta_i\log r_i>\frac{N-1}{N}\left(-1+\frac{\log r_{\min}}{n}\right)\geq -1,
\end{equation}
where the last inequality follows from \eqref{eq:n-must-be-large}.
Put $\beta_i'=\beta_i$ for $i\neq j$, and
\[
\beta_j':=-\frac{1+\sum_{i\neq j}\beta_i\log r_i}{\log r_j}.
\]
It follows at once that $h(\boldsymbol{\beta}')=1$, and $\beta_j'\geq 0$ by \eqref{eq:excluding-sum}. Furthermore,
\[
|\beta_j'-\beta_j|=\left|\frac{-1-\sum_i \beta_i\log r_i}{\log r_j}\right|\leq \frac{\log r_{\min}}{n\log r_{\max}}=\frac{b}{n}<\delta,
\]
where the first inequality follows from \eqref{eq:beta-sandwich}. Hence, $\psi(\boldsymbol{\beta})<\psi(\boldsymbol{\beta}')+\eps$. Finally, 
\begin{equation*}
\phi(\boldsymbol{\beta})\leq\phi(\boldsymbol{\beta}')+|\beta_j-\beta_j'||\log(Mp_j)|
\leq \phi(\boldsymbol{\beta}')+\frac{\tilde{b}}{n}<\phi(\boldsymbol{\beta}')+\eps,
\end{equation*}
and the Claim follows. $\diamond$

\bigskip

Combining the Claim with \eqref{eq:Gamma-bound} and noting that the factor $n^N\sqrt{n}$ is subexponential, we see that for each $\eps>0$ we can find $n_0\in\NN$ such that for all $n\geq n_0$,
\begin{align*}
\EE(\#\tilde{\Gamma}_n)&\leq e^{\eps n}\max\left\{\exp\left(n\big\{\psi(\boldsymbol{\beta})+\min\{0,\phi(\boldsymbol{\beta})\}\big\}\right): \boldsymbol{\beta}\in[0,\infty)^N, h(\boldsymbol{\beta})=1\right\}\\
&=e^{(s^*+\eps)n}.
\end{align*}
This completes the proof.
\end{proof}


\section{Proof of the lower bound} \label{sec:lower-bound}

In this section, we prove the second inequality in \eqref{eq:liminf-limsup-sandwich}:

\begin{proposition} \label{prop:key-lower-estimate}
We have
\[
\liminf_{n\to\infty}\frac{\log \EE(\#\tilde{\Gamma}_n)}{n}\geq s^*.
%E(\#\tilde{\Gamma}_n)\geq (s^*-\eps)^n.
\]
\end{proposition}

\begin{proof}
Let $\boldsymbol{\beta}=(\beta_1,\dots,\beta_N)$ be any vector in $[0,\infty)^N$ such that $h(\boldsymbol{\beta})=1$. It suffices to show that
\[
\liminf_{n\to\infty}\frac{\log \EE(\#\tilde{\Gamma}_n)}{n}\geq \psi(\boldsymbol{\beta})+\min\{0,\phi(\boldsymbol{\beta})\}.
\]
By continuity, we may assume without loss of generality that $\beta_i>0$ for each $i$.

We divide the proof in a series of steps. For $\ii\in\Gamma_n$, define
\[
a_\ii:=\PP\left(\mbox{at least one path in $\CP_{|\ii|}$ is labeled $\ii$}\right), \qquad \ii\in\{1,2,\dots,N\}^*,
\]
so that
\[
\EE(\#\tilde{\Gamma}_n)=\sum_{\ii\in\Gamma_n} a_\ii.
\]
%\textcolor{red}{Estimating this by establishing a general lower bound on the size of $a_\ii$ is doomed to fail (Example given in Section \ref{sec:sketch}), so}
Unfortunately, the probabilities $a_\ii$ are difficult to compute or even estimate in general. The example at the end of Section \ref{sec:sketch} shows that they can, in general, be exponentially small. Our goal is to construct a subset $D_n$ of $\Gamma_n$ of words in which each digit $i\in\{1,\dots,N\}$ appears approximately $\beta_i n$ times, and then derive a lower estimate for $a_\ii$, $\ii\in D_n$.

\bigskip
{\em Step 1. (Construction of $D_n$)} Since $h(\boldsymbol{\beta})=-\sum \beta_i\log r_i=1$, we have for each $n\in\NN$,
\begin{equation} \label{eq:floor-inequalities}
\prod_{i=1}^N r_i^{1+\lfloor\beta_i n\rfloor}<e^{-n}=\left(\prod_{i=1}^N r_i^{\beta_i}\right)^n\leq \prod_{i=1}^N r_i^{\lfloor\beta_i n\rfloor}.
\end{equation}
Using these inequalities, we first construct a specific word in $\Gamma_n$ in which each digit $i$ occurs approximately $\beta_i n$ times. If equality holds on the far right of \eqref{eq:floor-inequalities}, then the word
\[
\mathbf{v}:=1^{\lfloor\beta_1 n\rfloor}2^{\lfloor\beta_2 n\rfloor}\dots N^{\lfloor\beta_N n\rfloor}
\]
lies (barely) in $\Gamma_n$, where $i^k$ denotes the digit $i$ repeated $k$ times. Otherwise, this word is too short to belong to $\Gamma_n$, but by the left-most inequality in \eqref{eq:floor-inequalities}, we can extend $\mathbf{v}$ to a word in $\Gamma_n$ by appending the string $12\dots i_0$, for some $i_0\in\{1,2,\dots,N\}$. In either case, then, there is an integer $i_0\in\{0,1,\dots,N\}$ such that the word
\[
\ww:=1^{\lfloor\beta_1 n\rfloor}2^{\lfloor\beta_2 n\rfloor}\dots N^{\lfloor\beta_N n\rfloor}12\dots i_0.
\]
lies in $\Gamma_n$.
Let $L:=|\ww|=\sum_{i=1}^N\lfloor\beta_i n\rfloor+i_0$, and write $\ww=w_1\dots w_{L}$. Then
\begin{equation} \label{eq:L-bounds}
-N+\sum_{i=1}^N \beta_i n\leq L\leq \sum_{i=1}^N \beta_i n+N.
\end{equation}
Note furthermore, that all permutations of $\ww$ that fix the last digit $w_L$ also belong to $\Gamma_n$. Denote the set of all such permutations by $\hat{D}_n$. It would be easier to estimate the probability $a_\ii$, for $\ii\in\hat{D}_n$, if the occurrences of each digit were somewhat evenly distributed across the word $\ii$. Therefore, we form a subset $D_n$ of $\hat{D}_n$ by imposing an additional requirement.

For each $i\in\{1,\dots,N\}$, let $t_i$ be the number of occurrences of the digit $i$ in $w_1\dots w_{L-1}$. Then $t_i$ is either $\lfloor\beta_i n\rfloor$, $\lfloor\beta_i n\rfloor-1$, or $\lfloor\beta_i n\rfloor+1$, and $\sum_{i=1}^N t_i=L-1$. Put $m:=\lfloor\sqrt{L-1}\rfloor$, and assume $n$ (and hence $L$) is large enough so that $m\gg N$. Put
\[
k_i:=\left\lfloor\frac{t_i}{m}\right\rfloor, \qquad i=1,\dots,N,
\]
and
\[
q:=\sum_{i=1}^N k_i.
\]
Note that $L-1-mN<mq\leq L-1$. Write $L-1=mq+r$, so $0\leq r<mN$. Now let $D_n$ be the set of all words in $\hat{D}_n$ for which each of the first $m$ blocks of length $q$ contains the digit $i$ exactly $k_i$ times, for $i=1,\dots,N$. Precisely, $\ii=i_1\dots i_L\in D_n$ if and only if $\ii\in\hat{D}_n$ and for each $i\in\{1,\dots,N\}$ and $l\in\{1,\dots,m\}$,
\[
\#\{\nu\in\{(l-1)q+1,\dots,lq\}: i_\nu=i\}=k_i.
\]

\bigskip
{\em Step 2. (Estimating the cardinality of $D_n$)} We claim that
\begin{equation} \label{eq:D_n-lower-estimate}
\liminf_{n\to\infty}\frac{\log\#D_n}{n}\geq \psi(\boldsymbol{\beta}).
\end{equation}
To see this, note first that $\psi$ satisfies the positive homogeneity property
\begin{equation} \label{eq:psi-homogeneous}
\psi(\alpha\xx)=\alpha\psi(\xx) \qquad\mbox{for any $\alpha>0$ and $\xx\in[0,\infty)^N$}.
\end{equation}
We use Stirling's approximation to get the initial estimate
\begin{align*}
\#D_n\geq {\binom{q}{k_1,\dots,k_N}}^m&=\left(\frac{\sqrt{2\pi q}\cdot q^q}{\prod\sqrt{2\pi k_i}\cdot \prod k_i^{k_i}}
\cdot (1+o(1))\right)^m\\
& \geq \left(\frac{q^q}{(2\pi)^{N/2}q^{N/2}\prod k_i^{k_i}}\cdot (1+o(1))\right)^m.
\end{align*}
Thus,
\begin{align*}
\frac{\log\#D_n}{m}&\geq q\log q-\frac{N}{2}\log 2\pi-\frac{N}{2}\log q-\sum_i k_i\log k_i+o(1)\\
&=q\log q-\sum_i k_i\log k_i+O(\log q). %=\psi(k_1,\dots,k_N)+O(\log q).
%&\sim \psi\left(\frac{\beta_1 n}{m},\dots,\frac{\beta_N n}{m}\right)=\frac{n}{m}\psi(\boldsymbol{\beta}),
\end{align*}
Here we want to replace $k_i$ with $k_i':=\beta_i n/m$ (which is not necessarily an integer), and similarly, replace $q$ with $q':=\sum_i k_i'$.
The definitions of $t_i$ and $k_i$ imply
\begin{equation} \label{eq:k-i-estimates}
\frac{\beta_i n-2}{m}-1<\frac{t_i}{m}-1<k_i\leq\frac{t_i}{m}\leq \frac{\beta_i n+1}{m},
\end{equation}
so certainly $|k_i-k_i'|\leq 3$. The mean value theorem then gives $k_i\log k_i-k_i'\log k_i'=O(\log k_i)=O(\log q)$. Similarly, $|q-q'|\leq 3N$ and so $q\log q-q'\log q'=O(\log q)$.
Observe that %$q$, $m$ and the $k_i$'s all tend to $\infty$ at rate $\sqrt{n}$ as $n\to\infty$. Namely,
\[
q\leq \frac{L}{m}\sim \sqrt{L}\sim \sqrt{\sum \beta_i n}=O(\sqrt{n})
\]
by \eqref{eq:L-bounds}. 
Hence,
\begin{align*}
\frac{\log\#D_n}{m}&\geq q'\log q'-\sum_i k_i'\log k_i'+O(\log q)\\
&=\psi\left(\frac{\beta_1 n}{m},\dots,\frac{\beta_N n}{m}\right)+O(\log \sqrt{n})\\
&=\frac{n}{m}\psi(\boldsymbol{\beta})+O(\log n),
\end{align*}
where in the last step we used \eqref{eq:psi-homogeneous}. Multiplying by $m/n$, we obtain \eqref{eq:D_n-lower-estimate}.

\bigskip
{\em Step 3. (Estimating $a_\ii$ for $\ii\in D_n$)} Recall from Step 1 that all words in $D_n$ have length $L$. Note that $a_\ii$ satisfies the recursion
\begin{equation} \label{eq:recursion}
a_{i_1i_2\dots i_L}=1-(1-p_{i_1}a_{i_2\dots i_L})^M.
\end{equation}
This can be seen by a branching argument: Let $G_\ii$ be the event that {\em no} path of length $n$ starting at the root of the  tree has label sequence $\mathbf{i}$. For $k=1,\dots,M$, let $G_{\ii,k}$ be the event that no path starting with the $k$th edge emanating from the root has label sequence $\mathbf{i}$. By independence, $\PP(G_\ii)=\prod_{k=1}^M \PP(G_{\ii,k})$. Now $G_{\ii,k}^c$ happens if and only if the $k$th edge below the root receives label $i_1$ and the label sequence $a_{i_2\dots i_L}$ occurs at least once in the tree starting from the $k$th child of the root. By the stationarity of the labeling process, the latter event has probability $a_{i_2\dots i_L}$. Thus,
\[
a_\ii=1-\PP(G_\ii)=1-\prod_{k=1}^M\big(1-\PP(G_{\ii,k}^c)\big)=1-(1-p_{i_1}a_{i_2\dots i_L})^M.
\]

Let
\[
p_{\min}:=\min_i p_i, \qquad\mbox{and} \qquad p_{\max}:=\max_i p_i.
\]
We assume that $p_{\min}>0$. This is not a real restriction: If $p_i=0$ for some $i$, we simply remove the map $f_i$ from the IFS and reduce the value of $N$. %We may also assume, by reordering the maps in the IFS if necessary, that $p_{\max}=p_N$.
 Since the function $x\mapsto 1-(1-p_{\min}x)^M$ is increasing and concave on $[0,1]$, it follows from \eqref{eq:recursion} that
\begin{equation} \label{eq:lower-linear}
a_{i_1i_2\dots i_L}\geq \gamma a_{i_2\dots i_L} \qquad\forall i_1,\dots,i_L,
\end{equation}
where $\gamma:=1-(1-p_{\min})^M>0$ is a universal constant. Furthermore, it follows from \eqref{eq:recursion} and Bernoulli's inequality that
\begin{equation} \label{eq:upper-linear}
a_{i_1i_2\dots i_L}\leq Mp_{i_1}a_{i_2\dots i_L}
\end{equation}
and
\begin{align} 
\begin{split}
a_{i_1i_2\dots i_L}&\geq Mp_{i_1}a_{i_2\dots i_L}-\binom{M}{2}p_{i_1}^2 a_{i_2\dots i_L}^2\\
&\geq Mp_{i_1}a_{i_2\dots i_L}(1-Ma_{i_2\dots i_L}).
\end{split}
\label{eq:quadratic-lower}
\end{align}
Recall that $L=mq+r+1$, where $m=\lfloor\sqrt{L-1}\rfloor$, $q=\sum_i k_i$ and $0\leq r<mN$. Our goal is to show that the probability $a_{i_j\dots i_L}$ cannot oscillate too much as $j$ moves backwards from $L$ to $1$. In view of the definition of $D_n$, we consider decrementing $j$ in steps of size $q$. Precisely, we always take $j$ to be one more than a multiple of $q$. To shorten notation, put
\[
b_l(\ii):=a_{i_{lq+1}\dots i_L}, \qquad \ii\in D_n, \quad l=0,1,\dots,m.
\]
First, \eqref{eq:lower-linear} implies
\begin{equation} \label{eq:remainder-block}
b_m(\ii)\geq \gamma^{L-mq}=\gamma^{r+1}\geq \gamma^{mN}.
\end{equation} 
Fix $\eta>0$. Take $l\in\{1,\dots,m\}$. We consider two cases.
If
\[
b_l(\ii)>\eta(Mp_{\max})^{-q},
\]
then by \eqref{eq:lower-linear},
\[
b_{l-1}(\ii)\geq \gamma^q b_l(\ii)>\eta\left(\frac{\gamma}{Mp_{\max}}\right)^q.
\]
Suppose instead that
\begin{equation} \label{eq:small-intermediate}
b_l(\ii)\leq\eta(Mp_{\max})^{-q}.
\end{equation}
Then $a_{i_j\dots i_L}\leq\eta$ for $(l-1)q<j\leq lq$ by \eqref{eq:upper-linear}, and so \eqref{eq:quadratic-lower} implies
\begin{equation} \label{eq:block-lower-inequality}
b_{l-1}(\ii)\geq \prod_{i=1}^N \big(Mp_i(1-\eta M)\big)^{k_i}b_l(\ii)
=\big(M(1-\eta M)\big)^q\left(\prod_{i=1}^N p_i^{k_i}\right)b_l(\ii).
\end{equation}
At this point it is convenient to define (as in the proof of the upper bound)
\[
\alpha_i:=\frac{\beta_i}{\beta_1+\dots+\beta_N}, \qquad i=1,\dots,N.
\]
From the left half of \eqref{eq:k-i-estimates} it follows that
\[
\frac{\sum_i\beta_i n}{m}<q+N+\frac{N}{m}.
\]
Hence, by the right half of \eqref{eq:k-i-estimates},
\[
k_i\leq \frac{\beta_i n+1}{m}=\frac{\alpha_i\sum_j\beta_j n+1}{m}<\alpha_i\left(q+N+\frac{N}{m}\right)+\frac{1}{m}<\alpha_i(q+2N)+1,
\]
so that
\[
\prod_{i=1}^N p_i^{k_i}\geq \prod_{i=1}^N p_i^{\alpha_i(q+2N)+1}\geq \prod_{i=1}^N p_i^{\alpha_i q}\cdot \prod_{i=1}^N p_{\min}^{2N\alpha_i+1}=p_{\min}^{3N}\prod_{i=1}^N p_i^{\alpha_i q}=:C_{\pp}\prod_{i=1}^N p_i^{\alpha_i q}.
\]
Putting this estimate back into \eqref{eq:block-lower-inequality} yields
\[
b_{l-1}(\ii)\geq C_{\pp}\big(M(1-\eta M)\big)^q \left(\prod_{i=1}^N p_i^{\alpha_i q}\right)b_l(\ii)
\geq C_{\pp}(1-\eta M)^q K_{\vec\alpha}^q\, b_l(\ii),
\]
where
\[
K_{\vec\alpha}:=\min\left\{1,M\prod_{i=1}^N p_i^{\alpha_i}\right\}=\min\left\{1,\prod_{i=1}^N (Mp_i)^{\alpha_i}\right\}.
\]
(We do the estimate this way, because it will later be important that $K_{\vec\alpha}\leq 1$.) Now let
\[
u(\ii):=\#\{l\in\{1,\dots,m\}:\ \mbox{\eqref{eq:small-intermediate} holds}\}.
\]
Then for each $\ii\in D_n$ we obtain, using that $u(\ii)\leq m$ and $u(\ii)q\leq mq\leq L$,
\begin{align*}
a_\ii&\geq\eta\left(\frac{\gamma}{Mp_{\max}}\right)^q(1-\eta M)^{u(\ii)q}C_{\pp}^{u(\ii)} K_{\vec\alpha}^{u(\ii)q}\, b_m(\ii)\\
&\geq \eta\left(\frac{\gamma}{Mp_{\max}}\right)^q(1-\eta M)^{mq}C_{\pp}^m K_{\vec\alpha}^{mq}\gamma^{mN}\\
&\geq \eta C_{\pp}^m\gamma^{mN}\left(\frac{\gamma}{Mp_{\max}}\right)^q(1-\eta M)^L K_{\vec\alpha}^L, 
\end{align*}
where we also used \eqref{eq:remainder-block}. Note that this bound does not depend on $\ii$. Since $m\leq \sqrt{L}$ and $q\leq L/m\sim\sqrt{L}$, the factors $C_{\pp}^m\gamma^{mN}$ and $\left(\frac{\gamma}{Mp_{\max}}\right)^q$ go to zero sub-exponentially (if at all), hence for all large enough $n$, we have
\begin{equation*} %\label{eq:a_i-estimate}
\min_{\ii\in D_n}a_\ii\geq (1-\eta M)^L (K_{\vec\alpha}-\eta)^L\geq \big\{(1-\eta M)(K_{\vec\alpha}-\eta)\big\}^{\sum_i\beta_i n+N},
\end{equation*}
by \eqref{eq:L-bounds}. Since $\eta$ was arbitrary and $N$ is constant, it follows that
\begin{equation} \label{eq:a_i-estimate}
\liminf_{n\to\infty}\frac{1}{n}\log\left(\min_{\ii\in D_n}a_\ii\right)\geq \sum_i\beta_i \log K_{\vec\alpha}.
\end{equation}

\medskip
{\em Step 4. (Conclusion)} Clearly, we have
\[
\sum_{\ii\in\Gamma_n}a_\ii\geq \sum_{\ii\in D_n}a_\ii \geq \#D_n\cdot \min_{\ii\in D_n}a_\ii.
\]
Thus, by \eqref{eq:D_n-lower-estimate} and \eqref{eq:a_i-estimate},
\begin{align*}
\liminf_{n\to\infty} \frac{1}{n}\log\left(\sum_{\ii\in\Gamma_n}a_\ii\right)&\geq \liminf_{n\to\infty} \frac{\log\#D_n}{n}+\liminf_{n\to\infty} \frac{\log \min_{\ii\in D_n}a_\ii}{n}\\
&\geq \psi(\boldsymbol{\beta})+\sum_{i=1}^N \beta_i\log K_{\vec\alpha}.
\end{align*}
Recalling that $\alpha_i=\beta_i/(\beta_1+\dots+\beta_N)$ and noting that
\begin{align*}
\sum_{i=1}^N \beta_i\log K_{\vec\alpha}&=\sum_{i=1}^N\beta_i\cdot\min\left\{0,\sum_i \alpha_i\log(Mp_i)\right\}\\
&=\min\left\{0,\sum_i\beta_i\log(Mp_i)\right\}=\min\big\{0,\phi(\boldsymbol{\beta})\big\},
\end{align*}
we complete the proof.
\end{proof}


\section{Solving the constrained optimization} \label{sec:main-proof}

We first establish the existence and uniqueness of the pair $(\hat{s},\hat{t})$ in Theorem \ref{thm:main} (iii).

\begin{lemma} \label{lem:s-t-existence}
Assume
\begin{equation} \label{eq:main-case-re}
\sum_{i=1}^N r_i^{s_0}\log(Mp_i)<0<\sum_{i=1}^N p_i r_i^{\tilde{s}}\log(Mp_i).
\end{equation}
Then there is a unique pair $(\hat{s},\hat{t})$ of real numbers, with $\hat{s}>0$, satisfying the equations
\begin{gather} 
\sum_{i=1}^N r_i^{\hat{s}}(Mp_i)^{\hat{t}}=1, \label{eq:s-t-equation1} \\
\sum_{i=1}^N r_i^{\hat{s}}(Mp_i)^{\hat{t}}\log(Mp_i)=0.  \label{eq:s-t-equation2}
\end{gather}
\end{lemma}

\begin{proof}
Define the functions
\[
G_1(s,t):=\sum_{i=1}^N r_i^s (Mp_i)^t, \qquad G_2(s,t):=\sum_{i=1}^N r_i^s (Mp_i)^t\log(Mp_i).
\]
Note that for fixed $t$, $G_1(s,t)$ is strictly decreasing in $s$, with $\lim_{s\to\infty}G_1(s,t)=0$ and $\lim_{s\to-\infty}G_1(s,t)=\infty$. Thus, for fixed $t$, the equation $G_1(s,t)=1$ has a unique solution $s=g(t)$, say.  
%\textcolor{red}{Then
%\[
%0=g^\prime(t) D_1G_1(g(t), t)+D_2G_1=g^\prime(t) G_2+D_2 G_1,
%\]
%where $D_i$ is the partial derivative in the $i$-th coordinate},  and thus
Differentiating implicitly yields
\begin{equation} \label{eq:first-derivative}
g'(t)=-\frac{\sum_i r_i^s(Mp_i)^t\log(Mp_i)}{\sum_i r_i^s(Mp_i)^t\log r_i}.
\end{equation}
This shows that $G_2(s,t)=0$ precisely at those points $(s,t)$ where $s=g(t)$ and $g'(t)=0$. In other words, the curves
\[
C_1: G_1(s,t)=1 \qquad\mbox{and} \qquad C_2: G_2(s,t)=0
\]
intersect each other at those and only those points where $C_1$ has a horizontal tangent line.

Next, we rewrite \eqref{eq:first-derivative} as
\[
0=\sum_{i=1}^N r_i^{g(t)}(Mp_i)^t\{g^\prime(t)\log r_i+\log(Mp_i)\}.
\]
Differentiating implicitly once more, we find
\[
0=\sum_{i=1}^N r_i^{g(t)}(Mp_i)^t\left[g^{\prime \prime}(t)\log r_i+\{g^\prime(t)\log r_i+\log(Mp_i)\}^2\right].
\]
(These equations are well known in the multifractal analysis of self-similar sets.) It follows that $g''(t)\geq 0$, and so $g$ is convex. In fact, it is strictly convex unless $Mp_i=r_i^\lambda$ for all $i$ and some constant $\lambda$. But we can rule out the latter possibility because this would imply that $\log(Mp_i)$ has constant sign, contradicting \eqref{eq:main-case}. Hence, there is at most one point where $g'(t)=0$, and so $C_1$ and $C_2$ intersect at most once.

In order to show that $C_1$ and $C_2$ do intersect, we need to show that $g'(t)=0$ for some $t$. Observe that the equation $\sum_i p_i r_i^{\tilde s}=1/M$ is equivalent to $G_1(\tilde{s},1)=1$, so $g(1)=\tilde{s}$, and hence
\[
\sum_i r_i^{g(1)}(Mp_i)^1\log(Mp_i)=\sum_i Mp_i r_i^{\tilde s}\log(Mp_i)>0
\]
by the second inequality in \eqref{eq:main-case}. This implies $g'(1)>0$ by \eqref{eq:first-derivative}. On the other hand, the equation $\sum_i r_i^{s_0}=1$ is equivalent to $G_1(s_0,0)=1$, so $g(0)=s_0$ and hence,
\[
\sum_i r_i^{g(0)}(Mp_i)^0\log(Mp_i)=\sum_i r_i^{s_0}\log(Mp_i)<0
\]
by the first inequality in \eqref{eq:main-case}. This implies $g'(0)<0$. Therefore, there exists $\hat{t}\in(0,1)$ such that $g'(\hat{t})=0$, as required. 

It remains to verify that $g(\hat{t})>0$. By the second inequality in \eqref{eq:main-case}, $Mp_{i_0}>1$ for at least one $i_0$, and since $\hat{t}>0$, we have $(Mp_{i_0})^{\hat t}>1$.  By the definition of $g$, we thus have
\[
\sum_i r_i^{g(\hat{t})}(Mp_i)^{\hat t}=1<\sum_i(Mp_i)^{\hat t},
\]
and this implies $g(\hat{t})>0$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:main}]
(i) Assume 
\begin{equation} \label{eq:M-large-re}
\sum_{i=1}^N r_i^{s_0}\log(Mp_i)\geq 0,
\end{equation}
and recall that 
\begin{gather}
\psi(x_1,\dots,x_N):=\sum_{i=1}^N x_i\left(\log\sum_{j=1}^N x_j-\log x_i\right), \\
\phi(x_1,\dots,x_N):=\sum_{i=1}^N x_i\log(Mp_i), \\
h(x_1,\dots,x_N):=-\sum_{i=1}^N x_i\log r_i.
\end{gather}
Put $\boldsymbol\beta=(\beta_1,\dots,\beta_N)$, where
\begin{equation} \label{eq:case-1-optimal-beta}
\beta_i:=-\frac{r_i^s}{\sum_j r_j^s\log r_j}, \qquad i=1,\dots,N.
\end{equation}
It is immediate that $h(\boldsymbol{\beta})=1$, while \eqref{eq:M-large-re} implies $\phi(\boldsymbol{\beta})=\sum_i\beta_i\log(Mp_i)\geq 0$. Furthermore,
\[
\psi(r_1^{s_0},\dots,r_N^{s_0})=-s_0\sum_i r_i^{s_0}\log r_i,
\]
since $\sum_i r_i^{s_0}=1$. Thus, since $\psi(\alpha\xx)=\alpha\psi(\xx)$ for all $\alpha>0$ and $\xx\in[0,\infty)^N$ (cf. \eqref{eq:psi-homogeneous}),
\[
\psi(\boldsymbol{\beta})=-\frac{1}{\sum_j r_j^{s_0}\log r_j}\psi(r_1^{s_0},\dots,r_N^{s_0})=s_0.
\]
Applying Theorem \ref{thm:variational} we conclude $\dim_H F\geq s_0$ almost surely. Since $F \subset \Lambda$, the reverse inequality holds trivially. Thus, $\dim_H F=s_0$ almost surely.

%We can also see, by a Lagrange multiplier argument, that $\boldsymbol{\beta}$ given by \eqref{eq:case-1-optimal-beta} is the unique vector maximizing $\psi(\xx)$ subject to $h(\xx)=1$.

(ii) Next, assume 
\begin{equation} \label{eq:M-small-re}
\sum_{i=1}^N p_i r_i^{\tilde{s}}\log(Mp_i)\leq 0,
\end{equation}
where $\tilde{s}$ satisfies $\sum_i p_i r_i^{\tilde s}=1/M$. Put
\begin{equation} \label{eq:case-2-optimal-beta}
\beta_i':=-\frac{p_i r_i^{\tilde{s}}}{\sum_j p_j r_j^{\tilde s}\log r_j}, \qquad i=1,\dots,N,
\end{equation}
and $\boldsymbol{\beta}':=(\beta_1',\dots,\beta_N')$. Clearly $h(\boldsymbol{\beta}')=1$, and \eqref{eq:M-small-re} implies $\phi(\boldsymbol{\beta}')\leq 0$. Note that
\begin{align*}
\psi\big(Mp_1 r_1^{\tilde s},\dots, Mp_N r_N^{\tilde s}\big)&=-\sum_i Mp_i r_i^{\tilde s}\log(Mp_i r_i^{\tilde s})\\
&=-\sum_i Mp_i r_i^{\tilde s}\big(\log(Mp_i)+\tilde{s}\log r_i\big).
\end{align*}
So by \eqref{eq:psi-homogeneous},
\[
\dim_H F\geq \psi(\boldsymbol{\beta}')+\phi(\boldsymbol{\beta}')=\frac{\sum_i Mp_i r_i^{\tilde s}\big(\log(Mp_i)+\tilde{s}\log r_i\big)}{\sum_j Mp_j r_j^{\tilde s}\log r_j}-\frac{\sum_i p_i r_i^{\tilde s}\log(Mp_i)}{\sum_j p_j r_j^{\tilde s}\log r_j}=\tilde{s}.
\]
The reverse inequality follows since the vector $\boldsymbol{\beta}'$ defined by \eqref{eq:case-2-optimal-beta} maximizes $\psi(\xx)+\phi(\xx)$ subject to the constraint $h(\xx)=1$, as is easily seen by a Lagrange multiplier computation.
Hence, $\dim_H F=\tilde{s}\leq s_0$ almost surely.

Finally, we show that $\tilde{s}=s_0$ if and only if $N=M$ and $p_i=1/N$ for all $i$. Let $\boldsymbol{\beta}$ again be the vector defined by \eqref{eq:case-1-optimal-beta}. If $\boldsymbol{\beta}\neq\boldsymbol{\beta}'$, then 
\[
s_0=\psi(\boldsymbol{\beta})>\psi(\boldsymbol{\beta}')\geq \psi(\boldsymbol{\beta}')+\phi(\boldsymbol{\beta}')=\tilde{s},
\]
since $\boldsymbol{\beta}$ is the unique maximizer of $\psi(\xx)$ subject to $h(\xx)=1$. On the other hand, if $\boldsymbol{\beta}=\boldsymbol{\beta}'$, then it follows from equating the right hand sides of \eqref{eq:case-1-optimal-beta} and \eqref{eq:case-2-optimal-beta} that $p_i$ is constant in $i$, and so $p_i=1/N$ for $i=1,\dots,N$. Hence by \eqref{eq:weighted-Moran}, $\sum_i r_i^{\tilde{s}}=N/M$. So if $\tilde{s}=s_0$, it must be the case that $N=M$ and $p_i=1/N$ for all $i$. The reverse implication is obvious.

(iii) Assume \eqref{eq:main-case-re}. The existence and uniqueness of $(\hat{s},\hat{t})$ were established in Lemma \ref{lem:s-t-existence}. Let $\boldsymbol{\beta}$ and $\boldsymbol{\beta}'$ be the vectors from \eqref{eq:case-1-optimal-beta} and \eqref{eq:case-2-optimal-beta}, respectively. Since $\psi$ is unimodal on the hyperplane $h(\xx)=1$ with its constrained maximum at $\boldsymbol{\beta}$ and $\phi(\boldsymbol{\beta})<0$ by the first inequality in \eqref{eq:main-case}, it follows that 
\begin{align*}
\max\big\{\psi(\xx)&+\min\{0,\phi(\xx)\}: \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)\geq 0\big\}\\
&=\max\big\{\psi(\xx): \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)\geq 0\big\}\\
&=\max\big\{\psi(\xx): \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)=0\big\}\\
&=\max\big\{\psi(\xx)+\min\{0,\phi(\xx)\}: \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)=0\big\}.
\end{align*}
Likewise, since $\psi+\phi$ is unimodal on $\{\xx:h(\xx)=1\}$ with its constrained maximum at $\boldsymbol{\beta}'$ and $\phi(\boldsymbol{\beta}')>0$ by the second inequality in \eqref{eq:main-case}, we have
\begin{align*}
\max\big\{\psi(\xx)&+\min\{0,\phi(\xx)\}: \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)\leq 0\big\}\\
&=\max\big\{\psi(\xx)+\phi(\xx): \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)\leq 0\big\}\\
&=\max\big\{\psi(\xx)+\phi(\xx): \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)=0\big\}\\
&=\max\big\{\psi(\xx)+\min\{0,\phi(\xx)\}: \xx\in[0,\infty)^N, h(\xx)=1, \phi(\xx)=0\big\}.
\end{align*}
Thus, the constrained maximum of $\psi(\xx)+\min\{0,\phi(\xx)\}$ over $\{\xx:h(\xx)=1\}$ must be attained on the hyperplane $\phi(\xx)=0$. Solving the Lagrange multiplier problem 
\[
\mbox{maximize}\ \psi(\xx)\qquad \mbox{subject to}\qquad h(\xx)=1, \quad \phi(\xx)=0
\]
yields that the maximum is attained (uniquely) at the point $\hat{\boldsymbol\beta}=(\hat{\beta}_1,\dots,\hat{\beta}_N)$ given by
\[
\hat{\beta}_i=-\frac{r_i^{\hat s}(Mp_i)^{\hat t}}{\sum_j r_j^{\hat s}(Mp_j)^{\hat t}\log r_j}, \qquad i=1,\dots,N.
\]
We then have
\begin{align*}
\dim_H F&=\psi\big(\hat{\boldsymbol\beta}\big)=-\frac{\psi\big(r_1^{\hat s}(Mp_1)^{\hat t},\dots,r_N^{\hat s}(Mp_N)^{\hat t}\big)}{\sum_i r_i^{\hat s}(Mp_i)^{\hat t}\log r_i}\\
&=\frac{\sum_i r_i^{\hat s}(Mp_i)^{\hat t}\log\big(r_i^{\hat s}(Mp_i)^{\hat t}\big)}{\sum_i r_i^{\hat s}(Mp_i)^{\hat t}\log r_i}\\
&=\frac{\sum_i r_i^{\hat s}(Mp_i)^{\hat t}\big\{\hat{s}\log r_i+\hat{t}\log(Mp_i)\big\}}{\sum_i r_i^{\hat s}(Mp_i)^{\hat t}\log r_i}=\hat{s},
\end{align*}
where the first equality used \eqref{eq:psi-homogeneous} and \eqref{eq:s-t-equation1}, and the last inequality follows from \eqref{eq:s-t-equation2}. Finally, that $\hat{s}<s_0$ follows since $\hat{\boldsymbol\beta}\neq\boldsymbol{\beta}$ (because $\phi(\hat{\boldsymbol\beta})=0\neq\phi(\boldsymbol{\beta})$), and so $\hat{s}=\psi(\hat{\boldsymbol\beta})<\psi(\boldsymbol{\beta})=s_0$.
\end{proof}


\section{Proofs of the special cases} \label{sec:corollaries}

\begin{proof}[Proof of Corollary \ref{cor:homogeneous}]
Suppose $r_i=r$ for $i=1,\dots,N$. Then \eqref{eq:Moran} and \eqref{eq:weighted-Moran} give
\[
s_0=-\frac{\log N}{\log r}, \qquad \tilde{s}=-\frac{\log M}{\log r}.
\]
Furthermore, the conditions \eqref{eq:M-large-condition} and \eqref{eq:M-small-condition} simplify to $M\geq U(N,\pp)$ and $M\leq L(N,\pp)$, respectively. Finally, for $L(N,\pp)\leq M\leq U(N,\pp)$, \eqref{eq:s-t-equation-a} becomes
\begin{equation} \label{eq:simpler-s-t-equation-a}
r^{\hat s}\sum_i (Mp_i)^{\hat t}=1,
\end{equation}
and \eqref{eq:s-t-equation-b} reduces to
\[
\sum_i p_i^{\hat t}\log(Mp_i)=0.
\]
Putting $\lambda:=\hat{t}$, we see that $\lambda$ satisfies \eqref{eq:mu-equation}, and then \eqref{eq:simpler-s-t-equation-a} gives the desired expression for $\dim_H F$.
%\[
%\dim_H F=\hat{s}=-\frac{\log(\sum_i(Mp_i)^\lambda)}{\log r}.
%\]
\end{proof}

\begin{proof}[Proof of Theorem \ref{cor:two-maps-homogeneous}]
In principle, it is possible (but cumbersome!) to derive Theorem \ref{cor:two-maps-homogeneous} directly from Corollary \ref{cor:homogeneous}. It is simpler, however, to deduce it from Theorem \ref{thm:variational}. For $N=M=2$, we are always in the case $L(N,\pp)\leq M\leq U(N,\pp)$, so the constrained maximum in Theorem \ref{thm:variational} is attained on the line 
\[
\phi(x_1,x_2)=x_1\log(2p)+x_2\log(2(1-p))=0.
\]
Together with the equation $h(x_1,x_2)=-(x_1+x_2)\log r=1$, this gives a unique point $(x_1,x_2)$ which satisfies
\[
\frac{x_1}{x_1+x_2}=-\frac{\log(2(1-p))}{\log p-\log(1-p)}=1-\xi, \qquad \frac{x_2}{x_1+x_2}=\frac{\log(2p)}{\log p-\log(1-p)}=\xi.
\]
Thus,
\begin{align*}
\dim_H F&=\psi(x_1,x_2)=(x_1+x_2)\psi\left(\frac{x_1}{x_1+x_2},\frac{x_2}{x_1+x_2}\right)\\
&=-\frac{\psi(1-\xi,\xi)}{\log r}=\frac{\xi\log\xi+(1-\xi)\log(1-\xi)}{\log r},
\end{align*}
as desired.
\end{proof}

\begin{proof}[Proof of Theorem \ref{cor:two-maps-nonhomogeneous}]
In the non-homogeneous case, any of the three cases in Theorem \ref{thm:main} can apply, even for $N=M=2$. Here inequality \eqref{eq:M-large-condition} becomes
\begin{equation*} %\label{eq:p-inequality}
g(p):=r_1^{s_0}\log(2p)+r_2^{s_0}\log(2(1-p))\geq 0.
\end{equation*}
Note that $g(p)\to -\infty$ as $p\searrow 0$, $g(1/2)=0$, and
\[
g'(p)=\frac{r_1^{s_0}}{p}-\frac{r_2^{s_0}}{1-p}<0 \qquad\mbox{for $p\geq 1/2$},
\]
since $r_1<r_2$. Hence $g(p)$ has an additional zero $p_*$ in $(0,1/2)$, and $g(p)\geq 0$ if and only if $p_*\leq p\leq 1/2$.

Similarly, \eqref{eq:M-small-condition} becomes
\[
\tilde{g}(p):=pr_1^{\tilde s}\log(2p)+(1-p)r_2^{\tilde s}\log(2(1-p))\leq 0,
\]
where $\tilde{s}$ is given by \eqref{eq:s-tilde-equation}. Differentiating twice gives
\[
\tilde{g}'(p)=r_1^{\tilde s}\big\{1+\log(2p)\big\}-r_2^{\tilde s}\big\{1+\log(2(1-p))\big\}
\]
and
\[
\tilde{g}''(p)=\frac{r_1^{\tilde s}}{p}+\frac{r_2^{\tilde s}}{1-p}\geq 0.
\]
Thus, $\tilde{g}$ is convex. Furthermore, $\tilde{g}(1/2)=0$ and $\tilde{g}'(1/2)=r_1^{\tilde s}-r_2^{\tilde s}<0$. Finally, $\tilde{g}(p)\to\infty$ as $p\nearrow 1$. Hence, $\tilde{g}(p)$ has an additional zero $p^*$ in $(1/2,1)$, and $\tilde{g}(p)\leq 0$ if and only if $1/2\leq p\leq p^*$.

In the third case (when $p\leq p_*$ or $p\geq p^*$), the formula for $\hat{s}$ follows by solving the linear system
\begin{align*}
h(x_1,x_2)&=-x_1\log r_1-x_2\log r_2=1,\\
\phi(x_1,x_2)&=x_1\log(2p)+x_2\log(2(1-p))=0,
\end{align*}
and substituting the result into $\psi$.
\end{proof}


