    %\State $A_i \gets Z \cup \big\{ W \in X \backslash\{X_i\} : W \preceq_{\mathbf M} X_i \big\}$
    %\State $A_j \gets Z \cup \big\{ W \in X \backslash\{X_j\} : W \preceq_{\mathbf M} X_j \big\}$
    \State $S \gets MB(X_i) \cup MB(X_j)$
    \If{$X_i \indep X_j \mid S$} 
      \State  $\mathbf M_{ij} \gets$ $i \sim j$, \texttt{converged} $\gets$ \texttt{FALSE} 
    \Else
        \For{ $W \in S$ }
            \If{$W \indep X_j \mid S_{\backslash W} \cup [X_i]$}
              \State  $\mathbf M_{ij} \gets$ $i \prec j$, \texttt{converged} $\gets$ \texttt{FALSE}
            \ElsIf{$W \indep X_i \mid S_{\backslash W} \cup [X_j]$}
              \State  $\mathbf M_{ij} \gets$ $j \prec i$, \texttt{converged} $\gets$ \texttt{FALSE}
            \ElsIf{$W \not\indep X_j \mid S_{\backslash W} \cup [X_i]$}
              \State  $\mathbf M_{ij} \gets \mathbf M_{ij} \land j \preceq i$, \texttt{converged} $\gets$ \texttt{FALSE}
            \ElsIf{$W \not\indep X_i \mid S_{\backslash W} \cup [X_j]$}
            \State  $\mathbf M_{ij} \gets \mathbf M_{ij} \land i \preceq j$, \texttt{converged} $\gets$ \texttt{FALSE}
            \EndIf 
        \EndFor
    \EndIf
  \EndFor
  \State $\mathbf M \gets \texttt{Closure}(\mathbf M)$
  \ForAll{$X_i \in X$}
  \State $A_i \gets MB(X_i) \cup \{ W : W \preceq_{\mathbf M} X_i\}$
\State $MB(X_i) \gets \texttt{GrowShrink}(X_i, A_i)$
\EndFor
  %\State $t \gets t + 1$
\EndWhile


\end{algorithmic}
\end{algorithm}





