\caption{The disconnectivity graph for the Lennard-Jones-7 cluster in 2D and descriptions of its local potential energy minima and saddles. $E$ is the energy value, and PGO is the point group order.}
\label{fig:LJ7digraph}
\end{figure}
\begin{figure}[htbp]
