\section{Background: theory and methods}
\label{sec:background}
In this section, we review the necessary background to motivate and explain the proposed framework for learning CVs and estimating rates.

\subsection{Effective dynamics in collective variables}
The effective dynamics of a single collective variable with underlying overdamped Langevin dynamics were analyzed and quantified by Legoll and Lelievre~\cite{Legoll_2010} and then extended to a vector of CVs with underlying overdamped Langevin or Langevin dynamics by Duong et al.~\cite{Sharma_2018}.

Let a system be governed by the  \textit{overdamped Langevin equation} in $\Omega_x\subset\mathbb{R}^{n}$,
\begin{equation}
\label{eq:overdampedLangevin}
dX_t = - \nabla V(X_t)dt + \sqrt{2\beta^{-1}}dW_t,
\end{equation} 
where the potential energy function $V(x)$ is smooth almost everywhere, has a finite number of isolated minima, and $\beta^{-1} = k_B T$ is the temperature in units of Boltzmann's constant. 
The invariant density is given by
\begin{align}
\label{eq: gibbs}
    \mu_X(x) = Z^{-1}e^{-\beta V(x)},\quad Z = \int_{\mathbb{R}^{n}}e^{-\beta V(x)}dx.
\end{align}
Let $\xi:\Omega_X\rightarrow\Omega_Y$ map $X_t$ to a $d$-dimensional CV space. The governing SDE for $\xi$ can be readily written out using Ito's formula; however, this SDE is not closed as it contains coefficient functions that depend on $X_t$. Legoll and Lelievre~\cite{Legoll_2010} and Duong et al.~\cite{Sharma_2018} proposed the following closure for the effective dynamics of $Y_t = \xi(X_t)$:
\begin{equation}\label{eq:dynamics_Lelievre}
    dY_t = b(Y_t)dt + \sqrt{2\beta^{-1}A(Y_t)}dW_t
\end{equation}
where 
\begin{align}\label{eq:b_CVs}
    & b(y) = \mathbb{E}_\mu \left[(D\xi \nabla U - \beta^{-1}\Delta \xi)(X_t)|\xi(X_t) = y \right],\\
    \label{eq:A_CVs}
    & A(y) = \mathbb{E}_\mu\left[|D\xi D\xi^\top|(X_t)|\xi(X_t) = y \right],
\end{align}
and $D\xi$ is the Jacobian matrix of $\xi$. 
Under the assumption that $D\xi D\xi^\top\succeq \delta I_d$ where $\delta > 0$ is a constant and $I_d$ is a $d\times d$ identity matrix, SDE~\eqref{eq:dynamics_Lelievre} is equivalent to~\cite{Sule2025butane} 
\begin{align}    
    dY_t &= [-M(Y_t)\nabla F(Y_t) + \beta^{-1}\nabla \cdot M(Y_t)]dt + \sqrt{2\beta^{-1}}M(Y_t)^{\frac{1}{2}}dW_t, \label{eq:dynamics_Maragliano}
\end{align}
obtained by Maragliano et al.~\cite{Maragliano} by an argument based on the variational property of the committor.
In \eqref{eq:dynamics_Maragliano},
$F(Y_t)$ and $M(Y_t)$ are the free energy and the diffusion tensor defined as 
\begin{equation}\label{eq:FE}
    F(y) = -\beta^{-1}\ln \left(\int_{\Omega_x} Z^{-1} e^{-\beta U(x)}\prod_{l = 1}^d \delta(\xi_l(x) - y_l)dx\right),
\end{equation}
\begin{align}
    M(y) &= e^{-\beta F(y)}\int_{\Omega_x}D\xi(x)D\xi^\top(x)Z^{-1} e^{-\beta V(x)}\prod_{l = 1}^d \delta(\xi_l(x) - y_l)dx.\label{eq:DMatrix}
\end{align}
The delta-function in the definitions of the free energy (\ref{eq:FE}) and diffusion matrix (\ref{eq:DMatrix}) is interpreted according to the co-area formula \cite{co-area}. I.e., for an integrable function $f: \mathbb{R}^n \rightarrow \mathbb{R}$,
\begin{align}
  \int_{\Omega_x} f(x) \delta(\xi_l(x) - y_l)dx &= \int_{\Omega_{y_l}}\left(\int_{\Sigma(y'_l)}f|\nabla \xi_l|^{-1}\delta(y'_l - y_l)d\sigma \right)dy'_l  \notag\\
&= \int_{\Sigma(y_l)}f\|\nabla \xi_l\|^{-1}d\sigma,\label{eq:coarea}
\end{align}
where $\Sigma(y_l) = \{x \in \mathbb{R}^n, y_l \in \mathbb{R}: \xi_l(x) = y_l\}$ is the level set of the function $\xi_l$, $d\sigma$ denotes the surface element of $\Sigma(y_l)$, and
it is assumed that $\|\nabla \xi_l\|^{-1} \neq 0$.

The invariant density for SDE \eqref{eq:dynamics_Maragliano} is 
\begin{equation}
    \label{eq:muz}
    \mu_Y(y)=Z^{-1}_Fe^{-\beta F(y)},\quad Z_F: = \int_{\Omega_Y}e^{-\beta F(y)}.
\end{equation}




\subsection{Coarse-graining error in the transition rate}
How accurately does the effective dynamics governed by \eqref{eq:dynamics_Lelievre} represent the dynamics \eqref{eq:overdampedLangevin}? Let metastable sets $A_y$ and $B_y$ be chosen in the CV space and then lifted to the original space, i.e.
\begin{align*}
    A_x &= \{x\in\mathbb{R}^n~|~\xi(x)\in A_y\},\\
    B_x &= \{x\in\mathbb{R}^n~|~\xi(x)\in B_y\}.
\end{align*}
An important quantity of interest is the transition rate between the sets $A$ and $B$, 
\begin{equation}
    \label{eq:nuAB}
    \nu_{AB}: = \lim_{T\rightarrow\infty}\frac{N_{AB}(T)}{T},
\end{equation}
where $T$ is the elapsed time and $N_{AB}(T)$ is the number of transitions from $A$ to $B$ observed during the time $T$.
The transition rate between $A$ and $B$ can be expressed via the committor function $q$ whose value at any point of space is the probability that the process starting at this point will first hit $A$ rather than $B$~\cite{EVE2006,EVE2010}. The committor is the solution of the following boundary value problem for the backward Kolmogorov equation:
\begin{equation}
    \label{eq:commBVP}
    \begin{cases}
        \mathcal{L}q = 0,&x\in\Omega\backslash (A\cup B)\\
        ~~q = 0,&x\in\partial A\\
        ~~q = 1,& x \in \partial B
    \end{cases},
\end{equation}
where $\mathcal{L}$ is the generator of the SDE governing the stochastic process.
The transition rates from $A_x$ to $B_x$ and from $A_y$ to $B_y$ are equal, respectively, to
\begin{equation}
    \label{eq:nuABx}
    \nu_{A_xB_x} = \beta^{-1}\int_{\Omega^x_{A_xB_x}}\|\nabla q(x)\|^2\mu_X(x) dx
\end{equation}
and 
\begin{equation}
    \label{eq:nuABy}
    \tilde{\nu}_{A_yB_y} = \beta^{-1}\int_{\Omega^y_{A_y B_y}}\nabla \tilde{q}(y)^\top M(y) \nabla \tilde{q}(y)\mu_Y(y) dy,
\end{equation}
where $q(x)$ and $\tilde{q}(y)$ are the committors in the original space and the CV space respectively,  $\Omega_{AB}^x:=\Omega_x\backslash (A_x\cup B_x)$, and $\Omega_{AB}^y:=\Omega_y\backslash (A_y\cup B_y)$. Zhang et al.~\cite{ZhangHartmannSchutte_2016} have proven that the transition rate in the CV space, $\tilde{\nu}_{A_yB_y}$, is always greater or equal to the rate between the corresponding sets in the original space, $\nu_{A_xB_x}$, and the relationship between these rates in the case of the governing SDE being the overdamped Langevin \eqref{eq:overdampedLangevin} is
\begin{equation}
    \label{eq:rateZHS}
    \tilde{\nu}_{A_yB_y} = \nu_{A_xB_x} +\beta^{-1}\int_{\Omega^x_{A_xB_x}}\left\|\nabla(q(x) - \tilde{q}(\xi(x))\right\|^2\mu_X(x)dx.
\end{equation}
Moreover, if the CV is the committor, i.e., if $\xi(x)\equiv q(x)$, then~\cite{ZhangHartmannSchutte_2016} $\tilde{\nu}_{A_yB_y} = \nu_{A_xB_x}$. This means that the committor is an optimal CV for the preservation of the transition rate in the reduced model. This fact motivates our choice of the committor of the reduced model as the reaction coordinate for the forward flux sampling. 

\subsection{Coarse-graining error measured by the relative entropy and the orthogonality condition}
Legoll and Lelievre~\cite{Legoll_2010} and Duong et al.~\cite{Sharma_2018} measured the error between $Y_t$, governed by \eqref{eq:dynamics_Lelievre}, and $\xi(X_t)$, where $X_t$ is governed by \eqref{eq:overdampedLangevin}, by the relative entropy of the probability densities $\phi(t,\cdot)$ of $Y_t$ and $\psi(t,\cdot)$ of $\xi(X_t)$: 
\begin{align} 
    \mathcal{H}(t) &:=H\left(\psi^{\xi}(t, \cdot)|\phi(t, \cdot)\right) = \int_{\Omega_y}\psi^{\xi}(t, y)\log\left(\frac{\psi^{\xi}(t, y)}{\phi(t, y)}\right)dy.\label{eq:relative_entropy1}
\end{align}
Under several technical assumptions, the difference $\mathcal{H}(t) - \mathcal{H}(0)$ is bounded from above by~\cite{Legoll_2010,Sharma_2018} 
\begin{equation}
    \mathcal{H}(t) - \mathcal{H}(0) \le C_1 + C_2\left[H\left(\psi(0,\cdot)|\mu_X\right) - H\left(\psi(t,\cdot)|\mu_X\right)\right],
\end{equation}
where $\psi(t,\cdot)$ is the probability density of $X_t$ and the expressions for $C_1$ and $C_2$ involve several technical constants that are hard to estimate in practice. The constant $C_1$ is zero if the Jacobian matrix of $\xi$, $D\xi$, is constant along its level sets. The constant $C_2$ is small if the following \emph{orthogonality condition} holds. Suppose that the potential function $V(x)$ in \eqref{eq:overdampedLangevin} is decomposed as
\begin{equation}
\label{eq:Vdecomp}
    V(x) = V_0(x) + \epsilon^{-1}V_1(x),
\end{equation}
where $V_1(x) \ge 0$, the zero level set of $V_1$ has co-dimension one, and $\epsilon$ is a small parameter. In this case, the invariant density of \eqref{eq:overdampedLangevin} is concentrated near the set where $V_1 = 0$, which we call the \emph{residence manifold}.
Then $C_2$ is $O(\epsilon)$ if~\cite{Legoll_2010,Sharma_2018}
\begin{equation}
    \label{eq:OC}
    D\xi(x)\nabla V_1(x) = 0,
\end{equation}
i.e., if \emph{the level sets of the CV are orthogonal to the residence manifold}.

Our method for learning CVs is based on the orthogonality condition \eqref{eq:OC}. We first learn the residence manifold in the feature space that respects the system's symmetries using \emph{diffusion maps} and \emph{diffusion nets}, and then learn CVs whose level sets are normal to the residence manifold using \emph{autoencoders}.


\subsection{Diffusion maps and diffusion nets}
\subsubsection{Diffusion maps}
The diffusion map algorithm~\cite{CoifmanLafon2006,Coifman_2008} is a widely used method for manifold learning. Let $\{x_i\}_{i = 1}^N \subset \mathbb{R}^n$ be a dataset consisting of independent samples drawn from a probability density $\rho(x)$ residing on a low-dimensional manifold $\mathcal{M}$. The algorithm begins by computing the pairwise similarities between data points using a kernel function. Commonly used is the Gaussian kernel
\begin{equation}
\label{eq:Gkernel}
    k_\epsilon(x_i, x_j) = \exp\left( -\frac{\|x_i - x_j\|^2}{2\epsilon} \right),
\end{equation}
where the \textit{kernel bandwidth} $\epsilon > 0$ is a hyperparameter. The $N\times N$ similarity matrix $K_{\epsilon}$ has entries $K_\epsilon(i,j) = k_\epsilon(x_i, x_j)$. A remarkable feature of diffusion maps is that the user does not need to know the sampling density. Instead, the sampling density at the data points is estimated as the vector of row-wise averages:
\begin{equation}
\label{eq:rho_eps}
    \rho^N_\epsilon(i) = \frac{1}{N} \sum_{j = 1}^N K_\epsilon(i, j).
\end{equation}
Indeed, as $\epsilon\rightarrow 0$ and $N\rightarrow\infty$, we have:
\begin{align*}
    \rho(x_i) &= \int_{\mathbb{R}^n}\rho(y)\delta(x_i-y)dy\\
    & = \lim_{\epsilon\rightarrow0}(2\pi\epsilon)^{-n/2}\int_{\mathbb{R}^n}\rho(y)k_{\epsilon}(x_i,y)dy \\
    & = \lim_{\epsilon\rightarrow 0}\frac{1}{(2\pi\epsilon)^{-n/2}}\lim_{N\rightarrow\infty}\frac{1}{N} \sum_{j = 1}^N K_\epsilon(i, j).
\end{align*}
Since the normalization factor of $(2\pi\epsilon)^{-n/2}$ would cancel out in the construction of the Markov matrix below, it is immediately omitted in \eqref{eq:rho_eps}. 


To eliminate the influence of the sampling density $\rho$ on the Markov matrix, the kernel matrix is right-normalized as
\begin{equation}
\label{eq:K1}
    \tilde{K}_{\epsilon}: = K_\epsilon D_\epsilon^{-1},
\end{equation}
where $D_\epsilon: = {\sf diag}\{\rho^N_\epsilon(x_1), \ldots, \rho^N_\epsilon(x_N)\}$ is a diagonal matrix. Then the generator matrix constructed by the diffusion map approximates the Laplace-Beltrami operator. 
Alternatively, to construct an approximation to the generator of the overdamped Langevin dynamics with invariant density $\mu_X$ using enhanced sampling data, one needs to right-multiply $K_{\epsilon}$ by  $D_{\epsilon}^{-1}M^{1/2}$ where $M^{1/2} = {\sf diag}\{\mu_X(x_1), \ldots, \mu_X(x_N)\}$~~\cite{banisch2017_target_measure_diffusionMap}:
\begin{equation}
\label{eq:Kmu}
    \tilde{K}_{\epsilon}: = K_\epsilon D_{\epsilon}^{-1} M^{1/2}.
\end{equation}
One can use either of these options, \eqref{eq:K1} and \eqref{eq:Kmu}, in the proposed algorithm for learning CVs.

The transition matrix of a Markov chain defined on the dataset $\{x_i\}_{i = 1}^N$, the \emph{Markov Matrix},  is obtained by left-normalizing the kernel matrix to make its row sums equal to one:
\begin{equation}
\label{eq:Pmatrix}
    P_{\epsilon} = \tilde{D}_{\epsilon}^{-1}\tilde{K}_{\epsilon},
\end{equation}
where $\tilde{D}_{\epsilon}$ is the diagonal matrix with the row sums of $\tilde{K}_{\epsilon}$ along its diagonal. 

% The discrete generator on the dataset is constructed as:
% \begin{equation}
%     L_{\epsilon} = \frac{1}{\epsilon}\left(I - P_{\epsilon}\right).
% \end{equation}

Let $\lambda_0 >\lambda_1\ge \ldots$ be the eigenvalues of $P_{\epsilon}$ and $\psi_0$, $\psi_1$, $\ldots$, be the corresponding  right eigenvectors. The largest eigenvalue $\lambda_0$ is always equal to one, and the corresponding eigenvector $\psi_0$ has all entries equal. The other eigenvalues are strictly less than one. The eigenvectors $[\psi_1,\ldots,\psi_d]$, $d\le N-1$, are used to map the data into $\mathbb{R}^d$:
\begin{equation}
    \label{eq:dmap}
    z_i = \Psi(x_i): = [\psi_1(i),\ldots,\psi_d(i)],
\end{equation}
where $\psi_j(i)$ is the $i$th component of $\psi_j$, $j=1,\ldots,d$. We first try $d = 3$ hoping to obtain a two-dimensional manifold spanned by $\{z_i\}_{i=1}^N\subset\mathbb{R}^3$. This two-dimensional manifold is the residence manifold. The diffusion net algorithm~\cite{2015diffusionnets} is used to globally extend the diffusion map beyond the point cloud $\{x_i\}_{i=1}^N$.

\subsubsection{Diffusion net}
Although diffusion maps enable manifold learning for high-dimensional systems, they cannot directly accommodate out-of-sample data points. The diffusion net proposed by Mishne et al.~\cite{2015diffusionnets} is a machine learning-based method designed to extend diffusion maps to new data. The complete architecture consists of an encoder and a decoder. The encoder maps high-dimensional input data to a low-dimensional representation, while the decoder reconstructs the original data from this low-dimensional space.

Since our goal is to obtain analytically computable derivatives of the diffusion map on the dataset $\{x_i\}_{i=1}^N$, it suffices to train only the encoder neural network with a simpler loss function than the one proposed in Ref.~\cite{2015diffusionnets} Our loss is 
\begin{equation}
\label{eq:DNet_loss}
    \mathcal{L}_{\sf DNet}(\theta) = \frac{1}{2N} \sum_{i = 1}^N \|\Psi_{\sf DNet}(x_i;\theta) - \Psi(x_i)\|^2,
\end{equation}
where $\Psi_{\sf DNet}(x; \theta)$ is the encoder neural network and $\theta$ is the vector of its parameters.



\subsection{Forward flux sampling and stochastic control}
Our use of the committor in the reduced model is twofold:
\begin{itemize}
    \item as the reaction coordinate for the forward flux sampling~\cite{Allen_2005, Allen_2009}, and
    \item to design a stochastic control for sampling transition trajectories~\cite {YUAN_2024_optimalcontrol}.
\end{itemize}

\subsubsection{Forward Flux Sampling}
\label{sec:FFS}
Forward flux sampling (FFS)~\cite{Allen_2005, Allen_2009} is a splitting method for estimating escape rate $k_A$ and generating ensembles of transition paths from a region $A$ to a region $B$. The escape rate $k_A$ is different from the rate $\nu_{AB}$ defined by \eqref{eq:nuAB}. It is defined by
\begin{equation}
    \label{eq:kA}
    k_A = \lim_{T\rightarrow\infty}\frac{N_{AB}}{T_A},
\end{equation}
where $T_A$ is the total time within the interval $[0,T]$ during which a trajectory $X_t$, $0\le t\le T$, last hit $A$ rather than $B$.
Given a reaction coordinate $\lambda(x)$, $x\in\Omega$,
the phase space $\Omega$ is stratified using level sets of $\lambda$.
The region $A$ is defined as $\lambda < \lambda_A = \lambda_0$, and region $B$ as $\lambda > \lambda_B = \lambda_m$. The escape rate from $A$, $k_{A}$, is expressed as:
\begin{equation}
    \label{eqn:FFS_rate}
    k_{A} = \Phi_{A,0}\prod_{i=0}^{m-1} \mathbb{P}(\lambda_{i+1} \mid \lambda_i),
\end{equation}
where $\Phi_{A,0}$ is exit flux from $A$ and $P(\lambda_{i+1}\mid\lambda_i)$ is the probability that the trajectory starting at the interface $\lambda_i$ will next hit the interface $\lambda_{i+1}$ rather than $\lambda_0 = \partial A$. 

The implementation of FFS involves sampling both the initial flux $\Phi_{A,0}$ and the crossing probabilities between successive interfaces. The flux $\Phi_{A,0}$ is computed by initiating an unbiased simulation from region $A$ and monitoring how often trajectories cross the first interface $\lambda_0$. Each time a crossing of $\lambda_0$ from $A$ occurs, the system configuration is saved to be used to initiate trajectories for estimating the conditional probability $\mathbb{P}(\lambda_{1} \mid \lambda_0)$. Furthermore, if the trajectory enters the region $B$, i.e., crosses the interface $\lambda_m$, the unbiased simulation is interrupted and restarted at $A$.

The probabilities $\mathbb{P}(\lambda_{i+1} \mid \lambda_i)$ are estimated as the ratio of the number of trajectories initiated at $\lambda_i$ and hitting next $\lambda_{i+1}$ rather than $\lambda_0$ to the total number of trajectories initiated at $\lambda_i$. Whenever a trajectory initiated at $\lambda_i$ crosses $\lambda_{i+1}$, the configuration at $\lambda_{i+1}$ is saved to be used to initiate trajectories at $\lambda_{i+1}$.
We refer the reader to Ref.~\cite{Kratzer2013_FFS} for more details.

Although FFS is a widely used method for computing transition rates in rare-event systems via unbiased sampling, it has been shown~\cite{DicksonMakarov_2009} that its accuracy can suffer from a poor choice of reaction coordinate. This can lead to improper definitions of regions $A$ and $B$, and thus inaccurate rate estimates.




\subsubsection{Stochastic optimal control}
\label{sec:stochastic_control}
Let a process be governed by the overdamped Langevin dynamics~\eqref{eq:overdampedLangevin} and $A,B\subset\Omega$ be chosen disjoint metastable sets. Lu and Nolen~\cite{Lu2015} introduced the \emph{transition path process}, i.e., the process restricted to the trajectories of the original process that start at $\partial A$ and end at $\partial B$ without returning to $A$ in-between, is governed by
\begin{equation}
\label{eq:controlled}
    dX_t = \left[- \nabla V(X_t) + 2\beta^{-1} \nabla \log q(X_t)\right] dt + \sqrt{2\beta^{-1}} dW_t,
\end{equation}
where $q(x)$ is the committor.
Gao et al.~\cite{Gao_2023} established a connection of \eqref{eq:controlled} with stochastic optimal control, proving that the trajectories of \eqref{eq:controlled} minimize a certain cost functional. This means that $2\beta^{-1}\nabla\log q(x)$ is the optimal control, the minimal modification to the drift in the $L_2$ sense that ensures all trajectories go from $A$ to $B$ without returning to $A$.

Zhang et al.~\cite{Zhang_Marzouk_2022} showed that for a problem with a finite time horizon, even a rough approximation to the optimal control makes a very effective controller. So is true for sampling the transition path process~\cite{YUAN_2024_optimalcontrol}.


