	\begin{thm}\label{thm 4.3}\cite{[TH]}
		The idempotents $\{T^{(r,s)}_{l}\mathbb{E}^{(r,s)}_{\rho^{i}}, \ 1\leq i\leq p^{s}, \ \text{and}\ (i,p^{s})=1\}_{0\leq l \leq p^{r-s}-1}$, $ 1\leq s\leq r-1$ form a set of mutually orthogonal primitive idempotents that are conjugate, giving rise to an irreducible representation of degree $p^{s-1}(p-1)$, for every $l$ and for every $s$.
	\end{thm}

