			$\lambda(k,\frac{k-1}{2}\pm p^{r-s-1}j_{1}\pm p^{r-s-2}j_{2}\pm \dots \pm pj_{r-s-1}\pm j_{r-s})$ represents $T^{(r,s)}_{l}E^{(r,s)}_{\rho^{j}},$ 

			\noindent where 

			$k^{'}=\frac{k-1}{2}\pm p^{r-s-1}j_{1}\pm p^{r-s-2}j_{2}\pm \dots \pm pj_{r-s-1}\pm j_{r-s}$ and
			$l=(p-1)\displaystyle\sum_{i=1}^{r-s}p^{r-s-i}\nu(j_{i}),$ with
			$\nu(j_{i})
			=\begin{cases}
				2j_{i}, ~\text{if the coefficient of} ~p^{r-s-i}j_{i} ~\text{is}~ -1 \\
				2j_{i}-1,~ \text{if the coefficient of}~ p^{r-s-i}j_{i} ~\text{is}~ 1\\
				0, ~\text{if} ~j_{i}=0
			\end{cases}$ and
			$0\leq j_{i}\leq \frac{p-1}{2}$ for $i=1,\dots,r-s$. \label{G}
			\item Let $\lambda(p^{r-s}((2s+1)p-(2s+2)),k^{'})\in W^{r+1}_{s}$ and $k=p^{r-s}((2s+1)p-(2s+2))$. Then

			$\lambda(k,\frac{k-1}{2}\pm p^{r-s}j_{1}\pm p^{r-s-1}j_{2}\pm \dots \pm pj_{r-s}\pm j_{r-s+1})$ represents $T^{(r+1,s)}_{l}\mathbb{E}^{(r+1,s)}_{\rho^{j}},$ 

			\noindent where 

			$k^{'}=\frac{k-1}{2}\pm p^{r-s}j_{1}\pm p^{r-s-1}j_{2}\pm \dots \pm pj_{r-s}\pm j_{r-s+1}$ and $l=(p-1)\displaystyle\sum_{i=1}^{r-s+1}p^{r-s+1-i}\nu(j_{i}),$ with 
			$\nu(j_{i})
			=\begin{cases}
				2j_{i}, ~\text{if the coefficient of} ~p^{r-s-i}j_{i} ~\text{is}~ -1 \\
				2j_{i}-1,~ \text{if the coefficient of}~ p^{r-s-i}j_{i} ~\text{is}~ 1\\
				0, ~\text{if} ~j_{i}=0
			\end{cases}$ and
			$0\leq j_{i}\leq \frac{p-1}{2}$ for $i=1,\dots,r-s+1$. \label{SG}	
			\item Let $\lambda(p^{r-1}(p-1),k^{'})$, with $~0\leq k^{'}<p^{r-1}(p-1)$, be a hook partitions in $V^{r}_{0}$ or $W^{r}_{0}$. Then the hook partition
			$$\lambda(p^{r-1}(p-1),k^{'})~\text{ represents}~T^{(r)}_{j}E^{(r,0)}_{\rho^{i}}.$$ \label{Common}
		\end{enumerate}
	\end{rem}
	\subsection*{Schur function:} Let $\lambda/ \mu$ be a skew shape. The skew Schur function $s_{\lambda/\mu}(x)$ of shape $\lambda/\mu$ in variables $x=(x_{1},x_{2},x_{3},\dots)$ is the formal power series $s_{\lambda/\mu}(x)=\sum_{T}x^{T}$, summed over all SSYTs T of shape $\lambda/\mu$. If $\mu = \emptyset$ so $\lambda/\mu =\lambda$, then we call $s_{\lambda}(x)$ the Schur function of shape $\lambda$ \cite{[RS]}.
	\subsection*{Cauchy identity:} 
	$$\prod_{i,j}\frac{1}{1-x_{i}y_{j}} = \sum_{\lambda}s_{\lambda(x)}s_{\lambda(y)}$$
	where $s_{\lambda}(x),~s_{\lambda}(y)$ are Schur functions of shape $\lambda$ \cite{[RS]}.

		\section{Bijection between the elements of $G_{r}$ (and $SG_{r}$) and the pair of standard \textbf{\textit{p}}-Young tableaux}
	Using matrix units, we develop the Robinson-Schensted correspondence between the elements of the groups $G_{r}$ and $SG_{r}$ and the pair of standard \textbf{\textit{p}}-Young tableaux using matrix units. To construct this correspondence, we assign integers to blocks of size $p^{k}(p-1),~k\geq 0$. This aids in numbering each standard \textbf{\textit{p}}-Young tableau and plays a key role in defining the bijection. We discuss a few properties of the Robinson-Schensted correspondence in our case. First, we examine the element corresponding to a pair of standard \textit{\textbf{p}}-Young tableaux $(P,Q)$ and $(Q,P)$ \cite{[BS]}. Then, we consider the Knuth correspondence and the dual Knuth correspondence \cite{[BS]}.
	\begin{Def}\label{std}
		\begin{itemize}
			\item[]
			\item The \textbf{\textit{p}}-Young diagram of the hook partitions of shape $\lambda(p^{r-1}(p-1),k)\in V^{r}_{0}(\text{or}~W^{r}_{0})$, where $0\leq k <p^{r-1}(p-1)$, consists of blocks of size $p^{n}(p-1)^{2}$, for $0\leq n\leq r-2$, following the induction and restriction defined in \cite{[TH]}  and by Definition \ref{block}.  

			\item The standard \textbf{\textit{p}}-Young tableau corresponding to the one-dimensional representation of shape $\lambda(p^{r-1}(p-1),k)\in V^{r}_{0}$ (or $ W^{r}_{0}$) is obtained by filling every block with the same integer.
			\item The \textbf{\textit{p}}-Young diagram of the hook partitions of shape $\lambda(p^{r-s}[2sp-(2s+1)],i)\in V^{r}_{s}$, for $1\leq s\leq r$, $\left(\text{or}~\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],j)\in W^{r}_{s},~ \text{for}~0\leq s\leq r-1\right)$ consists of blocks of size $p^{r-s}(p-1)\left(\text{or}~p^{r-s-1}(p-1)\right)$ and $p^{r-s}(p-2)\left(\text{or}~p^{r-s-1}(p-2)\right)$ respectively, following the induction and restriction defined in \cite{[TH]} and by Definition \ref{block}, respectively.  

			In other words, every \textbf{\textit{p}}-Young tableau corresponds to the path in the Bratteli diagram that starts at $\lambda(p^{r-s}[2sp-(2s+1)],i)\in V^{r}_{s}$, for $1\leq s \leq r$, $(\text{or}~\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],j)\in W_{s}^{r}$, for $1\leq s\leq r-1)$ and ends at $\lambda(p-1,k)$ for some $0\leq k<p-1$.

			\item The standard \textbf{\textit{p}}-Young tableau \textbf{$(\textbf{\textit{SYT}}_{\textbf{\textit{p}}})$} is a \textbf{\textit{p}}-Young diagram obtained by filling each block with a single positive integer, such that the integers strictly increase along the blocks in the first row and along the blocks in the first column. 
		\end{itemize}
	\end{Def}
		\begin{ex}
		The	$\textbf{\textit{SYT}}_{\textbf{3}}$ of shape $\lambda(6,k),$ for $0\leq k <6$ such that $\lambda(6,k)\in V^{2}_{0},$ in the group $G_{2}$  is given as follows:

		\ytableausetup{centertableaux,boxsize=1em}	
