		\begin{ytableau}
			1 & 1 & 1 & 1 & 1 \\ 1
		\end{ytableau},
		$\lambda(6,2)$ = \ytableausetup{centertableaux}
		\begin{ytableau}
			1 & 1 & 1 & 1 \\ 1 \\ 1
		\end{ytableau},

		$\lambda(6,3)$ = \ytableausetup{centertableaux}
		\begin{ytableau}
			1 & 1 & 1 \\ 1 \\ 1 \\ 1
		\end{ytableau},
			$\lambda(6,4)$ = \ytableausetup{centertableaux}
