	\begin{Def}\label{Definition pob}
		We assign numbers to the block types of size $p^{k}(p-1)$ as follows:

		The block of type $B_{\frac{p^{k}(p-1)}{2}+p^{k}m,\frac{p^{k}(p-1)}{2}-p^{k}m}$ is numbered as $2m+1$, where $0\leq m\leq \frac{p-1}{2}$.

		The block of type $B_{\frac{p^{k}(p-1)}{2}-p^{k}m,\frac{p^{k}(p-1)}{2}+p^{k}m}$ is numbered as $2m$, where $1\leq m\leq \frac{p-1}{2}$. 


	\end{Def}

	\subsection{Robinson-Schensted correspondence}
	We develop the Robinson-Schensted correspondence between the pairs of $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ and the elements of the groups $G_{r}$ and $SG_{r}$.
	\subsubsection*{Assigning integer to standard $p$-Young tableau}
	To assign an integer to every $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$, we utilize the numbering defined in Definition \ref{Definition pob}. This process involves considering two distinct cases to assign an integer value appropriately.

	\begin{description}
		\item[Case (a)] Consider a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(2rp-(2r+1),r(p-1)-1)\in V_{r}^{r}$, corresponding to an irreducible representation of degree $p^{r-1}(p-1)$ of the group $G_{r}$.

		\begin{description}
			\item[Step 1] Look at the block of type $B_{p-1-t,t}$, where $0\leq t\leq p-1$, which contains the last entry (i.e., highest integer occurring in the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$) of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(2rp-(2r+1),r(p-1)-1)\in V_{r}^{r}$. By Definition \ref{Definition pob}, this block type is numbered as $'i_{1}'$. Subsequently, the block is removed and the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is reduced to a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda((2r-1)p-2r,k^{'})\in W_{r-1}^{r}$. After removing the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of the shape $\lambda((2r-1)p-2r,k^{'})\in W_{r-1}^{r}$, the tableau is reduced further to a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda((2r-2)p-(2r-1),(r-1)p-r)\in V_{r-1}^{r-1}$.

			\begin{figure}[!ht]
				\vspace{-0.4cm}
				\begin{center}
					\includegraphics[width=9cm, height=5cm]{pic1}
				\end{center}
				\vspace{-0.9cm}
			\end{figure}

			\item[Step 2]	
			Once again consider the block of type $B_{p-1-t,t}$, where $0\leq t \leq p-1$, which contains the last entry of the reduced tableau. By Definition \ref{Definition pob}, this block type is numbered as $'i_{2}'$. This block is then removed as well.			
			This process continues by successively removing such blocks. Now consider the reduced $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(2(r-m+1)p-(2(r-m+1)+1),(r-m+1)(p-1)-1)\in V^{r-m+1}_{r-m+1}$, and look at the block of type $B_{p-1-t,t}$, where $0\leq t \leq p-1$, which contains the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$. By Definition \ref{Definition pob}, this block type is numbered as $'i_{m}'$, and it is subsequently removed. As a result, the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is reduced to the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda((2(r-m+1)-1)p-2(r-m+1),k^{''})\in W^{r-m}_{r-m+1}$, from which the block containing the last entry is also removed. 

			This $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is reduced to $\lambda(2(r-m)p-(2(r-m)+1),(r-m)(p-1)-1)\in V^{r-m}_{r-m}$.
			Now, look at the block of type $B_{p-1-t,t},~0\leq t \leq p-1$, which contains the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$. By Definition \ref{Definition pob}, this block type is numbered as $'i_{m+1}'$ for $1\leq m \leq r-2$. This yields a sequence of integers  $i_{1},i_{2},\dots,i_{r-1}$, $1\leq i_{1},i_{2},\dots,i_{r-1}\leq p$.

			\item[Step 3] After removing all the blocks, as in the previous steps, we reach a stage where the partition has the shape $\lambda(2p-3,p-2)$ with dimension $p-1$. Consider the path from $\lambda(2p-3,p-2)$ to $\lambda(p-1,t_{1})$ by removing $t_{1}$ nodes horizontally and $p-2-t_{1}$ nodes vertically, where $0\leq t_{1}\leq p-2$. We assign numbers to these paths as follows:	
			$$\lambda(2p-3,p-2)\hookleftarrow \lambda(p-1,t_{1}) : 2t_{1}+1,~0\leq t_{1}<\frac{p-1}{2}$$
			and its conjugate is numbered as
			$$\lambda(2p-3,p-2)\hookleftarrow \lambda(p-1,p-2-t_{1}) : 2(t_{1}+1)$$
			\begin{figure}[!ht]
				\vspace{-0.5cm}
				\begin{center}
					\includegraphics[width=9cm, height=2.5cm]{pic2}
				\end{center}
				\vspace{-0.5cm}
			\end{figure}

			Let the numbering be, say, $i_{r}$.

			\item[Step 4]	
			Let	$j=
			i_{1}+p(i_{2}-1)+p^{2}(i_{3}-1)+\dots+p^{r-2}(i_{r-1}-1)+p^{r-1}i_{r} ~ \text{for} ~ r\geq1$.

			Then $1\leq j\leq p^{r-1}(p-1)$. The path corresponding to the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is denoted by $P_{j}$.

			Take a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of the shape $\lambda((2r-1)p-2r,k^{'})\in W_{r-1}^{r}$, $(r-1)p-r\leq k^{'} \leq rp-(r+1)$. Let $k = (2r-1)p-2r$, and the figure below is an example by fixing $k^{'} =\frac{k-1}{2}$. For any fixed $k^{'}$, the paths are the same as those for the partition $\lambda(k-(p-1),\frac{k-(p-1)-1}{2})\in V^{r-1}_{r-1}$. First, the block that contains the last entry is removed. Now, this case is reduced to the previous case and by doing the same procedure for the reduced tableau in $V^{r-1}_{r-1}$, we obtain the following integers $i_{1},i_{2},\dots,i_{r-1}$ where $1\leq i_{1},i_{2},\dots,i_{r-2}\leq p$ and $0\leq i_{r-1}\leq p-2$.

			\begin{figure}[!ht]
				\vspace{-0.3cm}
				\begin{center}
					\includegraphics[width=9cm, height=3cm]{pic3}
				\end{center}
				\vspace{-0.5cm}
			\end{figure}

			Let $j=i_{1}+p(i_{2}-1)+p^{2}(i_{3}-1)+\dots+p^{r-3}(i_{r-2}-1)+p^{r-2}i_{r-1},~ \text{for} ~ r>1$.
			\noindent Then $1\leq j\leq p^{r-2}(p-1)$. The path corresponding to the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is denoted by $P_{j}$.
		\end{description}	
		\item[Case (b)]	
		Consider a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],l_{1})\in V_{s}^{r}$, where $1\leq s\leq r-1$, and $p^{r-s}[sp-(s+1)]\leq l_{1}<sp^{r-s}(p-1)$, corresponding to an irreducible representation of degree $p^{s-1}(p-1)$ of the group $G_{r}$. Let us take $k=p^{r-s}[2sp-(2s+1)]$.
		\begin{description}
			\item[Step 1]	
			Let $l_{1}$ be fixed. Consider the block of type $B_{p^{r-s}(p-1-t),p^{r-s}t}$, where $0\leq t\leq p-1$, which contains the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],l_{1})\in V_{s}^{r}$. By Definition \ref{Definition pob}, this block type is numbered as $'i_{1}'$. Subsequently, the block is removed. Now, this $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is reduced to a  $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[(2s-1)p-2s],l^{'}_{1})\in W_{s-1}^{r}$. After removing the block containing the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[(2s-1)p-2s],l^{'}_{1})\in W_{s-1}^{r}$, it is further reduced to a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2(s-1)p-(2s-1)],l_{2})$ in $V_{s-1}^{r-1}$.	
			\begin{figure}[!ht]
				\begin{center}
					\includegraphics[width=9cm, height=4cm]{pic4}
				\end{center}
				\vspace{-0.5cm}
			\end{figure}

			\item[Step 2]	
			Once again, consider the block of type $B_{p^{r-s}(p-1-t),p^{r-s}t}$, where $0\leq t\leq p-1$, which contains the last entry in the reduced tableau. By Definition \ref{block}, this block type is numbered as $'i_{2}'$. This block is then removed.

			This process can be continued by successively removing blocks. Now, consider the reduced $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2(s-m+1)p-(2(s-m+1)+1)],l_{m})\in V_{s-m+1}^{r-m+1}$. Look at the block of type $B_{p^{r-s}(p-1-t),p^{r-s}t}$, with $0\leq t\leq p-1$, which contains the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$. By Definition \ref{block}, this block type is numbered as $'i_{m}'$. Consequently, the block is removed. Now, this $SYT_{p}$ is reduced to the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[(2(s-m+1)-1)p-2(s-m+1)],l^{'}_{m})\in W_{s-m}^{r-m+1}$, and the block containing the last entry is removed. 

			This $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is further reduced to $\lambda(p^{r-s}[2(s-m)p-2(s-m)+1],l_{m+1})\in V_{s-m}^{r-m}$. Now, look at the block of type $B_{p^{r-s}(p-1-t),p^{r-s}t}$, with $0\leq t\leq p-1$, which contains the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$. By Definition \ref{block}, this block type is numbered as  $'i_{m+1}'$ for $0\leq m\leq s-2$. This yields a sequence of integers
			$i_{1},i_{2},\dots,i_{s-1}$ where $1\leq i_{1},i_{2},\dots,i_{s-1}\leq p$. 

			\item[Step 3]	
			After removing all the blocks, we arrive at a stage where the partition takes the shape of $\lambda(p^{r-s}(2p-3),k^{'})$ with dimension $p-1$. Consider the path from $\lambda(p^{r-s}(2p-3),k^{'})$ to $\lambda(p^{r-s}(p-1),l^{'})$. We number these paths as follows:

			$\lambda(p^{r-s}(2p-3),k^{'})\hookleftarrow \lambda(p^{r-s}(p-1),k^{'}-p^{r-s}(p-2-t)) ~\text{numbered as}~j^{'}~\text{if}~j^{'}p^{r-s}\leq k^{'}-p^{r-s}(p-2-t)<(j^{'}+1)p^{r-s}. $

			\item[Step 4]	
			Let	

			$j=\begin{cases}
				1+j^{'}+p^{s-2}(p-1)(i_{1}-1)+\sum_{n=1}^{s-2}p^{n-1}(p-1)(i_{n+1}-1) & \text{for} ~ s>1\\
				j^{'}+1 & \text{for} ~ s=1
			\end{cases}$

			Then $1\leq j\leq p^{s-1}(p-1)$. The path corresponding to the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is denoted by $P_{j}$.


			Consider a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[(2s-1)p-2s],k^{'})\in W_{s-1}^{r}$, with $p^{r-s}[(s-1)p-s]\leq k^{'} \leq sp^{r-s}(p-1)$. Let $k = p^{r-s}[(2s-1)p-2s]$.	
			For any fixed $k^{'}$, the paths are the same as those in the partition 
			$\lambda(k-p^{r-s}(p-1),\frac{k-p^{r-s}(p-1)-1}{2})\in V^{r-1}_{s-1}$. Begin by removing the block that contains the last entry of the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$. This case then reduces to the previous one, so we obtain the integers $i_{1},i_{2},\dots,i_{s-2}$ where $1\leq i_{1},i_{2},\dots,i_{s-2}\leq p$. Let

			$j=\begin{cases}
				1+j^{'}+p^{s-3}(p-1)(i_{1}-1)+\sum_{n=1}^{s-3}p^{n-1}(p-1)(i_{n+1}-1) & \text{for} ~ s>1\\
				j^{'}+1 & \text{for} ~ s=1
			\end{cases}$

			Then $1\leq j\leq p^{s-2}(p-1)$. The path corresponding to the $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ is denoted by $P_{j}$.
		\end{description}	
	\end{description}

	\begin{Not}
		\item $\Lambda_{1} = \{V_{0}^{r}\cup V^{r}_{s}/r\geq 1,~1\leq s\leq r\}$, $\Lambda_{2} = \{W_{0}^{r}\cup W^{r}_{s}/r\geq 1,~1\leq s\leq r-1\}$
		\item $\Lambda = \Lambda_{1}\cup \Lambda_{2}$, $\tau^{*}=\tau^{\frac{p^{r-1}(p-1)}{2}}$ 
	\end{Not}
	\subsection*{Defining the mapping between the group $G_{r}$ (and $SG_{r}$) and pairs of $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$}
	Now, construct the map $h: \bigcup\limits_{\lambda \in \Lambda_{1}}\textbf{\textit{SYT}}_{\textbf{\textit{p}}}(\lambda)\times \textbf{\textit{SYT}}_{\textbf{\textit{p}}}(\lambda)\rightarrow G_{r}$. Consider an element $g\in G_{r}$ of order $p^{r}$. 
	\begin{description}
		\item[Case (a)] 	
		Let $P_{i},P_{j}\in \mathbb{T}^{p}_{\lambda}$, where $\mathbb{T}^{p}_{\lambda}$ denotes the set of all $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(k,\frac{k-1}{2})$, with $k=2rp-(2r+1)$. Based on the matrix units of Theorem \ref{thm 5.1}, we define $$h\bigl((P_{i},P_{j})\bigr)=\tau^{-(i-1)}g\tau^{*}\tau^{j-1},$$ where $1\leq i,j \leq p^{r-1}(p-1)$.  

		\item[Case (b)] For any $1\leq s\leq r-1$, we have:
		\begin{description}	
			\item[Type 1] 
			Let $P^{0}_{i},P^{0}_{j}\in \mathbb{T}^{P}_{\lambda(0)}$ where $\mathbb{T}^{p}_{\lambda(0)}$ represents the set of all $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of the shape $\lambda(k,\frac{k-1}{2})$, with $k=p^{r-s}[2sp-(2s+1)]$. Based on the matrix units of Theorem \ref{thm 5.1}, we define $$h\bigl((P^{0}_{i},P^{0}_{j})\bigr)=
			\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}, $$ where $1\leq i,j \leq p^{s-1}(p-1)$.

			\item[Type 2] Let $P^{m^{-}}_{i},P^{m^{-}}_{j}\in \mathbb{T}^{p}_{\lambda(m^{-})}$, where $\mathbb{T}^{p}_{\lambda(m^{-})}$ denotes the set of all $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(k,\frac{k-1}{2}-m)$, with $k=p^{r-s}[2sp-(2s+1)]$ and $1\leq m \leq \frac{p^{r-s}-1}{2}$. 
			Based on the matrix units of Theorem \ref{thm 5.1}, we define
			$$h\bigl((P^{m^{-}}_{i},P^{m^{-}}_{j})\bigr)=\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}\tau^{lp^{s-1}(p-1)},$$
			where $1\leq i,j \leq p^{s-1}(p-1)$, and $T^{(r,s)}_{l}E^{(r,s)}_{\rho^{j^{'}}}$ is the primitive idempotent indexed by the hook partition $\lambda(k,\frac{k-1}{2}-m)$ as in Remark \ref{rem1} (\ref{G}).

			\item[Type 3] Let $P^{m^{+}}_{i},P^{m^{+}}_{j}\in \mathbb{T}^{p}_{\lambda(m^{+})}$, where $\mathbb{T}^{p}_{\lambda(m^{+})}$ represents the set of all $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ of the shape $\lambda(k,\frac{k-1}{2}+m)$, with $k=p^{r-s}[2sp-(2s+1)]$ and $1\leq m \leq \frac{p^{r-s}-1}{2}$.
			Based on the matrix units of Theorem \ref{thm 5.1}, we get $$h\bigl((P^{m^{+}}_{i},P^{m^{+}}_{j})\bigr)=	\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}\tau^{lp^{s-1}(p-1)}, $$
			where $1\leq i,j \leq p^{s-1}(p-1)$, and $T^{(r,s)}_{l}E^{(r,s)}_{\rho^{j^{'}}}$ is the primitive idempotent indexed by the hook partition $\lambda(k,\frac{k-1}{2}+m)$ as in Remark \ref{rem1} (\ref{G}).
		\end{description}
