	\begin{thm}
		The map $h: \bigcup\limits_{\lambda \in \Lambda_{1}}\textbf{\textit{SYT}}_{\textbf{\textit{p}}}(\lambda)\times \textbf{\textit{SYT}}_{\textbf{\textit{p}}}(\lambda)\rightarrow G_{r}$ establishes a bijection between the pairs of standard $p$-Young tableaux of the same shape and elements in the group $G_{r}$.
	\end{thm}
	\begin{proof}
		Let $g^{m}\tau^{k}\in G_{r}$. There exist $i$ and $k^{'}$ such that $m=p^{r-s}t^{i}$ and $k=lp^{s-1}(p-1)+k^{'}$ where $1\leq i\leq p^{s-1}(p-1)$, $1\leq k^{'}\leq p^{s-1}(p-1)$ and $1\leq s\leq r$. Now we have 
		\begin{align*}
			g^{m}\tau^{k}&= g^{p^{r-s}t^{i}}\tau^{lp^{s-1}(p-1)+k^{'}}=\tau^{-i}g^{p^{r-s}}\tau^{*}\tau^{i}\tau^{lp^{s-1}(p-1)+k^{'}}\tau^{\frac{p^{r-1}(p-1)}{2}}\\ &=\tau^{-i}g^{p^{r-s}}\tau^{*}\tau^{i+\frac{p^{r-1}(p-1)}{2}+k^{'}}\tau^{lp^{s-1}(p-1)}=\tau^{-((i+1)-1)}g^{p^{r-s}}\tau^{*}\tau^{(j+1)-1}\tau^{lp^{s-1}(p-1)}
		\end{align*}
		where $j=i+\frac{p^{r-1}(p-1)}{2}+k^{'}$. Let $P_{i+1}$ be a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ indexed by the integer numbering $i+1$, and $P_{j+1}$ be a $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ indexed by $j+1$. Hence, the pair of $\textbf{\textit{SYT}}_{\textbf{\textit{p}}}$ $(P_{i+1},P_{j+1})$ is the inverse image of $g^{m}\tau^{k}$. 

		Consider the pair of tableaux $(P_{j},P_{j})$ of the same shape $\lambda(p^{r-1}(p-1),k^{'}) \in V^{r}_{0}$. This pair corresponds to the unique element $\tau^{j}$, where the relation between $k^{'}$ and $j$ is described in Remark \ref{rem1} (\ref{Common}). Hence, the bijection follows.
	\end{proof}
