	\subsection{Properties of Robinson-Schensted correspondence}
	\begin{thm}\label{prop 1}
		If $\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}\tau^{lp^{s-1}(p-1)}\in G_{r}~(\text{and}~SG_{r})$ corresponds to the pair of tableaux $(P_{i},P_{j})$, then $\tau^{-(j-1)}g^{p^{r-s}}\tau^{*}\tau^{i-1}\tau^{lp^{s-1}(p-1)}\in G_{r}~(\text{and}~SG_{r})$ corresponds to the pair of tableaux $(P_{j},P_{i})$, where $1\leq i,j\leq p^{s-1}(p-1),~0\leq l\leq p^{r-s}-1$, and $1\leq s\leq r$ (or $1\leq s\leq r-1$).
	\end{thm} 
	\begin{proof}
		Considering that the integer $i$ is assigned to the tableau $P_{i}$ and the integer $j$ is assigned to the tableau $P_{j}$, then for each fixed $l$, the element $\tau^{-(j-1)}g^{p^{r-s}}\tau^{*}\tau^{i-1}\tau^{lp^{s-1}(p-1)}$ corresponds to the pair of tableaux $(P_{j},P_{i})$.
	\end{proof}
		\begin{Def}	
		Let $a_{1},a_{2}$ be two elements in $G_{r}~(\text{and}~SG_{r})$. Then $a_{1}$ and $a_{2}$ differ by a \textbf{\textit{p}}-Knuth relation, denoted as $a_{1}\overset{\mathfrak{p}}{\cong} a_{2}$ if 
		$$a_{1}=\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}\tau^{lp^{s-1}(p-1)}~\text{and}~ a_{2}=\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{k-1}\tau^{lp^{s-1}(p-1)},$$
		where $ 1\leq i,j,k\leq p^{s-1}(p-1)$, $0\leq l\leq p^{r-s}-1$ and $1\leq s \leq r$ (or $1\leq s \leq r-1$ for $SG_{r}$).
	\end{Def}
	\begin{Def}
		Let $b_{1},b_{2}$ be two elements in $G_{r}~(\text{and}~SG_{r})$. Then $b_{1}$ and $b_{2}$ differ by a \textbf{\textit{p}}-dual Knuth relation of the first kind, denoted as $b_{1}\overset{\mathfrak{p}^{*}}{\cong} b_{2}$, if
		$$b_{1}=\tau^{-(i-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}\tau^{lp^{s-1}(p-1)}~\text{ and}~ b_{2}=\tau^{-(k-1)}g^{p^{r-s}}\tau^{*}\tau^{j-1}\tau^{lp^{s-1}(p-1)},$$ 
		where $1\leq i,j,k\leq p^{s-1}(p-1)$, $0\leq l\leq p^{r-s}-1$ and
		$1\leq s \leq r$ (or $1\leq s \leq r-1$ for $SG_{r}$).
	\end{Def}
	\begin{thm}
		If two elements, $a_{1}$ and $a_{2}$, from $G_{r}~(\text{and}~SG_{r})$ are \textbf{\textit{p}}-Knuth equivalent (of both the first and second kind), then their corresponding $P_{i}$-tableaux are the same.
	\end{thm}
	\begin{proof}
		Note that for each fixed $l$, the integer $i$ in both $a_{1}$ and $a_{2}$ corresponds to the $P_{i}$ tableau, and it remains constant in both elements. Clearly, the proof follows.
	\end{proof}
	\begin{thm}
		If two elements, $b_{1}$ and $b_{2}$, from $G_{r}~(\text{and}~SG_{r})$ are \textbf{\textit{p}}-dual Knuth equivalent (of both the first and second kind), then their corresponding $P_{j}$ tableaux are the same.
	\end{thm}
	\begin{proof}
		Note that for each fixed $l$, the integer $j$ in both $b_{1}$ and $b_{2}$ corresponds to the $P_{j}$ tableau, and it remains constant in both elements. Clearly, the proof follows.
	\end{proof}
	\section{Lacunary Cauchy identity}
	In this section, we discuss the merging of blocks in a Young diagram. We begin by defining the concept of \textbf{\textit{p}}-content and \textbf{\textit{p}}-Schur function and subsequently introduce the lacunary Cauchy identity. We extended the Cauchy identity to our \textbf{\textit{p}}-Brattelli diagram, similar to the classical case of the Robinson-Schensted-Knuth algorithm, resulting in the Cauchy identity. 
	\begin{lem}\label{merging}
		Let $\lambda(kp-(k+1),i)\in \Lambda$ be a hook partition of size $kp-(k+1)$, where $k\geq2$. Here $i=\frac{kp-(k+1)-1}{2}$ when $k$ is even and $\frac{(k-1)p-(k+1)}{2}\leq i < \frac{k+1}{2}(p-1)$ when $k$ is odd. Then the total number of ways in which a \textbf{\textit{p}}-Young diagram with $k$ blocks merged into $l^{'}$ blocks is $2^{k-1}$, where $1\leq l^{'}\leq l$ and $0\leq l\leq k-2$.  
	\end{lem}
	\begin{proof}
		To construct the \textbf{\textit{p}}-Young diagram of the shape $\lambda(kp-(k+1),i)$, blocks of size $p-1$ and $p-2$ are utilized. The construction process to achieve the shape $\lambda(kp-(k+1),i)$ starts with the $p-1$ block, followed by the addition of the $p-2$ block, and subsequently continues with the addition of the $p-1$ block.

		The number of blocks decreases to $k-1$ if the first two blocks of sizes $p-1$ and $p-2$ are combined into a single block. These $k-1$ blocks can be merged as follows: $(p(k-l)-(k+1-l),a_{1}(p-1),a_{2}(p-1),\dots,a_{l^{'}}(p-1))$ ($i^{th}$ coordinate indicates the $i^{th}$ block), where $\sum\limits_{i=1}^{l^{'}} a_{i} = l,~a_{i}\geq 1$, $1\leq l^{'} \leq l$ and $1\leq l\leq k-2$. In other words,  $\sum\limits_{i=1}^{l^{'}} a_{i} = l$ forms a composition of $l$. There are $2^{l-1}$ different types of \textbf{\textit{p}}-Young diagrams for each $l$. In total, the number of such $p$-Young diagrams is $1+\sum\limits_{l=1}^{k-2}2^{l-1}=2^{k-2}$.
		There is only one \textbf{\textit{p}}-Young diagram with one block when $l=0$.

		If the first two blocks are not combined, then the first block remains fixed with the size $p-1$, and the remaining $k-1$ blocks can be merged as $(p-1,p(k-1-l)-(k-l),a_{1}(p-1),a_{2}(p-1),\dots,a_{l^{'}}(p-1))$($i^{th}$ co-ordinate indicates the $i^{th}$ block), where $\sum\limits_{i=1}^{l^{'}} a_{i} = l,~a_{i}\geq 1$, $1\leq l^{'} \leq l$, and $1\leq l\leq k-2$. In other words,  $\sum\limits_{i=1}^{l^{'}} a_{i} = l$ forms a composition of $l$. There are $2^{l-1}$ different types of \textbf{\textit{p}}-Young diagrams for each $l$. These \textbf{\textit{p}}-Young diagrams can be found in total: $1+\sum\limits_{l=1}^{k-2}2^{l-1}=2^{k-2}$.
		We have only one \textbf{\textit{p}}-Young diagram with $2$ blocks when $l=0$.

		Therefore, the total number of \textbf{\textit{p}}- Young diagram of shape $\lambda(kp-(k+1),i)$ is $2^{k-1}$.
	\end{proof}
	\begin{Def}
		Let $T^{l,l^{'},J}$ be a semi-standard \textbf{\textit{p}}-Young tableau $\left(\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}\right)$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],i)$ consisting of either $l^{'}+1$ or $l^{'}+2$ blocks of size $p^{r-s}(p(2s-l)-(2s+1-l))+a_{1}p^{r-s}(p-1)+a_{2}p^{r-s}(p-1)+\dots+a_{l^{'}}p^{r-s}(p-1)$ or $p^{r-s}(p-1)+p^{r-s} (p(2s-1-l)-(2s-l))+a_{1}p^{r-s}(p-1)+a_{2}p^{r-s}(p-1)+\dots+a_{l^{'}}p^{r-s}(p-1)$, respectively, where the blocks are filled with entries $(j_{1},j_{2},\dots,j_{l^{'}+1}) =J$, and these entries are strictly increasing along the first row and strictly increasing along the first column. 

		We define the monomials as $$x^{\alpha(T^{l,l^{'},J})}:=x^{p^{r-s}(p(2s-l)-(2s+1-l))}_{j_{1}}x^{a_{1}p^{r-s}(p-1)}_{j_{2}}x^{a_{2}p^{r-s}(p-1)}_{j_{3}}\cdots x^{a_{l^{'}}p^{r-s}(p-1)}_{j_{l^{'}+1}}$$ and $$x^{\alpha(T^{l,l^{'},J})}:=x^{p^{r-s}(p-1)}_{j_{1}}x^{p^{r-s}(p(2s-l-1)-(2s-l))}_{j_{2}}x^{a_{1}p^{r-s}(p-1)}_{j_{3}}x^{a_{2}p^{r-s}(p-1)}_{j_{4}}\cdots x^{a_{l^{'}}p^{r-s}(p-1)}_{j_{l^{'}+2}}$$
		where $\sum\limits_{i=1}^{l^{'}}a_{i}=l,~a_{i}\geq 1$ $0\leq l \leq k-2$.

		Similarly, we define $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$, $T^{l,l^{'},J}$, and monomial for the shape $\lambda(p^{r-s}[(2s+1)p-2(s+1)],i)$.
	\end{Def}

	\noindent Let us define the set,

	\noindent $\mathbb{Q}^{(r,s)}_{2s}=$
	\begin{align*}
		& \left\{\alpha^{(1)}_{l,l^{'},J}/ 0\leq l\leq 2s-2,~1\leq l^{'}\leq l,~J=\left\{j_{1},j_{2},\dots, j_{l^{'}+1}\right\}\subseteq\left\{i_{1},i_{2},\dots,i_{2s}\right\}\subset\mathbb{N} \right\} \\ & \cup \left\{\alpha^{(2)}_{l,l^{'},J}/ 0\leq l\leq 2s-2,~1\leq l^{'}\leq l,~J=\left\{j_{1},j_{2},\dots, j_{l^{'}+2}\right\}\subseteq\left\{i_{1},i_{2},\dots,i_{2s}\right\}\subset\mathbb{N} \right\}
	\end{align*}
	\noindent $\mathbb{Q}^{(r,s)}_{2s+1}=$
	\begin{align*}
		&  \left\{\gamma^{(1)}_{l,l^{'},J}/ 0\leq l\leq 2s-1,~1\leq l^{'}\leq l,~J=\left\{j_{1},j_{2},\dots, j_{l^{'}+1}\right\}\subseteq\left\{i_{1},\dots,i_{2s+1}\right\}\subset\mathbb{N} \right\} \\ & \cup \left\{\gamma^{(2)}_{l,l^{'},J}/ 0\leq l\leq 2s-1,~1\leq l^{'}\leq l,~J=\left\{j_{1},j_{2},\dots, j_{l^{'}+2}\right\}\subseteq\left\{i_{1},\dots,i_{2s+1}\right\}\subset\mathbb{N} \right\} 	
	\end{align*}
	where $\alpha^{(1)}_{l,l^{'},J}(\text{and}~\gamma^{(1)}_{l,l^{'},J})$ denotes the $l^{'}+1$-tuple whose $i^{th}$ entry represents the number of times $j_{i}$ occurs in the $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],i)$ (and $\lambda(p^{r-s}[(2s+1)p-2(s+1)],j)$, respectively), and

	$\alpha^{(2)}_{l,l^{'},J}(\text{and}~\gamma^{(2)}_{l,l^{'},J})$ denotes the $l^{'}+2$-tuple whose $i^{th}$ entry represents the number of times $j_{i}$ occurs in the $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],i)$ (and $\lambda(p^{r-s}[(2s+1)p-2(s+1)],j)$, respectively).
	\begin{Def}
		Each element $\alpha^{(k)}_{l,l^{'},J}\in\mathbb{Q}^{(r,s)}_{2s}(\text{and}~\gamma^{(k)}_{l,l^{'},J}\in\mathbb{Q}^{(r,s)}_{2s+1})$, for $k=1,2$, is referred to as the \textbf{\textit{p}}-content of a $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],i)$ (and $\lambda(p^{r-s}[(2s+1)p-2(s+1)],j)$, respectively). For simplicity, we denote each element in $\mathbb{Q}^{(r,s)}_{2s}(\text{and}~\mathbb{Q}^{(r,s)}_{2s+1})$ as $\alpha(\text{and}~\gamma)$.
	\end{Def}
	\begin{rem}
		We must distinguish our definition of content from the classical definition. 

		We make the following convention: 

		The set $\{\lambda(p^{r-1}(p-1),i),~0\leq i <p^{r-1}(p-1) \}$ serves as the indexing set for the one-dimensional representation of $G_{r}$ for all $r\geq1$. The corresponding \textbf{\textit{p}}-Young diagram of the hook partition $\lambda(p^{r-1}(p-1),i),~0\leq i <p^{r-1}(p-1)$, consists of a single block, and the $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ is filled with a single entry, say $n,~n\in \mathbb{N}$.
	\end{rem}
	\begin{rem}\label{nob}	
		\begin{itemize}
			\item[1.] Let $\lambda(p^{r-s}(2sp-(2s+1)),k),~p^{r-s}[sp-(s+1)]\leq k<sp^{r-s}(p-1)$ represent the hook partitions, which constitute the complete set of irreducible representations of degree $p^{s-1}(p-1)$ for the group $G_{r}$. Furthermore, let $\lambda(2sp-(2s+1),k^{'})$ with $sp-(s+1)\leq k^{'}<s(p-1)$ represent the irreducible representation of degree $p^{s-1}(p-1)$ for the group $G_{s}$.

			The $p$-Young diagrams corresponding to $\lambda(2sp-(2s+1),k^{'})$ and $\lambda(p^{r-s}(2sp-(2s+1)),k)$ consist of $2s$ blocks, where the block sizes are arranged respectively as $(p-1,p-2,\underbrace{p-1\dots,p-1}_{2s-2~times})$ and $(p^{r-s}(p-1),p^{r-s}(p-2),\underbrace{p^{r-s}(p-1)\dots,p^{r-s}(p-1)}_{2s-2~times})$.
			\item[2.] Let $\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k),~p^{r-s-1}[sp-(s+1)]\leq k<(s+1)p^{r-s-1}(p-1)$ represent the hook partitions that form the complete set of irreducible representations of degree $p^{s-1}(p-1)$ for the group $SG_{r}$. Furthermore, let $\lambda((2s+1)p,2(s+1),k^{'})~sp-(s+1)\leq k^{'}<(s+1)(p-1)$ represent the irreducible representation of degree $p^{s-1}(p-1)$ for the group $SG_{s}$. The $p$-Young diagrams corresponding to $\lambda([(2s+1)p-2(s+1)],k^{'})$ and $\lambda(p^{r-s}[(2s+1)p-2(s+1)],k)$ consist of $2s+1$ blocks, where the block sizes are arranged respectively as $(p-1,p-2,\underbrace{p-1\dots,p-1}_{2s-1~times})$ and $(p^{r-s-1}(p-1),p^{r-s-1}(p-2),\underbrace{p^{r-s-1}(p-1)\dots,p^{r-s-1}(p-1)}_{2s-1~times})$.

			\item[3.] Each hook partition of shape $\lambda(p^{r-s}(2sp-(2s+1)),k)$ is obtained from the hook partition of shape $\lambda(p^{r-s}(2p-3),k^{'})$ by adding $2(s-1)$ blocks of size $p^{r-s}(p-1)$. Similarly, the hook partition of shape $\lambda(2sp-(2s+1),sp-(s+1))$ is obtained from the hook partition of shape $\lambda(2p-3,p-2)$ by adding blocks $2(s-1)$ of size $p-1$.

			The hook partition $\lambda(p^{r-s}(2p-3),i)~(\text{and}~\lambda(2p-3,p-2))$ is obtained from the hook partition of shape $\lambda(p^{r-s}(p-1),j)~(\text{and}~\lambda(p-1,j^{'}))$ of dimension one by adding blocks of size $p^{r-s}(p-2)$ $\textbf{(}\text{and}~p-2\textbf{)}$ respectively.
		\end{itemize}				
	\end{rem}				

	\begin{lem}\label{lem mp}
		For $r\geq 1$ and $1\leq s\leq r$,  $$x^{\alpha^{'}}_{\lambda(p^{r-s}[2sp-(2s+1)],i)} = \left(x^{\alpha}_{\lambda(2sp-(2s +1),j)}\right)^{p^{r-s}},$$ where $\alpha=\alpha^{(1)}_{l,l^{'},J}=((2s-l)p-(2s+1-l),a_{1}(p-1),a_{2}(p-1),\dots,a_{l^{'}}(p-1))$, $\alpha^{'}=p^{r-s}\alpha$, 
		$p^{r-s}[sp-(s+1)]\leq i <sp^{r-s}(p-1)$ and $[sp-(s+1)]\leq j<s(p-1)$. 
	\end{lem}
	\begin{proof}
		Fix $i_{1}<i_{2}<\dots<i_{k}$ and choose $\{j_{1},j_{2},\dots,j_{l^{'}+1}\}\subseteq\{i_{1},i_{2},\dots,i_{k}\}$ such that $j_{1}<j_{2}<\dots<j_{l^{'}+1}$.						
		\begin{align*}
			x^{\alpha^{'}}_{\lambda(p^{r-s}[2sp-(2s+1)],i)} & = x^{p^{r-s}[(2s-l)p-(2s+1-l)]}_{j_{1}}x^{a_{1}p^{r-s}(p-1)}_{j_{2}}x^{a_{2}p^{r-s}(p-1)}_{j_{3}}\cdots x^{a_{L}p^{r-s}(p-1)}_{j_{l^{'}+1}} \\ & =\left( x^{(2s-l)p-(2s+1-l)}_{j_{1}}x^{a_{1}(p-1)}_{j_{2}}x^{a_{2}(p-1)}_{j_{3}}\cdots x^{a_{L}(p-1)}_{j_{l^{'}+1}}\right)^{p^{r-s}}
			\\ & = \left(x^{\alpha}_{\lambda(2sp-(2s+1),j)}\right)^{p^{r-s}} 	
		\end{align*}

		Similarly, we can prove for $x^{\alpha^{'}}_{\lambda(p^{r-s}[2sp-(2s+1)],i)} = \left(x^{\alpha}_{\lambda(2sp-(2s +1),j)}\right)^{p^{r-s}}$ where $\alpha=\alpha^{(2)}_{l,l^{'},J}$ and $\alpha^{'}=p^{r-s}\alpha$.  
	\end{proof}

	\begin{lem}\label{lem mp 1}
		For $r\geq 2$ and $1\leq s\leq r$,  $$x^{\gamma^{'}}_{\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],i)} = \left(x^{\gamma}_{\lambda((2s+1)p-2(s+1),j)}\right)^{p^{r-s-1}},$$ where $\gamma = \gamma^{(k)}_{l,l^{'},J}$ for $k=1,2$, $\gamma^{'}=p^{r-s-1}\gamma$, $p^{r-s-1}[sp-(s+1)]\leq i <(s+1)p^{r-s-1}(p-1)$ and $[sp-(s+1)]\leq j<(s+1)(p-1)$. 
	\end{lem}
	\begin{proof}
		This proof is similar to Lemma \ref{lem mp}
	\end{proof}

	\begin{lem}
		Let $\lambda(p^{r-s}[2sp-(2s+1)],k)\in \Lambda_{1}, ~p^{r-s}[sp-(s+1)]\leq k<sp^{r-s}(p-1) $ be a hook partition of size $p^{r-s}[2sp-(2s+1)]$, where $r\geq1$ and $1\leq s \leq r$. Then the total number of ways in which the \textbf{\textit{p}}-Young diagram with $2s$ blocks can be merged into $l^{'}$ blocks is $2^{2s-1}$, where $1\leq l^{'}\leq l$ and $0\leq l\leq 2s-2$.  
	\end{lem}
	\begin{proof}
		The proof follows from Lemma \ref{merging} and Lemma \ref{lem mp}.
	\end{proof}

	\begin{lem}
		Let $\lambda(p^{r-s-1}[(2s+1)p-(2s+2)],k)\in \Lambda_{2}, ~p^{r-s-1}[sp-(s+1)]\leq k<(s+1)p^{r-s-1}(p-1) $ be a hook partition of size $p^{r-s-1}[(2s+1)p-(2s+2)]$, where $r\geq2$ and $1\leq s \leq r-1$. Then the total number of ways in which \textbf{\textit{p}}-Young diagram with $2s+1$ blocks can be merged into $l^{'}$ blocks is $2^{2s}$, where $1\leq l^{'}\leq l$ and $0\leq l\leq 2s-1$.  
	\end{lem}
	\begin{proof}
		The proof follows from Lemma \ref{merging} and Lemma \ref{lem mp 1}.
	\end{proof}

	\begin{Def}
		Let $K_{\lambda(p^{r-s}(2s)),\alpha}~(\text{and}~K_{\lambda(p^{r-s-1}(2s+1)),\gamma})$ denote the number of $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ of size $p^{r-s}[2sp-(2s+1)]~(\text{and}~p^{r-s-1}[(2s+1)p-2(s+1)])$ with \textbf{\textit{p}}-content $\alpha\in\mathbb{Q}^{(r,s)}_{2s}~(\text{and}~\gamma \in\mathbb{Q}^{(r,s)}_{2s+1})$. These numbers are called \textbf{\textit{p}}-Kostka numbers.   
	\end{Def}
	\begin{lem}\label{kostka}
		\begin{enumerate}
			\item $K_{\lambda(p^{r-s}(2s)),\beta^{(k)}_{l,l^{'},J}}=   K_{\lambda(2s),\alpha^{(k)}_{l,l^{'},J}}$, where $\beta^{(k)}_{l,l^{'},J}=p^{r-s}\alpha^{(k)}_{l,l^{'},J}$ for $k=1,2$. 
			\item 	$K_{\lambda(p^{r-s}(2s+1)),\beta^{(k)}_{l,l^{'},J}}=   K_{\lambda(2s+1),\gamma^{(k)}_{l,l^{'},J}}$, where $\beta^{(k)}_{l,l^{'},J}=p^{r-s-1}\gamma^{(k)}_{l,l^{'},J}$ for $k=1,2$. 
		\end{enumerate}
	\end{lem}
	\begin{proof}
		\begin{enumerate}
			\item	Since the maximum number of blocks in the $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ of shapes $\lambda([2sp-(2s+1)],k^{'})$ and $\lambda(p^{r-s}[2sp-(2s+1)],k)$ are the same (by remark \ref{nob}), it follows that the number of different types of filling to the $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ with the same number of blocks is also the same.\label{1}
			\item The proof is similar to (\ref{1}).
		\end{enumerate}
	\end{proof}

	\begin{Def}
		\noindent\textbf{\textbf{\textit{p}}-Schur function}
		\begin{itemize}
			\item For any partition $\lambda(p^{r-1}(p-1),k)\in\Lambda$, we define a \textbf{\textit{p}}-Schur function as
			$$\mathcal{S}_{\lambda(p^{r-1}(p-1)),k}(x) = \sum_{i\geq1} x^{p^{r-1}(p-1)}_{i}.$$        
			\item For any partition $\lambda(p^{r-s}[2sp-(2s+1)],k) \in \Lambda_{1}$, we define a \textbf{\textit{p}}-Schur function as

			$$\mathcal{S}_{\lambda(p^{r-s}[2sp-(2s+1)],k)}(x) =\sum_{\substack{I \\ |I|=2s}} \sum_{\alpha\in \mathbb{Q}^{(r,s)}_{2s}} x^{\alpha(T^{l,l^{'},J})}.$$    
			\item For any partition $\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k) \in \Lambda_{2}$, we define a \textbf{\textit{p}}-Schur function as

			$$\mathcal{S}_{\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k)}(x) = \sum_{\substack{I\\|I|=2s+1}}\sum_{\gamma\in \mathbb{Q}^{(r,s)}_{2s+1}} x^{\gamma(T^{l,l^{'},J})}.$$                                      \end{itemize}              	
	\end{Def}
	\begin{lem}\label{schur}
		\begin{enumerate}
			\item $S_{\lambda(p^{r-s}[2sp-(2s+1)],k)}(x)=S_{\lambda(p^{r-s}[2sp-(2s+1)],k^{'})}(x)$, where $p^{r-s}[sp-(s+1)\leq k,k^{'}<sp^{r-s}(p-1)]$
			\item $S_{\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k)}(x)=S_{\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k^{'})}(x)$, where $p^{r-s}[sp-(s+1)\leq k,k^{'}<(s+1)p^{r-s}(p-1)]$ 
		\end{enumerate}
	\end{lem}		
	\begin{proof}
		\begin{enumerate}

			\item The proof is obvious, for each $\textbf{\textit{SSYT}}_{\textbf{\textit{p}}}$ of shape $\lambda(p^{r-s}[2sp-(2s+1)],j)$ and size $p^{r-s}[2sp-(2s+1)]$ is attained by adding different types of block with same size. Since the number of blocks and their sizes are the same for all hook partitions with same size, the filling are also similar, which proves the equality. \label{11}

			\item The proof is similar to (\ref{11}). 
		\end{enumerate}
	\end{proof}	
	\begin{thm}(\textbf{Lacunary Cauchy identity})
	\begin{align*}
		\sum_{\lambda\in \Lambda}\mathcal{S}_{\lambda}(x)\mathcal{S}_{\lambda}(y)&= (p-1)^{2}\sum_{i,j\geq 1}g(x^{p-1}_{i}y^{p-1}_{j})+\sum_{s\geq 1}\sum_{\alpha,\beta\in \mathbb{Q}_{\lambda,2s}}K_{\lambda(2s),\alpha}K_{\lambda(2s),\beta}\cdot g(x^{\alpha},y^{\beta})\\&~~~+p^{2} \sum_{s\geq1}\sum_{\gamma,\delta\in\mathbb{Q}_{\lambda,2s+1}}K_{\lambda(2s+1),\gamma}K_{\lambda(2s+1),\delta}\cdot g(x^{\gamma},y^{\delta})
	\end{align*}	
	where $g(x)=\sum_{n\geq 0}p^{2n}x^{p^{n}}$.
\end{thm}
\begin{proof}
	\begin{itemize}
		\item Let $\lambda(p^{r-1}(p-1),k)\in V^{r}_{0}(W^{r}_{0}), ~r\geq 1$ be a hook partition of degree $1$. Then
		\begin{align*}
			\sum_{r\geq 1} \mathcal{S}_{\lambda(p^{r-1}(p-1),k)}(x)\mathcal{S}_{\lambda(p^{r-1}(p-1),k)}(y)
			&= \sum_{i,j\geq 1}(p-1)^{2}x^{p-1}_{i}y^{p-1}_{j}+p^{2}(p-1)^{2}(x^{p-1}_{i})^{p}(y^{p-1}_{j})^{p}\\&+p^{4}(p-1)^{2}(x^{p-1}_{i})^{p^{2}}(y^{p-1}_{j})^{p^{2}}+\dots \\
			&=\sum_{i,j\geq 1}(p-1)^{2}\sum_{n\geq0}p^{2n}(x^{p-1}_{i})^{p^{n}}(y^{p-1}_{j})^{p^{n}}\\
			& = (p-1)^{2}\sum_{i,j\geq 1}g(x^{p-1}_{i}y^{p-1}_{j})
		\end{align*}
		\item Let $\lambda(p^{r-s}[2sp-(2s+1)],k)\in V^{r}_{s}, ~r\geq 1$ be a hook partition of degree $p^{s-1}(p-1)$. Then
		\begin{align*}
			&\hspace*{-5cm}\sum_{\substack{1\leq s\leq r, \\r\geq 1}} \mathcal{S}_{\lambda(p^{r-s}[2sp-(2s+1)],k)}(x)\mathcal{S}_{\lambda(p^{r-s}[2sp-(2s+1)],k^{'})}(y)\\
			&\hspace*{-3.3cm}= \sum_{\substack{1\leq s\leq r, \\r\geq 1}}\left(\sum_{\alpha\in\mathbb{Q}^{(r,s)}_{2s}}x^{\alpha}\sum_{\beta\in\mathbb{Q}^{(r,s)}_{2s}}y^{\beta}\right)
		\end{align*}
		By using Lemma \ref{kostka}, Lemma \ref{schur}, Lemma \ref{lem mp} and rearranging the summation, we get
		\begin{align*}
			&\hspace*{1cm}=\sum_{s\geq 1}\sum_{\alpha,\beta\in\mathbb{Q}^{(s,s)}_{2s}}K_{\lambda(2s),\alpha}K_{\lambda(2s),\beta}\cdot(x^{\alpha}y^{\beta})+K_{\lambda(2s),\alpha}K_{\lambda(2s),\beta}\cdot p^{2}(x^{\alpha}y^{\beta})^{p}+\dots \\
			&\hspace*{1cm}=\sum_{s\geq 1}\sum_{\alpha,\beta\in\mathbb{Q}^{(s,s)}_{2s}}K_{\lambda(2s),\alpha}K_{\lambda(2s),\beta}\cdot g(x^{\alpha}y^{\beta})
		\end{align*}
		\item Let $\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k)\in W^{r}_{s}, ~r\geq 2$ be a hook partition of degree $p^{s-1}(p-1)$. Then
		\begin{align*}
			&\hspace*{-3.3cm}\sum_{\substack{1\leq s\leq r-1, \\r-1\geq 1}} \mathcal{S}_{\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k)}(x)\mathcal{S}_{\lambda(p^{r-s-1}[(2s+1)p-2(s+1)],k^{'})}(y)\\
			&\hspace*{-2cm}=\sum_{\substack{1\leq s\leq r-1, \\r-1\geq 1}}\left(\sum_{\gamma\in\mathbb{Q}^{(r,s)}_{2s+1}}x^{\gamma}\sum_{\delta \in\mathbb{Q}^{(r,s)}_{2s+1}}y^{\delta}\right)
		\end{align*}
		By using Lemma \ref{kostka}, Lemma \ref{schur}, Lemma \ref{lem mp 1} and  rearranging the summation, we get
		\begin{align*}
			&\quad= \sum_{s\geq 1}\sum_{\gamma,\delta\in\mathbb{Q}^{(s,s)}_{2s+1}}p^{2}K_{\lambda(2s+1),\gamma}K_{\lambda(2s+1),\delta}\cdot (x^{\gamma}y^{\delta})+p^{2}K_{\lambda(2s+1),\gamma}K_{\lambda(2s+1),\delta}\cdot p^{2}(x^{\gamma}y^{\delta})^{p}+\dots \\
			&\quad=p^{2}\sum_{s\geq 1}\sum_{\gamma,\delta\in\mathbb{Q}^{(s,s)}_{2s+1}}K_{\lambda(2s+1),\gamma}K_{\lambda(2s+1),\delta}\cdot g(x^{\gamma}y^{\delta})
		\end{align*}
	\end{itemize}
\end{proof}

	\begin{rem}
		\textbf{The series $g(x)=\sum\limits_{n\geq 0}p^{2n}x^{p^{n}}$ obtained in the above theorem is a ``lacunary series". The series $g(x)$ converges absolutely, but we could not find the closed form expression of it.}
	\end{rem}
	\section{Conclusions}
	This paper establishes a Robinson-Schensted correspondence between the group $G_{r}$ (and $SG_{r}$) and the pairs of  standard \textit{p}-Young tableaux. Our approach, which utilizes matrix units computed from the orthogonal primitive idempotents, provides a fresh perspective on the representation theory of these groups. In a future paper, we will build upon this work to define the descents for each tableau in sets $\Lambda_{1}$ and $\Lambda_{2}$. We then derive the generating function for the total number of descents at each vertex. In addition, we present several identities that establish connections between the tableaux and irreducible representations.

