\end{equation}
\end{mylem}

\begin{proof}
From (\ref{asy optimal state}) and (\ref{asy lim-optimal state}), the difference $\check{x}_i(\cdot)-x_i^+(\cdot)$ satisfies
\begin{equation}
\left\{\begin{aligned}
	d(\check{x}_i-x_i^+)&=\left\{\left[\tilde{A}-\left(\tilde{B}+\tilde{H}L\right)\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)^{-1}\left(\tilde{B}+\tilde{H}L\right)^\top\Sigma\right](\check{x}_i-x_i^+)\right.\\
    &\qquad +\tilde{F}\left(\check{x}^{(N)}-m^+\right)\bigg\}dt,\\
