	&\qquad \times\left(\check{x}^{(N)}-m^+\right)\bigg\}dt+\frac{\sigma}{N}\sum_{i=1}^{N}dW_i,\\
	\check{x}_i(0)-x_i^+(0)&=0,\quad\check{x}^{(N)}(0)-m^+(0)=0.
\end{aligned}\right.
