\begin{equation}
	\big\vert\mathcal{J}_i(u_{0i}(\check{u}_{1i}^+)(\cdot),\check{u}_{1i}^+(\cdot))-J_i(u_{0i}(u_{1i}^+)(\cdot),u_{1i}^+(\cdot))\big\vert=O\left(\frac{1}{\sqrt{N}}\right).
