	&\qquad\quad +\left\langle\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)(\check{u}_{1i}^+-u_{1i}^+),\check{u}_{1i}^+-u_{1i}^+\right\rangle
    +2\left\langle\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)u_{1i}^+,\check{u}_{1i}^+-u_{1i}^+\right\rangle\\
	&\qquad\quad +\left.2\left\langle L^\top\tilde{R}_0\zeta x_0^++L^\top\tilde{R}_0\eta m^+,\check{u}_{1i}^+-u_{1i}^+\right\rangle\right]dt
    +\left\langle\tilde{G}\left(\check{x}_i(T)-x_i^+(T)\right),\check{x}_i(T)-x_i^+(T)\right\rangle\\
	&\qquad +2\left\langle\tilde{G}x_i^+(T),\check{x}_i(T)-x_i^+(T)\right\rangle +\left\langle\tilde{\Gamma}_2^\top\tilde{G}\tilde{\Gamma}_2\left(\check{x}^{(N)}(T)-m^+(T)\right),\check{x}^{(N)}(T)-m^+(T)\right\rangle\\
