Noting the fact that $\mathbb{E}\int_0^T\big[\vert x_i^+(t)\vert^2+\vert m^+(t)\vert^2\big]dt<\infty$, $\mathbb{E}\int_0^T\vert\check{x}_i(t)\vert^2dt<\infty$ and from (\ref{est diff1}), it holds
\begin{equation}
	\big\vert\mathcal{J}_i(u_{0i}(\check{u}_{1i}^+)(\cdot),\check{u}_{1i}^+(\cdot))-J_i(u_{0i}(u_{1i}^+)(\cdot),u_{1i}^+(\cdot))\big\vert\leq\frac{C}{\sqrt{N}}.
\end{equation}
The lemma follows.
\end{proof}

For any $u_{1i}(\cdot)\in\mathcal{U}_{ic}$, consider the set of strategies $(u_{1i}(\cdot),\check{u}_{-1i}^+(\cdot))$. Obviously,
\begin{equation*}
	\lim\limits_{N\to\infty}\check{u}_{-1}^{(N)}(\cdot):=\lim\limits_{N\to\infty}\frac{1}{N}\left(\sum_{j\neq i}^{N}\check{u}_{1j}^+(\cdot)+u_{1i}(\cdot)\right)=\bar{\check{u}}_1^+(\cdot)=\bar{u}_1^+(\cdot).
\end{equation*}
The corresponding state processes are
\begin{equation}\label{asy state}\hspace{-2mm}
\left\{\begin{aligned}
	dx_i&=\left[\tilde{A}x_i+\tilde{F}x^{(N)}+\left(\tilde{B}+\tilde{H}L\right)u_{1i}+\tilde{H}\zeta x_0+\tilde{H}\eta m\right]dt+\sigma dW_i,\\
	dx_j&=\left[\tilde{A}x_j+\tilde{F}x^{(N)}+\left(\tilde{B}+\tilde{H}L\right)\check{u}_{1j}^++\tilde{H}\zeta x_0+\tilde{H}\eta m\right]dt+\sigma dW_j,\\
	dx^{(N)}&=\left[\left(\tilde{A}+\tilde{F}\right)x^{(N)}+\left(\tilde{B}+\tilde{H}L\right)\check{u}_1^{(N)}+\frac{1}{N}\left(\tilde{B}+\tilde{H}L\right)(u_{1i}-\check{u}_{1i}^+)\right.\\
	&\qquad +\tilde{H}\zeta x_0+\tilde{H}\eta m\bigg]dt+\frac{\sigma}{N}\sum_{i=1}^{N}dW_i,\\
	dm&=\left[\left(\tilde{A}+\tilde{F}+\tilde{H}\eta\right)m+\left(\tilde{B}+\tilde{H}L\right)\bar{u}_1^++\tilde{H}\zeta x_0\right]dt,\\
	dx_0&=\left[\left(A+\gamma^{-2}ER_2^{-1}E^\top P_1+B\zeta\right)x_0+\left(F+\gamma^{-2}ER_2^{-1}E^\top \Pi_1+B\eta\right)m\right.\\
    &\qquad +(H+BL)\bar{u}_1^+\Big]dt+\left[(C+D\zeta)x_0+D\eta m+DL\bar{u}_1^+\right]dW_0,\\
	x_i(0)&=x,\quad x_j(0)=x,\quad x^{(N)}(0)=x,\quad m(0)=x,\quad x_0(0)=\xi,\quad 1\leq j\leq N,\quad j\neq i,
\end{aligned}\right.
\end{equation}
and the cost functional is
\begin{equation}
\begin{aligned}
	&\mathcal{J}_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(\check{u}_{-1i}^+)(\cdot),u_{1i}(\cdot),\check{u}_{-1i}^+(\cdot)\right)\\
	&=\mathbb{E}\bigg\{\int_0^T\left[\left\langle\tilde{Q}x_i,x_i\right\rangle +\left\langle\tilde{\Gamma}_1^\top\tilde{Q}\tilde{\Gamma}_1x^{(N)},x^{(N)}\right\rangle
    +\left\langle\eta^\top\tilde{R}_0\eta m,m\right\rangle +\left\langle\zeta^\top\tilde{R}_0\zeta x_0,x_0\right\rangle\right.\\
	&\qquad\quad -2\left\langle\tilde{Q}\tilde{\Gamma}_1x^{(N)},x_i\right\rangle +2\left\langle\eta^\top\tilde{R}_0\zeta x_0,m\right\rangle +\left\langle\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)u_{1i},u_{1i}\right\rangle\\
	&\qquad\quad +\left.2\left\langle L^\top\tilde{R}_0\zeta x_0+L^\top\tilde{R}_0\eta m,u_{1i}\right\rangle\right]dt +\left\langle\tilde{G}x_i(T),x_i(T)\right\rangle\\
	&\qquad\quad -2\left\langle\tilde{G}\tilde{\Gamma}_2x^{(N)}(T),x_i(T)\right\rangle +\left\langle\tilde{\Gamma}_2^\top\tilde{G}\tilde{\Gamma}_2x^{(N)}(T),x^{(N)}(T)\right\rangle\bigg\}.
\end{aligned}
\end{equation}
Here, since $\bar{\check{u}}_1^+(\cdot)=\bar{u}_1^+(\cdot)$, thus $m(\cdot)=m^+(\cdot)$ and $x_0(\cdot)=x_0^+(\cdot)$.
When $N$ tends to infinity, $\check{u}_{1j}^+(\cdot)\to u_{1j}^+(\cdot)$, and the corresponding limiting system is as follows:
\begin{equation}\label{asy lim state}
\left\{\begin{aligned}
	d\bar{x}_i&=\left[\tilde{A}\bar{x}_i+\left(\tilde{F}+\tilde{H}\eta\right)m+\left(\tilde{B}+\tilde{H}L\right)u_{1i}+\tilde{H}\zeta x_0\right]dt+\sigma dW_i,\\
	d\bar{x}_j&=\left[\tilde{A}\bar{x}_j+\left(\tilde{F}+\tilde{H}\eta\right)m+\left(\tilde{B}+\tilde{H}L\right)u_{1j}^++\tilde{H}\zeta x_0\right]dt+\sigma dW_j,\\
	dm&=\left[\left(\tilde{A}+\tilde{F}+\tilde{H}\eta\right)m+\left(\tilde{B}+\tilde{H}L\right)\bar{u}_1^++\tilde{H}\zeta x_0\right]dt,\\
	dx_0&=\left[\left(A+\gamma^{-2}ER_2^{-1}E^\top P_1+B\zeta\right)x_0+\left(F+\gamma^{-2}ER_2^{-1}E^\top \Pi_1+B\eta\right)m\right.\\
	&\qquad +(H+BL)\bar{u}_1^+\Big]dt +\left[(C+D\zeta)x_0+D\eta m+DL\bar{u}_1^+\right]dW_0,\\
	\bar{x}_i(0)&=x,\quad \bar{x}_j(0)=x,\quad m(0)=x,\quad x_0(0)=\xi,\quad 1\leq j\leq N,\quad j\neq i,
\end{aligned}\right.
\end{equation}
with
\begin{equation}
\begin{aligned}
	&J_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(u_{-1i}^+)(\cdot),u_{1i}(\cdot),u_{-1i}^+(\cdot)\right)\\
	&=\mathbb{E}\bigg\{\int_0^T\left[\left\langle\tilde{Q}\bar{x}_i,\bar{x}_i\right\rangle +\left\langle\left(\eta^\top\tilde{R}_0\eta+\tilde{\Gamma}_1^\top\tilde{Q}\tilde{\Gamma}_1\right)m,m\right\rangle
    +\left\langle\zeta^\top\tilde{R}_0\zeta x_0,x_0\right\rangle\right.\\
	&\qquad\quad -2\left\langle\tilde{Q}\tilde{\Gamma}_1m,\bar{x}_i\right\rangle +2\left\langle\eta^\top\tilde{R}_0\zeta x_0,m\right\rangle +\left\langle\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)u_{1i},u_{1i}\right\rangle\\
	&\qquad\quad +\left.2\left\langle L^\top\tilde{R}_0\zeta x_0+L^\top\tilde{R}_0\eta m,u_{1i}\right\rangle\right]dt +\left\langle\tilde{G}\bar{x}_i(T),\bar{x}_i(T)\right\rangle\\
	&\qquad\quad -2\left\langle\tilde{G}\tilde{\Gamma}_2m(T),\bar{x}_i(T)\right\rangle +\left\langle\tilde{\Gamma}_2^\top\tilde{G}\tilde{\Gamma}_2m(T),m(T)\right\rangle\bigg\}.
\end{aligned}
\end{equation}

\begin{mylem}
Let \textbf{(A1)}-\textbf{(A4)} hold, and $\gamma>\hat{\gamma}$. Then the following estimations hold
\begin{equation}\label{est diff3}
\begin{aligned}
	&\sup_{0\leq t\leq T}\mathbb{E}\left\vert x^{(N)}(t)-m(t)\right\vert^2=O\left(\frac{1}{N}\right),\\
	&\sup_{0\leq t\leq T}\mathbb{E}\left\vert x_i(t)-\bar{x}_i(t)\right\vert^2=O\left(\frac{1}{N}\right),\\
	&\sup_{0\leq t\leq T}\mathbb{E}\left\vert x_j(t)-\bar{x}_j(t)\right\vert^2=O\left(\frac{1}{N}\right),\quad 1\leq j\leq N,\quad j\neq i.
\end{aligned}
\end{equation}
\end{mylem}

\begin{proof}
Subtract (\ref{asy state}) from (\ref{asy lim state}), we have
\begin{equation}
\left\{\begin{aligned}
	d(x_i-\bar{x}_i)&=\left[\tilde{A}(x_i-\bar{x}_i)+\tilde{F}\left(x^{(N)}-m\right)\right]dt,\\
	d(x_j-\bar{x}_j)&=\left[\tilde{A}(x_j-\bar{x}_j)+\tilde{F}\left(x^{(N)}-m\right)+\left(\tilde{B}+\tilde{H}L\right)(\check{u}_{1j}^+-u_{1j}^+)\right]dt,\\
	d(x^{(N)}-m)&=\left[\left(\tilde{A}+\tilde{F}\right)\left(x^{(N)}-m\right)+\left(\tilde{B}+\tilde{H}L\right)\left(\check{u}_1^{(N)}-\bar{u}_1^+\right)\right.\\
	&\qquad +\left.\frac{1}{N}\left(\tilde{B}+\tilde{H}L\right)(u_{1i}-\check{u}_{1i}^+)\right]dt+\frac{\sigma}{N}\sum_{i=1}^{N}dW_i,\\
	x_i(0)-\bar{x}_i(0)&=0,\quad x_j(0)-\bar{x}_j(0)=0,\quad x^{(N)}(0)-m(0)=0.
\end{aligned}\right.
\end{equation}
Since
\begin{equation}
\left\{
\begin{aligned}
	\check{u}_1^{(N)}(\cdot)&=-\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)^{-1}\left\{\left(\tilde{B}+\tilde{H}L\right)^\top\Sigma \check{x}^{(N)}+\left[L^\top\tilde{R}_0\zeta+\left(\tilde{B}+\tilde{H}L\right)^\top\Psi\right]x_0^+\right.\\
	&\qquad +\left.\left[L^\top\tilde{R}_0\eta+\left(\tilde{B}+\tilde{H}L\right)^\top\Phi\right] m^+\right\},\\
	\bar{u}_1^+(\cdot)&=-\left(\tilde{R}_1+L^\top\tilde{R}_0L\right)^{-1}\left\{\left[L^\top\tilde{R}_0\zeta+\left(\tilde{B}+\tilde{H}L\right)^\top\Theta\right]x_0^+\right.\\
    &\qquad +\left.\left[L^\top\tilde{R}_0\eta+\left(\tilde{B}+\tilde{H}L\right)^\top\Delta\right] m^+\right\},
\end{aligned}
\right.
\end{equation}
and the difference is
\begin{equation}
	\check{u}_1^{(N)}(\cdot)-\bar{u}_1^+(\cdot)=-\left(\tilde{R}_1+L^{\top}\tilde{R}_0L\right)^{-1}\left(\tilde{B}+\tilde{H}L\right)^\top\Sigma\left(\check{x}^{(N)}-m^+\right).
\end{equation}
Thus, by Lemma \ref{est lemma1} and the boundedness of the coefficients, we obtain
\begin{equation*}
	\mathbb{E}\int_0^T\left\vert\check{u}_1^{(N)}(t)-\bar{u}_1^+(t)\right\vert^2dt=O\left(\frac{1}{N}\right).
\end{equation*}
By (\ref{est diff2}) and linear SDEs' estimates, the lemma follows.
\end{proof}

\begin{mylem}\label{est lemma3}
Let \textbf{(A1)}-\textbf{(A4)} hold, and $\gamma>\hat{\gamma}$. It holds that
\begin{equation}
\begin{aligned}
	&\left\vert\mathcal{J}_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(\check{u}_{-1i}^+)(\cdot),u_{1i}(\cdot),\check{u}_{-1i}^+(\cdot)\right)\right.\\
&\quad -\left.J_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(u_{-1i}^+)(\cdot),u_{1i}(\cdot),u_{-1i}^+(\cdot)\right)\right\vert=O\left(\frac{1}{\sqrt{N}}\right).
\end{aligned}
\end{equation}
\end{mylem}

\begin{proof}
The proof is similar to Lemma \ref{est lemma2} and omitted.
\end{proof}
From the above, we have the following result.
\begin{mythm}\label{followers asy thm}
Let \textbf{(A1)}-\textbf{(A4)} hold, and $\gamma>\hat{\gamma}$. Assume that the CC-incentive system (\ref{cc-incentive}) admits a solution. For any alternative $u_{1i}(\cdot)$ and the decentralized strategy $(\check{u}_{11}^+(\cdot),\cdots,\check{u}_{1N}^+(\cdot))$, we have
\begin{equation}
	\bar{\check{u}}_1^+(\cdot)=\lim\limits_{N\to\infty}\frac{1}{N}\sum_{i=1}^{N}\check{u}_{1i}^+(\cdot)=\bar{u}_1^+(\cdot)=\bar{u}_1^*(\cdot),
\end{equation}
\begin{equation}
\begin{aligned}
	&\mathcal{J}_i\left(u_{0i}(\check{u}_{1i}^+)(\cdot),\check{u}_{1i}^+(\cdot)\right)\\
&\leq\mathcal{J}_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(\check{u}_{-1i}^+)(\cdot),u_{1i}(\cdot),\check{u}_{-1i}^+(\cdot)\right)+O\left(\frac{1}{\sqrt{N}}\right),\quad\forall u_{1i}(\cdot)\in\mathcal{U}_{ic}.
\end{aligned}
\end{equation}
\end{mythm}

\begin{proof}
Using the results mentioned in Lemmas \ref{est lemma2} and \ref{est lemma3}, we have
\begin{equation}
\begin{aligned}
	&\mathcal{J}_i(u_{0i}(\check{u}_{1i}^+)(\cdot),\check{u}_{1i}^+(\cdot))= J_i(u_{0i}(u_{1i}^+)(\cdot),u_{1i}^+(\cdot))+O\left(\frac{1}{\sqrt{N}}\right)\\
	&\leq J_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(u_{-1i}^+)(\cdot),u_{1i}(\cdot),u_{-1i}^+(\cdot)\right)+O\left(\frac{1}{\sqrt{N}}\right)\\
	&\leq \mathcal{J}_i\left(u_{0i}(u_{1i})(\cdot),u_{-0i}(\check{u}_{-1i}^+)(\cdot),u_{1i}(\cdot),\check{u}_{-1i}^+(\cdot)\right)+O\left(\frac{1}{\sqrt{N}}\right),
\end{aligned}
\end{equation}
thus the decentralized strategies $\check{u}_1^+(\cdot)=(\check{u}_{11}^+(\cdot),\cdots,\check{u}_{1N}^+(\cdot))$ has the $\hat{\epsilon}$-followers' Nash equilibrium property with $\hat{\epsilon}=O\left(\frac{1}{\sqrt{N}}\right)$.
\end{proof}
From Definition \ref{def}, Theorem \ref{leader asy thm} and \ref{followers asy thm}, we now state the main result of this section.

\begin{mythm}
Let \textbf{(A1)}-\textbf{(A4)} hold, and $\gamma>\hat{\gamma}$. Assume that the CC-incentive system (\ref{cc-incentive}) admits a solution. Then $(\hat{u}_0^*(\cdot),\hat{u}_1^*(\cdot),\hat{v}^*(\cdot))$ given by (\ref{de-sts}) is an $\epsilon$-robust incentive strategy.
\end{mythm}

