    \begin{tabular}{ | P{2.8cm}|| P{5.5cm} | P{5.5cm} |  }
    \hline 
    \bigg. & $\gamma \ll H$ & $H \gg \gamma$ \\
    \hline
    \bigg.$\tilde{G}_{0}~ \text{mixing:}$ & $\epsilon \ll 1$ & $ \epsilon \ll 1$ \\
    \hline 
    \bigg.$\tilde{G}_{1}~ \text{mixing:}$ & $\epsilon \ll 1$ & $\epsilon H \ll \gamma$\\
    \hline
    \bigg.$\tilde{G}_{2}~ \text{mixing:}$ & $\epsilon \ll 1$  & $\cs\epsilon H \ll \gamma$ \\
     \hline
    \end{tabular}
    \end{center}
\caption{Hierarchy of scales among the noise coefficients to reach decoupling of the $\pi$ sector in the presence of noise in the gravity sector.}
\label{tab:noisedecoupv0}
\end{table}

At last, we include the noise contributions appearing in the constraints \eqref{eq:c1} and \eqref{eq:c2}, that is
\begin{align}
    \phi \supset \frac{\xi_{||}}{H\Mpl^{2}},\quad \mathrm{and}\quad
    \nabla^{2}F \supset a(t)\left[ - \frac{\xi_{00}}{\Mpl^{2}H} - \left(\frac{3c_{s}^{2}-\epsilon}{c_{s}^{2}\Mpl^{2}}\right)\xi_{||}\right].
\end{align}
%
By demanding that $\xi_{\pi}$ dominates over the stochastic terms coming from the constraints, we obtain a set of requirements. Making use of \Eq{eq:noisepi}, we further ask that the $\xi_{00}$ contributions from $\xi_{\pi}$ dominates from the $\xi_{00}$ contributions from the constraints, and similarly for $\xi_{\parallel}$.\footnote{One may need the heuristic estimate $\cs k^2 \sim (a H)^2$ at low dissipation and $\cs k^2 \sim  (\gamma/H) \times (a H)^2$ at large dissipation \cite{Salcedo:2024smn}.} This is a conservative requirement, as the aggregate contributions of $\xi_{\pi}$ could collectively dominate over the stochastic contributions of the constraints. We obtain the results stated in Table \ref{tab:noisedecoupv0} for decoupling to hold. Again, these bounds are easy to satisfied when the slow-roll hierarchy holds. 
%
We conclude that the quadratic dynamics of \cite{Salcedo:2024smn},
\begin{align}\label{eq:Sdecoup}
    S_{\pi}&\xrightarrow{(\text{decoupl.})} \int\sqrt{-g}\left\{- \dpir \dpia + \cs \bar{g}^{ij} \partial_i\pir \partial_j \pia + 2 \gamma \dpir \pia +  \frac{c_{s}^{2}}{\epsilon H^{2}\Mpl^{2}}\xi_{\pi} \pia\right\}, 
\end{align}
can indeed be understood as the decoupling limit of the theory of open gravity. 


