\appendix

\section{Background quantities}\label{App:background}

In this appendix, we include the relevant background quantities used in the discussion of Sec.~\ref{Sec:Background}. 
%

\subsection{Flat FLRW}\label{app:flat}
%

Let us first discuss the case where the spatial curvature is flat. The background metric is given by 
\begin{align}
    \bar{g}_{00} &= - 1, \qquad \bar{g}_{ij} = a^2(t) \delta_{ij} \,,\\
    \bar{g}^{00} &= - 1, \qquad \bar{g}^{ij} = a^{-2}(t) \delta^{ij}.
\end{align}
The background Riemann tensor is
\begin{align}
    \bar{R}_{0i0j}=&-(\dot{H}+H^{2})a^{2}(t)\delta_{ij}\,,\\
    \bar{R}_{ijkl}=&-H^{2}a^{2}(t)\left(\delta_{ik}\delta_{jl}-\delta_{il}\delta_{jk}\right)\,,
\end{align}
with all other components vanishing on the background. It follows that 
\begin{align}
    \bar{R}^{\mu \nu} &= \begin{pmatrix}
       - 3(\dot{H}+H^2) & 0 & 0 & 0 \\
        0 & a^{-2}(\dot{H}+3H^2) &0 &0 \\
        0 & 0 & a^{-2}(\dot{H}+3H^2) & 0 \\
        0 & 0 & 0 &a^{-2}(\dot{H}+3H^2)
    \end{pmatrix},
\end{align}
or equivalently 
\begin{align}
    \bar{R}_{\mu \nu} &= \begin{pmatrix}
        -3(\dot{H}+H^2) & 0 & 0 & 0 \\
        0 & a^{2}(\dot{H}+3H^2) &0 &0 \\
        0 & 0 & a^{2}(\dot{H}+3H^2) & 0 \\
        0 & 0 & 0 &a^{2}(\dot{H}+3H^2)
    \end{pmatrix}.
\end{align}
Consequently, $\bar{R} = 12H^2 + 6\dot{H}$ and 
\begin{align}
    \bar{G}_{\mu \nu} &= \begin{pmatrix}
        3H^2& 0 & 0 & 0 \\
        0 & -a^{2}(2\dot{H}+3H^2) &0 &0 \\
        0 & 0 & -a^{2}(2\dot{H}+3H^2)  & 0 \\
        0 & 0 & 0 & -a^{2}(2\dot{H}+3H^2) 
    \end{pmatrix}.
\end{align}
%
The non-vanishing background Christoffel symbols are
\begin{align}
    \bar{\Gamma}^0_{ij} = H a^{2}(t) \delta_{ij}, \qquad \bar{\Gamma}^i_{0j} = \bar{\Gamma}^i_{j0} = H \delta^i_j.
\end{align}
The background timelike vector is
\begin{equation}
    n_{\mu}=(-1,0,0,0),
\end{equation}
such that the background extrinsic curvature reads
\begin{equation}
    \bar{K}_{\mu\nu}=h^{~\alpha}_{\mu}\bar{\nabla}_{\alpha}\bar{n}_{\nu}=\bar{\Gamma}^{0}_{\mu\nu},
\end{equation}
from which we deduce that the only non-zero elements are $\bar{K}_{ii}=H a^{2}(t)$ (no sum over $i$) and the trace of the extrinsic curvature is $\bar{K}=3H$.

\subsection{Curved FLRW}\label{app:curvature}
%

Here, we include spatial curvature. It is easier to achieve this in spherical coordinates, where the coordinates are $t,~r,~\theta$ and $\varphi$. The background metric is given by
\begin{align}
    \bar{g}_{\mu\nu}&=\text{Diag}\left\{-1,\frac{a^{2}(t)}{1-\mathfrak{C}r^{2}},r^{2}a^{2}(t),r^{2}\text{sin}^{2}\left(\theta\right)\right\} \,,\\
    \bar{g}^{\mu\nu}&=\text{Diag}\left\{-1,\frac{1-\mathfrak{C}r^{2}}{a^{2}(t)},\frac{1}{a^{2}(t)r^{2}},\frac{1}{a^{2}(t)r^{2}\text{sin}^{2}\left(\theta\right)}\right\}.
\end{align}
The background Riemann tensor then becomes
\begin{equation}
    R^{\;0\;\;0}_{\;\;\;\mu\;\;\nu}=\text{Diag}\left\{0,\frac{a^{2}(t)}{1-\mathfrak{C}r^{2}}\left(\dot{H}+H^{2}\right),a^{2}(t)r^{2}\left(\dot{H}+H^{2}\right),a^{2}(t)r^{2}\text{sin}^{2}\left(\theta\right)\left(\dot{H}+H^{2}\right)\right\}.
\end{equation}
The Ricci tensor is given by
\begin{equation}
    \bar{R}_{\mu\nu}=\begin{pmatrix}
       -3\left(\dot{H}+H^{2}\right) & 0 & 0 & 0 \\
       0 & \frac{a^{2}(t)\left(2\mathfrak{C}+\dot{H}+3H^{2}\right)}{1+\mathfrak{C}r^{2}} & 0 & 0 \\
       0 & 0 & a^{2}(t)r^{2}\left(2\mathfrak{C}+\dot{H}+3H^{2}\right) & 0 \\
       0 & 0 & 0 & a^{2}(t)r^{2}\text{sin}^{2}\left(\theta\right)\left(2\mathfrak{C}+\dot{H}+3H^{2}\right) 
    \end{pmatrix}
\end{equation}
from which we deduce the Ricci scalar 
\begin{equation}
    \bar{R}=12H^{2}+6\dot{H}+\frac{6\mathfrak{C}}{a^{2}(t)}.
\end{equation}
%
The non-vanishing Christoffel symbols are
\begin{align}
    \Gamma^{0}_{\mu\nu}&= \text{Diag}\left\{ 0,\, \frac{a^{2}(t)H}{1-\mathfrak{C} r^2},\, r^2 a^{2}(t)H,\, r^2 a^{2}(t) \sin ^2(\theta ) H \right\},
\end{align}
together with 
\begin{equation}
    \Gamma^{r}_{\mu\nu}=\left(
\begin{array}{cccc}
 0 & H & 0 & 0 \\
 H & \frac{\mathfrak{C} r}{1-\mathfrak{C} r^2} & 0 & 0 \\
 0 & 0 & r \left(\mathfrak{C} r^2-1\right) & 0 \\
 0 & 0 & 0 & r \sin ^2(\theta ) \left(\mathfrak{C} r^2-1\right) \\
\end{array}
\right),
\end{equation}
and
\begin{align}
    \Gamma^{\theta}_{\mu\nu}=\left(
\begin{array}{cccc}
 0 & 0 & H & 0 \\
 0 & 0 & \frac{1}{r} & 0 \\
 H & \frac{1}{r} & 0 & 0 \\
 0 & 0 & 0 & -\sin (\theta )\cos (\theta ) \\
\end{array}
\right), \qquad 
    \Gamma^{\varphi}_{\mu\nu}=\left(
\begin{array}{cccc}
 0 & 0 & 0 & H \\
 0 & 0 & 0 & \frac{1}{r} \\
 0 & 0 & 0 & \cot (\theta ) \\
 H & \frac{1}{r} & \cot (\theta ) & 0 \\
\end{array}
\right)\,.
\end{align}
At last, the extrinsic curvature is given by
\begin{equation}
    K_{\mu\nu} \doteq \Gamma_{\mu\nu}^{0}=\left(
\begin{array}{cccc}
 0 & 0 & 0 & 0 \\
 0 & \frac{a^{2}(t)H}{1-\mathfrak{C} r^2} & 0 & 0 \\
 0 & 0 & r^2 a^{2}(t)H & 0 \\
 0 & 0 & 0 & r^2 a^{2}(t) \sin ^2(\theta ) H \\
\end{array}
\right),
\end{equation}
with trace $K=3H$. While this work discusses perturbation theory on a flat FLRW background, there has been works on the spectrum of perturbation in closed universes \cite{Thavanesan:2020lov,Cespedes:2021oso}. The study of open dynamics for perturbations in said backgrounds is left for future work. 

