\section{Operators in open gravity}\label{app:ope}

In this appendix, we discuss specific operators to build intuition about the structure of the terms appearing in $S_1$ (\Eq{eq:S1v1}) and $S_2$ (\Eq{eq:S2v1}).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Universal part}\label{app:univ}

We begin by expressing the universal part of the EFToI  \cite{Cheung:2007st} in the Keldysh basis. The universal part \eqref{eq:universal} governs the background dynamics and contributes to the quadratic action. The theory being unitary, the effective functional separates into
\begin{align}
S_{\mathrm{univ}}[g_+,g_-] = S_{\mathrm{univ}}[g_+] - S_{\mathrm{univ}}[g_-]\,.
\end{align}
If the only gauge fixing in this theory is the retarded unitary clock gauge $t_r=t$, see \eqref{tr=t}, then one would expect this theory to be invariant under 3d retarded diffs \textit{and} 4d advanced diffs. This is indeed what one finds including all $t_a$ terms. However, as we discussed in the main text, in a single clock cosmology $t_a$ can be removed by a field redefinition of $a^{\mu\nu}$. This procedure does not change the predictions of the theory, but breaks invariance under advanced time diffs. In the following we remedy this by performing an advanced St\"uckelberg trick, which introduces $\pia$. This in effect brings back all the $t_a$ terms we had removed, since if we had included the $t_a$ term the theory would have been 4d advanced diff invariant and the St\"uckelberg trick would have been a trivial operation. Therefore we proceed with
\begin{align}\label{eq:unitpmv2}
&S_{\mathrm{univ}}[g]= \int \dd^4 x \sqrt{-g} \left[ \frac{M^2_{\mathrm{\mathrm{Pl}}}}{2}R - \Lambda(t) - c(t )g^{00}\right].
\end{align}
We need to re-write this expression in the Keldysh basis, and then expand at linear order in the advanced fields. A useful expression is
\begin{align}
\sqrt{-g_\pm} &= \sqrt{- \mathrm{det}\left( g \pm \frac{a}{2}\right)}=\sqrt{-g}\left[1 \mp \frac{1}{4} g_{\mu\nu} a^{\mu\nu} + \frac{1}{16} g_{\mu\nu} a^{\nu\sigma} g_{\sigma\rho} a^{\rho\mu}  + \frac{1}{32} \left(g_{\mu\nu} a^{\mu\nu}\right)^2 + \cdots \right]. \label{eq:sqrt1v2}
\end{align}
Perturbing the Ricci scalar \cite{Weinberg:2008zzc}, we obtain
\begin{align}\label{eq:Sunivv2}
 S_{\mathrm{univ}} = \int \dd^4 x \sqrt{-g} \Bigg\{& \left[\frac{M^2_{\mathrm{\mathrm{Pl}}}}{2} G_{\mu\nu}a^{\mu \nu}  + \frac{M^2_{\mathrm{\mathrm{Pl}}}}{2} g^{\mu\nu} \delta_{a}R_{\mu\nu} \right] + \left[\frac{\Lambda(t)}{2} g_{\mu\nu} a^{\mu\nu} \right]\\
+& \left[\frac{c(t)}{2} \gr g_{\mu\nu} a^{\mu\nu} - c(t) \ga   \right]\Bigg\} + \cdots \nonumber 
\end{align}
where geometric objects such as the Einstein tensor $G_{\mu\nu}$ are constructed from the retarded metric and $\delta_{a}R_{\mu\nu}$ stands for the perturbation of the Ricci tensor induced by the advanced metric, that is
%
\begin{align}\label{eq:Rmunuv2}
\delta_{a}R_{\mu\nu} \equiv \delta R_{\mu \nu}\left[g + \frac{a}{2}\right] - \delta R_{\mu \nu}\left[g - \frac{a}{2}\right].
\end{align}
%
The contribution from this term is explicitly computed in \App{app:ft} and vanishes by integration by part (as long as we do not consider an $f(t)R$ extension of general relativity). We conclude that, at linear order in the advanced field, the unitary effective functional reads\footnote{Note that the gravitational side of the effective functional can equally be recovered from the deterministic equations of motion — for instance, as derived in \cite{Gubitosi:2012hu}:
\begin{align}
    M_{\mathrm{Pl}}^2G_{\mu\nu} + \Lambda(t)  g_{\mu\nu} + c(t) g^{00} g_{\mu\nu} - c(t) \delta^0_\mu \delta^0_\nu = 0,
\end{align}
from which we deduce that the universal part of \cite{Cheung:2007st, Gubitosi:2012hu} generates \Eq{eq:univfinv2}. It indeed fulfills the construction rules found above. One can then reintroduce the $\pir$ and $\pia$ contributions by performing a retarded and advanced \stuck trick.}
\begin{align}\label{eq:univfinv2}
    S_{\mathrm{univ}}=\int d^{4}x\sqrt{-g}&\bigg[\frac{\Mpl^{2}}{2}G_{\mu\nu}a^{\mu\nu}+\frac{\Lambda(t)}{2} g_{\mu\nu}a^{\mu\nu}+\frac{c(t)}{2}g^{00}g_{\mu\nu}a^{\mu\nu}-c(t)a^{00} \bigg].
\end{align}
Explicitly, in the language of \Eq{eq:decomp}, it amounts to consider the EFT operators controlled by the coefficients
\begin{align}
  \gtto{1} = - c(t), \quad \gssi{1} =\frac{c(t)}{2}, \quad \gsso{1} = \frac{\Lambda(t)}{2} - \frac{c(t)}{2}.
\end{align}
\Eq{eq:univfinv2} indeed fulfills the structure discussed above, namely the constraints given in \Eqs{eq:norm}, \eqref{eq:herm} and \eqref{eq:pos} are satisfied, all the terms are at least linear in an advanced component and the effective functional is invariant under retarded spatial diffeomorphisms. 

Upon performing the advanced St\"uckelberg trick (\Sec{subsec:advstuck}), we obtain the $\pi_a$ contributions,
\begin{align}
   S_{\mathrm{univ}} \rightarrow S_{\mathrm{univ}} + \int \dd^4 x \sqrt{-g} \left[ - \dot{\Lambda}(t) \pia  - 2 c(t) g^{0\mu}\partial_\mu \pia  - \dot{c}(t) \gr \pia \right], 
\end{align}
While the second term can be easily deduced from the advanced St\"uckelberg of $-c(t) a^{00}$,
the other two terms come with no derivatives acting on $\pia$, originate from the integration by part of 
\begin{align}
     \frac{\Lambda(t)}{2} g_{\mu\nu}a^{\mu\nu} \quad&\xrightarrow{(\text{t-diff}_a)} \quad\Lambda(t) \left(\dpia + 3H\pia \right)\quad \xrightarrow{(\text{IBP})}\quad -\dot{\Lambda} \pia. 
\end{align}
and similarly for $- \dot{c}(t) \gr \pia $ (up to higher order operators that can eventually be reabsorbed into non-universal operators).
At the background level, these contributions generate the tadpole equation
\begin{align}\label{eq:tadv1v2}
   \frac{\delta \bar{S}_{\mathrm{eff}}}{\delta \pia} = 0 \qquad \Rightarrow \qquad \dot{\Lambda}(t)+\dot{c}(t)+6Hc(t)=0.
\end{align}
Equivalently, using the first and second Friedmann equations, 
\begin{align}\label{eq:tadv2v2}
   3 H^{2}\Mpl^{2}&=\Lambda(t)+c(t)\quad,\quad2\Mpl^{2}\dot{H}=-2c(t),
\end{align}
we recover the exact same equation. Indeed, there is no new information in the continuity equation compared to the Einstein equations.  

Note that one can explicitly check that once the $\pia$ is reintroduced, the theory is indeed invariant under advanced diffs $\epsilon_a^\mu$. First, the Einstein-Hilbert term is invariant\footnote{In checking diff-invariance we systematically drop all boundary terms.} thanks to the Bianchi identity
\begin{equation}
    \Delta S_{\rm EH}=\Mpl^{2}\int\sqrt{-g}\left[G_{\mu\nu}\nabla^{\mu}\epsilon^{\nu}_{a}\right]=\Mpl^{2}\int\sqrt{-g}\nabla^{\mu}\left[G_{\mu\nu}\epsilon^{\nu}_{a}\right]=0.
\end{equation}
Second, the $\Lambda(t)$ term transform as
\begin{equation}
    \Delta S_{\Lambda(t)}=\int\sqrt{-g}\left[\Lambda(t)\nabla_{\mu}\epsilon^{\mu}_{a}+\dot{\Lambda}(t)\epsilon^{0}_{a}\right]=\int\sqrt{-g}\nabla_{\mu}\left[\Lambda(t)\epsilon^{\mu}_{a}\right]=0,
\end{equation}
which is also invariant. At last, the invariance under advanced diffs of the $c(t)$ terms can be checked through
\begin{align}
    \Delta S_{c(t)}=&\int\sqrt{-g}\left[-2c(t)\nabla^{0}\epsilon^{0}_{a}+c(t)g^{00}\nabla_{\mu}\epsilon^{\mu}_{a}+2c(t)g^{0\mu}\partial_{\mu}\epsilon_{a}^{0}+\dot{c}(t)g^{00}\epsilon_{a}^{0}\right]\\
    =&\int\sqrt{-g}\left\{\left[-2c(t)\nabla^{0}\epsilon^{0}_{a}+2c(t)g^{0\mu}\partial_{\mu}\epsilon_{a}^{0}\right]+\nabla_{\mu}\left[c(t)g^{00}\epsilon_{a}^{\mu}\right]\right\}=0,
\end{align}
where we have used that $\partial=\nabla$ when acting on a scalar. Note the cancellation here takes places in two different ways, as there is a piece that sums up to a boundary term and a piece that cancels identically.

\subsection{Minimal extension}\label{app:minimal}

In \cite{Salcedo:2024smn}, we constructed an open EFT for inflation in which the inflaton field experiences dissipation and noise from its interactions with an unknown environment. We considered the linear functional for the canonically normalized scalar field
\begin{align}\label{eq:target}
    S_{\mathrm{eff}} = \int \dd^4x \sqrt{-g} \bigg\{\dpir \dpia - c_s^2 \partial_i \pir \partial_i \pia - \gamma \dpir \pia + i \beta_\pi  \pia^2  \bigg\},
\end{align}
where we neglect derivative noises.
%
While the standard kinetic term can be extracted from the $c(t)$ terms of $S_{\mathrm{univ}}$, as discussed around \Eq{eq:Stuck2}, the remaining contributions require additional ingredients.

\paragraph{Speed of sound.} In addition to the standard kinetic term for the $\pi$ sector, breaking Lorentz invariance allows one to modify the speed of sound for the Goldstone mode \cite{Cheung:2007st, Piazza:2013coa}. In the Schwinger-Keldysh contour, this can be achieved by considering $S_{\cs}[g_+] - S_{\cs}[g_-]$ with 
\begin{align}\label{eq:onebranchv0v2}
    S_{\cs}[g] = \frac{M_2}{2}\int \dd^4 x \sqrt{-g} (\delta g^{00} )^2,
\end{align}
where we introduced the notation $\delta g^{00} = 1 + g^{00}$.
In the Keldysh basis, at linear order in the advanced metric, it leads to
\begin{align}\label{eq:addcs}
    S_{\cs} = \frac{M_2}{2}\int \dd^4 x \sqrt{-g} \bigg[ - \frac{1}{2} (\delta g^{00})^2 g_{\mu\nu} a^{\mu\nu} + 2 \delta g^{00} a^{00} \bigg],
\end{align}
that is $\gssii{1} = M_2 /4$ and $\gtti{1} = M_2$.
%
One can reintroduce the $\pia$ by performing an advanced \stuck trick, leading to 
\begin{align}\label{eq:csfin}
    S_{\cs} \rightarrow S_{\cs} + \int \dd^4 x\sqrt{-g}\left[2M_{2}(t)(1+g^{00})g^{0\mu} \partial_{\mu}\pi_{a} +\frac{\dot{M}_{2}(t)}{2}\left(1+g^{00}\right)^{2}\pi_{a}\right]\,.
\end{align}
At last, upon reintroducing $\pir$, the first term in \Eq{eq:csfin} generates a quadratic operator $ 4 M_2 \dpir \dpia$, which, once added to the standard kinetic term of the universal part, generates a non-trivial speed of sound $c^2_s$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\paragraph{Dissipation.}
%
Comparing the dissipation term $- \gamma \dpir \pia$ with the building blocks identified above, the former can be captured by 
\begin{align}\label{eq:dissiprefv2}
    S_{\mathrm{dissip}} &= \int \dd^4 x \sqrt{ - g}  \frac{\Gamma(t)}{3H}\left( 1 + g^{00}\right) \left( g_{\mu\nu} a^{\mu\nu} + a^{00}\right) .
\end{align}
Indeed, reintroducing the $\pia$ by performing an advanced \stuck trick, we obtain
\begin{align}
     S_{\mathrm{dissip}} & \rightarrow S_{\mathrm{dissip}} + \int \dd^4 x \sqrt{ - g}  2\Gamma(t)\left( 1 + g^{00}\right) \pia,
\end{align}
which generates a dissipative operator $\dpir \pia$ once the retarded \stuck trick is performed.  
%

\paragraph{Noise.}
%
At last, the noise term appearing in \Eq{eq:target} is easily embedded in our open gravity EFT once a Hubbard-Stratonovich trick \cite{Hubbard:1959ub,Stratonovich1957} analogue to \Eq{eq:HStrick} is performed, leading to
\begin{align}\label{eq:noisev2}
    S_{\mathrm{noise}} 
\equiv -  \int d^{4}x\sqrt{-g}&\xi_{\mu\nu} a^{\mu\nu}.
\end{align}
Reintroducing the $\pia$ by performing an advanced \stuck trick, we obtain a noise for the $\pi$ sector, that is 
\begin{align}
     S_{\mathrm{noise}} & \rightarrow S_{\mathrm{noise}} + \int \dd^4 x \sqrt{ - g}  \left(- 2 \xi_{00} \dot{\pi}_a + 2 \bar{g}^{ij} \xi_{0i} \partial_j \pia + 2H \bar{g}^{ij} \xi_{ij} \pia\right).
\end{align}


