\subsection{Modified Einstein-Hilbert term}\label{app:ft}

At last, we discuss a well known modification of the Einstein-Hilbert term known as $f(t)$ gravity \cite{Gubitosi:2012hu}. Let us consider $S_{f(t)}[g_+,g_-] = S_{f(t)}[g_+] - S_{f(t)}[g_-] $ with
\begin{align}
    S_{f(t)}[g] = \int \dd^4 x \sqrt{-g} \frac{M^2_*}{2} f(t) R,
\end{align}
where we introduced a time dependent function $f(t)$. In the Keldysh basis, after performing the advanced \stuck trick, we obtain
\begin{equation}
    S_{f(t)} =\int\dd^4 x\sqrt{-{g}}\frac{M^{2}_{*}}{2}\left[f(t){G}_{\mu\nu}a^{\mu\nu}+f(t)\delta_{a}R_{\mu\nu}{g}^{\mu\nu} - {R}\dot{f}(t)\pia\right],
\end{equation}
where the variation of the Ricci tensor is given by the Palatini's identity
\begin{equation}\label{eq:Palatini}        \delta_{a}R_{\mu\nu}=\nabla_{\rho}\delta_{a}\Gamma^{\rho}_{\mu\nu}-\nabla_{\nu}\delta_{a}\Gamma^{\rho}_{\rho\mu}\,,
\end{equation}
in which
\begin{equation}
    \delta_{a}\Gamma^{\rho}_{\mu\nu}=\frac{1}{2}{g}^{\rho\alpha}\left(\nabla_{\mu}\delta_{a}g_{\alpha\nu}+\nabla_{\nu}\delta_{a}g_{\alpha\mu}-\nabla_{\alpha}\delta_{a}g_{\mu\nu}\right).
\end{equation}
Using the relation between inverse and direct variations of the metric
\begin{equation}
    \delta_{a}g_{\mu\nu}=-{g}_{\mu\mu'}{g}_{\nu\nu'}a^{\mu'\nu'}\,,
\end{equation}
one finds
\begin{equation}
    \delta_{a}\Gamma^{\rho}_{\mu\nu}=-\frac{1}{2}{g}^{\rho\alpha}\nabla_{\mu}{g}_{\alpha\alpha'}{g}_{\nu\nu'}a^{\alpha'\nu'}-\frac{1}{2}{g}^{\rho\alpha}\nabla_{\nu}\delta_{a}{g}_{\mu\mu'}{g}_{\alpha\alpha'}a^{\mu'\alpha'}+\frac{1}{2}{g}^{\rho\alpha}\nabla_{\alpha}{g}_{\mu\mu'}{g}_{\nu\nu'}a^{\mu'\nu'}.
\end{equation}
At last, using that the connection is metric affine, we obtain 
\begin{equation}
    \delta_{a}\Gamma^{\rho}_{\mu\nu}=-\frac{1}{2}{g}_{\nu\nu'}\nabla_{\mu}a^{\rho\nu'}-\frac{1}{2}{g}_{\mu\mu'}\nabla_{\nu}a^{\rho\mu'}+\frac{1}{2}{g}^{\rho\alpha}{g}_{\mu\mu'}{g}_{\nu\nu'}\nabla_{\alpha}a^{\mu'\nu'},
\end{equation}
and
\begin{equation}
    \delta_{a}\Gamma^{\rho}_{\rho\nu}=-\frac{1}{2}{g}_{\rho\mu'}\nabla_{\nu}a^{\rho\mu'}.
\end{equation}
It leaves a term of the form
\begin{equation}
    \int \dd^4 x \sqrt{-{g}}\frac{M^{2}_{*}}{2}\left[f(t)\delta_{a}R_{\mu\nu}{g}^{\mu\nu}\right]=\int \dd^4 x \sqrt{-{g}}\frac{M^{2}_{*}}{2}f(t)\left({g}_{\mu\nu}\Box-\nabla_{\mu}\nabla_{\nu}\right)a^{\mu\nu}\,,
\end{equation}
where
\begin{align}
    \Box f(t) \equiv \frac{1}{\sqrt{- {g}}} \partial_\mu \left[\sqrt{-{g}} {g}^{\mu\nu}\partial_\nu f(t)\right]\,.
\end{align}
This can be integrated by parts into
\begin{equation}
    \int \dd^4 x\sqrt{-{g}}\frac{M^{2}_{*}}{2}\left[f(t)\delta_{a}R_{\mu\nu}{g}^{\mu\nu}\right]=\int \dd^4 x \sqrt{-{g}}\frac{M^{2}_{*}}{2}\left[\left({g}_{\mu\nu}\Box-\nabla_{\mu}\nabla_{\nu}\right)f(t)\right]a^{\mu\nu}.
\end{equation}
In the end, the full modified Einstein-Hilbert term reads
\begin{align}
     S_{f(t)} &= \int \dd^4x \sqrt{-{g}}  
    \frac{M^2_*}{2} \bigg\{\Big[ \left(  {G}_{\mu \nu} +{g}_{\mu\nu}\Box -\nabla_{\mu}\nabla_{\nu} \right)f(t) \Big] a^{\mu\nu} - \dot{f}(t) {R} \pia  \bigg\}.         
      \label{eq:ft1}
\end{align}
Whenever $f(t)$ is time independent, only the $G_{\mu\nu}$ contribution survives in \Eq{eq:ft1}. This particular modification of the theory will be relevant when we will use our theory of open gravity to describe dark energy as an open system.

