\section{Noise sector}

This appendix gathers a series of technical results on the noise part of the effective functional $S_2$ given in \eqref{eq:S2v1}. In \App{app:S2_second_order}, we extend the main text construction up to second order in derivatives. In \App{App:noise_constraints}, we derive so-called noise constraints that limit the number of independent advanced variables. At last, in \App{app:mixedHS}, we discuss the mixing between noises in the gravity sector and scalar sector.

\subsection{Noise functional to second order in derivatives}\label{app:S2_second_order}

To construct $S_2$ up to second order in derivatives in a systematic manner, we follow a similar approach to the construction of $S_1$ in \Sec{subsec:functional}. We begin again by expanding each term in $S_2$ in powers of $(1+g^{00})^\ell$ 
\begin{align}
    N &= \sum_{\ell=0}\left(g^{00} + 1 \right)^\ell N_{\ell}(R_{\mu\nu\rho\sigma}, K_{\mu\nu}, n_\mu, \nabla_\mu; t)  \, ,\\
    N_{\mu\nu} &= \sum_{\ell=0}\left(g^{00} + 1 \right)^\ell N_{\mu\nu, \ell}(R_{\mu\nu\rho\sigma}, K_{\mu\nu}, n_\mu, \nabla_\mu; t)   \, , \\
    N_{\mu\nu\rho\sigma} &= \sum_{\ell=0}\left(g^{00} + 1 \right)^\ell N_{\mu\nu\rho\sigma, \ell}(R_{\mu\nu\rho\sigma}, K_{\mu\nu}, n_\mu, \nabla_\mu; t)  \, .
\end{align}
$N_\ell$, $N_{\mu\nu, \ell}$ and $N_{\mu\nu\rho\sigma}$ are constructed with the same building blocks $M_\ell$, $M^{ts}_{\mu, \ell}$ and $M^{ss}_{\mu\nu, \ell}$ that were used to construct $S_1$ in \Sec{subsec:functional}. A major difference to the construction of $S_1$ is additional covariant derivatives that can appear when constructing $S_2$. When constructing $S_1$, we did not have to worry about covariant derivatives acting on the advanced fields $t_a$ or $a^{\mu\nu}$, as these can always be integrated by part to yield only terms already considered in \Eq{eq:S1v1}. Contrarily, we encounter terms of the form $\sim t_a \nabla_\mu t_a$ in $S_2$, which must be considered explicitly. To abbreviate the construction we introduce the notation $\{ M_\ell \}_n$, which denotes a building block, which is made out of the same operators as $M_\ell$, up to $n$th order in derivatives. Each operator in $\{ M_\ell \}_n$ comes with a new EFT coefficient. For instance
\begin{align}
    \{ M_\ell \}_1 &= \beta_{1,\ell} K + \beta_{2,\ell} \, , \bigg. \\
    \{ M_\ell \}_0 &= \beta_{3,\ell} \, .
\end{align}
Note that $\{ M_\ell \}_0 \subseteq \{ M_\ell \}_1$, as $\{ M_\ell \}_1$ also includes all operators at zeroth order in derivatives. Using this notation, we obtain
\begin{align}\label{eq:noise_scalar_bb}
    N_\ell &= \{ M_\ell \}_2 + \{ M_\ell \}_1 n^\alpha \nabla_\alpha + \{ M_\ell \}_0 n^\alpha n^\beta \nabla_\alpha \nabla_\beta + \{ M_\ell \}_0 \Box \\
    &= \btt{1} + \btt{2} K + \btt{3}  K^2 + \btt{4} K_{\alpha\beta} K^{\alpha\beta} + \btt{5} \nabla^0 K + \btt{6} R + \btt{7} R^{00} \nonumber \bigg. \\
    +& \btt{8} \nabla^0 + \btt{9} K \nabla^0 + \btt{10} \nabla^0 \nabla^0 + \btt{11} \Box 
    \, .
\end{align}
In this expression, covariant derivatives are understood to act on one of the two $t_a$'s that appear in $S_2 \supset \int \dd^4 x \sqrt{-g} \, N t_a^2$.
$N_{\mu\nu, \ell} (R_{\mu\nu\rho\sigma}, g^{00}, K_{\mu\nu}, \nabla_\mu; t)$ can be split along the foliation just as $M_{\mu\nu, \ell}$ in \Eq{eq:decomp} and \Eq{eq:decomp_Mmunu},
\begin{equation}
    N_{\mu\nu, \ell} = n_\mu n_\nu N^{tt}_\ell + g_{\mu\nu} N^{ss}_\ell + n_{(\mu} N^{ts}_{\nu),\ell} + \tilde{N}^{ss}_{\mu \nu, \ell}\,.
\end{equation}
Taking the new derivative terms into account, we find: 
\begin{align}
    N^{tt}_\ell &= \{M_\ell\}_2 + \{ M_\ell \}_1 n^\alpha \nabla_\alpha + \{ M_\ell \}_0 n^\alpha n^\beta \nabla_\alpha \nabla_\beta + \{ M_\ell \}_0 \Box \bigg.\,, \\
    N^{ss}_\ell &= \{M_\ell\}_2 + \{ M_\ell \}_1 n^\alpha \nabla_\alpha + \{ M_\ell \}_0 n^\alpha n^\beta \nabla_\alpha \nabla_\beta + \{ M_\ell \}_0 \Box \bigg. \,,\\
    N^{ts}_{\mu,\ell} &= \{M^{ts}_{\mu,\ell}\}_2 + \{M^{ts}_{\mu,\ell}\}_1 n^\alpha \nabla_\alpha + \{M^{ts}_{\mu,\ell}\}_0 n^\alpha n^\beta \nabla_\alpha \nabla_\beta \bigg. \nonumber  \\
    +& \{M^{ts}_{\mu,\ell}\}_0 \Box + \{M_\ell\}_1 \nabla_\mu + \{M_\ell\}_0 n^\alpha \nabla_\alpha \nabla_\mu \nonumber \bigg. \\
    &= \bts{1} R^{0}{}_\mu + \bts{2} \nabla_\mu K + \bts{3} \nabla_\beta K^{\beta}{}_\mu + \left( \bts{4}K + \bts{5} \right) \nabla_\mu +\bts{6} \nabla^0 \nabla_\mu  \bigg. \,,\label{eq:noise_vector_bb}\\
    \tilde{N}^{ss}_{\mu\nu,\ell} &= \{\tilde{M}^{ss}_{\mu\nu,\ell}\}_2 + \{\tilde{M}^{ss}_{\mu\nu,\ell}\}_1 n^\alpha \nabla_\alpha + \{\tilde{M}^{ss}_{\mu\nu,\ell}\}_0 n^\alpha n^\beta \nabla_\alpha \nabla_\beta \bigg.  \nonumber\\
    +& \{\tilde{M}^{ss}_{\mu\nu,\ell}\}_0 \Box + \{M^{ts}_{(\mu,\ell}\}_1 \nabla_{\nu)} + \{M^{ts}_{(\mu,\ell}\}_0 n^\alpha \nabla_{\nu)} \nabla_\alpha + \{M_\ell\}_0 \nabla_{(\mu} \nabla_{\nu)} \nonumber \bigg. \\
    &= \bss{12} R_{\mu\nu} + \bss{13} R_\mu{}^0{}_\nu{}^0 + \bss{14} K_{\mu\nu} + \bss{15} \nabla^0 K_{\mu\nu} \nonumber \bigg. \\
    +&  \bss{16} K_{\mu\alpha} K^{\alpha}{}_{\nu} + \bss{17} K K_{\mu\nu} + \bss{18} K_{\mu\nu} \nabla^0 + \bss{19} \nabla_{(\mu} \nabla_{\nu)} \, .\label{eq:noise_rank2tensor_bb}
\end{align}
Note that $\{M^{ts}_{\mu,\ell}\}_1 = \{M^{ts}_{\mu,\ell}\}_0 = \{\tilde{M}^{ss}_{\mu\nu,\ell}\}_0 = 0$.

Lastly, we also decompose $N_{\mu\nu\rho\sigma, \ell}$ along the foliation. As this tensor is contracted with two advanced metrics in \Eq{eq:S2try}, we decide to make its symmetries manifest. In particular it is symmetric in $\mu \leftrightarrow \nu$ and $\rho \leftrightarrow \sigma$, as well as in $(\mu\nu) \leftrightarrow (\rho\sigma)$. 
\begin{align}\label{eq:noise4_decomp}
    N_{\mu\nu\rho\sigma, \ell} &= n_\mu n_\nu n_\rho n_\sigma N^1_l + g_{\mu\nu} g_{\rho\sigma} N^2_l + g_{\mu(\rho} g_{\sigma)\nu} N^3_l + \left(g_{\mu\nu}n_\rho n_\sigma + n_\mu n_\nu g_{\rho\sigma} \right) N^4_l \bigg. \\
    +& \left(g_{\mu(\rho} n_{\sigma)} n_\nu + g_{\nu(\rho} n_{\sigma)} n_\mu \right) N^5_l + \left( n_\nu n_\rho n_\sigma  N^1_{\mu,\ell} + \textrm{3 perm's} \right) \nonumber \bigg. \\
    +& \left( g_{\nu\rho} n_\sigma  N^2_{\mu,\ell} + \textrm{7 perm's} \right) + \left( g_{\rho\sigma} n_\nu  N^3_{\mu,\ell} + \textrm{7 perm's} \right) \nonumber \bigg. \\
    +& \left( N^1_{\mu\nu,\ell} g_{\rho\sigma} + g_{\mu\nu} N^1_{\rho\sigma,\ell} \right)
    + \left(N^2_{\mu(\rho,\ell} g_{\sigma)\nu} + N^2_{\nu(\rho,\ell} g_{\sigma)\mu} \right) \nonumber \bigg. \\
    +& \left(N^3_{\mu\nu,\ell} n_\rho n_\sigma + N^3_{\rho\sigma,\ell} n_\mu n_\nu\right) + \left(N^4_{\mu(\rho,\ell} n_{\sigma)} n_\nu +N^4_{\nu(\rho,\ell} n_{\sigma)} n_\mu \right) \nonumber \bigg. \\
    +& \left( N_{\mu\nu\rho,\ell} n_\sigma + \textrm{7 perm's} \right) + \left( N_{\mu\nu\rho\sigma,\ell} + \textrm{7 perm's} \right) \nonumber  \bigg. \, ,
\end{align}
where the various permutations, abbreviated with $\text{perm's}$, are such that every term is individually symmetric in $\mu \leftrightarrow \nu$ and $\rho \leftrightarrow \sigma$, as well as in $(\mu\nu) \leftrightarrow (\rho\sigma)$.
The various $N$-scalars, vectors and tensors are build completely analogous to before, such that for instance all five $N^i{}_\ell$ feature the same operators, namely the ones in \Eq{eq:noise_scalar_bb}, but they may in general all come with different EFT coefficients. Likewise, the three $N^i{}_{\alpha, \ell}$ are build similarly to \Eq{eq:noise_vector_bb} and the four $N^i{}_{\alpha\beta, \ell}$ are build similar to \Eq{eq:noise_rank2tensor_bb}. Finally, we have to construct $N_{\alpha\beta\gamma,\ell}$ and $N_{\alpha\beta\gamma\delta,\ell}$ as the most generic rank-3 and rank-4 tensors constructed out of $R_{\mu\nu\rho\sigma}$, $K_{\mu\nu}$, $g_{\mu\nu}$, $n_\mu$ and $\nabla_\mu$ as before. As before, any term that has free indices on $n_\mu$ or $g_{\mu\nu}$ is redundant with the other terms in our decomposition in \Eq{eq:noise4_decomp}. Conversely leaving free indices on $\nabla_\mu$ is not, as explained previously. We arrive at   
\begin{align}
    N_{\alpha\beta\gamma,\ell} &= \beta^3_{10,\ell} n^\delta R_{\alpha\gamma\beta\delta} + \{M^{ts}_{\alpha, \ell}\}_0 \nabla_\beta \nabla_\gamma + \{M^{ss}_{\alpha \beta, \ell}\}_1 \nabla_\gamma + \{M^{ts}_{\alpha, \ell}\}_1 K_{\beta\gamma} \bigg.\nonumber \\
    +& \{M_{\alpha\beta,\ell}^{ss}\}_0 \nabla^{\mu}K_{\mu\gamma} + \{M_{\alpha\beta,\ell}^{ss}\}_0 \nabla_{\gamma}K \nonumber \bigg. \\
    &= \beta^3_{10,\ell} n^\delta R_{\alpha\gamma\beta\delta} + \beta^3_{11,\ell} K_{\alpha \beta} \nabla_\gamma \bigg. \,,\\
    N_{\alpha\beta\gamma\delta,\ell} &= \beta^4_{31,\ell} R_{\alpha\beta\gamma\delta} + \{\tilde{M}_{\alpha\beta}\}_1 K_{\gamma\delta} + \{\tilde{M}^{ss}_{\alpha\beta}\}_0 \nabla_\gamma \nabla_\delta + \{N_{\alpha\beta\gamma,\ell}\}_1 \nabla_\delta \bigg. \nonumber\\
    &= \beta^4_{31,\ell} R_{\alpha\beta\gamma\delta} + \beta^4_{32,\ell} K_{\alpha\beta}K_{\gamma\delta} \bigg. \,.
\end{align}
Note that $\{M^{ts}_{\alpha, \ell}\}_0 = \{\tilde{M}^{ss}_{\alpha\beta}\}_0 = \{N_{\alpha\beta\gamma,\ell}\}_1 = 0$.


