\subsection{Noise mixing between gravity and the scalar}\label{app:mixedHS}

In general, the quadratic action includes mixing between the advanced metric $a^{\mu\nu}$ and the advanced clock $t_{a}$ at the level of the noise operators, 
\begin{equation}
    S_2 = i \int \dd^4 x \sqrt{-g} \Big[N_{\mu\nu\rho\sigma}  a^{\mu\nu}  a^{\rho\sigma}  +  N_{\mu\nu} a^{\mu\nu} t_a  + N t_a^2 \Big]. 
\end{equation}
It is instrumental to assess how strong this mixing is at the level of the stochastic noises. To do this, we have to generalize the Hubbard-Stratonovich \cite{Hubbard:1959ub,Stratonovich1957} trick to include various tensors of different rank. The simplest way consists in considering the SVT decomposition of the advanced metric
\begin{equation}
    a^{\mu\nu}\equiv \begin{pmatrix}
       2\phi_{a} & a^{-1}(t)\partial_{i}F_{a}+C^{a}_{i}\\
       a^{-1}(t)\partial_{i}F_{a}+C^{a}_{i} & 2\psi_{a}a^{-2}(t)\delta_{ij}-2a^{-2}(t)\left(\partial_{i}\partial_{j}-\frac{1}{3}\nabla^{2}\delta_{ij}\right)\beta_{a}+2\partial_{(i}D_{j)}+\gamma_{ij}^{TT,a}
    \end{pmatrix},
\end{equation}
where there are 4 scalar variables, 4 components corresponding to two transverse vectors and 2 components corresponding to the two transverse and traceless polarizations. This means we can rearrange the variables into a list $\mathfrak{A}^{c}$, such that
\begin{equation}
    \mathfrak{A}^{c} \equiv \left(\phia,\psi_{a},F_{a},\beta_{a},C^{a}_{i},D^{a}_{i},\gamma^{TT,a}_{ij},t_{a}\right),
\end{equation}
which allows to rewrite the quadratic action as
\begin{equation}
    S_{2}=i\int\sqrt{-g}\mathfrak{A}^{c}\tilde{\mathfrak{N}}_{cd}\mathfrak{A}^{d}\quad,\quad\tilde{\mathfrak{N}}_{cd}=-i\frac{\delta^{2}S_{2}}{\delta\mathfrak{A}^{c}\delta\mathfrak{A}^{d}}.
\end{equation}
Under this decomposition, the first $10\times10$ block of $\mathfrak{N}_{cd}$ corresponds to $N_{\mu\nu\rho\sigma}$, while the last column (row) corresponds to $N_{\mu\nu}$ and $N$:
\begin{equation}
    \tilde{\mathfrak{N}}_{cd}=\begin{pmatrix}
        \frac{\partial^{2}}{\partial\mathfrak{A}^{c}\partial\mathfrak{A}^{d}}N_{\mu\nu\rho\sigma}a^{\mu\nu}a^{\rho\sigma} & \frac{\partial}{\partial\mathfrak{A}^{c}} N_{\mu\nu}a^{\mu\nu}\\
        \frac{\partial}{\partial\mathfrak{A}^{d}} N_{\mu\nu}a^{\mu\nu} & N
    \end{pmatrix}=\begin{pmatrix}
        \mathfrak{N}_{cd} & \mathfrak{N}_{c}\\
        \mathfrak{N}_{d} & \mathfrak{N}^{2}+\mathfrak{N}^{ab}\mathfrak{N}_{a}\mathfrak{N}_{b}
    \end{pmatrix}.
\end{equation}

We can then use the results for the noise in open electromagnetism \cite{Salcedo:2024nex} to rewrite $S_{2}$ in terms of these new variables:
\begin{equation}
    \text{exp}\left(-S_{2}\left[\mathfrak{A}^{c}\right]\right)=\int\mathcal{D}\mathfrak{E}_{c}\text{exp}\left\{\int \dd^4 x \sqrt{-g}\left[-\frac{1}{4}\left(\tilde{\mathfrak{N}}^{-1}\right)^{cd}\mathfrak{E}_{c}\mathfrak{E}_{d}+i\mathfrak{E}_{c}\mathfrak{A}^{c}\right]\right\},
\end{equation}
with
\begin{equation}
    \left(\tilde{\mathfrak{N}}^{-1}\right)^{cd}=\begin{pmatrix}
      \left(\mathfrak{N}^{-1}\right)^{cd}+\frac{\mathfrak{N}^{c}\mathfrak{N}^{d}}{\mathfrak{N}^{2}}& -\frac{\mathfrak{N}^{c}}{\mathfrak{N}^{2}} \\
      -\frac{\mathfrak{N}^{d}}{\mathfrak{N}^{2}}  & \frac{1}{\mathfrak{N}^{2}}
    \end{pmatrix}
\end{equation}
such that the correlation function of the stochastic noises $\mathfrak{E}_{c}$ is given by: 

\begin{equation}
    \langle\mathfrak{E}_{c}(t,\bfx)\mathfrak{E}_{d}(t',\bfx')\rangle=2\tilde{\mathfrak{N}}_{cd}\delta(t-t')\delta(\bfx-\bfx').
\end{equation}



We are particularly interested in the mixing between the \stuck field noise $\xi_{\pi}$ and the scalar sector of the advanced metric, composed of the variables $(\phi_a,\psi_a,F_a,\beta_a)$\footnote{Note that in this case the noises associated to advanced components $F_a, \beta_a$ are not simply $\xi_{0i}$ and $\xi_{ij}$, but rather:
\begin{align}
    \frac{\delta}{\delta F_{a}}\int\sqrt{-g} 2a^{0i}\xi_{0i}&=-2\frac{1}{a(t)}\partial_{i}\xi_{0i}=-2\frac{1}{a(t)}\partial^{2}\xi^{||}=\xi_{F}\\
    \frac{\delta}{\delta \beta_{a}}\int\sqrt{-g} a^{ij}\xi_{ij}&=2\frac{1}{a^{2}(t)}\left(\partial_{i}\partial_{j}-\frac{1}{3}\delta_{ij}\partial^{2}\right)\xi_{ij}=\frac{2 k^{4}\Xi^{TT}}{3a^{2}(t)}=\xi_{\beta}
\end{align}
}. Therefore, we expand \eqref{eq:S2v1} in terms of these variables and the advanced time $t_{a}$. In this paper we focus on the linear dynamics, and hence it is enough to truncate at $\ell=0$:
\begin{align}
    S_{2}=i\int\sqrt{-g}&\bigg[\beta_{1,0}t_{a}^{2}+2\beta_{2,0}\phi_{a}t_{a}-2\beta_{3,0}\left(\phi_{a}-3\psi_{a}\right)t_{a}+4\beta_{4,0}\phi_{a}^{2}+4\beta_{5,0}\left(\phi_{a}-3\psi_{a}\right)^{2} \nonumber \\
    &+\beta_{6,0}\left(4\phia^{2}+2F_{a}\partial^{2}F_{a}+12\psi_{a}^{2}+\frac{8}{3}\partial^{2}\partial^{2}\beta_{a}^{2}\right) \nonumber\\
    &-4\beta_{7,0}\phia\left(\phia-3\psi_{a}\right)+\beta_{8,0}\left(2\phia^{2}-F_{a}\partial^{2}F_{a}\right)\bigg],
\end{align}
which can be rewritten as
\begin{equation}
    S_{2}=i\int\sqrt{-g}\begin{pmatrix}
        \phia & \psi_{a} & F_{a} & \beta_{a} & t_{a}
    \end{pmatrix}^c \mathfrak{N}_{cd} \begin{pmatrix}
        \phia \\ \psi_{a} \\ F_{a} \\ \beta_{a} \\ t_{a}
    \end{pmatrix}^d.
\end{equation}
with 
\begin{align}
	\mathfrak{N}_{cd} = \begin{pmatrix}
	 	8 (\beta_{4}+\beta_{5}+\beta_{6}-\beta_{7}+\beta_{8}) & 12 (\beta_{7}-2 \beta_{5}) & 0 & 0 & 2 (\beta_{2}-\beta_{3}) \\
	 	12 (\beta_{7}-2 \beta_{5}) & 24 (3 \beta_{5}+\beta_{6}) & 0 & 0 & 6 \beta_{3} \\
	 	0 & 0 & 2 k^2 (\beta_{8}-2 \beta_{6}) & 0 & 0 \\
	 	0 & 0 & 0 & \frac{16}{3}\beta_{6,0}k^{4} & 0 \\
	 	2 (\beta_{2}-\beta_{3}) & 6 \beta_{3} & 0 & 0 & 2 \beta_{1} \\
	 \end{pmatrix}.
\end{align}
This matrix must verify the Silvester's criteria for positivity of a matrix, coming from the constraints \eqref{eq:pos}. It implies the bounds
\begin{align}
    &\beta_{4}+\beta_{5}+\beta_{6}-\beta_{7}+\beta_{8}>0, \qquad \quad ~~ \beta_{8}-2 \beta_{6}>0, \qquad \quad  ~~ \beta_{6}>0, \bigg.  \\
    &4 \beta_{4} (3 \beta_{5}+\beta_{6})+4 \beta_{8} (3 \beta_{5}+\beta_{6})+16 \beta_{5} \beta_{6}+4 \beta_{6}^2-4 \beta_{6} \beta_{7}-3 \beta_{7}^2>0, \bigg.\\
    &\beta_{1} \left[4 \beta_{4} \left(3 \beta_{5}+\beta_{6}\right)+4 \beta_{8} \left((3 \beta_{5}+\beta_{6}\right)+16 \beta_{5} \beta_{6}+4 \beta_{6}^2-4 \beta_{6} \beta_{7}-3 \beta_{7}^2\right] \Big. \nonumber \\
    &\quad -\beta_{2}^2 (3 \beta_{5}+\beta_{6})+\beta_{2} \beta_{3} (2 \beta_{6}+3 \beta_{7})-\beta_{3}^2 (3 \beta_{4}+4 \beta_{6}+3 \beta_{8})>0. 
\end{align}

We close this Appendix by noticing that the advanced \stuck mixes the noises $\xi_{t_{a}},\xi_{00}$ and $\xi_{0i}$ to form the noise $\xi_{\pi}$
\begin{align}
    \int\sqrt{-g}\left(\xi_{t_{a}}t_{a}+\xi_{\mu\nu}a^{\mu\nu}\right)&\xrightarrow{(\text{t-diff}_a)} \int\sqrt{-g}\Bigg\{\left(\xi_{t_{a}}t_{a}+\xi_{\mu\nu}a^{\mu\nu} \right) \nonumber \\
    +&\pia\left[\xi_{t_{a}}+2\left(\dot{\xi}_{00}+3H\xi_{00}\right)-\frac{2}{a^{2}(t)}\partial_{i}\xi_{0i}+\frac{2H}{a^{2}(t)}\delta^{ij}\xi_{ij}\right]\Bigg\},
\end{align}
such that
\begin{equation}
    \xi_{\pi}=\xi_{t_{a}}+2\left(\dot{\xi}_{00}+3H\xi_{00}\right)-\frac{2}{a^{2}(t)}\partial_{i}\xi_{0i}+\frac{2H}{a^{2}(t)}\delta^{ij}\xi_{ij}.
\end{equation}
In particular, this provides a mechanism to generate noise in the $\pi$ sector even if $t_a = 0$. 

