\section{Technical derivations for mixing with gravity}\label{app:mixing}

In this appendix, we gather the technical details relative to the estimate of the mixing with gravity studied in \Sec{Sec:minimal}.

\subsection*{Perturbed Einstein's equations} 

We start from \Eq{eq:th2}, which we reproduce here for clarity,
\begin{align}\label{eq:th2app}
	S_{\rm eff}=\int\sqrt{-g}\bigg[&\frac{\Mpl^{2}}{2}G_{\mu\nu}a^{\mu\nu}+\frac{\Lambda(t)}{2}g_{\mu\nu}a^{\mu\nu}-c(t)a^{00}+\frac{c(t)}{2}g^{00}g_{\mu\nu}a^{\mu\nu}\nonumber \\
	 -&\frac{M_{2}(t)}{4}\left(1+g^{00}\right)^{2}g_{\mu\nu}a^{\mu\nu}+M_{2}(t)\left(1+g^{00}\right)a^{00} \bigg.\nonumber\\
     +& \frac{\Gamma(t)}{3H}\left(1 + g^{00} \right)\left( a^{00} + g_{\mu\nu} a^{\mu\nu}\right)-\xi_{\mu\nu}a^{\mu\nu}\bigg].
\end{align}
The first step is reintroducing $\pir$ by performing a retarded St\"uckelberg trick. Each of the terms in $S_{\rm eff}$ is susceptible to receiving new terms. Bearing in mind that any tensor transforms as (method II)
\begin{align}
	A^{00}&\rightarrow \partial_{\mu}(t+\pir)\partial_{\nu}(t+\pir) A^{\mu\nu}\,,\\
	A^{0i}&\rightarrow \partial_{\mu}(t+\pir) A^{\mu i}\,,\\
	A^{ij}&\rightarrow A^{ij},
\end{align}
while any function of time becomes
\begin{equation}
	f(t)\to f(t+\pir),
\end{equation}
we can now reintroduce the $\pir$ contributions. While the Einstein-Hilbert term
\begin{equation}
	S_{\rm EH} \supset \frac{\Mpl^{2}}{2}\int\sqrt{-g}G_{\mu\nu}a^{\mu\nu},
\end{equation}
remains invariant as there is no explicit time dependence and the integrand is a scalar under retarded time diffeomorphisms, the cosmological constant term transforms as
\begin{equation}
	S_{\Lambda(t)}\supset\int\sqrt{-g}\left[\frac{1}{2}\Lambda(t+\pir)g_{\mu\nu}a^{\mu\nu}\right].
\end{equation}
Similarly, the kinetic term receives
\begin{align}
	S_{c(t)}\supset&\int\sqrt{-g}\bigg[-c(t+\pir)\partial_{\mu}\left(t+\pir\right)\partial_{\nu}\left(t+\pir\right)a^{\mu\nu} \nonumber \\
	+&\frac{1}{2}c(t+\pir)\partial_{\alpha}\left(t+\pir\right)\partial_{\beta}\left(t+\pir\right)g^{\alpha\beta}g_{\mu\nu}a^{\mu\nu}\bigg].
\end{align}
The speed of sound contributions become
\begin{align}
	S_{\cs}\supset&\int\sqrt{-g}\frac{M_{2}(t+ \pir)}{2}\left\{-\frac{1}{2}\left[1+\partial_{\alpha}\left(t+\pir\right)\partial_{\beta}\left(t+\pir\right)g^{\alpha\beta}\right]^{2}g_{\mu\nu}a^{\mu\nu}\right. \nonumber\\
	+&2\left[1+\partial_{\alpha}\left(t+\pir\right)\partial_{\beta}\left(t+\pir\right)g^{\alpha\beta}\right]\partial_{\mu}\left(t+\pir\right)\partial_{\nu}\left(t+\pir\right)a^{\mu\nu}\bigg\}.
\end{align}
At last, the dissipation operator transforms as
\begin{align}
    S_{\Gamma(t)}\supset&\int\sqrt{-g}\frac{\Gamma(t + \pir)}{3H}\bigg\{\left[1+\partial_{\alpha}\left(t+\pir\right)\partial_{\beta}\left(t+\pir\right)g^{\alpha\beta}\right]\left[\partial_{\mu}\left(t+\pir\right)\partial_{\nu}\left(t+\pir\right) + g_{\mu\nu}\right]a^{\mu\nu} \bigg\}.
\end{align}
and the noise operator $\xi_{\mu\nu}a^{\mu\nu}$ does not transform, being fully contracted. 

Thanks to the introduction of the retarded \stuck we can now write the Einstein equations in a covariant form. Introducing the short hand notation
\begin{equation}
	A_{\alpha\beta}=\partial_{\alpha}\left(t+\pir\right)\partial_{\beta}\left(t+\pir\right),
\end{equation}
we obtain the Einstein's equations
\begin{align}
	&\frac{\Mpl^{2}}{2}G_{\mu\nu}+\frac{\Lambda(t+\pir)}{2}g_{\mu\nu}-c(t+\pir)A_{\mu\nu}+\frac{c(t+\pir)}{2}A_{\alpha\beta}g^{\alpha\beta}g_{\mu\nu}\nonumber\\
	&-\frac{M_{2}(t+\pir)}{4}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)^{2}g_{\mu\nu}+M_{2}(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)A_{\mu\nu}\nonumber \bigg. \\
    &+ \frac{\Gamma(t + \pir)}{3H}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)\left(A_{\mu\nu}+ g_{\mu\nu}\right) =\xi_{\mu\nu}.
\end{align}
Each term has to be expanded to linear order in perturbations, leading to 
\begin{align}
	\frac{\Mpl^{2}}{2}G_{\mu\nu}\quad \rightarrow \quad & \frac{\Mpl^{2}}{2}\delta G_{\mu\nu}\,,\\ 
	\frac{\Lambda(t+\pir)}{2}g_{\mu\nu}\quad \rightarrow \quad & \frac{\Lambda}{2}\delta g_{\mu\nu}+\frac{\dot{\Lambda}(t)}{2}\pir\bar{g}_{\mu\nu},
\end{align}
for the Einstein-Hilbert term and the cosmological constant, 
\begin{align}
	-c(t+\pir)A_{\mu\nu}\quad \rightarrow \quad& -\dot{c}(t)\pir\delta_{\mu}^{0}\delta_{\nu}^{0}-c(t)\left(\delta_{\mu}^{0}\partial_{\nu}\pir+\partial_{\mu}\pir\delta_{\nu}^{0}\right)\,, \bigg.\\
	\frac{c(t+\pir)}{2}A_{\alpha\beta}g^{\alpha\beta}g_{\mu\nu}\quad \rightarrow \quad& -\frac{\dot{c}(t)}{2}\pir\bar{g}_{\mu\nu}+\frac{c(t)}{2}\left(\delta g^{00}-2\dpir\right)\bar{g}_{\mu\nu}-\frac{c(t)}{2}\delta g_{\mu\nu},
\end{align}
for the kinetic term,
\begin{align}
	-\frac{M_{2}(t+\pir)}{4}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)^{2}g_{\mu\nu}\quad \rightarrow \quad&0\,, \bigg.\\
	M_{2}(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)A_{\mu\nu}\quad \rightarrow \quad&M_{2}(t)\left(\delta g^{00}-2\dpir\right)\delta_{\mu}^{0}\delta_{\nu}^{0},
	%
\end{align}
for the speed of sound contributions and
\begin{align}
    \frac{\Gamma(t + \pir)}{3H}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)\left(A_{\mu\nu}+ g_{\mu\nu}\right) \quad \rightarrow \quad&  \frac{\Gamma(t)}{3H}\left(\delta g^{00}-2\dpir\right) \left(\delta_{\mu}^{0}\delta_{\nu}^{0} + \bar{g}_{\mu\nu} \right)\,, \bigg.
\end{align}
for the dissipation. 

At last, we use the freedom introduced by the \stuck and the retarded spatial diffs to work in the flat gauge
\begin{equation}
	\delta g_{ij}^{\rm scalar}=0\quad,\quad\delta g_{00}=-2\phi=-\delta g^{00}\quad,\quad \delta g_{0i}=a(t)\partial_{i}F=\delta g^{0i}.
\end{equation}
The perturbed Einstein's equations are given by
\begin{align}
	\frac{\Mpl^{2}}{2}\delta G_{00}+\left[\frac{\Lambda(t)-2M_{2}(t)}{2}\right]\delta g_{00}+3Hc(t)\pir-\left[c(t)+2M_{2}\right]\dot{\pi}_r&=\xi_{00}, \\
	\frac{\Mpl^{2}}{2}\delta G_{0i}+\frac{\Lambda(t)-c(t)}{2}\delta g_{0i}-c(t)\partial_{i}\pir&=\xi_{0i},
\end{align}
as stated in the main text. Note that dissipation does not enter the $00$ and $0i$ Einstein's equations and so does not directly affect the constraints.

\subsection*{Equation of motion for $\pir$}

To derive the equation of motion for $\pir$, we first need to consider all the terms that are linear in $\pia$. To do so, we first perform an advanced \stuck on \Eq{eq:th2app} to reintroduce the $\pia$. It leads to 
\begin{align}
	S_{\mathrm{scalar}}=&\int \dd^4x \sqrt{-g} \bigg[-\dot{\Lambda}(t+\pir)\pia-2c(t+\pir)g^{\mu\nu}\partial_{\mu}\left(t+\pir\right)\partial_{\nu}\pia-\dot{c}(t+\pir)A_{\alpha\beta}g^{\alpha\beta}\pia \nonumber\\
	&+2M_{2}(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)g^{\mu\nu}\partial_{\mu}\left(t+\pir\right)\partial_{\nu}\pia+\frac{\dot{M}_{2}(t+\pir)}{2}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)^{2}\pia \nonumber \\
	&+2\Gamma(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)\pia - \xi_\pi \pia\bigg],
\end{align}
where we defined the scalar noise
\begin{align}
    \xi_\pi &= 2( \dot{\xi}_{00} + 3H \xi_{00} ) - \frac{2}{a^2(t)} \left( \xi_{\parallel}  - 3H \Xi_{\parallel}\right),
\end{align}
by decomposing $\xi_{\mu\nu}$ into 
\begin{align}
    \xi_{00}, \qquad \xi_{0i} =  \partial_i \xi_{\parallel}, \qquad \xi_{ij} = \Xi_{\parallel} \delta_{ij} + \left(\partial_i \partial_i - \frac{1}{3}  \delta_{ij} \partial^2 \right)  \Xi^{\mathrm{TT}}.
\end{align}
This leaves a $\pia$ variation of the form
\begin{align}
	&-\dot{\Lambda}(t+\pir)+2\nabla_{\mu}\left[c(t+\pir)g^{\mu\nu}\partial_{\nu}(t+\pir)\right]-\dot{c}(t+\pir)A_{\alpha\beta}g^{\alpha\beta} \nonumber \\
	&-2\nabla_{\mu}\left[M_{2}(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)g^{\mu\nu}\partial_{\mu}\left(t+\pir\right)\right]+\frac{\dot{M}_{2}(t+\pir)}{2}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)^{2} \nonumber \\
	&+2\Gamma(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)=\xi_{\pi}.
\end{align}
We can then expand all the terms to linear order. The cosmological constant simply becomes
\begin{align}
	-\dot{\Lambda}(t+\pir)\rightarrow&-\ddot{\Lambda}(t)\pir,
\end{align}
while the first part of the kinetic term generates
\begin{align}
	2\nabla_{\mu}\left[c(t+\pir)g^{\mu\nu}\partial_{\nu}(t+\pir)\right]=&2\partial_{\mu}\left[c(t+\pir)\right]g^{\mu\nu}\partial_{\nu}\left(t+\pir\right) \nonumber\\
	&+2c(t+\pir)\partial_{\mu}g^{\mu\nu}\partial_{\nu}\left(t+\pir\right) \nonumber \\
	&+2c(t+\pir)g^{\mu\nu}\partial_{\mu}\partial_{\nu}\pir.
\end{align}
Expanding each term leads to 
\begin{align*}
	2\partial_{\mu}\left[c(t+\pir)\right]g^{\mu\nu}\partial_{\nu}\left(t+\pir\right)\rightarrow&-2\ddot{c}(t)\pir+2\dot{c}(t)\left(\delta g^{00}-2\dot{\pir}\right)\,,\\
	2c(t+\pir)g^{\mu\nu}\partial_{\mu}\left[\text{Log}\left(\sqrt{-g}\right)\right]\partial_{\nu}\left(t+\pir\right)\rightarrow&-6H\dot{c}(t)\pir+6Hc(t)\delta g^{00}-c(t)\partial_{0}\delta g^{00}-6Hc(t)\dot{\pi}_r\,,\\
	2c(t+\pir)\partial_{\mu}g^{\mu\nu}\partial_{\nu}\left(t+\pir\right)\rightarrow& ~2c(t)\partial_{\mu}g^{\mu0}\,,\\
	2c(t+\pir)g^{\mu\nu}\partial_{\mu}\partial_{\nu}\pir\rightarrow&+2c(t)\bar{g}^{\mu\nu}\partial_{\mu}\partial_{\nu}\pir    \,.
\end{align*}
The second part of the kinetic term is much simpler and leads to
\begin{align}
	-\dot{c}(t+\pir)A_{\alpha\beta}g^{\alpha\beta}\rightarrow&~\Ddot{c}(t)\pir-\dot{c}(t)\left(\delta g^{00}-2\dot{\pi}_r\right).
\end{align}
Turning our attention to the speed of sound, the first contribution generates
\begin{align}
	-2\nabla_{\mu}\left[M_{2}(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)g^{\mu\nu}\partial_{\mu}\left(t+\pir\right)\right]\rightarrow&~\frac{2}{a^{3}(t)}\partial_{0}\left[a^{3}(t)M_{2}(t)\left(\delta g^{00}-2\dot{\pi}_r\right)\right],
\end{align}
which is expanded into
\begin{align}
	\frac{2}{a^{3}(t)}\partial_{0}\left[a^{3}(t)M_{2}(t)\left(\delta g^{00}-2\dot{\pi}_r\right)\right]=\left[6HM_{2}(t)+2\dot{M}_{2}(t)\right]\left(\delta g^{00}-2\dot{\pi}_r\right)+2M_{2}(t)\left(\partial_{0}\delta g^{00}-2\ddot{\pi}_r\right).
\end{align}
The second speed of sound contribution has no linear contribution, such that 
\begin{equation}
	\frac{\dot{M}_{2}(t+\pir)}{2}\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)^{2}\rightarrow 0.
\end{equation}
At last, the dissipation operator generates
\begin{equation}
	2\Gamma(t+\pir)\left(1+A_{\alpha\beta}g^{\alpha\beta}\right)\rightarrow 2\Gamma(t)\left(\delta g^{00}-2\dot{\pi}_r\right).
\end{equation}

Gathering these contributions together, we can now write a first equation as
\begin{equation}\label{eq:pre}
	A\ddot{\pi}_r+B\dot{\pi}_r+C\partial_{i}^{2}\pi_r+D\pir+G_{0}\delta g^{00}+G_{1}\partial_{0}\delta g^{00}+G_{2}\partial_{i}\delta g^{i0}=\xi_{\pi},
\end{equation}
with the self dynamics of the scalar controlled by
\begin{align}
	A=&-2\left[c(t)+2M_{2}(t)\right]\,,\\
	B=&-2\dot{c}(t)-4\Gamma(t)-4\dot{M}_{2}-6Hc(t)-12HM_{2}(t)\,,\\
	C=&~2c(t)\,,\\
	D=&-\ddot{c}(t)-\ddot{\Lambda}(t)-6H\dot{c}(t)\,,
\end{align}
and the mixing with gravity by
\begin{align}
	G_{0}=&~\dot{c}(t)+2\Gamma(t)+2\dot{M}_{2}(t)+6Hc(t)+6HM_{2}(t)\,,\\
	G_{1}=&~c(t)+2M_{2}(t)\,,\\
	G_{2}=&~2c(t)\,.
\end{align}
Dividing \Eq{eq:pre} by $A$, we find the main text result presented in \Eq{eq:pireomexp}.

