\begin{remark}[Some limit behaviors of the impact function $h_{x_{0},c}$] \label{R:limit_behaviors_impact_function}
    Note in particular that for $c = 1$, the impact function becomes linear while for $c = 0.5$, we get back the impact function from \cite[Example 2.3]{hey2023trading}:
    \begin{equation*}
        h_{x_{0}, 0.5}(x) = \begin{cases}
        x, & \text{ if } |x| \leq x_{0}, \\
        \emph{sign}(x) \sqrt{2|x|x_{0}-x_{0}^{2}}, & \text{ if } |x| > x_{0},
    \end{cases}
    \end{equation*}
    so that the derivative of the impact function is given explicitly by
    \begin{equation*}
        h_{x_{0}, 0.5}^{'}(x) = \mathbbm{1}_{[-x_{0}, x_{0}]}(x) + \frac{x_{0}}{\sqrt{2|x|x_{0}-x_{0}^{2}}} \mathbbm{1}_{(-\infty, -x_{0}) \cup (x_{0}, \infty)}(x).
    \end{equation*}

    Finally, note that $c \leq 1$ ensures that $h_{x_{0}, 0.5}^{'}$ is bounded, while \eqref{eq:arrow_pratt_ratio_condition_satisfied} is satisfied only if the concavity of the transient impact is at most a square root, meaning that Theorem \ref{T:mainnonlinear} can be applied for $\frac{1}{2} \le c \le 1$ and $x_{0} > 0$.
\end{remark}

\textbf{Signals specification.} We specify an Ornstein-Uhlenbeck drift-like price  signal  $\tilde{I}$ such that
\begin{equation} \label{eq:drift_signal_specification}
\dd \tilde I_t = (\tilde \theta - \tilde \kappa \tilde I_t) \dd t + \tilde \xi \dd W_t, \quad \tilde I_{0} \in \mathbb{R}.
\end{equation}
The fundamental alpha-signal $\alpha$ that we consider is then given by
\begin{equation} \label{eq:signal_specification}
\alpha_{t} := \mathbb{E}_{t} \left[ \int_{t}^{T} \tilde I_r \dd r \right] = \left( \tilde I_{t} - \frac{\tilde \theta}{\tilde \kappa} \right) \frac{ 1 - e^{- \tilde \kappa (T-t)}}{\tilde \kappa} + \frac{\tilde \theta}{\tilde \kappa} (T-t), \quad t \in [0,T].
\end{equation}


