\textbf{Asymptotic explicit benchmark for one exponential.} Extending the formulation of \cite[Corollary 4.4]{hey2023trading}, with exponential impact time decay $\tau > 0$ and ``Kyle's $\lambda$'' specified as $\lambda = 1 = e^{0}$, to the impact function $h: x \mapsto \text{sign}(x) |x|^{c}, \; x \geq 0$, $c \in [1/2, 1]$ to allow for negative values of the input $x$, we explicitly get  the optimal impact function
\begin{equation*}
    I_{t}^{*} = \frac{1}{1+c} \left( \alpha_{t} + \tau \tilde I_t \right),
\end{equation*}
where recall $\tilde I$ is the stochastic drift price signal. Since $
I_{t}^{*} := \text{sign}(J_{t}^{*}) \left|J_{t}^{*}\right|^{c}$, 
we readily deduce that 
\begin{equation*}
    J_{t}^{*} =  \text{sign}(I_{t}^{*}) \left| I_{t}^{*} \right|^{1/c},
\end{equation*}
which leads to
\begin{equation*}
    J_{t}^{*} = \text{sign} \left( \alpha_{t} + \tau \tilde I_t \right) \left( \frac{1}{1+c} \left| \alpha_{t} + \tau \tilde I_t \right| \right)^{1/c}, \quad t \in (0,T).
\end{equation*}
Now, also considering that $\alpha_{T} = 0$,  the boundary conditions on the impact function $I^{*}$ read $    I_{0}^{*} = 0$, 
   and $I_{T}^{*} = \alpha_T=0$
% \begin{equation*}
% \begin{cases}
%     I_{0}^{*} = 0, \\
%     I_{T}^{*} = \alpha_T=0%\frac{\tau}{1+c} \tilde I_T,
% \end{cases}
% \end{equation*}
which translate for $J^{*}$  into $J_{0}^{*} = 0$  and 
   $J_{T}^{*} = 0.$
% \begin{equation*}
% \begin{cases}
%     J_{0}^{*} = 0, \\
%     J_{T}^{*} = 0 %\text{sign}\left( \tilde I_T \right) \left| \frac{\tau}{1+c} \tilde I_T \right|^{1/c}.
% \end{cases}
% \end{equation*}
Thus, the optimal traded volume, which satisfies 
\begin{equation*}
Q_{t}^{*} = \int_{0}^{t} \dd J_{s}^{*} + \int_{0}^{t} \frac{J_{s}^{*}}{\tau} \dd s, \quad t \in (0,T], \quad Q_0=0,
\end{equation*}
is explicitly given by
\begin{equation} \label{eq:explicit_benchmark_smooth}
Q_{t}^{*} = J^{*}_t + \frac{1}{\tau}\int_{0}^{t}  \text{sign} \left( \alpha_{s} + \tau \tilde I_s \right) \bigg( \frac{| \alpha_{s} + \tau \tilde I_s |}{1+c} \bigg)^{1/c} \dd s, \quad t \in (0,T],
\end{equation}
with the bulk trades 
\begin{equation} 
\begin{aligned}\label{eq:explicit_benchmark_bulk_trades}
&\Delta Q_{0} = Q_{0+}-Q_0 = \text{sign} \left( \alpha_{0} + \tau \tilde I_0 \right) \left( \frac{1}{1+c} \left| \alpha_{0} + \tau \tilde I_{0} \right| \right)^{1/c}, \\ &
\Delta Q_{T} = Q_T-Q_{T-}=J_T-J_{T-}= - \text{sign} \left( \tilde I_T \right) \left| \frac{\tau \tilde I_{T} }{1+c} \right|^{1/c}.
\end{aligned}
\end{equation}
Such bulk trades ensure that the boundary conditions are satisfied.

