\subsection{Impact of power-law decay approximation on trading}

\textbf{Multi-factor approximation of the fractional kernel.} Define the following $\epsilon$-shifted fractional kernel
\begin{equation} \label{eq:def_shifted_frac_kernel}
    G_{\nu, \epsilon}(t) := \xi \left(t+\epsilon\right)^{\nu - 1} \quad \xi>0, \quad \epsilon \geq 0, \quad \nu \in \left( \frac{1}{2}, 1 \right),
\end{equation}
and, for $p \in \mathbb{N}^{*}$, denote the sum of exponential time scales decay kernel by
\begin{equation} \label{eq:def_sum_of_exponentials}
    G_p(t) := \sum_{i=1}^p \xi_i e^{-x_i t},\quad \xi_i,x_i>0, \quad i \in \{ 1, \cdots, p \}.
\end{equation}
Then, given a trading time horizon $T>0$, we aim to approximate the power-law impact decay captured in \eqref{eq:def_shifted_frac_kernel} by a sum of exponential decays in a kernel of the form \eqref{eq:def_sum_of_exponentials}. We minimize the quantity 
\begin{align} \notag
    ||G_{\nu, \epsilon} - G_p||^2_{L^{2}} & := \int_{0}^{T} \left( G_{\nu, \epsilon}(t)-G_p(t) \right)^2 dt \\ \notag
    & = \sum_{i,j=1}^p \frac{\xi_i \xi_j}{x_i + x_j} \left( 1-e^{-(x_i + x_j)T_{l}} \right) + \xi^2 \frac{(T_{l}+\epsilon)^{2\nu - 1} - \epsilon^{2\nu - 1}}{2\nu - 1} \\ \label{eq:loss_approximate_fractional_kernel}
    & \quad - 2\xi\sum_{i=1}^p \frac{\xi_i e^{x_{i} \epsilon}}{x_i^{\nu}} \Gamma \left( \nu \right) \left( P \left( \nu, x_i (T_{l}+\epsilon) \right) - P \left( \nu, x_i \epsilon \right) \right),
\end{align}
with $\Gamma$ and $P$ denoting, respectively, the Gamma function and the regularized lower incomplete Gamma  function, that is,
\begin{equation*}
    \Gamma(a) := \int_0^{\infty} u^{a-1} e^{-u} du, \quad \text{and} \quad P(a,t) := \frac{1}{\Gamma(a)} \int_0^t u^{a-1} e^{-u} du, \quad a >0, \quad t \geq 0.
\end{equation*}
Figure \ref{F:approximated_epsilon_shifted_power_law_kernel_by_exponentials} shows the resulting approximating sum of exponentials kernels \eqref{eq:def_sum_of_exponentials} to fit the $\epsilon$-shifted power-law kernel \eqref{eq:def_shifted_frac_kernel}. The parameters $\left( \xi_{i}, x_{i} \right)_{i \in \{ 1, \cdots, p\}}$ are calibrated incrementally from $1$ to $p$ exponential time scales by minimizing the loss \eqref{eq:loss_approximate_fractional_kernel} on the trading horizon $T=1$ using a standard nonlinear solver. The results of the calibration are displayed in Table~\ref{tab:optimal_weights_mean_reversions_approx_shifted_fractional_kernel}. Notice that fewer exponentials are required to approximate well the power-law when the shift is indeed strictly positive.
