\section{Proof of Theorem~\ref{T:mainnonlinear} } \label{S:proofofoptimality}

The main idea of the proof is to use general results of convex optimization in infinite dimensional spaces. We recall that, given a positive constant $\beta>0$, a map $\mathcal{T}\colon \mathcal{L}^{2}\to \mathbb{R}$ is said to be $\beta-$\emph{strongly concave} if the following inequality is satisfied for every $u,\,v\in \mathcal{L}^{2}$:
\begin{equation}\label{def:strongly_concave}
\mathcal{T}(\theta u+(1-\theta)v) \ge \theta\mathcal{T}(u)+(1-\theta)\mathcal{T}(v)
+\frac{\beta \theta(1-\theta)}{2}\norm{u-v}^2 ,\quad \theta\in(0,1).
\end{equation}
Supposing that $\mathcal{J}$ in \eqref{eq:gain_functional} is concave and G\^ateaux differentiable in $\mathcal{L}^{2}$,  we can study the existence of optimal strategies $\hat{u} \in \mathcal{L}^{2}$ in the sense of \eqref{eq:optimal_strategy} by solving the equation 
\begin{equation}\label{eq:FOC}
	\nabla \mathcal{J}(u)=0,\quad u\in \mathcal{L}^{2},
\end{equation} 
where $\nabla \mathcal{J}(u)\in \mathcal{L}^{2}$ is the G\^ateaux differential of $\mathcal{J}$, defined by
\begin{equation*}
    \langle \nabla \mathcal{J}(u), h \rangle = \lim_{\epsilon\to 0} \frac{\mathcal{J}(u+\epsilon h)-\mathcal{J}(u)}{\epsilon}, \quad h \in \mathcal{L}^{2}.
\end{equation*}
More precisely, the following theorem holds.

%\fbox{{\ma (don't you need some lower semicontinuity on $\mathcal{J}$ for next thm?}}
\begin{theorem}\label{thm:concave}
	Suppose that the performance functional $\mathcal{J}$ in \eqref{eq:gain_functional} is well-defined and G\^ateaux differentiable in $\mathcal{L}^{2}$. 
	\begin{enumerate}[label={(\roman*)}]
		\item\label{point:concave}If $\mathcal{J}$ is concave in $\mathcal{L}^{2}$, then the set of optimal strategies $\hat{u}\in \mathcal{L}^{2}$ satisfying \eqref{eq:optimal_strategy} coincide with the set of solutions of \eqref{eq:FOC}. In addition, if the functional $-\mathcal{J}$ is coercive, i.e., $\lim_{\norm{u}\to \infty}\mathcal{J}(u)=-\infty$, then there exists at least one optimal strategy that solves \eqref{eq:optimal_strategy}. If additionally $\mathcal{J}$ is strictly concave, then such an optimal strategy is unique.
		\item\label{point:strictly_concave} In particular, if $\mathcal{J}$ is strongly concave in the sense of \eqref{def:strongly_concave}, then there exists a unique optimal strategy $\hat{u}\in \mathcal{L}^{2}$ satisfying \eqref{eq:optimal_strategy}, which is also the unique solution of \eqref{eq:FOC}.
	\end{enumerate}
\end{theorem}
\begin{proof}
    The proof of the theorem statements are  consequences of well-known results of convex analysis in Hilbert spaces that can be found in \cite{bauschke2017} (see also \cite{ekeland1999convex}). We first notice that $\hat{u} \in \mathcal{L}^{2}$ satisfies \eqref{eq:optimal_strategy} if and only if 
    \begin{equation}\label{eq:minimization}
        -\mathcal{J}(\hat{u})=\inf_{u\in\mathcal{L}^{2}}(-\mathcal{J}(u)),
    \end{equation}
	and that $-\mathcal{J}$ is proper because, by the hypothesis of well-posedness of $\mathcal{J}$, $\mathcal{J}(\mathcal{L}^{2})\subset \mathbb{R}$. Since $\mathcal{J}$ is supposed to be G\^ateaux differentiable and concave in $\mathcal{L}^{2}$,  the fact that the set of optimal strategies $\hat{u} \in \mathcal{L}^{2}$ according to \eqref{eq:minimization} (or \eqref{eq:optimal_strategy}) coincides with the set of solutions to \eqref{eq:FOC} is ensured by \cite[Proposition 17.4]{bauschke2017}.	Moreover, by \cite[Proposition 17.39]{bauschke2017}, the opposite performance functional $-\mathcal{J}$ is lower semi-continuous in $\mathcal{L}^{2}$. Consequently, if we further require $-\mathcal{J}$ to be  coercive, an application of \cite[Proposition 11.14]{bauschke2017} yields the existence of at least one optimal strategy $\hat{u} \in \mathcal{L}^{2}$ satisfying \eqref{eq:minimization}, hence \eqref{eq:optimal_strategy}, too. Such an optimal strategy $\hat{u} \in \mathcal{L}^{2}$ is unique when $-\mathcal{J}$ is  strictly convex by \cite[Corollary 11.8]{bauschke2017}. This completes the proof of \ref{point:concave}.\\
	As for the assertion in  \ref{point:strictly_concave}, it follows by the same arguments as before combined with \cite[Corollary 11.16]{bauschke2017}. The theorem is now fully proved.
\end{proof}

Given an admissible kernel $G$ and an admissible impact function $h$, we can readily observe that assuming either assumption (i) or assumption (ii) ensures that $\mathcal{J}$ is well-defined in $\mathcal{L}^{2}$.

Therefore, it remains to prove that $\mathcal{J}$ is
\begin{enumerate}
    \item strongly concave,
    \item Gâteaux differentiable, and to compute its derivative.
\end{enumerate}
This is the objective of the next two subsections.

\subsection{\texorpdfstring{$\mathcal{J}$ is Gâteaux differentiable}{J is Gateaux differentiable}} \label{ss:gateau_diff}

	The next lemma shows that, under suitable requirements on the impact function $h$, recall also Remark \ref{rem_conditions_h}, the performance functional $\mathcal{J}$ is G\^ateaux differentiable in $\mathcal{L}^{2}$. In the sequel, we denote by $\mathbf{1}$ the linear integral operator in $\mathcal{L}^{2}$ defined by  
\begin{equation*}
	(\mathbf{1}v)_{t} := \int_{0}^{T} \mathbbm{1}_{\{s\le t\}} v_{s} \dd s = \int_{0}^{t} v_{s} \dd s, \quad t\in [0,T], \quad v\in \mathcal{L}^{2}.
\end{equation*}
\begin{lemma}\label{thm:FOC}
    Suppose that the impact function $h\colon \mathbb{R}\to \mathbb{R}$ satisfies assumption (i) from Definition \ref{def:admissible_impact_function}. Then the functional $\mathcal{J}$ in \eqref{eq:gain_functional_alpha_impact_cost_trade_of} is well-defined and G\^ateaux differentiable in $\mathcal{L}^{2}$, with G\^ateaux differential given by 
    \begin{equation}\label{Gat_diff_J}
         \nabla \mathcal{J}(u)=
         \alpha - X_{0} \left( \phi (T-\cdot) + \varrho \right) - \gamma u - \mathbf{A}(u) - \left( \mathbf{H}_{\phi,\varrho}(u) \right)_{\cdot}
         - \left( \mathbf{H}_{\phi,\varrho}^{*}(u) \right)_{\cdot},\quad u\in \mathcal{L}^{2},
    \end{equation}
    where $\mathbf{A}$ and $H_{\phi,\varrho}$ are respectively defined in \eqref{eq:def_A_operator} and \eqref{eq:kernel_H}.
\end{lemma}

\begin{proof}
Note that, for $u\in \mathcal{L}^{2}$, the definition of $\mathcal{J}$ in  \eqref{eq:gain_functional_alpha_impact_cost_trade_of} can be rewritten as follows
\begin{equation} \label{eq:J_def_rewrite}
	\mathcal{J}(u) = \langle \alpha, u \rangle
	- \frac{\gamma}{2} \norm{u}^2
    - \langle h(Z^u), u\rangle
    - \frac{\phi}{2}\norm{X^u}^2
    - \frac{\varrho}{2} \mathbb{E}\left[|X^u_T|^2\right]
    + X_{0}\E S_{T} =: \sum_{i=1}^{6}\mathcal{J}_i(u).
\end{equation}
We now proceed to G\^ateaux differentiate all the addends in \eqref{eq:J_def_rewrite}. Evidently, $\langle \nabla \mathcal{J}_1(u), f\rangle=\langle \alpha, f\rangle$, $\langle \nabla \mathcal{J}_2(u), f\rangle= \langle -\gamma u, f\rangle$ and $\langle \nabla \mathcal{J}_6(u), f\rangle=0$ for every $f\in \mathcal{L}^{2}.$ As for $\mathcal{J}_3$, we let $\epsilon\in (-1,1)\setminus\{0\}$ and compute 
the incremental ratio in a direction $f\in \mathcal{L}^{2}$, namely
\begin{align}\label{eq:J_3_diff1}
	\notag&\frac{\mathcal{J}_3(u+\epsilon f)-\mathcal{J}_3(u)}{\epsilon}=-\mathbb{E}\left[\int_{0}^{T}\frac{h(Z^{u+\epsilon f}_t)-h(Z^u_t)}{\epsilon}(u_t+\epsilon f_t)\,\dd t \right] - \mathbb{E}\left[\int_{0}^{T}h(Z^u_t) f_t \dd t\right]\\
	&\qquad =\notag - \mathbb{E}\left[\int_{0}^{T}\frac{h(Z^{u+\epsilon f}_t)-h(Z^u_t)}{\epsilon}u_t \dd t \right] - \mathbb{E}\left[\int_{0}^{T}{\left(h(Z^{u+\epsilon f}_t) - h(Z^u_t)\right)}f_t \dd t \right] - \langle h(Z^u), f\rangle \\
	& \qquad =:
	\mathbf{\upperRomannumeral{1}}^{u,f}(\epsilon) +
	\mathbf{\upperRomannumeral{2}}^{u,f}(\epsilon) - \langle h(Z^u), f\rangle.
\end{align}
We then study the limits of $\mathbf{\upperRomannumeral{1}}^{u,f}(\epsilon)$ and $\mathbf{\upperRomannumeral{2}}^{u,f}(\epsilon)$ as $\epsilon \to 0$. Notice that, from the definition in \eqref{eq:def_Z}, $Z^{u+\epsilon f}_t=Z^{u}_t + \epsilon \left( \mathbf{G} f\right)_{t},\, t\in [0,T]$, so that, by Lipschitz continuity of $h$ with constant $\norm{h'}_\infty$, we immediately get
\[
\left|h(Z^{u+\epsilon f}_t)-h(Z^u_t)\right||f_t|\le \epsilon \norm{h'}_\infty |f_t| \left| \left( \mathbf{G} f\right)_{t} \right| \underset{\epsilon \to 0}{\longrightarrow} 0, \quad \dd t \otimes \mathbb{P}-\text{a.e}.
\] 
Since $f, \; \mathbf{G} f \in \mathcal{L}^{2} \subset \mathcal{L}^{1}$, the dominated convergence theorem entails that $\lim_{\epsilon \to 0}\mathbf{\upperRomannumeral{2}}^{u,f}(\epsilon)=0$. Regarding $\mathbf{\upperRomannumeral{1}}^{u,f}(\epsilon)$, by the tower property of the conditional expectation and Fubini's theorem, 
\begin{align*}
    \notag \mathbf{\upperRomannumeral{1}}^{u,f}(\epsilon) &
    = - \mathbb{E}\left[\int_{0}^{T}\frac{h(Z^{u+\epsilon f}_t)-h(Z^u_t)}{Z^{u+\epsilon f}_t - Z^{u}_t} \left( \mathbf{G} f\right)_{t} \mathbbm{1}_{\left\{\left( \mathbf{G} f\right)_{t} \neq 0\right\}}u_t\,\dd t \right]
    \\&\underset{\epsilon\to 0}{\longrightarrow} \,
    -\mathbb{E}\left[\int_{0}^{T}h'(Z^u_t) \left( \mathbf{G} f\right)_{t} u_t \dd t\right]
    = - \mathbb{E} \left[ \int_{0}^{T} \left(\mathbf{G}^{\ast}\left(h'(Z^u)u\right)\right)_{t} f_t \dd t \right] \\
    & = - \mathbb{E}\left[ \int_{0}^{T} \left(\mathbf{G}^{\ast}\left(h'(Z^u)u\right)\right)_{t} f_t \dd t \right] = -
    \langle \mathbf{G}^{\ast}\left(h'(Z^u)u\right), f\rangle.
    \end{align*}
The passage to the limit under the integral sign in the previous step is again justified by the dominated convergence theorem, which can be applied since $\left(\dd t \otimes \mathbb{P}\right)-${a.e.},
\begin{equation*}
    \frac{\left|h(Z^{u+\epsilon f}_t)-h(Z^u_t)\right|}{\epsilon} \mathbbm{1}_{\left\{\left( \mathbf{G} f\right)_{t} \neq 0\right\}} |u_t|\le \norm{h'}_\infty\left|\left( \mathbf{G} f\right)_{t} \right||u_t|\in \mathcal{L}^1.
\end{equation*}
Therefore, thanks to the previous computations, we take the $\lim_{\epsilon \to 0}$ in \eqref{eq:J_3_diff1} to infer that
 \[
 	\big\langle \nabla \mathcal{J}_3(u), f \rangle = - \langle \mathbf{G}^\ast (h'(Z^u)u) + h(Z^u), f\big\rangle.
 \] 
Recall the definition of $X^u$ in \eqref{eq:running_inventory}, which in particular gives for any $f \in \mathcal{L}^{2}$,  $X_t^{u+\epsilon f}=X_t^u-\epsilon \int_{0}^{t}f_s\dd s, \; t \in [0,T], \; \mathbb{P}-$a.s. Then, expanding the squares, taking the limit $\epsilon \to 0$, and applying Fubini readily yields
\begin{equation*}
    \big\langle \nabla \left(\mathcal{J}_4(u) + \mathcal{J}_5(u) \right), f \rangle = - \langle \phi \mathbf{1}^{\ast} X^{u} + \varrho \E_{\cdot} \left[ X_{T}^{u} \right], f\big\rangle.
\end{equation*}
Notice that, by Fubini's theorem, for any $t \in [0,T]$,
\begin{align*}
    \phi \left(\mathbf{1}^{\ast} X^{u}\right)_{t} + \varrho \E_{t} \left[ X_{T}^{u} \right] & = \phi X_{0} (T-t) + \E_{t} \int_{0}^{T} \left( \int_{0}^{s} \mathbbm{1}_{\{s>t\}} u_{r} \dd r \right) \dd s + \varrho X_{0} + \E_{t} \int_{0}^{T} \varrho u_{r} \dd r \\
    & = X_{0} \left( \phi (T-t) + \varrho \right) + \E_{t} \int_{0}^{T} \left( \int_{r}^{T} \mathbbm{1}_{\{s>t\}} \dd s \right) u_{r} \dd r + \E_{t} \int_{0}^{T} \varrho u_{r} \dd r \\
    & = X_{0} \left( \phi (T-t) + \varrho \right) + \int_{0}^{t} \left( \int_{r}^{T} \mathbbm{1}_{\{s>t\}} \dd s \right) u_{r} \dd r \\
    & \quad + \int_{t}^{T} \left( \int_{r}^{T} \mathbbm{1}_{\{s>t\}} \dd s \right) \E_{t} u_{r} \dd r + \int_{0}^{t} \varrho u_{r} \dd r + \int_{0}^{t} \varrho \E_{t} u_{r} \dd r,
\end{align*}
and 

\begin{equation*}
    \begin{cases}
        \int_{0}^{t} \left( \int_{r}^{T} \mathbbm{1}_{\{s>t\}} \dd s \right) u_{r} \dd r = \int_{0}^{t} \left( \int_{t}^{T} \dd s \right) u_{r} \dd r = \int_{0}^{t} \left( T-t \right) u_{r} \dd r \\
        \int_{t}^{T} \left( \int_{r}^{T} \mathbbm{1}_{\{s>t\}} \dd s \right) \E_{t} u_{r} \dd r = \int_{t}^{T} \left( \int_{r}^{T} \dd s \right) \E_{t} u_{r} \dd r = \int_{t}^{T} \left( T-r \right) \E_{t} u_{r} \dd r
    \end{cases},
\end{equation*}
so that
\begin{align} \notag
    \phi \left(\mathbf{1}^{\ast} X^{u}\right)_{t} + \varrho \E_{t} \left[ X_{T}^{u} \right] & = X_{0} \left( \phi (T-t) + \varrho \right) + \int_{0}^{t} \left( \phi (T-t) + \varrho \right) u_{r} \dd r \\ \notag
    & \quad + \int_{t}^{T} \left( \phi (T-r) + \varrho \right) \E_{t} u_{r} \dd r \\ \label{eq:expression_H_phi_rho}
    & = X_{0} \left( \phi (T-t) + \varrho \right) + \left( \mathbf{H}_{\phi,\varrho}(u) \right)_{t} + \left( \mathbf{H}_{\phi,\varrho}^{*}(u) \right)_{t}.
\end{align}
Consequently,
\begin{equation*}
    \big\langle \nabla \left(\mathcal{J}_4(u) + \mathcal{J}_5(u) \right), f \rangle = - \langle X_{0} \left( \phi (T-t) + \varrho \right) + \left( \mathbf{H}_{\phi,\varrho}(u) \right)_{t}
    + \E_{t} \left( \mathbf{H}_{\phi,\varrho}^{*}(u) \right)_{t}, f\big\rangle,
\end{equation*}
where the admissible kernel $H_{\phi,\varrho}$ is defined in \eqref{eq:kernel_H}. Combining the previous computations, we obtain the G\^ateaux derivatives of all the terms in \eqref{eq:J_def_rewrite}, which  yields \eqref{Gat_diff_J} and completes the proof.  
\end{proof}

\subsection{\texorpdfstring{If $\mathbf{A}$ is monotone, then $\mathcal{J}$ is strongly concave}{If A is monotone, then J is strongly concave}}

Motivated by Theorem \ref{thm:concave}, we aim to determine suitable  conditions on the impact function $h$, the endogenous signal $g$ and the kernel $G$  to ensure the (strong) concavity of the performance functional $\mathcal{J}$.  This is done in the next lemma, where we focus on the operator $\mathbf{A}$ defined in \eqref{eq:def_A_operator}, which is indeed fully determined by $h, \; g$ and $G$.

\begin{lemma}\label{thm:conc_conditions}
	Suppose that the map $h \colon \mathbb{R} \to  \mathbb{R}$ is differentiable, with bounded derivative $h'$. The operator $\mathbf{H}_{\phi,\varrho}$ is positive semi-definite. As a consequence, if the operator  $\mathbf{A} \colon \mathcal{L}^{2} \to \mathcal{L}^{2}$ in \eqref{eq:def_A_operator} is monotone in the sense of \eqref{eq:definition_monotone}, then the functional $\mathcal{J}$ in \eqref{eq:gain_functional} is $\gamma-$strongly concave.
\end{lemma}

\begin{proof}
	We define the functional $\widetilde{\mathcal{J}}$ in $\mathcal{L}^{2}$  by
    \begin{equation*}
        \widetilde{\mathcal{J}}(u):= - \mathcal{J}(u) - \frac{\gamma}{2} \norm{u}^2,\quad u \in \mathcal{L}^{2}.
    \end{equation*}
	The aim of the proof consists in showing that $\widetilde{\mathcal{J}}$ is convex because, by \cite[Proposition 10.8]{bauschke2017}, this fact is equivalent to the $\gamma-$strong convexity of $-\mathcal{J}$.
	By Lemma~\ref{thm:FOC}, $\widetilde{\mathcal{J}}$ is G\^ateaux differentiable. Hence, \cite[Proposition 17.10]{bauschke2017} gives the equivalence between the convexity of $\widetilde{\mathcal{J}}$ and the monotonicity of the G\^ateaux gradient $\nabla\widetilde{\mathcal{J}}$, i.e.,
	\begin{equation*}
	\langle u-v, \nabla \widetilde{\mathcal{J}}(u)-\nabla \widetilde{\mathcal{J}}(v)\rangle\ge0,\quad u,\, v\in \mathcal{L}^{2}.
	\end{equation*}
    By \eqref{Gat_diff_J} while using the definition of $\mathbf A$ from \eqref{eq:def_A_operator}, we readily get for $u, \; v \in \mathcal{L}^{2}$
    \begin{equation*}
        \left\langle \nabla \widetilde{\mathcal{J}}(u)-\nabla \widetilde{\mathcal{J}}(v), u-v \right\rangle = \left \langle \mathbf{A}(u)-\mathbf{A}(v), u-v \right \rangle + \left \langle \left(\mathbf{H}_{\phi,\varrho} + \mathbf{H}_{\phi,\varrho}^{\ast} \right)(u-v), u-v \right \rangle.
    \end{equation*}
    It is then sufficient to prove that $\mathbf{H}_{\phi,\varrho}$ is positive semi-definite in the sense of \eqref{eq:sdp_operator_def}. Using \eqref{eq:expression_H_phi_rho}, we obtain
    \begin{align*}
        \left \langle \left(\mathbf{H}_{\phi,\varrho} + \mathbf{H}_{\phi,\varrho}^{\ast} \right)(u-v), u-v \right \rangle & = \left \langle \phi \mathbf{1}^{\ast} X^{u-v} + \varrho X_{T}^{u-v}, u-v \right \rangle \\
        & = \phi \left \langle X^{u-v}, \mathbf{1} \left(u-v\right) \right \rangle + \varrho \left \langle X_{T}^{u-v}, u-v \right \rangle \\
        & = \mathbb{E}\left[ \phi \int_{0}^{T}\left(\int_{0}^{t}(u_s-v_s)\dd s\right)^2\dd t  + \varrho \bigg(\int_{0}^{T}(u_t-v_t)\dd t\bigg)^2 \right] \ge 0.
    \end{align*}
    The proof is now complete.
\end{proof}


\subsection{Putting everything together}

We can now complete the proof of Theorem~\ref{T:mainnonlinear}.

\begin{proof}[Proof of Theorem~\ref{T:mainnonlinear}]
The assumptions of Theorem \ref{T:mainnonlinear} enable us to apply Lemmas \ref{thm:FOC}-\ref{thm:conc_conditions} to deduce that the performance functional $\mathcal{J}$ in \eqref{eq:gain_functional} is well-defined, G\^ateaux differentiable and $\gamma-$strongly concave in $\mathcal{L}^{2}$. Consequently, by Theorem \ref{thm:concave}\ref{point:strictly_concave}, there exists a unique optimal strategy $\hat{u} \in \mathcal{L}^{2}$ that satisfies \eqref{eq:optimal_strategy}, which is also the unique solution to \eqref{eq:FOC}. By the G\^ateaux derivative expression \eqref{Gat_diff_J} of $\mathcal{J}$, this is equivalent to solving the nonlinear stochastic Fredholm equation \eqref{eq:nonlinearfredholm}, completing the proof.    
\end{proof}

\section{Proof of Proposition \ref{P:one_exponential_case}} \label{s:sufficient_conditions_A_monotone}

Let  the admissible kernel $G$ be  such that $k: t \in [0,T] \mapsto G(t,t) > 0$ is a well-defined positive function\footnote{This condition excludes all kernels with a singularity at the origin such as the fractional kernel.}. Suppose that $G$ is differentiable with respect to its first argument, and denote by $\partial_{x}G(t,s), \; t,s \in [0,T]$ the resulting kernel. The associated operator will be denoted by $\mathbf{\partial_{x}G}$  and  assumed to be admissible\footnote{Any combination of exponential kernels with positive weights satisfies such requirements.}.

For $u \in \mathcal{L}^{2}$, the dynamics of $Z^u$ from \eqref{eq:def_Z} are given by 
\begin{equation} \label{eq:dynamics_Z_u}
    \dd Z^u_t= \dd g_{t} + \left( k(t) u_t +(\mathbf{\partial_{x}G}u)_{t} \right) \dd t, \quad Z^u_0 = g(0).
\end{equation}
Using \eqref{eq:dynamics_Z_u}, and then integrating by parts the second addend in the definition \eqref{eq:def_A_operator} of $\mathbf{A}$, we obtain
\begin{align*}
    \left(\mathbf{A}(u)\right)_{t} & = h(Z_t^u) +
    \mathbb E_t \left[ \int_t^T \frac{G(s,t)}{k(s)} h'\left(Z^u_s\right) \dd Z^u_s\right]
    - \mathbb E_t \left[ \int_t^T \frac{G(s,t)}{k(s)} h'\left(Z^u_s\right) \dd g_{s} \right] \\
    & \quad -  \mathbb E_t \left[ \int_t^T \frac{G(s,t)}{k(s)} h'\left(Z^u_s\right) (\mathbf{\partial_{x}G}u)_{s} \dd s \right] \\
    & = \mathbb{E}_t\left[\frac{G(T,t)}{k(T)}h(Z^u_T)\right] -\mathbb{E}_t\left[ \int_{t}^{T}\frac{\partial_{x}G(s,t)k(s)-G(s,t)k'(s)}{k(s)^2}h(Z^u_s) \dd s \right] \\
    & - \mathbb E_t\bigg[\int_t^T  \frac{G(s,t)}{k(s)} h'\left(Z^u_s\right) \dd g_{s} \bigg]
    -\mathbb E_t\bigg[\int_t^T  \frac{G(s,t)}{k(s)} h'\left(Z^u_s\right) \left(\mathbf{\partial_x G}u\right)_{s} \,\dd s\bigg]
    \\&=:(\left( \mathbf{\upperRomannumeral{1}+\upperRomannumeral{2}+\upperRomannumeral{3}}+\mathbf{\upperRomannumeral{4}})(u)\right)_{t}, \quad t \in [0,T].
\end{align*}
Observe that $\mathbf{\upperRomannumeral{1}} \; \colon \; \mathcal{L}^{2}\to\mathcal{L}^{2}$ is a monotone operator as soon as $h$ is a nondecreasing map, since
\begin{align*}
	\left\langle
	\mathbf{\upperRomannumeral{1}}(u)-\mathbf{\upperRomannumeral{1}}(v),u-v
	\right\rangle
&	=\frac{1}{k(T)}
	\mathbb{E}\bigg[\left(h(Z^u_T)-h(Z^v_T)\right)\int_{0}^{T}G(T-t)(u_t-v_t) \dd t\bigg]
	\\&=
	\frac{1}{k(T)}
	\mathbb{E}\Big[\left(h(Z^u_T)-h(Z^v_T)\right)(Z^u_T-Z^v_T)\Big]\ge 0,\quad u,v\in \mathcal{L}^{2}.
\end{align*}
Then,  applying Fubini's Theorem we get
\begin{align}
    \left\langle
    \mathbf{\upperRomannumeral{3}}(u)-\mathbf{\upperRomannumeral{3}}(v),u-v
    \right\rangle
    =-\mathbb{E}\bigg[\int_{0}^{T}(h'(Z^u_t)-h'(Z^v_t))(Z^u_t-Z^v_t) \frac{\dd g_{t}}{k(t)}\bigg], \quad u,v\in\mathcal{L}^{2},
\end{align}
so that the monotonicity of the operator $\mathbf{\upperRomannumeral{3}}$ may not true in general and depends on the dynamics of the endogenous signal $g$. The particular case where $\dd g_{t} = g'(t) dt$ with $g' \ge 0$ (i.e., $g$ is a nondecreasing input curve) and $h'$ is nonincreasing (i.e., the impact function $h$ is concave on the real line) would yield the monotonicity of $\mathbf{\upperRomannumeral{3}}$, but such assumptions may be too restrictive. 

Furthermore, verifying the monotonicity property of the  operators $\mathbf{\upperRomannumeral{2}}$ and $\mathbf{\upperRomannumeral{4}}$ in general is not obvious and depends on the form of the kernel $G$ and its first-argument derivative $\partial_x G$. 

\paragraph*{Case of one exponential for the impact decay.} For this reason, in what follows we assume (i) $h$ to be nondecreasing and we restrict our attention to the exponential Volterra kernel, i.e.,
\[
    G(t,s) = \mathbbm{1}_{\{t\ge s\}}ae^{-b(t-s)}, \quad t,s\in [0,T], \quad a > 0, \; b \ge 0,
\]
to study the monotonicity property of the operator $\mathbf{\upperRomannumeral{5}} := \mathbf{\upperRomannumeral{2}} + \mathbf{\upperRomannumeral{4}}$. In this way, we conveniently use the relation $\partial_xG(t,s)=-bG(t,s)$, for $0\le s <t\le T,$ and the fact that $k \equiv a$. Specifically, by Fubini's Theorem and straightforward calculus, we get for any $u,\; v \in \mathcal{L}^{2}$
\begin{align*}
    \left\langle \mathbf{\upperRomannumeral{5}}(u)-\mathbf{\upperRomannumeral{5}}(v),u-v \right\rangle & = \frac{b}{a}\left\langle h(Z^u)-h(Z^v),\,Z^u-Z^v\right\rangle \\
    & + \quad \frac{b}{a} \left\langle Z^uh'(Z^u)-Z^vh'(Z^v),Z^u-Z^v \right\rangle \\
    & - \frac{b}{a} \mathbb{E}\bigg[ \int_{0}^{T} g_{t} (h'(Z^u_t)-h'(Z^v_t))(Z^u_t-Z^v_t)\dd t \bigg].
\end{align*}
Concluding on the nonnegativity of the above quantity in general depends on the endogenous signal $g$ as was the case for $\mathbf{\upperRomannumeral{3}}$. But if we additionally assume that (ii) $g\equiv 0$ and (iii) $x\mapsto xh'(x)$ is nondecreasing, then clearly $\mathbf{\upperRomannumeral{5}}$ is monotone, which proves Proposition \ref{P:one_exponential_case}.

\paragraph*{Case of a sum of exponential time scales for the impact decay.} More generally, one may wonder whether we could derive in a similar way sufficient conditions to get the monotonicity property of the operator $\mathbf{\upperRomannumeral{5}}\colon\mathcal{L}^{2}\to\mathcal{L}^{2}$ in the case of a Volterra kernel given by a finite sum of exponentials, i.e., 
\[
G(t,s)=\mathbbm{1}_{\{t\ge s\}}\sum_{i=1}^{n}a_ie^{-b_i(t-s)}, \quad t,s\in [0,T], \quad 
a_i > 0, \;  b_i \ge 0, \quad i \in \{ 1, \cdots, n \}, \quad n\in\mathbb{N}.
\]
The answer turns out to be negative. Indeed, assume without loss of generality that the mean--reversion speeds $(b_i)_i$ differ from one another. Then, in this case, $k \equiv \sum_{i=1}^{N}a_i=: A$ and 
\[
	\partial_{x}G(t,s)=-\sum_{i=1}^n a_ib_i\exp\{-b_i(t-s)\}, \quad 0 \le s < t \le T.
\]
For any $i=1,\dots, n$, we also define the Volterra kernels $G_i(t,s)=\mathbbm{1}_{\{t\ge s\}}a_ie^{-b_i(t-s)}$, so that $G(t,s)=\sum_{i=1}^n G_i(t,s), \; s,t \in [0,T]$, and $\partial_xG(t,s)=-\sum_{i=1}^n b_iG_i(t,s),\,0<s<t<T$. Considering the initial input curve $g\equiv 0$, we can write 
$$
    Z^u = \sum_{i=1}^n \mathbf{G_i}u =: \sum_{i=1}^n Z^{i,u}, \quad u \in \mathcal{L}^{2}.
$$ 
Direct computations based on the definitions of $\mathbf{\upperRomannumeral{2}}$ and $\mathbf{\upperRomannumeral{4}}$ yield, for every $u\in\mathcal{L}^{2}$, 
\begin{equation*}
	\left(\mathbf{\upperRomannumeral{6}}(u)\right)_{t} = \frac{1}{A}\sum_{i=1}^{N} \bigg(\mathbf{G_i}^\ast\bigg(b_{i}h(Z^u) + h'(Z^u)\bigg(\sum_{j=1}^n b_j Z^{j,u}\bigg)\bigg)\bigg)_{t}, \quad t \in [0,T].
\end{equation*}
It follows by Fubini's Theorem and putting the finite sum inside the integrals that
\begin{align*}
    \left\langle \mathbf{\upperRomannumeral{6}}(u)-\mathbf{\upperRomannumeral{6}}(v),u-v \right\rangle & = \frac{1}{A}\sum_{i=1}^n \mathbb{E}\bigg[ \int_{0}^{T} \left(\mathbf{G_i}(u-v)\right)_{t} \bigg(b_i(h(Z^u_t)-h(Z^v_t)) \\
    &\quad + \bigg(h'(Z^u_t)\bigg(\sum_{j=1}^n b_j Z_{t}^{j,u} \bigg) - h'(Z^v_t)\bigg(\sum_{j=1}^n b_j Z_{t}^{j,v} \bigg)\bigg)\bigg) \dd t \bigg] \\
    & = \frac{1}{A} \mathbb{E}\bigg[\int_{0}^{T}\bigg((h(Z^u_t)-h(Z^v_t))\sum_{i=1}^n b_i(Z^{i,u}_t-Z^{i,v}_t) \\
    & \quad + (Z^u_t-Z^v_t) \bigg(h'(Z^u_t)\bigg(\sum_{j=1}^n b_jZ^{j,u}_t \bigg) - h'(Z^v_t)\bigg(\sum_{j=1}^n b_jZ^{j,v}_t \bigg)\bigg)\bigg)\dd t
    \bigg].
\end{align*}
Therefore, a sufficient condition on $h$ that guarantees the monotonicity of the operator $\mathbf{\upperRomannumeral{6}}$ is 
\begin{multline} \label{suff_condition_f}
\bigg(h\bigg(\sum_{i=1}^n x_i\bigg)-h\bigg(\sum_{i=1}^{n} y_i\bigg)\bigg)\bigg(\sum_{i=1}^n b_i(x_i-y_i)\bigg) \\
+ \bigg(\sum_{i=1}^n (x_i-y_i)\bigg) \bigg( h'\bigg(\sum_{i=1}^n x_i\bigg)\bigg(\sum_{i=1}^n b_i x_i \bigg) - h'\bigg(\sum_{i=1}^n y_i\bigg)\bigg(\sum_{i=1}^n b_i y_i \bigg) \bigg)\ge 0,
\end{multline}
for every $(x_1,\dots,x_n),\,(y_1,\dots, y_n)\in \mathbb{R}^n$. 

\begin{remark}
    Observe that condition \eqref{suff_condition_f} is too strong, as it is not even satisfied for $h(x)=x$. Indeed, in this case, choosing $n=2$, \eqref{suff_condition_f} reads
\[
	\big(x_1+x_2-y_1-y_2\big)(b_1(x_1-y_1)+b_2(x_2-y_2))\ge 0,\quad x_i,\,y_i\in\mathbb{R},
\]
which can be rewritten as 
\[
	b_1(x_1-y_1)^2+b_2(x_2-y_2)^2\ge -(b_1+b_2)(x_1-y_1)(x_2-y_2).
\]
However, this inequality is not satisfied on the entire plane $\mathbb{R}^2.$
\end{remark}

\section{Proof of Theorem \ref{T:existence_beyond_monotonicity} } 
\label{s:proof_existence_beyond_monotonicity}
\subsection{\texorpdfstring{$-\mathcal{J}$ is coercive}{-J is coercive}} \label{ss:coercive}

\begin{lemma} \label{lemma:coercive}
    Let $G$ be an admissible kernel, and let $h \colon \mathbb{R} \to \mathbb{R}$ satisfy Definition \ref{def:admissible_impact_function}(i). % so that $\mathcal{J}$ is well-defined. 
    Additionally, suppose that one of the following conditions holds.
    \begin{enumerate}
        \item[a)] $h:x \mapsto x$ and $G$ is positive semi-definite;
        \item[b)] Definition \ref{def:admissible_impact_function}(ii) holds;
        \item[c)] the inequality
        \begin{equation*}
            \frac{\gamma}{2} > \norm{h'}_{\infty} \sqrt{T C_{G}}
        \end{equation*}
     is satisfied.
    \end{enumerate}
    Then $- \mathcal{J} \colon \mathcal{L}^2\to \mathbb{R}$ is coercive, i.e., $\lim_{\norm{u}\to \infty } \mathcal{J}(u) = -\infty$. 
\end{lemma}
\begin{proof}
    First of all, if Assumption a) holds, starting from the expression \eqref{eq:gain_functional_alpha_impact_cost_trade_of} of the gain functional $\mathcal{J}$, we readily have
    \begin{align*}
        \mathcal{J}(u) & \le \norm{\alpha-g} \norm{u} + X_{0} \E S_{T} - \frac{\gamma}{2} \norm{u}^{2} - \langle \mathbf{G}u, u \rangle \\
        & \le \norm{\alpha-g} \norm{u} + X_{0} \E S_{T} - \frac{\gamma}{2} \norm{u}^{2},
    \end{align*}
    where the second inequality is consequence of the positive semi-definite property of $G$. Coercivity follows immediately.

    Furthermore, starting again from \eqref{eq:gain_functional_alpha_impact_cost_trade_of}, and applying twice the Cauchy-Schwarz inequality, we have
    \begin{align} \notag
        \mathcal{J}(u) & \le \norm{\alpha} \norm{u} + X_{0} \E S_{T} - \frac{\gamma}{2} \norm{u}^{2} - \langle h \left( g_{t} + \mathbf{G}u \right), u \rangle \\ \label{eq:estimate_on_J_for_coercivity}
        & \le \norm{\alpha} \norm{u} + X_{0} \E S_{T} - \frac{\gamma}{2} \norm{u}^{2} + \norm{h \left( g +  \mathbf{G}u \right)} \norm{u}.
    \end{align}

    Suppose Assumption b) holds. By sublinearity of $h$ in the sense of Definition \ref{def:admissible_impact_function}(ii), we fix $0 \leq \zeta < 1$ such that
    \begin{align} \notag
        \norm{h \left( g + \mathbf{G}u \right)} & \leq C_{h} \mathbb{E}\bigg[ \int_{0}^{T} \Big( 1+|g_{t}+\left(\mathbf{G}u\right)_{t}|^\zeta \Big)^2 \dd t \bigg]^{\frac{1}{2}} \\ \notag
        & \leq \sqrt{2} C_{h} \mathbb{E}\bigg[ \int_{0}^{T} \left(1+|g_{t}+\left(\mathbf{G}u\right)_{t}|^{2\zeta} \right) dt \bigg]^{\frac{1}{2}} \\ \notag
        & \leq \sqrt{2} C_{h} \Big( \sqrt{T} + \mathbb{E}[\|g+\mathbf{G}u\|_{L^{2\zeta}}]^{\zeta} \Big) \\ \notag
        & \leq \sqrt{2} C_{h} \Big( \sqrt{T} + T^{\frac{1-\zeta}{2}}\mathbb{E}[\|g+\mathbf{G}u\|_{L^{2}}]^{\zeta} \Big) \\ \notag
        & \leq \sqrt{2} C_{h} \Big( \sqrt{T} + T^{\frac{1-\zeta}{2}}(\|g\| +\|\mathbf{G}u\|)^{\zeta} \Big) \\ \notag
        & \leq \sqrt{2} C_{h} \left( \sqrt{T} + T^{\frac{1-\zeta}{2}} \left( \|g\| + \sqrt{T C_{G}} \|u\| \right)^{\zeta} \right) \\ \label{eq:estimate_on_h}
        & \leq \sqrt{2} C_{h} \left( \sqrt{T} + T^{\frac{1-\zeta}{2}} \left( \|g\|^{\zeta} + \left(T C_{G} \right)^{\frac{\zeta}{2}} \|u\|^{\zeta} \right) \right).
    \end{align}
   Here we obtain the fourth inequality by using the fact that $\|h\|_{L^{2\zeta}}\leq T^{\frac{1-\zeta}{2\zeta}}\|h\|_{L^{2}},\; h\in L^2$ as a direct consequence of Hölder's inequality (with conjugate exponents $\frac{1}{\zeta}, \frac{1}{1-\zeta}$), while the fifth inequality follows by Minkowski's inequality, the sixth one is a consequence of the estimate \eqref{eq:estimate_on_admissible_G_operator} and the last one follows by sub-additivity of $z \mapsto |z|^{\zeta}, \; z \ge 0$.

    Following \eqref{eq:estimate_on_h}, we have
    \begin{equation} \label{eq:asymptotic_behavior_h_of_Z}
        \norm{h \left( g + \left( \mathbf{G}u\right) \right)} = O(\|u\|^{\zeta}) \quad  \text{as } \norm{u} \to \infty,
    \end{equation}
    so that combining \eqref{eq:asymptotic_behavior_h_of_Z} and \eqref{eq:estimate_on_J_for_coercivity}, we get
    \begin{equation*}
        \mathcal{J}(u) \underset{\norm{u} \to \infty}{\sim} - \frac{\gamma}{2} \norm{u}^{2} \underset{\norm{u} \to \infty}{\longrightarrow} - \infty,
    \end{equation*}
    which yields the desired coercivity.

    Finally, by Lipschitz continuity of $h$ and using the estimate \eqref{eq:estimate_on_admissible_G_operator}, we readily obtain
    \begin{align} \notag
        \norm{h \left( g + \mathbf{G}u \right)} & \le \norm{h \left( g \right)} + \norm{h'}_{\infty} \norm{\mathbf{G}u} \\ \label{eq:interm_coercivity_regularize}
        & \le \norm{h \left( g \right)} + \norm{h'}_{\infty} \sqrt{T C_{G}} \norm{u},
    \end{align}
    so that injecting \eqref{eq:interm_coercivity_regularize} into \eqref{eq:estimate_on_J_for_coercivity}, while noting that $1+\zeta<2$, readily yields
    \begin{equation*}
        \mathcal{J}(u) \underset{\norm{u} \to \infty}{\sim} \left( \norm{h'}_{\infty} \sqrt{T C_{G}} - \frac{\gamma}{2} \right) \norm{u}^{2} \underset{\norm{u} \to \infty}{\longrightarrow} - \infty,
    \end{equation*}
    where the divergence holds thanks to Assumption c).
\end{proof}

\subsection{\texorpdfstring{$-\mathcal{J}$ is sequentially weakly lower semi-continuous}{-J is sequentially weakly lower semi-continuous}} \label{ss:wlsc}

We are now interested in proving the sequential weak lower semi-continuity of $-\mathcal{J}$ on $\mathcal{L}^{2}$, that is, given any sequence $(u^n)_n \in \left(\mathcal{L}^{2}\right)^{\mathbb{N}}$ such that $(u^n)_n$ weakly converges to some $u \in \mathcal{L}^{2}$, denoted by $u^{n} \rightharpoonup u$, we aim to show that 
	\begin{equation*}
    	\liminf_{n\to \infty} (-\mathcal{J}(u^{n})) \ge -\mathcal{J}(u).
    \end{equation*}
This property is established in the next lemma, which requires the probability space $\Omega$ to be countable.

\begin{lemma} \label{lemma_wlsc}
	Suppose that $(\Omega, 2^{\Omega},\mathbb{P})$ is a countable probability space, where $2^{\Omega}$ denotes the power set of $\Omega$. If $h \colon \mathbb{R}\to\mathbb{R}$ is Lipschitz continuous and satisfies the strict sublinearity condition in Definition \ref{def:admissible_impact_function} (ii), then $- \mathcal{J}$ is sequentially weakly lower semi-continuous (denoted hereafter by s.w.l.s-c.).
\end{lemma}

\begin{proof}
    Recall from \eqref{eq:gain_functional_alpha_impact_cost_trade_of} that
    \begin{equation*}
        - \mathcal{J}(u) = - \langle \alpha, u \rangle + \frac{\gamma}{2} \norm{u}^{2} + \langle h \left( Z^{u} \right), u \rangle + \frac{\phi}{2} \norm{X^{u}}^{2} + \frac{\varrho}{2} \E \left| X_{T}^{u} \right|^{2} - X_{0} \E S_T, \quad u \in \mathcal{L}^{2}.
    \end{equation*}
   To complete the proof, it is then sufficient to demonstrate that the first five addends in the right-hand side of the equation above are s.w.l.s-c.

    First, $\norm{\cdot}^{2}$ is convex and (strongly) continuous, hence s.w.l.s-c., and $\langle \alpha, \cdot \rangle$ is weakly continuous. 
    Furthermore,  $u \mapsto X^{u}$ is a linear bounded operator in $\mathcal{L}^2$, hence it is weakly continuous. Since the operator $\norm{\cdot}^{2}$ is s.w.l.s-c., the corresponding penalization term $\frac{\phi}{2} \norm{X^{u}}^{2}$ is s.w.l.s-c. 
      Analogously, the mapping $u\mapsto X^u_T$ is weakly continuous from $\mathcal{L}^2$ to the space of square integrable, $\mathcal{F}_T-$measurable random variables endowed with the usual norm $(\mathbb{E}[|\cdot|^2])^{1/2}$.  It follows that $\frac{\varrho}{2} \E \left| X_{T}^{u} \right|^{2}$ is s.w.l.s-c., as well. In particular, notice that the four operators discussed so far are weakly lower semi-continuous.

    It remains to study the functional $\left\langle h(Z^\cdot), \cdot \right\rangle$. Fix $(u^{n})_n \in \left(\mathcal{L}^{2}\right)^{\mathbb{N}}$ such that $u^{n}\rightharpoonup u\in\mathcal{L}^2$ and consider, for every $n\in\mathbb{N}$,
    \begin{equation*}
        \left| \left\langle h(Z^{u^{n}}),u^{n}\right\rangle-
    	\left\langle h(Z^u),u\right\rangle\right|\le 
    	\left| \left\langle h(Z^{u}),u^{n}-u\right\rangle\right|
    	+ \left| \left\langle h(Z^{u^{n}}) -h(Z^{u}), u^{n} \right\rangle\right|=:\mathbf{\upperRomannumeral{1}}_n + \mathbf{\upperRomannumeral{2}}_n.
    \end{equation*}
    It is clear that $\lim_{n\to\infty}\mathbf{\upperRomannumeral{1}}_n=0$, hence we only have to focus on $\mathbf{\upperRomannumeral{2}}_n$. By hypothesis, the space $\Omega$ is countable and the probability measure $\mathbb{P}$ is defined on the $\sigma$-algebra $2^{\Omega}$. Therefore, for every $\bar{\omega}\in\Omega$ such that $\mathbb{P}(\{\bar{\omega}\})>0$, from the  weak convergence of $u^{n}$ to $u$ in $\mathcal{L}^{2}$ we infer that, while using the tower property of the conditional expectation, Fubini's Theorem and the fact that $u^{n}$ and $u$ are adapted,  
    \begin{align*}
    \int_{0}^{T} u_{t}^{n}(\bar{\omega}) \psi(t) \dd t & = \frac{1}{\mathbb{P}( \{ \bar{\omega}\})} \mathbb{E}\bigg[ \mathbbm{1}_{\{\bar{\omega}\}}(\omega)\int_{0}^{T} u_{t}^{n}(\bar{\omega}) \psi(t)\dd t \bigg] \\
    & = \frac{1}{\mathbb{P}(\{\bar{\omega}\})} \int_{0}^{T} \mathbb{E}\bigg[ \mathbb{E}_t[\mathbbm{1}_{\{\bar{\omega}\}} \psi(t)](\omega) u_{t}^{n}(\bar{\omega})\bigg] \dd t \\ 
    & = \frac{1}{\mathbb{P}(\{\bar{\omega}\})}  \mathbb{E}\bigg[ \int_{0}^{T} \mathbb{E}_t[\mathbbm{1}_{\{\bar{\omega}\}} \psi(t)](\omega) u_{t}^{n}(\bar{\omega}) \dd t \bigg] \\    
    & \underset{n\to\infty}{\longrightarrow}
    \frac{1}{\mathbb{P}( \{ \bar{\omega}\})}\mathbb{E}\bigg[ \mathbbm{1}_{\{\bar{\omega}\}}(\omega)\int_{0}^{T} u_{t}(\omega) \psi(t)\dd t \bigg]
    = \int_{0}^{T} u_{t}(\bar{\omega}) \psi(t)\dd t, \quad \psi \in L^{2}.
    \end{align*}
    Note that, in the previous step, we consider a progressively measurable version of the process $(t,\omega) \mapsto \mathbb{E}_t[\mathbbm{1}_{\{\bar{\omega}\}}](\omega),$ which exists by, e.g.~the optional projection theorem, hence $\mathbb{E}_.[\mathbbm{1}_{\{\bar{\omega}\}} \phi(.)](\omega) \in \mathcal{L}^{2}$ is a proper test function. This demonstrates that $u^{n}(\omega,\cdot)\rightharpoonup u(\omega,\cdot)$ in $L^{2}$ for $\mathbb{P}-$a.e. $\omega\in \Omega$. Moreover, the restriction of $\mathbf{G}$ to the separable Hilbert space $L^{2}$ is a Hilbert-Schmidt operator. Indeed, denoting by $(e_n)_n$ an orthonormal basis of $L^{2}$, by the monotone convergence theorem and Parseval's identity
     \begin{align*}
     	\sum_{n=1}^{\infty} \norm{\mathbf{G}e_n}_{L^{2}}^2 & = \sum_{n=1}^\infty\int_{0}^{T} \left|\left(\mathbf{G}e_n\right)(t)\right|^2 \dd t \\
        & = \sum_{n=1}^\infty \int_{0}^{T}\bigg|\int_{0}^{t}G(t,s) e_n(s)\dd s\bigg|^2 \dd t \\
        & = \int_{0}^{T} \sum_{n=1}^\infty\left|\langle G(t,\cdot), e_n \rangle_{L^{2}} \right|^2\dd t \le T C_{G} < \infty.
     \end{align*}
     As a result, the restriction of $\mathbf{G}$ to $L^2$ is a compact operator, which in particular maps weakly convergent sequences into strongly convergent ones. Combining the two previous observations with the Lipschitz continuity of $h$ we conclude that
      \begin{equation}\label{strong_Gcompact}
     \lim_{n\to\infty}\norm{h(g_{\cdot}(\omega) + \mathbf{G}u_{\cdot}^{n}(\omega))-h(g_{\cdot}(\omega) + \mathbf{G}u_{\cdot}(\omega))}_{L^{2}}=0,\quad \text{for $\mathbb{P}-$a.e. $\omega\in\Omega$}.
     \end{equation}
     By strict sublinearity of $h$, fix $\zeta \in [0,1)$ such that 
     \begin{equation} \label{eq_strict_sub_for_proof}
        |h(x)| \le C' \left( 1+|x|^\zeta \right), \quad x \in \R, 
    \end{equation}
    is satisfied for some constant $C'>0$. Assume for now $\zeta > 0$ and let us show that the sequence 
    \begin{equation*}
        (\norm{h(g + \mathbf{G}u^{n})-h(g + \mathbf{G}u)}_{L^{2}}^2)_{n} \in \mathbb{R}^{\mathbb{N}}
    \end{equation*} 
     is uniformly integrable. To achieve this, it is enough to show that 
    \begin{equation} \label{est_Vitali}
    \sup_{n\in \mathbb{N}}\mathbb{E}\left[\norm{h(g + \mathbf{G}u^{n})-h(g + \mathbf{G}u)}_{L^{2}}^{\frac{2}{\zeta}}\right]<\infty.
    \end{equation}
    Fix $\omega \in \Omega$. Then, denoting by $C'$ some positive constant, independent of $\omega$ and possibly dependent on $T,h,\zeta$, allowed to change from line to line, we have
    \begin{align} \notag
        \norm{h(g(\omega)+\mathbf{G}u^n(\omega))}_{L^2}^{\frac{2}{\zeta}}
         & \le C'\left(\int_0^T \left(1+|g_t(\omega)|^{2\zeta} + |\left(\mathbf{G}u^n\right)_t(\omega)|^{2\zeta}\right)\dd t \right)^{\frac{1}{\zeta}} \\ \notag
         & \le C'\Bigg( T^{\frac{1}{\zeta}} +\left(\int_0^T |g_t(\omega)|^{2\zeta} \dd t\right)^{\frac{1}{\zeta}}
         +
         \left(\int_0^T |\left(\mathbf{G}u^n\right)_t(\omega)|^{2\zeta} \dd t\right)^{\frac{1}{\zeta}}\Bigg) \\ \label{eq:estimate_intermediate_proof_existence_countable}
         & \le 
         C'\left(1+ \norm{g(\omega)}^2_{L^2}+\norm{\left(\mathbf{G}u^n\right)(\omega)}^2_{L^2}\right),\quad n\in \mathbb{N},
    \end{align}
    where in particular, we used \eqref{eq_strict_sub_for_proof} to get the first inequality, while the last one holds by Jensen's inequality, noting that $1/\zeta>1$. Taking the expected value on \eqref{eq:estimate_intermediate_proof_existence_countable}, given that any weakly convergent sequence is bounded i.e., $\sup_{n\in\mathbb{N}}\norm{u^{n}}^2<\infty$ and applying the estimate \eqref{eq:estimate_on_admissible_G_operator}, we conclude that 
    \[
        \sup_{n\in\mathbb{N}}\mathbb{E}\left[
        \norm{h(g+\mathbf{G}u^n)}_{L^2}^{2\frac{1}{\zeta}}
        \right]
        \le 
        C'\left( 1 + \norm{g}^2 + T C_{G} \sup_{n\in\mathbb{N}}\| u ^n\|^2\right)<\infty.
    \]
    An analogous argument demonstrates that $\mathbb{E}\Big[
    \norm{h(g+\mathbf{G}u)}_{L^2}^{\frac{2}{\zeta}}
    \Big]<\infty$, hence \eqref{est_Vitali} holds. 

    Combining \eqref{strong_Gcompact} and \eqref{est_Vitali}, Vitali's convergence theorem yields 
    \begin{equation} \label{eq:h_Z_n_convergence}
        \lim_{n\to\infty}\norm{h(g + \mathbf{G}u^{n})-h(g + \mathbf{G}u)}= 0.
    \end{equation}
    If $\zeta = 0$, then $h$ is bounded and \eqref{eq:h_Z_n_convergence} is immediate by the dominated convergence theorem. Therefore, by the Cauchy-Schwarz inequality,
    \begin{equation*}
        \mathbf{\upperRomannumeral{2}}_n \le \left(\sup_{n\in\mathbb{N}}\norm{u^n}\right)\norm{h(Z^{u^{n}})-h(Z^u)}\underset{n\to \infty}{\longrightarrow}0,
    \end{equation*}
    which proves the desired sequential weak continuity of $\left\langle h(Z^\cdot),\cdot\right\rangle$ and concludes the proof.
\end{proof}

\subsection{Putting everything together} \label{ss:everything_together_existence}

\begin{proof}[Proof of Theorem \ref{T:existence_beyond_monotonicity}]
    Since $\mathcal{L}^{2}$ is a Hilbert space and $-\mathcal{J}$ is coercive and s.w.l.s-c. by Lemma \ref{lemma:coercive}-\ref{lemma_wlsc}, respectively,  an application of \cite[Theorem 1.2, Chapter 1]{Struwe2008} yields the existence of a solution $\hat{u} \in \mathcal{L}^{2}$ satisfying \eqref{eq:optimal_strategy}. Additionally, if we assume  the differentiability of $h$ according to Definition \eqref{def:admissible_impact_function}(i), Fermat's rule for G\^ateaux differentiable functions in Hilbert spaces yields that $\hat{u}$ satisfies the FOC \eqref{eq:nonlinearfredholm}.
\end{proof}


\section{Proof of Proposition \ref{pp:conv_scheme} } \label{ss:proof_conv_scheme}

Recalling the definition of $\tilde{\mathbf{A}}$ in \eqref{eq:Atilde}, the iterates $(u^{[n]})_n$ in \eqref{scheme_update} satisfy, $\left(\dd t \otimes \mathbb{P}\right)-$ a.e.,
    \begin{multline*}
        \gamma u_{t}^{[n]} + \mathbf{A}(u^{[n-1]})_{t} + (\mathbf{G}+
        \mathbf{G}^*)(u^{[n]}-u^{[n-1]})_t
       \\+\mathbf{H}_{\phi,\varrho}u^{[n]}_{t} + \mathbf{H}_{\phi,\varrho}^{*}u^{[n]}_{t} = \alpha_t - X_{0} \left(\phi(T-t)+\varrho\right), \quad n \in \mathbb{N},
    \end{multline*}
    where the kernel $H_{\phi,\varrho}$ is given in \eqref{eq:kernel_H}.
    If we now subtract \eqref{eq:nonlinearfredholm} to the previous equation, and then apply the scalar product of the resulting processes against $u^{[n]}-\hat{u}$, we obtain
    \begin{align*}
        \gamma{\lVert{u^{[n]}-\hat{u}}\rVert}^2= &\left\langle u^{[n]}-\hat{u},\mathbf{A}(\hat{u})-\mathbf{A}(u^{[n-1]})\right\rangle
        -
        \left\langle u^{[n]}-\hat{u},(\mathbf{G}+\mathbf{G}^*)({u}^{[n]}-u^{[n-1]})\right\rangle
        \\ &
        - \left\langle u^{[n]}-\hat{u}, \left(\mathbf{H}_{\phi,\varrho} + \mathbf{H}^\ast_{\phi,\varrho}\right)(u^{[n]}-\hat{u})
        \right\rangle,\quad \mathbb{P}-\text{a.s.}
    \end{align*}
Since, by  hypothesis and  Lemma \ref{thm:conc_conditions}, the operators $\mathbf{G}$ and  $\mathbf{H}_{\phi,\varrho}$ are positive semi-definite,  an application of the Cauchy-Schwarz inequality, \eqref{eq:estimate_on_admissible_G_operator} and \eqref{eq:estimate_on_adjoint}, as well as the triangle inequality with \eqref{eq:def_A_operator}, yields
\begin{align}
&\notag 
\gamma{\lVert{u^{[n]}-\hat{u}}\rVert}  \le 
    {\lVert\mathbf{A}(\hat{u})-\mathbf{A}(u^{[n-1]})\rVert} +2\sqrt{T C_{G}} \lVert\hat{u}-u^{[n-1]}\rVert \\	\notag
    &\qquad  \le {\Big\lVert{h\Big(Z^{\hat{u}}\Big)-h\Big(Z^{u^{[n-1]}}\Big)}\Big\rVert}
        + {\Big\lVert{\mathbf{G}^\ast\Big(h'\Big(Z^{\hat{u}}\Big)\hat{u}-h'\Big(Z^{u^{[n-1]}}\Big)u^{[n-1]}\Big)\Big\rVert}}
        +2\sqrt{T C_{G}} \lVert\hat{u}-u^{[n-1]}\rVert
    \\ \label{eq:conve_proof1}
    &\qquad  =:\mathbf{\upperRomannumeral{1}}_n + \mathbf{\upperRomannumeral{2}}_n
    +
    \mathbf{\upperRomannumeral{3}}_n,\quad n \in \mathbb{N}.
\end{align}
By the Lipschitz continuity of $h$ with constant $\norm{h'}_{\infty}$, recalling the definition \eqref{eq:def_Z} and using the estimate \eqref{eq:estimate_on_admissible_G_operator},
\begin{align*}
\mathbf{\upperRomannumeral{1}}^2_n & \le \norm{h'}_{\infty}^2 \norm{\mathbf{G}(u^{[n-1]}-\hat{u})}
 \le T C_{G} \norm{h'}_{\infty}^2
{\lVert{u^{[n-1]}-\hat{u}}\rVert}^2.
\end{align*}
Next, by the triangle inequality, 
\begin{align*}
    \mathbf{\upperRomannumeral{2}}_n & \leq
    {\Big\lVert{\mathbf{G}^\ast\Big(h'\Big(Z^{u^{[n-1]}}\Big)(\hat{u}-u^{[n-1]})\Big) \Big\rVert}}
    + {\Big\lVert{\mathbf{G}^\ast\Big(\Big(h'\Big(Z^{\hat{u}}\Big)-h'\Big(Z^{u^{[n-1]}}\Big)\Big)\hat{u}\Big) \Big\rVert}} \\
    & =:\mathbf{\upperRomannumeral{2}}_{1,n} + \mathbf{\upperRomannumeral{2}}_{2,n}.
\end{align*} 
Notice that, by boundedness of $h'$ and using the estimate \eqref{eq:estimate_on_adjoint}, we get
\begin{align*}
    \mathbf{\upperRomannumeral{2}}^2_{1,n} \le T C_{G} \norm{h'}_\infty^2 {\lVert{u^{[n-1]}-\hat{u}}\rVert}^2.
\end{align*}
Moreover, letting $L>0$ be the Lipschitz constant of $h'$,  we have
\begin{align*}
    \mathbf{\upperRomannumeral{2}}^2_{2,n} & \le T C_{G} L^2 \norm{\left(\mathbf{G}(\hat{u}-u^{[n-1]})\right) \hat{u}}^{2} \\
    & \le T C_{G}^{2} L^2 \E \bigg[ \int_{0}^{T} \hat{u}_{t}^{2} \dd t \int_{0}^{T} \left(\hat{u}_{s}^{[n-1]} - \hat{u}_{s} \right)^{2} \dd s \bigg]  \le T C_{G}^{2} L^2 M_{\gamma}(\hat{u}) \lVert \hat{u}^{[n-1]} - \hat{u}\rVert^{2},
\end{align*}
where we apply \eqref{eq:estimate_on_adjoint} for the first inequality, Cauchy-Schwarz's inequality as in \eqref{eq:bound_product_term} for the  second, and \eqref{eq:definition_ess_sup} for the last one.

Combining all the above and coming back to \eqref{eq:conve_proof1}, we obtain
\begin{equation*}
    \gamma{\lVert{u^{[n]}-\hat{u}}\rVert} \leq \widetilde{C} {\lVert{u^{[n-1]}-\hat{u}}\rVert},
\end{equation*}
where $\widetilde{C}>0$ is given in \eqref{eq:common_ratio_geometric_sequence}.  Since $\widetilde{C}/\gamma<1$ by \eqref{eq:common_ratio_geometric_sequence}, the previous inequality coincides with \eqref{eq:convergence_rate}, hence 
the proof is complete.

\section{Proofs of Propositions~\ref{pp:stability_with_respect_to_kernel} and \ref{pp:stability_with_respect_to_signals} } \label{s:proofs_stability_results}

\begin{proof}[Proof of Proposition~\ref{pp:stability_with_respect_to_kernel}]
    To start with, we denote by 
    \begin{equation*}
        C_n := \sup_{t\in [0,T]} \int_{0}^{t}\left|G_n(t,s)-G(t,s)\right|^2\dd s, \quad n \in \mathbb{N},
    \end{equation*}
    such that $C_n\to 0$ as $n\to \infty$ by assumption \eqref{eq:condition_stability}. By applying the estimate \eqref{eq:estimate_on_admissible_G_operator}, we readily have
    \begin{equation}\label{estimate_Gnorm}
     	\norm{(\mathbf{G}-\mathbf{G}_n)h}
     	\le \sqrt{TC_n}\norm{h}, \quad h \in \mathcal{L}^{2}.
    \end{equation}
    The required hypotheses enable us to apply Theorem \ref{T:mainnonlinear}, which characterizes the optimal strategies $\hat{u}$ and $\left(\hat{u}_n\right)_{n\in\mathbb{N}}$ as the unique solutions of the nonlinear stochastic Fredholm equation \eqref{eq:nonlinearfredholm}, replacing accordingly $\mathbf{A}$ by $\left(\mathbf{A}_n\right)_{n\in\mathbb{N}}$. Consequently, for every $n \in \mathbb{N}$, $\dd t \otimes \mathbb{P}-$a.e., 
    \begin{equation*}
        \gamma (\left(\hat{u}_{n}\right)_{t}-\hat{u}_t)=\mathbf{A}(\hat{u})(t)-\mathbf{A}_n(\hat{u}_{n})(t)-\left(\mathbf{H}_{\phi,\varrho}\left(\hat{u}_n-\hat{u}\right) \right)_{t}
        - \left(\mathbf{H}^\ast_{\phi,\varrho}\left(\hat{u}_n-\hat{u}\right)\right)_{t}.
    \end{equation*}
    Taking the scalar product in $\mathcal{L}^{2}$ of the previous equation with $\hat{u}_{n}-\hat{u}$ yields
    \begin{equation*}
    	\gamma \norm{\hat{u}_n-\hat{u}}^2
    	= \left\langle\mathbf{A}(\hat{u})-\mathbf{A}_n(\hat{u}_{n}), \hat{u}_{n}-\hat{u}\right\rangle
    	- \left\langle \left(\mathbf{H}_{\phi,\varrho}+\mathbf{H}_{\phi,\varrho}^{\ast}\right) (\hat{u}_{n}-\hat{u}),\hat{u}_{n}-\hat{u} \right\rangle.
    \end{equation*}
    Observing again that $\mathbf{H}_{\phi,\varrho}$ is a positive semi-definite operator in the sense of \eqref{eq:sdp_operator_def} by Lemma \ref{thm:conc_conditions}, recalling also the monotonicity of $\mathbf{A}_n$ in \eqref{eq:definition_monotone} we deduce that 
    \begin{align*}
    	\gamma \norm{\hat{u}_n-\hat{u}}^2
    	& \le \left\langle(\mathbf{A}(\hat{u})-\mathbf{A}_n(\hat{u}))+(\mathbf{A}_n(\hat{u})-\mathbf{A}_n(\hat{u}_{n})), \hat{u}_{n}-\hat{u}\right\rangle
    	\\
        & \le \left\langle\mathbf{A}(\hat{u})-\mathbf{A}_n(\hat{u}), \hat{u}_{n}-\hat{u}\right\rangle \\
        & = \left\langle h(g+\mathbf{G}(\hat{u}))-h(g+\mathbf{G}_{n}(\hat{u})),  \hat{u}_{n}-\hat{u} \right\rangle + \left\langle h'(g+\mathbf{G}(\hat{u}))\hat{u},  \left( \mathbf{G} - \mathbf{G}_{n}\right) \left( \hat{u}_{n}-\hat{u} \right)\right\rangle \\
        & \quad + \left\langle \left(h'(g+\mathbf{G}(\hat{u}))-h'(g+\mathbf{G}_n(\hat{u}))\right) \hat{u}, \mathbf{G}_n(\hat{u}_n-\hat{u}) \right\rangle,
    \end{align*}
    where the last equality follows from the definitions of the operators $(\mathbf{A}_n)_n$ and $\mathbf{A}$ in \eqref{eq:def_A_operator} and an application of Fubini.
    Now, we have by the Cauchy-Schwarz inequality
    \begin{align} \notag 
        \gamma \norm{\hat{u}_n-\hat{u}}^2
    	& \le \norm{h(g+\mathbf{G}(\hat{u}))-h(g+\mathbf{G}_{n}(\hat{u}))}\norm{\hat{u}_n-\hat{u}} \\ \notag
        & \quad + \norm{h'(g+\mathbf{G}(\hat{u}))\hat{u}}\norm{\left( \mathbf{G} - \mathbf{G}_{n}\right) \left( \hat{u}_{n}-\hat{u} \right)} \\ \notag
        & \quad + \left\langle
    	\left(h'(g+\mathbf{G}(\hat{u}))-h'(g+\mathbf{G}_n(\hat{u}))\right) \hat{u}, \mathbf{G}_n(\hat{u}_n-\hat{u}) \right\rangle \\ \label{est_proof_stability}
        &=: \mathbf{\upperRomannumeral{1}}_n + \mathbf{\upperRomannumeral{2}}_n + \mathbf{\upperRomannumeral{3}}_n.
    \end{align}
    Using the fact that $h$ is Lipschitz continuous with constant $\norm{h'}_\infty$ and the estimate \eqref{estimate_Gnorm}, we have
    \begin{equation} \label{est_1}
        \mathbf{\mathbf{\upperRomannumeral{1}}}_n \le \norm{h'}_\infty \norm{(\mathbf{G}-\mathbf{G}_n)(\hat{u})} \norm{\hat{u}_n-\hat{u}} \le \norm{h'}_\infty \sqrt{TC_n}
        \norm{\hat{u}} \norm{\hat{u}_n-\hat{u}}.
    \end{equation}
    As for $\mathbf{\mathbf{\upperRomannumeral{2}}}_n$ in \eqref{est_proof_stability}, by boundedness of $h'$, it is immediate to deduce from \eqref{estimate_Gnorm} that 
    \begin{equation} \label{est_2}
    	\mathbf{\upperRomannumeral{2}}_n \le \norm{h'}_\infty \sqrt{TC_n} \norm{\hat{u}}\norm{\hat{u}_n-\hat{u}}.
    \end{equation}
    Finally, applying Hölder's inequality, the Lipschitz continuity of $h'$ and using again the estimate \eqref{estimate_Gnorm}, we get
    \begin{align*}
        \mathbf{\upperRomannumeral{3}}_n & = \left\langle
    	\left(h'(g+\mathbf{G}(\hat{u}))-h'(g+\mathbf{G}_n(\hat{u}))\right) \hat{u}, \left(\mathbf{G}_n-\mathbf{G}\right)(\hat{u}_n-\hat{u})
    	\right\rangle \\
        & \quad + \left\langle
    	\left(h'(g+\mathbf{G}(\hat{u}))-h'(g+\mathbf{G}_n(\hat{u}))\right) \hat{u}, \mathbf{G}(\hat{u}_n-\hat{u})
    	\right\rangle \\
        & =: \mathbf{\upperRomannumeral{3}}_{1,n} + \mathbf{\upperRomannumeral{3}}_{2,n}
    \end{align*}
    Observe that
    \begin{equation} \label{estimate:rough}
    	\norm{\left(h'(g+\mathbf{G}(\hat{u}))-h'(g+\mathbf{G}_n(\hat{u}))\right) \hat{u}} \le \sqrt{2}\norm{h'}_\infty\norm{\hat{u}}.
    \end{equation}
    Then, by the Cauchy--Schwarz inequality and using the estimates \eqref{estimate_Gnorm} and \eqref{estimate:rough}, we obtain
    \begin{equation} \label{est_3_1}
    	\mathbf{\mathbf{\upperRomannumeral{3}}}_{1,n} \le \sqrt{2TC_n} \norm{h'}_\infty \norm{\hat{u}} \norm{\hat{u}_{n}-\hat{u}}.
    \end{equation}
    Furthermore, since $G$ is admissible according to Definition \ref{def:admissible_kernel}, by the Cauchy-Schwarz inequality, \eqref{eq:estimate_on_admissible_G_operator} and \eqref{estimate:rough} we infer that 
    \begin{align} \label{eq:est_to_be_refined}
    	\mathbf{\mathbf{\upperRomannumeral{3}}}_{2,n} & \le \sqrt{TC_{G}} \norm{\left(h'(g+\mathbf{G}(\hat{u}))-h'(g+\mathbf{G}_n(\hat{u}))\right) \hat{u}} \norm{\hat{u}_{n}-\hat{u}} \\ \label{est_3_2_rough}
        & \le \sqrt{2T C_{G}} \norm{h'}_\infty \norm{\hat{u}} \norm{\hat{u}_{n}-\hat{u}}.
    \end{align}
    Combining all the above estimates \eqref{est_1}--\eqref{est_2}--\eqref{est_3_1}--\eqref{est_3_2_rough} into \eqref{est_proof_stability}, we eventually obtain
    \begin{equation} \label{eq:rough_estimate_norm_diff}
        \norm{\hat{u}_n-\hat{u}} \le \frac{\sqrt{2T} \norm{h'}_\infty \norm{\hat{u}}}{\gamma} \left( \sqrt{C_n} \left( 1 + \sqrt{2} \right) + \sqrt{C_{G}} \right) < \infty,
    \end{equation}
    hence the sequence $(\hat{u}_n)_n$ is bounded in $\mathcal{L}^{2}$, which is a necessary but not sufficient condition to ensure $\norm{\hat{u}_n-\hat{u}} \underset{n \to \infty}{\longrightarrow} 0$.
    To achieve such convergence, first notice that, by the Cauchy-Schwarz inequality,  
    \begin{align} \notag
        \norm{\left( \left( \mathbf{G} - \mathbf{G}_{n} \right) \hat{u} \right) \hat{u}}^{2} & = \E \bigg[ \int_{0}^{T} \left( \int_{0}^{t} \left( G(t,s) - G_{n}(t,s) \right) \hat{u}_{s} \dd s \right)^{2} \hat{u}_{t}^{2} \dd t \bigg] \\ \notag
        & \leq \E \bigg[ \int_{0}^{T} \left( \int_{0}^{t} \left| G(t,s) - G_{n}(t,s) \right|^{2} \dd s \int_{0}^{t} \hat{u}_{s}^{2} \dd s \right) \hat{u}_{t}^{2} \dd t \bigg] \\ \label{eq:bound_product_term}
        & \le C_{n} \mathbb{E} \bigg[ \bigg(\int_{0}^{T} \hat{u}_{t}^{2} \dd t \bigg)^{2} \bigg].
    \end{align}
  We now refine the estimate \eqref{eq:est_to_be_refined}. Leveraging the Lipschitz continuity of $h'$ with constant $L>0$ instead of using the rough estimate \eqref{estimate:rough}, it readily follows from  \eqref{eq:bound_product_term} that 
    \begin{align} \notag
        \mathbf{\mathbf{\upperRomannumeral{3}}}_{2,n} & \le L \sqrt{T C_{G}} \norm{\left( \left( \mathbf{G} - \mathbf{G}_{n} \right) \hat{u} \right) \hat{u}} \norm{\hat{u}_{n}-\hat{u}} \\ \label{est_3_2_refined}
        & \le L \sqrt{T C_{G} C_{n} \mathbb{E} \bigg[ \bigg(\int_{0}^{T} \hat{u}_{t}^{2} \dd t \bigg)^{2} \bigg]} \norm{\hat{u}_{n}-\hat{u}}.
    \end{align}
    Then, using \eqref{est_3_2_refined} instead of \eqref{est_3_2_rough} for $\mathbf{\mathbf{\upperRomannumeral{3}}}_{2,n}$, \eqref{eq:rough_estimate_norm_diff} becomes 
    \begin{equation*}
        \norm{\hat{u}_n-\hat{u}} \le \frac{\sqrt{2TC_{n}} \norm{h'}_\infty \norm{\hat{u}}}{\gamma} \Bigg( 1 + \sqrt{2} + L \sqrt{ \frac{1}{2} C_{G} \mathbb{E} \bigg[ \bigg(\int_{0}^{T} \hat{u}_{t}^{2} \dd t \bigg)^{2} \bigg]} \Bigg) \underset{n \to \infty}{\longrightarrow} 0,
    \end{equation*}
    where the convergence holds due to the assumption \eqref{eq:assumption_on_optimal_strategy_for_stability}, concluding the proof.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{pp:stability_with_respect_to_kernel}]
    By definition of the gain functional in \eqref{eq:gain_functional}, the Cauchy-Schwarz inequality, and the Lipschitz continuity of $h$, there is a constant $C'>0$ such that 
    \begin{equation}\begin{aligned}\label{eq:J_n-J}
        \big|\mathcal{J}_n(u)-\mathcal{J}(u)\big|&=\langle\alpha_n-\alpha,u\rangle+\langle h(g+\mathbf{G}u)-h(g_n+\mathbf{G}u)\alpha,u\rangle\\
        &\leq \|\alpha_n-\alpha\|\|u\|+C'\|g-g_n\|\|u\|.
    \end{aligned}\end{equation}
    Next, due to the convergence assumption, $(\alpha_n)_n$ and $(g_n)_n$ are bounded  in $\mathcal{L}^2$, that is,
    $$ \sup_n \|\alpha_n\|<\infty, \quad  \sup_n \|g_n\|<\infty.$$
    Therefore, it follows from \eqref{eq:estimate_on_J_for_coercivity} and \eqref{eq:estimate_on_h} with $\alpha$ and $g$ replaced by $\alpha_n$ and $g_n$, that there is a constant $M>0$ such that 
    $$
    \sup_{u\in\mathcal{L}^2}\mathcal{J}(u)=\sup_{\substack{u\in\mathcal{L}^2\\\|u\|\leq M}}\mathcal{J}(u),\quad \sup_{u\in\mathcal{L}^2}\mathcal{J}_n(u)=\sup_{\substack{u\in\mathcal{L}^2\\\|u\|\leq M}}\mathcal{J}_n(u),\quad\text{for all }n\in\mathbb{N}.
    $$
    Hence, \eqref{eq:J_n-J} implies that 
    \begin{align*}
        \Big|\sup_{u\in\mathcal{L}^2}\mathcal{J}_n(u)-\sup_{u\in\mathcal{L}^2}\mathcal{J}(u)\Big| & = \Big|\sup_{\substack{u\in\mathcal{L}^2 \\|u\|\leq M}}\mathcal{J}_n(u)-\sup_{\substack{u\in\mathcal{L}^2\\\|u\|\leq M}}\mathcal{J}(u)\Big|\\
        & \leq \sup_{\substack{u\in\mathcal{L}^2\\\|u\|\leq M}}\Big|\mathcal{J}_n(u)-\mathcal{J}(u)\Big|\\
        &\leq  M\big(\|\alpha_n-\alpha\|+C''\|g-g_n\|\big)\underset{n\to\infty}{\longrightarrow}0,
    \end{align*}
    which completes the proof.
\end{proof}

\section{Proof of Theorem \ref{T:existence_uniqueness_beyond_monotonicity} } \label{s:proof_existence_uniqueness_beyond_monotonicity}

 In the following lemma, we establish an \emph{a priori} estimate on the $L^2$-norm of any solution to \eqref{eq:nonlinearfredholm}, which will enable us to deduce properties of a solution to \eqref{eq:nonlinearfredholm} from the signals $\alpha$ and $g$.

\begin{lemma} \label{a_priori_lemma}
Suppose that 
\begin{equation*}
    C_{G}^{\ast} := \sup_{t \in [0,T]} \int_{t}^{T} \left| G(s,t) \right|^{2} \dd s < \infty.
\end{equation*}
Let $h\colon\mathbb{R}\to\mathbb{R}$ be differentiable with bounded derivative $h'$, and  assume that the following bound holds:
\begin{equation}\label{a_priori_precise}
    \gamma > 2\sqrt{T} \max \left\{\widetilde{C}_{H,G}, \; \sqrt{C_{H}} + \frac{1}{2}\norm{h'}_{\infty}
    \left(\sqrt{C_{G}} + \sqrt{T C_{G}^{\ast}}
     \left( \gamma - 2\sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \widetilde{C}_{H,G}
    \right) \right\},
\end{equation}
with
\begin{equation} \label{eq:def_c_h_k_constant}
    \widetilde{C}_{H,G} := \sqrt{C_{H}} + \norm{h'}_\infty \sqrt{C_{G}},
\end{equation}
where the constants $C_{H},\,C_{G}$ associated with the admissible kernels $H_{\phi,\varrho}, \; G$, respectively, are defined in \eqref{eq:constant_norm_of_G}.
Then a solution $\hat{u}\in\mathcal{L}^2$ of \eqref{eq:nonlinearfredholm} satisfies $\mathbb{P}-$a.s. the a priori estimate
\begin{align} \notag
    \norm{\hat{u}}_{L^2} \le \frac{1}{\widetilde{C}_\gamma}
    \Bigg( & \norm{\tilde \alpha}_{L^2} + \norm{h(g)}_{L^2} + \norm{h'}_\infty \sqrt{C_{G}^{\ast}} \left( \gamma - 2 \sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \\ \label{est_apriori}
    & \times \bigg( \bigg(\int_{0}^{T}\mathbb{E}_t\Big[ \norm{\tilde \alpha}_{L^2}^2 \Big]\dd t \bigg)^{\frac{1}{2}} + \bigg( \int_{0}^{T}\mathbb{E}_t\Big[ \norm{h(g)}_{L^2}^2 \Big]\dd t \bigg)^{\frac{1}{2}} \bigg) \Bigg),
\end{align}
where 
\begin{equation} \label{eq:effective_signal_with_soft_penalization}
    \tilde \alpha_v := \alpha_v - X_{0} \left( \phi(T-v) + \varrho \right), \quad v \in [0,T],
\end{equation}
and
\begin{equation} \label{constant_Ctilde}
    \widetilde{C}_\gamma := \gamma - \sqrt{T} \left( 2\sqrt{C_{H}} + \norm{h'}_{\infty} \left( \sqrt{C_{G}} + \sqrt{T C_{G}^{\ast}} \left( \gamma - 2 \sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \widetilde{C}_{H,G} \right) \right).
\end{equation}
\end{lemma}

\begin{proof}
    Fix a solution $\hat{u} \in \mathcal{L}^{2}$ to the nonlinear Fredholm equation \eqref{eq:nonlinearfredholm}. Note that \eqref{eq:nonlinearfredholm} re-writes as
    \begin{equation*}
        \gamma \hat{u}_v = \tilde \alpha_v - \left(\mathbf A(\hat{u})\right)_{v} - \left( \mathbf{H}_{\phi,\varrho}\hat{u} \right)_{v}
        - \left( \mathbf{H}_{\phi,\varrho}^{*}\hat{u} \right)_{v} \quad \left( \dd t \otimes \mathbb{P} \right)-a.e.,
    \end{equation*}
    where $\tilde \alpha$ is given by \eqref{eq:effective_signal_with_soft_penalization}, so that applying the absolute value together with the triangular inequality yields
    \begin{equation} \label{eq:estimate_by_abs_value}
        \gamma \left|\hat{u}_v\right| \le \left|\tilde \alpha_v \right| + \left|\left(\mathbf A(\hat{u})\right)_{v}\right| + \left( \mathbf{H}_{\phi,\varrho}|\hat{u}| \right)_{v}
        + \left( \mathbf{H}_{\phi,\varrho}^{*}|\hat{u}| \right)_{v} \quad \left( \dd t \otimes \mathbb{P} \right)-a.e.
    \end{equation}
    By boundedness of $h'$, $h$ is Lipschitz continuous with constant $\norm{h'}_{\infty}$ satisfying
    \begin{equation} \label{eq:lipschitz_continuity_h}
        \left| h \left( g + \mathbf{G}u \right) \right| \le \left| h \left( g \right) \right| + \norm{h'}_{\infty} \left| \mathbf{G}u \right|,
    \end{equation}
    such that using the definition of $\mathbf{A}$ from \eqref{eq:def_A_operator}, we readily get
    \begin{equation} \label{eq:estimate_on_A_lipschitz}
        \left|\left(\mathbf A(\hat{u})\right)_{v}\right| \le \left|h\left( g_{v} \right)\right| + \norm{h'}_{\infty} \left( \left(\mathbf{G} |\hat{u}| \right)_{v} + \left(\mathbf{G}^{\ast} |\hat{u}| \right)_{v} \right) \quad \left( \dd t \otimes \mathbb{P} \right)-a.e.
    \end{equation}
    Now, combining \eqref{eq:estimate_by_abs_value} and \eqref{eq:estimate_on_A_lipschitz} yields
    \begin{align} \notag
        \gamma \left|\hat{u}_v\right| \le & \left|\tilde \alpha_v\right| + \left|h\left( g_{v} \right)\right| + \norm{h'}_{\infty} \left( \left(\mathbf{G} |\hat{u}| \right)_{v} + \left(\mathbf{G}^{\ast} |\hat{u}| \right)_{v} \right) \\ \label{eq:estimate_before_massacre}
        & + \left( \mathbf{H}_{\phi,\varrho}|\hat{u}| \right)_{v}
        + \left( \mathbf{H}_{\phi,\varrho}^{*}|\hat{u}| \right)_{v} \quad \left( \dd t \otimes \mathbb{P} \right)-a.e.
    \end{align}
   Fix $t \in [0,T]$ and define 
    \begin{equation*}
        m_{v}^{(t)} := \mathbbm{1}_{\{v>t\}}\mathbb{E}_t{[|\hat{u}_v|]},\quad v\in[0,T].
    \end{equation*}
    Then, taking the conditional expectation $\mathbbm{1}_{\{v>t\}} \mathbb{E}_t[\cdot]$ on the last estimate \eqref{eq:estimate_before_massacre} gives, thanks to the tower property,
    \begin{align} \notag
        \gamma m_{v}^{(t)} \le \; & Y_{v}^{(t)} + \mathbbm{1}_{\{v>t\}} \left(\left(\norm{h'}_{\infty} \mathbf{G}^{(t)} + \mathbf{H}^{(t)}_{\phi,\rho} \right) m^{(t)}\right)_{v} \\ \label{eq_estimate_intermediary_m_t}
        & + \left(\left( \norm{h'}_{\infty} \left(\mathbf{G}^{(t)}\right)^{\ast} + \left(\mathbf{H}^{(t)}_{\phi,\rho}\right)^{\ast} \right) m^{(t)}\right)_{v}, \quad \left( \dd t \otimes \mathbb{P} \right)-a.e.
    \end{align}
    Here $\mathbf{G}^{(t)}$ (resp.~$\mathbf{H}^{(t)}_{\phi,\rho}$) is the linear integral $\mathcal{L}^2-$operator associated with the kernel 
    $$G^{(t)}(v,s) := \mathbbm{1}_{\{s>t\}}G(v,s)\quad  \text{(resp.~$H^{(t)}_{\phi,\rho}(v,s) := \mathbbm{1}_{\{s>t\}}H_{\phi,\rho}(v,s)$)},$$ for $s,v\in [0,T]$, and $Y^{(t)}=(Y^{(t)}_v)_{v\ge0}\in \mathcal{L}^2$ is the auxiliary process defined by 
    \begin{align} \notag
        Y^{(t)}_v := \mathbbm{1}_{\{v>t\}} \Big( & \mathbb{E}_t[|\tilde \alpha_v|]+\mathbb{E}_t[|h(g_v)|] + \int_{0}^{t} H_{\phi,\rho}(v,s)|\hat{u}_s|\dd s \\ \label{def:aux_Y}
        & + \norm{h'}_\infty \int_{0}^{t} G(v,s)|\hat{u}_s|\dd s
        \Big),\quad v\in [0,T].
    \end{align}
    Taking the $L^2([0,T])-$norm in the previous estimate \eqref{eq_estimate_intermediary_m_t}, similarly to  \eqref{eq:estimate_on_admissible_G_operator} and \eqref{eq:dual_operator_def},
    \begin{equation*}
        \gamma\lVert{m^{(t)}}\rVert_{L^2}\le \lVert{Y^{(t)}}\rVert_{L^2} + 
        2 \sqrt{T} \widetilde{C}_{H,G} \lVert{m^{(t)}}\rVert_{L^2}, \quad \mathbb{P}-\text{a.s.},
    \end{equation*}
    where $\widetilde{C}_{H,G}$ is given by \eqref{eq:def_c_h_k_constant}. Considering also the joint measurability in $[0,T] \times \Omega$ of the processes $(t,\omega) \mapsto \norm{m^{(t)}(\omega)}_{L^2}$ and $(t,\omega) \mapsto \norm{Y^{(t)}(\omega)}_{L^2}$, it follows from assumption \eqref{a_priori_precise} that
    \begin{equation}\label{est_mt}
        \lVert{m^{(t)}}\rVert_{L^2} \le \left(\gamma-2\sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \lVert{Y^{(t)}}\rVert_{L^2}, \quad \text{for a.e. }t\in [0,T], \quad \mathbb{P}-\text{a.s.}
    \end{equation}
    Furthermore, from \eqref{def:aux_Y} we compute, also employing conditional Jensen's and Jensen's inequalities
    \begin{equation} \label{eq:estimate_on_Y}
        \lVert{Y^{(t)}}\rVert_{L^2} \le \left( \mathbb{E}_t \left[ \norm{\tilde \alpha}_{L^2}^2 \right] \right)^{\frac{1}{2}} + \left( \mathbb{E}_t \left[ \norm{h(g)}_{L^2}^2 \right] \right)^{\frac{1}{2}} + \sqrt{T} \widetilde{C}_{H,G} \norm{\hat{u}}_{L^2} \quad \left(\dd t\otimes \mathbb{P}\right)-\text{a.e.}
    \end{equation}
    In particular, injecting the estimate \eqref{eq:estimate_on_Y} into \eqref{est_mt}, together with the triangular inequality yields
    \begin{align} \notag
        \left(\int_{0}^{T} \lVert{m^{(t)}}\rVert_{L^2}^2\dd t \right)^{\frac{1}{2}} \le & \left(\gamma-2\sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \Bigg( \left( \int_{0}^{T}\mathbb{E}_t \Big[ \norm{\tilde \alpha}_{L^2}^2 \Big]\dd t \right)^{\frac{1}{2}} \\ \label{eq:estimate_integral_m_t}
        & + \left( \int_{0}^{T}\mathbb{E}_t\Big[ \norm{h(g)}_{L^2}^2 \Big]\dd t \right)^{\frac{1}{2}} + T \widetilde{C}_{H,G} \norm{\hat{u}}_{L^2} \Bigg).
    \end{align}
    Furthermore, by the estimate \eqref{eq:lipschitz_continuity_h} and the Cauchy--Schwarz inequality, from \eqref{eq:def_A_operator} we obtain $\mathbb{P}$ almost surely the following estimate:
    \begin{equation} \label{eq:estimate_on_A_L_2_norm}	
        \norm{\mathbf A (\hat{u})}_{L^2} \le \norm{h(g)}_{L^2} + \sqrt{T C_{G}}\norm{h'}_\infty \norm{\hat{u}}_{L^2} + \norm{h'}_\infty \sqrt{C_{G}^{\ast}} \left( \int_{0}^{T} \lVert{m^{(t)}}\rVert^2_{L^2} \dd t \right)^{\frac{1}{2}}.
    \end{equation}
    Starting from \eqref{eq:nonlinearfredholm}, taking the $L^2$-norm, injecting \eqref{eq:estimate_on_A_L_2_norm} and then \eqref{eq:estimate_integral_m_t} yields successively
    \begin{align*}
        \gamma \norm{\hat{u}}_{L^2} & \le \norm{\tilde \alpha}_{L^2} + \norm{\mathbf A (\hat{u})}_{L^2} + 2 \sqrt{T C_{H}} \norm{\hat{u}}_{L^2} \\
        & \le \norm{\tilde \alpha}_{L^2} + \norm{h(g)}_{L^2} + \sqrt{T} \left( 2\sqrt{C_{H}} + \norm{h'}_{\infty} \sqrt{C_{G}} \right) \norm{\hat{u}}_{L^2} \\
        & \quad + \norm{h'}_\infty\sqrt{C_{G}^{\ast}}	\bigg(\int_{0}^{T} \lVert{m^{(t)}}\rVert_{L^2}^2\dd t\bigg)^{\frac{1}{2}} \\ 
        & \le \norm{\tilde \alpha}_{L^2} + \norm{h(g)}_{L^2} + \norm{h'}_\infty \sqrt{C_{G}^{\ast}} \left( \gamma - 2 \sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \\ 
        & \quad \times \bigg( \bigg(\int_{0}^{T}\mathbb{E}_t\Big[ \norm{\tilde \alpha}_{L^2}^2 \Big]\dd t \bigg)^{\frac{1}{2}} + \bigg( \int_{0}^{T}\mathbb{E}_t\Big[ \norm{h(g)}_{L^2}^2 \Big]\dd t \bigg)^{\frac{1}{2}} \bigg) \\
        & \quad + \sqrt{T} \bigg( 2\sqrt{C_{H}} + \norm{h'}_{\infty} \Big( \sqrt{C_{G}} + \sqrt{T C_{G}^{\ast}} \left( \gamma - 2 \sqrt{T} \widetilde{C}_{H,G} \right)^{-1} \widetilde{C}_{H,G} \Big) \bigg) \norm{\hat{u}}_{L^2},
    \end{align*}
    which holds $\mathbb{P}-$a.s. By \eqref{a_priori_precise} and \eqref{constant_Ctilde}, this inequality gives the desired a priori estimate \eqref{est_apriori}, completing the proof.
\end{proof}

Thanks to Lemma \ref{a_priori_lemma}, the following corollary is immediate.
\begin{corollary} \label{cor_Linfinity}
    Under the hypotheses of Lemma \ref{a_priori_lemma}, if $\alpha,\,g\in\mathcal{L}^{\infty} ( \Omega, L^{2}([0,T]))$, that is,
    \begin{equation*}
        \esssup_{\omega\in\Omega}\norm{\alpha(\omega)}_{L^2}<\infty \quad \text{ and }\quad  \esssup_{\omega\in\Omega}\norm{g(\omega)}_{L^2}<\infty,
    \end{equation*}
    then any solution of \eqref{eq:nonlinearfredholm} belongs to the space $ \mathcal{L}^\infty(\Omega;L^2([0,T]))$. 
\end{corollary}

\begin{proof}[Proof of Theorem \ref{T:existence_uniqueness_beyond_monotonicity}]
    Theorem \ref{T:existence_beyond_monotonicity} ensures the existence of an optimal trading strategy $\hat{u}\in\mathcal{L}^2$ that satisfies the nonlinear stochastic Fredholm equation \eqref{eq:nonlinearfredholm}.
    For every  $\gamma$ sufficiently large, following the a priori estimate \eqref{est_apriori} in Lemma \ref{a_priori_lemma}, and an application of Corollary \ref{cor_Linfinity} under assumption \eqref{eq:alpha_infinity}, any solution of \eqref{eq:nonlinearfredholm} belongs to $\mathcal{L}^{\infty} \left( \Omega, L^{2}([0,T]) \right)$ and satisfies \eqref{eq:common_ratio_geometric_sequence}. Hence, Proposition \ref{pp:conv_scheme} applies and guarantees the convergence of the iterative scheme \eqref{scheme_initialization}-\eqref{scheme_update} to $\hat{u}$, which is then unique solution in $\mathcal{L}^2$. This completes the proof.
\end{proof}

