%  \mathrm{F'}_{1} &= \left[\begin{array}{l}\mathrm{F}_{1} \\ \mathrm{E}_{2}\end{array}\right], & \mathrm{F'}_{1} & \in \mathbb{R}^{4C  \times \frac{A}{4} \times \frac{L}{4}} \\
%  \mathrm{B'}_{1} &= \left[\begin{array}{l}\mathrm{B}_{1} \\ \mathrm{E}_{2}\end{array}\right], & \mathrm{B'}_{1} & \in \mathbb{R}^{4C \times \frac{A}{4} \times \frac{L}{4}} \\
