\begin{figure}[h!]
\centering
\includegraphics[width=\columnwidth]{figures/new/GLE74a.png}
\caption{Count rate variation of selected NMs during GLE 74. The vertical dashed black line depicts the 0\% level. De-trended 5-min averaged data are used.} 
\label{fig:NM}
\end{figure}
