\citet{eyster_rabin_2005} introduce their cursed equilibrium as a modification of the Bayesian Nash equilibrium that accounts for players' incapacity to correctly investigate the correlation between the other players' types and their strategies.
We slightly adjust their definition in order to allow for infinite type spaces, and adopt it to our model.

\begin{definition} \label{def:cursed_equilibrium}
    Let  $\Gamma = \left( N, \left(A_k\right)_{k\in N}, \left(\Theta_k\right)_{k\in N}, \left(u_k\right)_{k \in N}, \Prob \right)$ be a Bayesian game as specified above.
    For player $k$, the \emph{average strategy} of the other players, given their own type $\theta_k$ and probability distribution $\Prob$, is
    \begin{align}
        \bar{\sigma}_{-k}\left(a_{-k} \mid \theta_k, \Prob\right) \colonequals \int_{\Theta_{-k}} \sigma_{-k}\left(a_{-k} \mid \theta_{-k}\right) \; \d\Prob\left(\theta_{-k} \mid \theta_k \right). \label{eq:average_strategy}
    \end{align}
    For a strategy profile $\sigma_{-k}$ of $k$'s opponents, $\sigma_k$ is a \emph{(fully) cursed best response} against $\sigma_{-k}$ if for each $\theta_k \in \Theta_k$, and each $a_k^*$ such that $\sigma_k\left(a_k^* \mid \theta_k\right)>0$,
    \begin{align}
        a_k^* &\in \argmax_{a_k \in A_k} v_k\left(a_k\mid \theta_k, \sigma_{-k}\right), \text{ where} \nonumber \\
        v_k\left(a_k\mid \theta_k, \sigma_{-k}\right) &\colonequals \int_{\Theta_{-k}}
        \sum_{a_{-k} \in A_{-k}} \bar{\sigma}_{-k}\left(a_{-k}\mid \theta_k, \Prob\right) 
        u_k\left(a_k, a_{-k} ; \theta_k, \theta_{-k}\right) \d\Prob\left(\theta_{-k} \mid \theta_k\right)\label{eq:definition_v}
    \end{align}
    is the \emph{perceived interim expected utility} of action $a_k$, given the own type $\theta_k$ and the opponents' strategy profile $\sigma_{-k}$.
    A strategy profile $\sigma^*$ is a \emph{(fully) cursed equilibrium} if for each $k\in N$, $\sigma^*_k$ is a (fully) cursed best response against $\sigma^*_{-k}$.
\end{definition}

\noindent As \citet{eyster_rabin_2005} point out, a cursed player mistakenly believes that their opponents play the mixed strategy profile $\bar \sigma_{-k}$ independent of their types $\theta_{-k}$, when in fact they play the strategy profile $\sigma_{-k}$ which does depend on their type.
Such a player then optimally responds to this strategy, choosing their action $a_k$ as to maximize $v_k\left(a_k\mid \theta_k, \sigma_{-k}\right)$.
In contrast, in a (interim) Bayesian Nash equilibrium\footnote{
    Interim and ex-ante equilibria in Bayesian games are equivalent if the type distribution has full support.
    In this work, we solely focus on the interim interpretation of Bayesian games, as this is the ``language'' in which the cursed equilibrium has been formulated.
}, 
each player maximizes their actual \emph{interim expected utility} 
\begin{align}
    w_k\left(a_k\mid \theta_k, \sigma_{-k}\right) &\colonequals \int_{\Theta_{-k}} \sum_{a_{-k} \in A_{-k}} \sigma_{-k}\left(a_{-k} \mid \theta_{-k}\right) u_k\left(a_k, a_{-k} ; \theta_k, \theta_{-k}\right) \; \d\Prob\left(\theta_{-k}\mid\theta_k \right).\label{eq:definition_w}
\end{align}

\noindent \citet{eyster_rabin_2005} also define the concept of partial cursedness, in which players optimally respond to a convex combination of the opponent's actual strategy and the average one.
In this work, we will solely focus on the fully cursed equilibrium\footnote{
    Complementary results on partial equilibria can be found in Appendix \ref{app:Partial_Cursedness}.
}
and will therefore drop the word ``fully''.

We shall now go on by generalizing the model to games in which the probability distribution $\Prob$ is not known.
To this end, let $\Gamma = \left( N, \left(A_k\right)_{k\in N}, \left(\Theta_k\right)_{k\in N}, \left(u_k\right)_{k \in N}, \mathcal{P} \right)$ be an \emph{incomplete information game with imprecise probabilistic information}.
The components of such a game are identical to the ones of the Bayesian game as specified above, except for the fact that there is a nonempty \emph{ambiguity set} $\mathcal{P}$ of probability distributions over $\Theta$ instead of a single distribution $\Prob$.

\begin{definition} \label{def:knight_nash_equilibrium}
    Let $\Gamma = \left( N, \left(A_k\right)_{k\in N}, \left(\Theta_k\right)_{k\in N}, \left(u_k\right)_{k \in N}, \mathcal{P} \right)$ be an incomplete information game with imprecise probabilistic information.
    For a strategy profile $\sigma_{-k}$ of  player $k$'s opponents, $\sigma_k$ is a \emph{maxmin best response} against $\sigma_{-k}$ if for each $\theta_k \in \Theta_k$, and each $a_k^*$ such that $\sigma_k\left(a_k^* \mid \theta_k\right)>0$,
    \begin{align*}
        a_k^* &\in \argmax_{a_k \in A_k} \ubar w_k\left(a_k\mid \theta_k, \sigma_{-k}\right),\text{ where} \\
        \ubar w_k\left(a_k\mid \theta_k, \sigma_{-k}\right) &\colonequals \inf_{\Prob \in \mathcal{P}} \int_{\Theta_{-k}} \sum_{a_{-k} \in A_{-k}} \sigma_{-k}\left(a_{-k} \mid \theta_{-k}\right) u_i\left(a_k, a_{-k} ; \theta_k, \theta_{-k}\right) \d\Prob\left(\theta_{-k}\mid\theta_k\right)
    \end{align*}
    is the \emph{infimal interim expected utility} of action $a_k$, given the own type $\theta_k$ and the opponents' strategy profile $\sigma_{-k}$.
    A strategy profile $\sigma^*$ is a \emph{Knight-Nash equilibrium} if for each $k\in N$, $\sigma_k^*$ is a maxmin best response against $\sigma_{-k}^*$.\footnote{
        Definition \ref{def:knight_nash_equilibrium} resembles Definition 8 in \citet{decerf_riedel_2020}.
        Their definition requires optimality in the ex-ante stage, in which a player does not yet know their own type, and has to take expectations over their type as well.
        In this work, we focus on the interim stage.
        It is straightforward to show that in the framework of this paper, every Knight-Nash equilibrium in the sense of Definition \ref{def:knight_nash_equilibrium} is also an equilibrium in the sense of \citet{decerf_riedel_2020}.
    }
\end{definition}

\noindent Definition \ref{def:knight_nash_equilibrium} mimics the definition of a Bayesian Nash equilibrium.
The only difference is that instead of choosing optimal strategies with respect to a unique distribution, the infimal expected value over all distributions is maximized.
Hence, the Knight-Nash equilibrium takes the maxmin or Gilboa-Schmeidler approach to tackle uncertainty (cf. \cite{gilboa_schmeidler_1989}).

We now want to include Knightian uncertainty into the concept of cursed equilibria.
\citet{eyster_rabin_2005} do not base their equilibrium concepts on an axiomatic foundation, but they provide the following learning story that justifies the concept of fully cursed equilibrium:
Players who observe previous generations playing the game at hand ``(i) have correct a priori beliefs about a game's informational structure, (ii) observe the behavior of a large number of players previously playing the game---but not  players' final payoffs---and (iii) are entirely unsophisticated about other players' strategic incentives'' \citep[p. 1633]{eyster_rabin_2005}.
In our framework that features Knightian uncertainty, the ``correct a priori beliefs'' imply that the ambiguity set $\mathcal{P}$ is \emph{correct}, hence the \emph{correct probability distribution} $\Prob^*$ that generates the players' types is contained in $\mathcal{P}$.
The average strategy of other players, observed from previous generations playing the game, is the average according to $\Prob^*$.
Consequently, this average strategy is not subject to the maxmin optimization problem of player $k$, but it is---given player $k$'s type and the strategies of the opponents---a fixed object, $\bar{\sigma}_{-k}\left(\cdot \mid \theta_k, \Prob^*\right)$.\footnote{
An alternative approach in which this average strategy is also subject to uncertainty is outlined in Appendix \ref{app:Ambiguous_Cursed_Equilibria}.
}
\begin{definition} \label{def:cursed_knight_nash_equilibrium_given_P*}
    Let $\Gamma = \left( N, \left(A_k\right)_{k\in N}, \left(\Theta_k\right)_{k\in N}, \left(u_k\right)_{k \in N}, \mathcal{P} \right)$ be an incomplete information game with imprecise probabilistic information, and let $\Prob^* \in \mathcal{P}$ be the true type generating distribution.
    For a strategy profile $\sigma_{-k}$ of  player $k$'s opponents, $\sigma_k$ is a \emph{maxmin cursed best response (under $\Prob^*$)} against $\sigma_{-k}$ if for each $\theta_k \in \Theta_k$, and each $a_k^*$ such that $\sigma_k\left(a_k^* \mid \theta_k\right)>0$,
    \begin{align}
        a_k^* &\in \argmax_{a_k \in a_k} \ubar v_k^{\Prob^*}\left(a_k \mid \theta_k, \sigma_{-k}\right), \text{ where} \nonumber \\
        \ubar v_k^{\Prob^*}\left(a_k \mid \theta_k, \sigma_{-k}\right) &\colonequals \inf_{\Prob \in \mathcal{P}} \int_{\Theta_{-k}}
        \sum_{a_{-k} \in A_{-k}} \bar{\sigma}_{-k}\left(a_{-k} \mid \theta_k, \Prob^* \right) 
        u_i\left(a_k, a_{-k} ; \theta_k, \theta_{-k}\right) \d\Prob\left(\theta_{-k}\mid\theta_k\right).\label{eq:definition_vP*_uncertainty}
    \end{align}
    A strategy profile $\sigma^*$ is a \emph{cursed Knight-Nash equilibrium (given $\Prob^*$)} if for each $k\in N$, $\sigma^*_k$ is a maxmin cursed best response given $\Prob^*$ against $\sigma^*_{-k}$.
\end{definition}

\noindent We may think of a cursed player acting according to Definition \ref{def:cursed_knight_nash_equilibrium_given_P*} as follows:
They play the game repeatedly, knowing that types are drawn according to some probability distribution in $\mathcal{P}$.
The player is only aware of $\mathcal{P}$, having no idea about the exact distribution $\Prob^*$.
Alternatively, they might have a correct estimate about the true distribution $\Prob^*$, but, as they are not sure and want to be cautious, base their decision on a distribution band $\mathcal{P}$ that surrounds $\Prob^*$.
Our player observes that whenever they are of type $\theta_k$, their opponents play action profile $a_{-k}^1$ in, say, 70\% of the cases, while in the remaining 30\%, the opponents play $a_{-k}^2$.
Using the law of large numbers, our player (correctly) deduces that the opponents' average strategy, given their own type $\theta_k$, is $\bar\sigma_{-k}\left(a_{-k}^1 \mid\theta_k, \Prob^*\right) = 0.7 = 1-\bar\sigma_{-k}\left(a_{-k}^2 \mid \theta_k, \Prob^*\right)$.
As they are cursed, they ignore that the other agents' actions might (and typically will) depend on their types, instead assuming that all types of the other players play the same mixed action profile $0.7a_{-k}^1+0.3a_{-k}^2$.
In the presence of Knightian uncertainty, our player does not know with which probability measure to calculate their expected utilities.
%The expected utilities from their own actions depend on the type distribution of the other players via the primitive utility function $u_i$. 
Therefore, they calculate their (cursed) expected utility for each $\Prob \in \mathcal{P}$ and each of their own actions $a_k \in a_k$ and, being cautious, chooses $a_k$ to be the maxminimizer of this expected utility.
Note that in order to deduce the average strategy given $\Prob^*$, our player need not know $\Prob^*$.
Moreover, as they are ignorant about the other players' strategic incentives, knowing $\bar{\sigma}_{-k}\left(\cdot \mid \theta_k, \Prob^*\right)$ tells them nothing about $\Prob^*$.\footnote{
Even if they were more sophisticated and could deduce the other players' strategies, not only their average strategies, from observing their play, this would not necessarily allow the player to pin down $\Prob^*$, as there are typically many $\Prob \in \mathcal{P}$ that, together with a strategy profile of the opponent, induce the same distribution over actions.
}

If $\mathcal{P}=\{\Prob^*\}$ is a singleton, Definition \ref{def:cursed_knight_nash_equilibrium_given_P*} collapses to the cursed equilibrium (Definition \ref{def:cursed_equilibrium}).
In particular, the cursed Knight-Nash equilibrium relates to the cursed equilibrium in the same way the Knight-Nash equilibrium relates to the Bayesian Nash equilibrium.

Finally, let us also define equilibria in which only some players are cursed, while others act rationally, given the ambiguity set $\mathcal{P}$.

\begin{definition} \label{def:cursed_unscursed_nash_equilibrium}
    Let $\Gamma = \left( N, \left(A_k\right)_{k\in N}, \left(\Theta_k\right)_{k\in N}, \left(u_k\right)_{k \in N}, \mathcal{P} \right)$ be an incomplete information game with imprecise probabilistic information, and let $\Prob^* \in \mathcal{P}$ be the true type generating distribution.
    Moreover, let $N=N_1\sqcup N_2$ be a partition of $N$.
    A strategy profile $\sigma^*$ is an \emph{$(N_1, N_2)$-cursed-uncursed Knight-Nash equilibrium under $\Prob^*$} if for all $k\in N_1$, $\sigma^*_k$ is a maxmin cursed best response under $\Prob^*$ against $\sigma^*_{-k}$; and for all $j\in N_2$, $\sigma^*_j$ is a maxmin best response against $\sigma^*_{-j}$.
\end{definition}









\section{The Trading Game Without Uncertainty}
\label{sec:The_Trading_Game_Without_Uncertainty}

In this work, we focus on a constant-sum trading game in which both players hold private information.
One might think of a sale, for example of an asset on the stock market.
Both players hold some private information about the advantageousness of the potential trade.
Trade only occurs if there is mutual agreement about it.
At some point after the trade, it turns out who has profited from the trade. 
For instance, when the deal is about selling an asset, then the buyer profits if it evolves positively, and they do not profit if otherwise.
The person who profits from trade is happy, the other person will wish that they had not engaged in trade.
This regret is modeled by assigning this person a reward in case that there is no agreement on trade.
The private information that the players have is modeled by their types.


\subsection{The Game}
\label{subsec:The_Game}

We set up the game as prescribed in the Introduction, with the sole generalization that types are not necessarily uniformly distributed, but follow some distribution $\Prob_F$ induced by a strictly increasing and continuous cumulative distribution function $F$ on $[0,1]$.
More formally, the player set is $N=\{1,2\}$ with generic player $k$ (``they''), and both players' action sets are $A_1=A_2=\left\{nt, tr\right\}$.
The type spaces are $\Theta_1=\Theta_2=[0,1]$, the distribution on $\Theta=[0,1]^2$ is $\Prob_F^{\otimes 2}$, and a strategy for player $k$ is a mapping $\sigma_k \colon [0,1] \mapsto \Delta\left(\{nt, tr\}\right)$ from private types to probability distributions over actions.
As types are independent across players, $\bar \sigma_{k} \left(a_{k} \mid \theta_k, \Prob_{F}^{\otimes 2}\right)=\bar \sigma_{k} \left(a_{k} \mid \theta_k', \Prob_{F}^{\otimes 2}\right)$ for $k\in\{1,2\}$ and all $\theta_k, \theta_k'\in[0,1]$, so we will abbreviate this notation to $\bar \sigma_{k} \left(a_{k} \mid F\right)$.
Player 1's utility function is 
\begin{align} \label{eq:utility_function_1}
    u_1\left( a_1,a_2;\theta_1,\theta_2 \right) = 
    \begin{cases}
        1 &\text{ if } \theta_1 > \theta_2 \text{ and } a_k=nt \text{ for some } k \in \{1,2\}, \\
        1 &\text { if } \theta_1 < \theta_2 \text{ and } a_1=a_2=tr, \\
        0 &\text{ else.}
    \end{cases}
\end{align}
Ties are irrelevant as distributions are independent and atomless. 
Player 2's utility is $u_2\left( a_1,a_2;\theta_1,\theta_2 \right)= 1-u_1\left( a_1,a_2;\theta_1,\theta_2 \right)$.

The distribution function $F$ might either be known to the players, in which case we are facing a Bayesian game, or it is unknown and players are only aware of a set $\F$ of distribution functions that contains $F$.
In the latter case, we arrive at an incomplete information game with imprecise probabilistic information.
Note that as $F$ is continuous and strictly increasing on $[0,1]$, it is invertible, and $F^{-1}$ is also a continuous and strictly increasing function on $[0,1]$.

The game defined above is a \emph{constant-sum game} and can be transformed into a \emph{zero-sum game} by subtracting $\tfrac{1}{2}$ from each player's utility.
Doing so, all essential results in this paper would remain unchanged.
We avoid such a normalization in order to simplify calculations.
Still, one can think of the game as a stylized version of any zero-sum trading game in the sense that it models the characteristics that were outlined at the beginning of the subsection.

We shall define an important class of strategies, namely those in which a player offers to trade if their type is low, and refuses to do so for higher types.

\begin{definition} \label{def:cut-off_strategy}
    For $k \in \{1,2\}$, a strategy $\sigma_k$ is called \emph{cut-off strategy} if there exists a threshold $\hat\theta \in [0,1]$ such that $\sigma_k\left(tr\mid \theta\right)=1$ for $\theta<\hat\theta$ and $\sigma_k\left(nt\mid \theta\right)=1$ for $\theta>\hat\theta$.
\end{definition}

\noindent If a threshold in the sense of Definition \ref{def:cut-off_strategy} exists, it must necessarily be unique.
The action of player $k$ at $\theta=\hat\theta$ does not matter as $\{\hat\theta\}$ is a nullset.
Without loss of generality, we might assume that they offer to trade for $\theta \leq \hat\theta$.
In this case, we denote the cut-off strategy with threshold $\hat\theta$ by $\sigma^{\hat\theta}$.
Sometimes, we want to stress that the strategy is employed by player $k$ and therefore write $\sigma_k^{\hat\theta}$.

The following lemma provides the interim expected utilities of actions $nt$ and $tr$ against any cut-off strategy of the opponent, both for a cursed as well as for a rational player.

\begin{lemma} \label{lem:v(nt)_and_v(tr)}
    Let player $-k$ play the cut-off strategy $\sigma_{-k}^{\hat\theta}$.
    Then, for any type $\theta_k$ of player $k$,
    \begin{align}
        w_k\left(nt \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= v_k\left(nt \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) = F(\theta_k), \label{eq:v(nt)} \\
        w_k\left(tr \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= \LV F\left(\theta_k\right)-F(\hat\theta_2) \RV, \text{ and} \label{eq:w(tr)}\\
        v_k\left(tr \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= F(\hat\theta_2)\left(1-F(\theta_k)\right)+(1-F(\hat\theta_2))F(\theta_k). \label{eq:v(tr)}
    \end{align}
\end{lemma}

\noindent Equation \eqref{eq:v(tr)} nicely illustrates the phenomenon of the cursed equilibrium:
Assume that player $k$ has private type $\theta_k$ and plays ``$tr$''.
In this case, their probability of winning---which is their interim expected utility---equals the probability that the opponent also plays ``tr'' (which is $F(\hat\theta_2)$) and has a a higher type ($1-F(\theta_k)$), plus the probability that the opponent plays ``$nt$'' ($1-F(\hat\theta_2)$) and has a lower type ($F(\theta_k)$).
These events are not stochastically independent such that the probability of their intersection cannot be calculated by multiplying the probabilities of the events.
However, the cursed player treats the events as independent and splits the probabilities accordingly, which leads them to arrive at \eqref{eq:v(tr)} instead of \eqref{eq:w(tr)}.

The rational Bayesian Nash equilibrium of our game is fairly simple:
both players almost surely never offer to exchange their types.

\begin{proposition}\label{prop:BNE_is_nt}
    A strategy profile $\left(\sigma_1, \sigma_2\right)$ is a Bayesian Nash equilibrium if and only if $\sigma_1\left(nt \mid \theta_1\right)=\sigma_2\left(nt \mid \theta_2\right)=1$ for $F$-almost all $\theta_1, \theta_2 \in [0,1]$.
\end{proposition}

\noindent The logic behind the proof of Proposition \ref{prop:BNE_is_nt} is simple, and has been observed numerous times before:
%If the opponent sometimes offers to trade their types, a player should be willing to engage in trade if their type is very low, as they have a good chance to end up with a higher type after trading.
%However, if their type is at or above the maximal type at which the opponent engages in trade, a player should refuse to do so, as in every situation where they could potentially benefit from trade, there will not be trade anyway.
%In this situation, a player can only lose from offering to exchange types.
%Hence, every player wants to ``undercut'' their opponent and only trade at types that are lower than the average type at which the opponent trades.
%In equilibrium, mutual behavior of this kind leads to trade being impossible.
If player 1 sometimes offers to exchange types, player 2 wants to ``undercut'' them and only trade at types that are lower than the average type at which player 1 wants to trade.
In equilibrium, mutual behavior of this kind leads to trade being impossible.





\subsection{How Cursedness Leads Players To Trade}
\label{subsec:How_Cursedness_Leads_Players_To_Trade}

While trade is impossible in the rational equilibrium, it can be rationalized by cursedness.

\begin{proposition}\label{prop:cNE_is_median_cutoff}
    A strategy profile $(\sigma_1,\sigma_2)$ is a cursed equilbrium if only if it is a Bayesian Nash equilibrium or if both players play a cut-off strategy with threshold $F^{-1}\left(\tfrac{1}{2}\right)$.
\end{proposition}

\noindent Let us imagine the situation of a cursed player 1 whose opponent sometimes offers to trade, that is, $\bar\sigma_{2}\left(tr\mid F\right)>0$.
Player 1 correctly identifies the value of $\bar\sigma_{2}\left(tr\mid F\right)$.
However, they do not notice that player 2 offers to trade for some of their types, and declines to do so for other types.
Instead, player 1 thinks that player 2 plays $tr$ with probability $\bar\sigma_{2}\left(tr\mid F\right)$ and $nt$ with probability $1-\bar\sigma_{2}\left(tr\mid F\right)$, independently of their type.
Against such a type-independent mixed strategy, it would be optimal for player 1 to offer to trade if and only if the probability that $\theta_2>\theta_1$ exceeds the probability that the $\theta_2<\theta_1$.
This is the case if and only if $\theta_1$ lies below the median of the distribution $F$.
In particular, in this game, the play of a cursed player coincides with behavior under level-1 reasoning (cf. \cite{nagel_1995, stahl_wilson_1995}).

% Remark \ref{rmk:monotonicity_assumptions} generalizes this paragraph, do not need it here.
\begin{comment}
We shall briefly comment on the assumption that $F$ is strictly increasing.
If we allow $F$ to be constant on intervals, Proposition \ref{prop:BNE_is_nt} would still hold:
In every Bayesian Nash equilibrium, both players play $nt$ $F$-almost surely.
Regarding Proposition \ref{prop:cNE_is_median_cutoff}, one can show that any cursed equilibrium is either a Bayesian Nash equilibrium or such that for $k \in \{1,2\}$, player $k$ plays $tr$ if $F\left(\theta_k\right)<\tfrac{1}{2}$, they play $nt$ if $F\left(\theta_k\right)>\tfrac{1}{2}$, and for $F\left(\theta_k\right)=\tfrac{1}{2}$, they can play either $tr$ or $nt$ or any mixture, resulting in possible equilibrium strategies that are not necessarily of cut-off type.
In order to avoid such cumbersome statements, and to make the proofs as concise as possible, we refrain from allowing $F$ to be constant on intervals.
\end{comment}



\section{The Trading Game With Uncertainty}
\label{sec:The_Trading_Game_With_Uncertainty}


In Section \ref{sec:The_Trading_Game_Without_Uncertainty}, we assumed the type distribution $F$ to be fixed. 
In this section, we weaken this assumption and consider $F$ to be subject of \emph{Knightian uncertainty}, arriving at the concept of an incomplete information game with imprecise probabilistic information.
We make the following assumption on the ambiguity set $\mathcal{P}$.



\begin{assumption} \label{ass:prior_distributions}
    Types are independent and identically distributed according to some strictly increasing, continuous cumulative distribution function $F^*$ on $[0,1]$.
    Let $F_l$ and $F_h$ be strictly increasing and continuous functions on $[0,1]$ that satisfy $F_l(\theta) \leq F^*(\theta)\leq F_h(\theta)$ for all $\theta \in [0,1]$, as well as
    \begin{align}
    \label{eq:symmetry_F}
        F_l\left({F^*}^{-1}(1-\theta)\right) = 1- F_h\left({F^*}^{-1}(\theta)\right).
    \end{align}
    The ambiguity set is $\mathcal{P}_{\F} = \left\{ \Prob_F^{\otimes 2} \colon F \in \F\right\}$, where $\F$ is the set of all monotonously increasing, continuous cumulative distribution functions $F$ on $[0,1]$ that satisfy $F_l(\theta)\leq F(\theta) \leq F_h(\theta)$ for all $\theta \in [0,1]$.
\end{assumption}

\noindent Given this assumption, we will, with an abuse of notation, speak about maxmin cursed best responses and cursed Knight-Nash equilibria \emph{under $F^*$} instead of \emph{under $\Prob_{F^*}^{\otimes 2}$}, and we will use $\ubar v_k^{F^*}$ as a shorthand for $\ubar v_k^{\Prob_{F^*}^{\otimes 2}}$. 
As in Section \ref{sec:The_Trading_Game_Without_Uncertainty}, we write $\bar \sigma_{k} \left(a_{k} \mid F^*\right)$ for the average strategy of player $k$ under $F^*$.

We can interpret Assumption \ref{ass:prior_distributions} as follows:
Types are distributed according to $F^*$.
While players have some estimate or guess that $F^*$ is the true distribution, they are not definitely sure about this.
Hence, in order to use a more robust approach that accounts for other distributions, they base their decision not on $F^*$ alone, but on the distribution band $\F$ that symmetrically encloses $F^*$ and consists of all distributions between some dominating distribution $F_l$ and some dominated distribution $F_h$.
As players do not have a second-order distribution over $\F$, other approaches towards uncertainty apart from playing maxmin strategies are not readily available, and as types are independent, knowing their own type does not give them any additional information about the opponent's type or its distribution.
If $F_l=F_h$, we are in the situation of Section \ref{sec:The_Trading_Game_Without_Uncertainty}.

\begin{remark}
\label{rmk:true_F_uniform}
    Without loss of generality, we can assume that $F^*$ is the uniform distribution on $[0,1]$---that is, $F^*(\theta)=\text{Id}(\theta)=\theta$ for all $\theta\in[0,1]$---and that the functions $F_l$ and $F_h$ satisfy
    \begin{align}
    \label{eq:symmetry_F_uniform}
        F_l(1-\theta)=1-F_h(\theta) \text{ for all } \theta \in [0,1].
    \end{align}
    Indeed, under Assumption \ref{ass:prior_distributions}, we can define
    \begin{align*}
        \mathcal{G} \colonequals \F \circ {F^*}^{-1} = \left\{ G \colon \text{there is } F \in \F \text{ such that }G(\theta) = F({F^*}^{-1}(\theta)) \text{ for all } \theta \in [0,1] \right\}.
    \end{align*}
    Then, Assumption \ref{ass:prior_distributions} is also satisfied if types are uniformly distributed and the ambiguity set is $\left\{ \Prob_{G}^{\otimes 2} \colon G \in \mathcal{G}\right\}$.
    In particular, for the upper and lower bounds of $\mathcal{G}$ (these are $F_h\circ{F^*}^{-1}$ and $F_h\circ{F^*}^{-1}$, respectively), Equation \eqref{eq:symmetry_F_uniform} holds.
    Identifying types with quantiles, we can always assume that $F^*=\text{Id}$ and that the upper and lower bounds of $\F$ satisfy \eqref{eq:symmetry_F_uniform}, as a situation in which some player is of type $\theta$ and faces uncertainty over the set $\F$ (which symmetrically encloses $F^*$) is behaviorally and mathematically equivalent to a situation in which this player is of type ${F^*}(\theta)$ and faces uncertainty over the set $\mathcal{G}$ (which symmetrically encloses $\text{Id}$).
\end{remark}

\noindent Let us give some examples and counterexamples for Assumption \ref{ass:prior_distributions}.

\begin{example}
\label{ex:parametrizations}
Following Remark \ref{rmk:true_F_uniform}, let the true distribution be the uniform distribution.
\begin{enumerate}
    \item\label{it:contamination} For $\kappa \in [0,1)$ and $\theta\in [0,1]$, let 
    \begin{align*}
        F_{l,\kappa}(\theta) &= \begin{cases}
            (1-\kappa)\theta &\text{ for } \theta \leq \tfrac{1}{2},\\
            -\kappa + (1+\kappa)\theta &\text{ for } \theta \geq \tfrac{1}{2},
        \end{cases} \\
        F_{h,\kappa}(\theta) &= \begin{cases}
            (1+\kappa)\theta &\text{ for } \theta \leq \tfrac{1}{2}, \\
            \kappa + (1-\kappa)\theta &\text{ for } \theta \geq \tfrac{1}{2},
        \end{cases}
    \end{align*}
    and let $\F_{\kappa}$ be the set of all continuous cumulative distribution functions $F$ on $[0,1]$ that satisfy $F_{l, \kappa}(\theta)\leq F(\theta) \leq F_{h, \kappa}(\theta)$ for all $\theta \in [0,1]$.
    It is immediate to verify that Assumptions \ref{ass:prior_distributions} is satisfied with $F^*=\text{Id}$, in particular, Equation \eqref{eq:symmetry_F_uniform} holds true.
    The distribution set $\F$ includes the so-called \emph{contamination of the uniform distribution on $[0,1]$}, that is, the set of all probability distributions on $[0,1]$ that are absolutely continuous with respect to the Lebesgue measure and whose Lebesgue density lies between $1-\kappa$ and $\kappa$ (cf. \cite{decerf_riedel_2020}).\footnote{
    Note that we allow for distributions that do not have a Lebesgue density.
    There are (pathologic) examples of cumulative distribution functions that are continuous but not absolutely continuous and therefore do not have density functions, for instance the Cantor distribution.
    }
    The limit case of $\kappa=0$ corresponds to the unambiguous uniform distribution.
    The distribution functions $F_{l,\kappa}$ and $F_{h,\kappa}$ are depicted in Subfigure \ref{subfig:F_contamination}.

     \item\label{it:triangles} For $a \in [1, \infty)$, let 
     \begin{align*}
        F_{l,a}(\theta) &= \begin{cases}
            \frac{1}{a}\theta &\text{for } \theta \leq \frac{a}{a+1}, \\
            a\theta+1-a &\text{for } \theta \geq \frac{a}{a+1},
        \end{cases} \\
        F_{h,a}(\theta) &= \begin{cases}
            a\theta &\text{for } \theta \leq \frac{1}{a+1}, \\
            \frac{1}{a}\theta+1-\frac{1}{a} &\text{for } \theta \geq \frac{1}{a+1}.
        \end{cases} 
    \end{align*}
    Let $\F_a$ be the set of all continuous distribution functions between $F_{l,a}$ and $F_{h,a}$, see Subfigure \ref{subfig:F_triangle}.
    Assumption \ref{ass:prior_distributions} is again satisfied.
    As in \ref{it:contamination}., the dominated and the dominant distribution form a triangle around the uniform distribution, 
    However, in this parametrization, the kinks do not lie at $\frac{1}{2}$, but parameter-dependently at $\frac{1}{a+1}$ and $\frac{a}{a+1}$.
    If $a$ approaches infinity, this allows to approximate the case of full uncertainty that includes every continuous distribution on $[0,1]$.
    If $a=1$, there is no uncertainty.

    \item\label{it:eps_band} For $\eps \in \left[0,\tfrac{1}{2}\right)$, let
    \begin{align*}
        F_{l, \eps}(\theta) &= \max\{\theta-\eps, 0\} \text{ for } \theta \in [0,1), \quad F_{l, \eps}(1)=1,\\
        F_{h, \eps}(\theta) &= \min\{\theta+\eps, 1\} \text{ for } \theta \in [0,1],
    \end{align*}
    and let $\F_{\eps}$ be defined as above, see Subfigure \ref{subfig:F_eps_band}.
    In this case, $\F_{\eps}$ contains all continuous distribution functions on $[0,1]$ that lie in an $\eps$-ball around the identity with respect to the supremum norm.
    There is no uncertainty in the limit case $\eps=0$.
    While Equation \eqref{eq:symmetry_F_uniform} is valid for all $\theta\in(0,1)$, $F_{l, \eps}$ and $F_{h, \eps}$ are not continuous everywhere, and piece-wise constant.
    Hence, Assumption \ref{ass:prior_distributions} is not satisfied.
    \qedhere
\end{enumerate}
\end{example}

