\begin{proof}[Proof of Lemma \ref{lem:v(nt)_and_v(tr)}]
    Equation \eqref{eq:v(nt)} is clear:
    If a player does not offer to trade, their (cursed or uncursed) interim expected value does not depend on the opponent's action and is just given by $\Prob_F\left(\theta_{-k}<\theta_k\right)=F(\theta_k)$.

    For Equation \eqref{eq:w(tr)}, we have
    \begin{align*}
        w_k\left(tr \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= \Prob_F\left(a_{-k}=tr, \theta_{-k}>\theta_k\right) + \Prob_F\left(a_{-k}=nt, \theta_{-k}<\theta_k\right) \\
        &= \Prob_F\left(\theta_k<\theta_{-k}\leq \hat\theta\right) + \Prob_F\left(\hat\theta < \theta_{-k} < \theta_k\right) \nonumber\\
        &= \LV F(\hat\theta_2)-F(\theta_k)\RV.\nonumber
    \end{align*}
    As the average strategy of the opponent is $\bar\sigma_{-k}^{\hat\theta}=F(\hat\theta_2)\cdot tr + \left(1-F(\hat\theta_2)\right)\cdot nt$, we obtain
    \begin{align*}
        v_k\left(tr \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= \Prob_F\left(a_{-k}=tr\right)\Prob_F\left(\theta_{-k}>\theta_k\right) + \Prob_F\left(a_{-k}=nt\right)\Prob_F\left(\theta_{-k}<\theta_k\right) \\
        &= F(\hat\theta_2)\left(1-F(\theta_k)\right)+\left(1-F(\hat\theta_2)\right)F(\theta_k) \nonumber
    \end{align*}
    which shows Equation \eqref{eq:v(tr)}.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:BNE_is_nt}]
    If, for $k \in \{1,2\}$, player $-k$ plays some strategy $\sigma_{-k}$ such that $\sigma_{-k}\left(nt \mid \theta_{-k}\right)=1$ for $F$-almost all $\theta_{-k}$, then 
    \begin{align*}
        w_k \left( tr \mid \theta_k, \sigma_{-k} \right) = w_k \left( nt \mid \theta_k, \sigma_{-k} \right) = F\left(\theta_k\right)
    \end{align*}
    for all $\theta_k \in [0,1]$.
    Hence, every strategy is a best response against $\sigma_{-k}$.
    It follows that any strategy profile in which both players $F$-almost surely play $nt$ is a Bayesian Nash equilibrium.

    Let us show that there cannot be more equilibria.
    For each player $k \in \{1,2\}$, define the cursed expected difference between not trading and trading at type $\theta_k$, given the opponent's strategy $\sigma_{-k}$, as
    \begin{align} \label{eq:definition_difference_d_k}
        d_k \left( \theta_k, \sigma_{-k} \right)
        \colonequals w_k\left(nt \mid \theta_k, \sigma_{-k}\right) - w_k\left(tr \mid \theta_k, \sigma_{-k}\right).
    \end{align}
    Let $T_k$ be the set in which player $k$ offers to trade with positive probability, that is, 
    \begin{align} \label{eq:definition_T_k}
        T_k \colonequals \left\{ \theta_k \in [0,1] \colon \sigma_k (tr \mid \theta_k) >0 \right\}.
    \end{align}
    By means of contradiction, assume that $T_k$ is a non-nullset for at least one player, without loss of generality $\Prob_F(T_2)>0$. 
    Then, with $d_1$ as defined in \eqref{eq:definition_difference_d_k},
    \begin{align*}
        d_1\left(\theta_1, \sigma_2\right) = \int_0^1 \sigma_2\left(tr \mid \theta_2 \right) \left(\mathbbm{1}_{\{\theta_1 > \theta_2\}} - \mathbbm{1}_{\{\theta_2 > \theta_1\}} \right) \d F \left(\theta_2\right),
    \end{align*}
    in particular
    \begin{align*}
        d_1\left(0, \sigma_2\right) = -\int_0^1 \sigma_2(tr \mid \theta_2) \d F\left(\theta_2\right) < 0 \quad \text{and} \quad
        d_1\left(\sup T_2, \sigma_2\right) = \int_0^1 \sigma_2(tr \mid \theta_2) \d F\left(\theta_2\right) > 0.
    \end{align*}
    By continuity, there exists $\varepsilon>0$ such that $d_1 \left(\theta_1, \sigma_2\right) <0$ for all $\theta<\varepsilon$ and $d_1 \left(\theta_1, \sigma_2 \right) >0$ for all $\theta_1 \geq \sup T_2 -\varepsilon$.
    Therefore, every strategy $\sigma_1$ that is a best response to $\sigma_2$ must satisfy $\sigma_1(tr \mid \theta_1)=1$ for $\theta<\varepsilon$ and $\sigma_1(tr \mid \theta_1)=0$ for $\theta_1 \geq \sup T_2 -\varepsilon$.
    Hence, $\Prob_F(T_1)>0$ and $\sup T_1 < \sup T_2$.
    In an equilibrium, $\sigma_2$ must be a best response against $\sigma_1$ as well.
    As $\Prob_F(T_1)>0$, repeating the same arguments with reversed roles yields $\sup T_2 < \sup T_1$, which is impossible.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:cNE_is_median_cutoff}]
    First note that by the very same arguments as the ones from the first paragraph of the proof of Proposition \ref{prop:BNE_is_nt}, every Bayesian Nash equilibrium is also a cursed equilibrium.
    Now assume that player $-k$ plays a strategy $\sigma_{-k}$ such that $T_{-k}$ as defined in \eqref{eq:definition_T_k} is not a nullset.
    This is equivalent to $\bar\sigma_{-k}(tr\mid F)>0$.
    In this case, for all $\theta_k \in [0,1]$,
    \begin{align*}
        v_k \left(nt \mid \theta_k, \sigma_{-k} \right) &= F\left(\theta_k\right), \text{ while} \\
        v_k \left(tr \mid \theta_k, \sigma_{-k} \right)
        &= \bar\sigma_{-k}(tr\mid F) \left(1-F\left(\theta_k\right)\right) + \left(1-\bar\sigma_{-k}(tr\mid F)\right) F\left(\theta_k\right).
    \end{align*}
    As $\bar\sigma_{-k}(tr\mid F)>0$, it follows that $v_k \left(tr \mid \theta_k, \sigma_{-k} \right) \geq v_k \left(nt \mid \theta_k, \sigma_{-k} \right)$ if and only if $F\left(\theta_k\right) \leq \tfrac{1}{2}$.
    Hence, any cut-off strategy with threshold $F^{-1}\left(\tfrac{1}{2}\right)$ is a cursed best response against $\sigma_{-k}$, and any cursed best response is such a strategy.
    It follows that every strategy profile in which both players play a cut-off strategy with threshold $F^{-1}\left(\tfrac{1}{2}\right)$ is a cursed equilibrium, and that these, together with the Bayesian Nash equilibria, are all cursed equilibria.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:KNE_is_nt}]
    Obviously, $\left(\sigma_1^0, \sigma_2^0\right)$ constitutes a Knight-Nash equilibrium:
    When the opponent never offers to trade---or only does so at type 0, which happens with probability 0 under any probability measure from $\mathcal{P}_{\F}$---, the own strategy does not matter, as there will not be a trade anyway.
    In particular, it is optimal to always play $nt$.

    Let us now assume that player 2 plays a cut-off strategy $\sigma_2^{\hat\theta}$ with $\hat\theta>0$.
    Then, following Lemma \ref{lem:v(nt)_and_v(tr)}, player 1's infimal interim expected utilities from playing ``$nt$'' or ``$tr$'', respectively, are
    \begin{align*}
        \ubar w_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta}\right)=  F_l(\theta_1) \qquad \text{and} \qquad \ubar w_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right) = \inf_{F \in \F} \LV F(\theta_1)-F(\hat\theta_2) \RV,
    \end{align*} 
    respectively.
    The value of the second term depends on the location of $\hat\theta$ and $\theta_1$:
    If $F(\theta_1)\leq F_l(\hat\theta_2)$ for all $F \in \F$---that is, if $F_h(\theta_1)\leq F_l(\hat\theta_2)$---then there exists a function $G \in \F$ that satisfies $G(\theta_1)=F_h(\theta_1)$ and $G(\hat\theta_2)=F_l(\hat\theta_2)$, and $G$ minimizes $ \LV F(\theta_1)-F(\hat\theta_2) \RV$ over $\F$.
    Similarly, if $F_h(\hat\theta_2)\leq F_l(\theta_1)$, any function $G \in \F$ that satisfies $G(\hat\theta_2)=F_h(\hat\theta_2)$ and $G(\theta_1)=F_l(\theta_1)$ minimizes $ \LV F(\theta_1)-F(\hat\theta_2) \RV$; and if neither of the two is the case, there is a function that is constant between $\theta_1$ and $\hat\theta$, and any such function minimizes $ \LV F(\theta_1)-F(\hat\theta_2) \RV$.
    Putting all of this together, we see that the infimum is always attained and that
    \begin{align} \label{eq:w(tr)_uncertain_uncursed}
        \ubar w_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right) = \min_{F \in \F} \LV F(\theta_1)-F(\hat\theta_2) \RV = \begin{cases}
            F_l(\hat\theta_2)-F_h(\theta_1) &\text{ for } \theta_1 \leq F_h^{-1}\left(F_l(\hat\theta_2)\right), \\
            0 &\text{ for } \theta_1 \in \left[ F_h^{-1}\left(F_l(\hat\theta_2)\right), F_l^{-1}\left(F_h(\hat\theta_2)\right) \right], \\
            F_l(\theta_1)-F_h(\hat\theta_2) &\text{ for } \theta_1 \geq F_l^{-1}\left(F_h(\hat\theta_2)\right).
        \end{cases}
    \end{align}
    It follows that $\ubar w_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right) < \ubar w_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta}\right)$ for $\theta_1 \geq F_h^{-1}\left(F_l(\hat\theta_2)\right)$ such that for these $\theta_1$, any best reply requires to play $nt$.
    For $\theta_1 \leq  F_h^{-1}\left(F_l(\hat\theta_2)\right)$, $\ubar w_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta}\right)$ is strictly increasing, while $\ubar w_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right)$ is decreasing in $\theta_1$.
    Moreover, 
    \begin{align*}
        \ubar w_1 \left(tr \mid 0, \sigma_2^{\hat\theta}\right) = F_l(\hat\theta_2)&>F_l(0)=\ubar w_1 \left(nt \mid 0, \sigma_2^{\hat\theta}\right) \text{ and} \\
        \ubar w_1 \left(tr \mid F_h^{-1}\left(F_l(\hat\theta_2)\right), \sigma_2^{\hat\theta}\right) = 0&< F_l \left(F_h^{-1}\left(F_l(\hat\theta_2)\right)\right) = \ubar w_1 \left(nt \mid F_h^{-1}\left(F_l(\hat\theta_2)\right), \sigma_2^{\hat\theta}\right)
    \end{align*}
    such that there must be a unique intersection at some $\theta_1^*$ with $0<\theta_1^*< F_h^{-1}\left(F_l(\hat\theta_2)\right) \leq \hat\theta$.
    Hence, the best response to the cut-off strategy $\sigma_2^{\hat\theta}$ is the cut-off strategy $\sigma_1^{\theta_1^*}$ with $\theta_1^*<\hat\theta$.
    But as players are symmetric, a Knight-Nash equilibrium requires that also $\hat\theta<\theta_1^*$, which is impossible.
\end{proof}

\noindent For the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle_under_F*}, we need the following Lemma.

\begin{lemma} \label{lem:value_of_minimum_under_F*}
    Let Assumption \ref{ass:prior_distributions} be satisfied.
    For $k \in \{1,2\}$ and any strategy $\sigma_{-k}$ of player $-k$,
    \begin{align*}
        \ubar v_k^{F^*} \left(nt \mid \theta_k, \sigma_{-k}\right) &= F_l\left(\theta_k\right), \text{ and} \\
        \ubar v_k^{F^*} \left(tr \mid \theta_k, \sigma_{-k}\right) &= 
        \begin{cases}
            \left( 1-2\bar\sigma_{-k} \left( tr \mid F^* \right) \right) F_l(\theta_1) + \bar\sigma_2 \left( tr \mid F^* \right) &\text{ if } \bar \sigma_{-k} \left( tr \mid F^* \right) \leq \tfrac{1}{2}, \\
            \left( 1-2\bar\sigma_{-k} \left( tr \mid F^* \right) \right) F_h(\theta_1) + \bar\sigma_2 \left( tr \mid F^* \right) &\text{ if } \bar \sigma_{-k} \left( tr \mid F^* \right) \geq \tfrac{1}{2}.
        \end{cases}
    \end{align*}
\end{lemma}

\begin{proof}
    Let $k=1$ without loss of generality.
    For any strategy $\sigma_2$ of player 2,
    \begin{align*}
        \ubar v_1^{F^*} \left( nt \mid \theta_1, \sigma_2 \right) = \inf_{F \in \F} \Prob_{F} \left(\theta_2 \leq \theta_1 \right) = F_l\left(\theta_1\right).
    \end{align*}
    If player 1 offers to trade, their cursed expected utility is given by
    \begin{align*}
        \ubar v_1^{F^*} \left( tr \mid \theta_1, \sigma_2 \right) &= \inf_{F \in \F} \int_0^1 \bar\sigma_2 \left( tr \mid F^* \right) \mathbbm{1}_{\{\theta_2>\theta_1\}} + \left(1-\bar\sigma_2 \left( tr \mid F^* \right)\right) \mathbbm{1}_{\{\theta_2<\theta_1\}} \dF (\theta_2) \\
        &= \inf_{F \in \F} \bar\sigma_2 \left( tr \mid F^* \right) \left(1-F(\theta_1)\right) + \left(1-\bar\sigma_2 \left( tr \mid F^* \right)\right) F(\theta_1) \\
        &= \inf_{F \in \F} \left( 1-2\bar\sigma_2 \left( tr \mid F^* \right) \right) F(\theta_1) + \bar\sigma_2 \left( tr \mid F^* \right).
    \end{align*}
    If $1-2\bar\sigma_2 \left( tr \mid F^* \right) \geq 0$, this infimum is attained by $F=F_l$, while if $1-2\bar\sigma_2 \left( tr \mid F^* \right) \leq 0$, it is attained by $F=F_h$.
\end{proof}

\noindent In order to prove Proposition \ref{prop:cut-offs_ambiguity_in_middle_under_F*}, we first establish that only cut-off strategies with thresholds in $(0,1)$ are played in equilibrium.

\begin{proof}[Proof that only cut-off strategies are played in equilibrium]
    Without loss of generality, let $\bar\sigma_2\left(tr \mid F^*\right)>0$.
    In order to establish that only cut-off strategies are played in equilibrium, it suffices to show that for any such strategy player 2 might employ, every maxmin fully cursed best response of player 1 is of the cut-off type, with some cut-off $\theta_1^* \in (0,1)$.
    Having shown this, we can reverse the roles of 1 and 2 and conclude that player 2 must play a cut-off strategy as well.

    Following Lemma \ref{lem:value_of_minimum_under_F*}, 
    \begin{align*}
        &\ubar v_1^{F^*} \left(nt \mid \theta_1, \sigma_2 \right) - \ubar v_1^{F^*} \left(tr \mid \theta_1, \sigma_2 \right) \\
        = 
        &\begin{cases}
            \left(2F_l(\theta_1)-1\right) \bar \sigma_{2} \left( tr \mid F^* \right) &\text{ if } \bar \sigma_{2} \left( tr \mid F^* \right) \leq \tfrac{1}{2},\\
            F_l\left(\theta_1\right) + \left(2\bar\sigma_2 \left(tr \mid F^* \right)-1 \right) F_h\left(\theta_1\right) - \bar\sigma_2 \left(tr \mid F^* \right) &\text{ if } \bar \sigma_{2} \left( tr \mid F^* \right) \geq \tfrac{1}{2}
        \end{cases}
    \end{align*}
    which is negative for $\theta_1=0$, positive for $\theta_1=1$, and strictly increasing in between.
    Hence, there must be a unique threshold $\theta_1^* \in (0,1)$ such that $\ubar v_1^{F^*} \left(tr \mid \theta_1, \sigma_2 \right)>\ubar v_1^{F^*} \left(nt \mid \theta_1, \sigma_2 \right)$ if and only if $\theta_1>\theta_1^*$.
    It follows that every best response of player 1 is of cut-off type with threshold $\theta_1^*$.
    Reverting the roles of the players, we see that in equilibrium, both players employ a cut-off strategy with tresholds in $(0,1)$.
\end{proof}

\noindent The following lemma is needed in order to localize these equilibria and therefore conclude the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle_under_F*}.

\begin{lemma} \label{lem:best_responses_under_F^*}
    Let Assumption \ref{ass:prior_distributions} be satisfied, and let player $-k$ play a cut-off strategy $\sigma_{-k}^{\hat\theta_{-k}}$ with threshold $\hat\theta_{-k}>0$.
    Then, there is a unique maxmin cursed best response under $F^*$ for player $k$.
    If player $-k$'s threshold satisfies $F^*\left(\hat\theta_{-k}\right)\leq \frac{1}{2}$, this best response is the cut-off strategy with threshold $F_l^{-1}\left(\tfrac{1}{2}\right)$.
    If $F^*\left(\hat\theta_{-k}\right)> \frac{1}{2}$, the best response is also a cut-off strategy, and the threshold lies in $\left[ F_h^{-1}\left(\tfrac{1}{2}\right), 1 \right)$.
\end{lemma}

\begin{proof}
    As usual, let $k=1$ and $-k=2$.
    When player 2 plays the cut-off strategy $\sigma_2^{\hat\theta_2}$ with threshold $\hat\theta_2 >0$, their average strategy under $F^*$ is given by $\bar\sigma_2^{\hat\theta_2}\left(tr \mid F^* \right) = F^*(\hat\theta_2) = 1- \bar\sigma_2^{\hat\theta_2}\left(nt \mid F^* \right)$.

    If $F^*(\hat\theta_2)\leq \frac{1}{2}$, then, by Lemma \ref{lem:value_of_minimum_under_F*}, $\ubar v_1^{F^*} \left(nt \mid \theta_1, \sigma_2^{\hat\theta_2}\right)=F_l\left(\theta_1\right)$, while 
    \begin{align*}
        \ubar v_1^{F^*} \left(tr \mid \theta_1, \sigma_2^{\hat\theta_2}\right) = F_l\left(\theta_1\right) + F^*(\hat\theta_2) - 2F_l\left(\theta_1\right) F^*(\hat\theta_2).
    \end{align*}
    It follows that $\ubar v_1^{F^*} \left(tr \mid \theta_1, \sigma_2^{\hat\theta_2}\right) > \ubar v_1^{F^*} \left(nt \mid \theta_1, \sigma_2^{\hat\theta_2}\right)$ if and only if $F_l\left(\theta_1\right)< \frac{1}{2}$.
    So indeed, the maxmin fully cursed best response against $\sigma_2^{\hat\theta_2}$ is the cut-off strategy with threshold $F_l^{-1}\left(\frac{1}{2}\right)$.

    Next, let $F^*(\hat\theta_2)>\tfrac{1}{2}$.
    We have already seen that the best response must be of cut-off type with threshold less than 1.
    As 
    \begin{align*}
        \ubar v_1^{F^*}\left(nt \mid  F_h^{-1}\left(\tfrac{1}{2}\right), \sigma_2^{\hat\theta_2}\right) = F_l\left(F_h^{-1}\left(\tfrac{1}{2}\right)\right) \leq \tfrac{1}{2} = \ubar v_1^{F^*}\left(tr \mid  F_h^{-1}\left(\tfrac{1}{2}\right), \sigma_2^{\hat\theta_2}\right), 
    \end{align*}
    the threshold for player 1 must be at least $F_h^{-1}\left(\tfrac{1}{2}\right)$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle_under_F*}]
    We have already shown that in equilibrium, only cut-off strategies with thresholds in $(0,1)$ are played.
    We now aim at localizing the thresholds of these equilibrium strategies.
    To this end, let $\left(\sigma_1^{\theta_1^*}, \sigma_2^{\theta_2^*}\right)$ be an equilibrium in which player $k$ plays the cut-off strategy with threshold $\theta_k^*$, for $k \in \{1,2\}$.

    Assume by means of contradiction that $\theta_1^* < F_h^{-1}\left(\tfrac{1}{2}\right)$ which implies $F^*\left(\theta_1^*\right)\leq \tfrac{1}{2}$.
    As $\sigma_1^{\theta_1^*}$ and $\sigma_2^{\theta_2^*}$ are mutual maxmin cursed best responses under $F^*$, $\theta_2^*=F_l^{-1}\left(\tfrac{1}{2}\right)$ by Lemma \ref{lem:best_responses_under_F^*}, in particular $F^*\left(\theta_2^*\right)\geq\frac{1}{2}$.
    Again by Lemma \ref{lem:best_responses_under_F^*}, $\theta_1^*\geq F_h^{-1}\left(\tfrac{1}{2}\right)$ which is impossible.
    Analogously, $\theta_2^* \geq F_h^{-1}\left(\tfrac{1}{2}\right)$.

    Assume next that, say, $\theta_2^*>F_l^{-1}\left(\tfrac{1}{2}\right)$ which implies that $F_h\left(\theta_2^*\right)>\tfrac{1}{2}$.
    In this case, $F^*\left(\theta_1^*\right)>\tfrac{1}{2}$ because otherwise, player 2's best response would be to play the cut-off strategy with threshold $F_l^{-1}\left(\tfrac{1}{2}\right)$, not the one with $\theta_2^*$.
    As player 2 is, given type $\theta_2^*$, indifferent between playing $nt$ and $tr$, Lemma \ref{lem:value_of_minimum_under_F*} yields
    \begin{align*}
        F_l\left(\theta_2^*\right) = \left(1-2F_h\left(\theta_2^*\right)\right) F^*\left(\theta_1^*\right) + F_h\left(\theta_2^*\right) < \left(1-2F_h\left(\theta_2^*\right)\right) \tfrac{1}{2} + F_h\left(\theta_2^*\right) = \tfrac{1}{2},
    \end{align*}
    where in the inequality, we used that $1-2F_h\left(\theta_2^*\right)<0$ and $F^*\left(\theta_1^*\right) > \tfrac{1}{2}$.
    The overall inequality contradicts our standing assumption that $\theta_2^*>F_l^{-1}\left(\tfrac{1}{2}\right)$.
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:fully_cursed_Knight_Nash_equilibrium_certain_median_under_F*}]
    As $\left[ F_h^{-1}\left(\tfrac{1}{2}\right), F_l^{-1}\left(\tfrac{1}{2}\right) \right]=\left\{{F^*}^{-1}\left(\tfrac{1}{2}\right)\right\}$ is a singleton, the proposed strategy profile is the only candidate for such an equilibrium by Proposition \ref{prop:cut-offs_ambiguity_in_middle_under_F*}.
    It directly follows from Lemma \ref{lem:best_responses_under_F^*} that both players' strategies are indeed mutual best responses to one another.
\end{proof}

\noindent The following Lemma is needed for the proof of Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*}.

\begin{lemma} \label{lem:g_decreasing}
    Let $F_l$ and $F_h$ be continuous, strictly increasing cumulative distribution functions on $[0,1]$ that satisfy $F_l(\theta)\leq \theta\leq F_h(\theta)$ for all $\theta\in[0,1]$ as well as $F_h^{-1}\left(\tfrac{1}{2}\right)<F_l^{-1}\left(\tfrac{1}{2}\right)$ and Equation \eqref{eq:symmetry_F_uniform}.
    The continuous function $g \colon \left[\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right] \to \left[\tfrac{1}{2}, 1\right]$ defined via $g(\theta) \colonequals \frac{F_h(\theta)-F_l(\theta)}{2F_h(\theta)-1}$ is monotonously decreasing.    
\end{lemma}

\begin{proof}
    Continuity follows from $F_l$ and $F_h$ being continuous.
    It is obvious that for all $\theta$ in the relevant domain, the numerator of $g(\theta)$ is nonnegative, while the denominator is strictly positive.
    Let $\theta, \theta' \in \left[\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ with $\theta \leq \theta'$.
    It then holds that
    \begin{align*}
        \frac{F_h\left(\theta\right)-F_l\left(\theta\right)}{F_h\left(\theta'\right)-F_l\left(\theta'\right)} \geq \frac{F_h\left(\theta\right)-F_l\left(\theta'\right)}{F_h\left(\theta'\right)-F_l\left(\theta'\right)} \geq \frac{F_h\left(\theta\right)-\tfrac{1}{2}}{F_h\left(\theta'\right)-\tfrac{1}{2}}
    \end{align*}
    where the first inequality follows from $F_l\left(\theta\right)\leq F_l\left(\theta'\right)$ and the second one from the fact that for any real numbers $a$ and $b$ with $a\leq b$, the mapping $x \mapsto \frac{a-x}{b-x}$ is monotonously decreasing on $(-\infty, b)$.
    Hence,
    \begin{align*}
        g\left(\theta\right) = \frac{1}{2}\frac{F_h\left(\theta\right)-F_l\left(\theta\right)}{F_h\left(\theta'\right)-F_l\left(\theta'\right)} \frac{F_h\left(\theta'\right)-F_l\left(\theta'\right)}{F_h\left(\theta\right)-\tfrac{1}{2}} \geq \frac{1}{2}\frac{F_h\left(\theta\right)-\tfrac{1}{2}}{F_h\left(\theta'\right)-\tfrac{1}{2}} \frac{F_h\left(\theta'\right)-F_l\left(\theta'\right)}{F_h\left(\theta\right)-\tfrac{1}{2}} = g\left(\theta'\right)
    \end{align*}
    which shows the claimed monononicity.
    Using Equation \eqref{eq:symmetry_F_uniform}, one finds that $g\left(\tfrac{1}{2}\right)=1$ and $g\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)=\tfrac{1}{2}$ which completes the proof.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*}]
   Following Remark \ref{rmk:true_F_uniform}, it is no loss of generality to assume that $F^*=\text{Id}$, and that $F_l$ and $F_h$ satisfy Equation \eqref{eq:symmetry_F_uniform}.
   We first show that in every cursed Knight-Nash equilibrium, players use cut-off strategies with thresholds above $\frac{1}{2}$.

   Observe that it directly follows from the assumptions that $F_l\left(\frac{1}{2}\right)<\frac{1}{2}<F_h\left(\frac{1}{2}\right)$ and that $F_h^{-1}\left(\frac{1}{2}\right)<\frac{1}{2}<F_l^{-1}\left(\frac{1}{2}\right)$.

   We know from Proposition \ref{prop:cut-offs_ambiguity_in_middle_under_F*} that in any such equilibrium, both players impose cut-off strategies with thresholds $\theta_1^*, \theta_2^* \in \left[F_h^{-1}\left(\tfrac{1}{2}\right), F_l^{-1}\left(\tfrac{1}{2}\right)\right]$.
   If $\theta_1^*\leq {F^*}^{-1}\left(\tfrac{1}{2}\right)=\tfrac{1}{2}$, Lemma \ref{lem:best_responses_under_F^*} implies that $\theta_2^*=F_l^{-1}\left(\tfrac{1}{2}\right)> \tfrac{1}{2}$.
   Hence, it is not possible that both $\theta_1^*$ and $\theta_2^*$ are less than or equal $\tfrac{1}{2}$.

   Assume next that $\theta_1^*\leq \tfrac{1}{2}$ and $\theta_2^* > \tfrac{1}{2}$.
   Again by Lemma \ref{lem:best_responses_under_F^*}, this is only possible if $\theta_2^*=F_l^{-1}\left(\tfrac{1}{2}\right)$.
   By Lemma \ref{lem:value_of_minimum_under_F*}, $\ubar v_1^{\text{Id}} \left(nt \mid \theta_1,  \sigma_2^{\theta_2^*}\right)$ is strictly increasing in $\theta_1$, and $\ubar v_1^{\text{Id}} \left(tr \mid \theta_1,  \sigma_2^{\theta_2^*}\right)$ is decreasing.
   As the two are equal for $\theta_1=\theta_1^*\leq\tfrac{1}{2}$, we must have that $\ubar v_1^{\text{Id}} \left(nt \mid \tfrac{1}{2}, \sigma_2^{\theta_2^*}\right) \geq \ubar v_1^{\text{Id}} \left(tr \mid \tfrac{1}{2}, \sigma_2^{\theta_2^*}\right)$.
   However,
   \begin{align}
       \ubar v_1^{\text{Id}} \left(tr \mid \tfrac{1}{2}, \sigma_2^{\theta_2^*}\right) &= \left(1-2F_l^{-1}\left(\tfrac{1}{2}\right)\right) F_h\left(\tfrac{1}{2}\right) + F_l^{-1}\left(\tfrac{1}{2}\right) \nonumber \\
       &= \left(1-2F_l^{-1}\left(\tfrac{1}{2}\right)\right) \left(1-F_l\left(\tfrac{1}{2}\right)\right) + F_l^{-1}\left(\tfrac{1}{2}\right) \label{eq:equality_F_h(1/2)=1-F_l(1/2)}\\
       &= \left(1-F_l^{-1}\left(\tfrac{1}{2}\right)\right) \left(1-2F_l\left(\tfrac{1}{2}\right)\right) + F_l\left(\tfrac{1}{2}\right) \nonumber \\
       &> F_l\left(\tfrac{1}{2}\right) \label{eq:inequality_equilbrium_above_1/2}\\
       &= \ubar v_1^{\text{Id}} \left(nt \mid \tfrac{1}{2}, \sigma_2^{\theta_2^*}\right), \nonumber
   \end{align}
   where we used Equation \eqref{eq:symmetry_F_uniform} in \eqref{eq:equality_F_h(1/2)=1-F_l(1/2)}, and $F_l\left(\tfrac{1}{2}\right)<\tfrac{1}{2}$ in \eqref{eq:inequality_equilbrium_above_1/2}.
   Hence, it is impossible that $\theta_1^*\leq \tfrac{1}{2}$ and, analogously, that $\theta_2^*\leq\tfrac{1}{2}$.

   We have thus shown that in every cursed Knight-Nash equilibrium under $F^*=\text{Id}$, both thresholds must exceed $\tfrac{1}{2}$.
   It remains to show that such an equilibrium actually exists.
   The continuous function $g$ defined in Lemma \ref{lem:g_decreasing} is monotonously decreasing on $\left[\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$, and $g\left(\tfrac{1}{2} \right)=1>\tfrac{1}{2}$ as well as $g\left(F_l^{-1}\left(\tfrac{1}{2}\right) \right) = \tfrac{1}{2}< F_l^{-1}\left(\tfrac{1}{2}\right)$, so there must be a unique $\theta^* \in \left(\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right)$ that satisfies $\theta^*=g\left(\theta^*\right)$.
   Rearranging terms, we see that for $k\in \{1,2\}$,
   \begin{align*}
       \ubar v_k^{\text{Id}}\left(nt \mid \theta^*, \sigma_{-k}^{\theta^*}\right) =F_l\left(\theta^*\right) = \left(1-2\theta^*\right) F_h\left(\theta^*\right) + \theta^* = \ubar v_k^{\text{Id}}\left(tr \mid \theta^*, \sigma_{-k}^{\theta^*}\right)
   \end{align*}
   which yields Equation \eqref{eq:symmetric_cursed_equilibrium_under_F*}.
   As $\theta^*>\frac{1}{2}$, $\ubar v_k^{\text{Id}}\left(tr \mid \theta_k, \sigma_{-k}^{\theta^*}\right)$ is strictly decreasing on $[0,1]$, while $\ubar v_k^{\text{Id}}\left(nt \mid \theta_k, \sigma_{-k}^{\theta^*}\right)$ is strictly increasing.
   It follows that for player $k$, $\sigma_k^{\theta^*}$ is a best reply against $\sigma_{-k}^{\theta^*}$, such that $\left(\sigma^{\theta^*}, \sigma^{\theta^*}\right)$ is indeed a symmetric non-trivial cursed Knight-Nash equilibrium.
   As any threshold used in such an equilibrium must satisfy \eqref{eq:symmetric_cursed_equilibrium_under_F*}, and as $\theta^*$ is the only number in $\left[\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ that solves this equation, there cannot be any further symmetric non-trivial cursed Knight-Nash equilibria.    
   %As $\bar\sigma^{\theta_{-k}}_{-k}\left(tr \mid \text{Id}\right)=\theta_{-k}>\frac{1}{2}$ , $\ubar v_k^{\text{Id}}\left(nt \mid \theta_k, \sigma_{-k}^{\theta_{-k}^*}\right)$ is strictly increasing in $\theta_k$ on $[0,1]$, while $\ubar v_k^{\text{Id}}\left(tr \mid \theta_k, \sigma_{-k}^{\theta_{-k}^*}\right)$ is decreasing.
   %Hence, $\ubar v_k^{\text{Id}}\left(nt \mid \theta_k, \sigma_{-k}^{\theta_{-k}^*}\right)=\ubar v_k^{\text{Id}}\left(tr \mid \theta_k, \sigma_{-k}^{\theta_{-k}^*}\right)$ is necessary and sufficient for $\sigma_k^{\theta_k^*}$ to be a best reply against $\sigma_{-k}^{\theta_{-k}^*}$.
   %It therefore suffices to show that there exist $\theta_1^*, \theta_2^* \in \left(\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ that satisfy
   %\begin{align} \label{eq:cursed_equilibrium_under_F*}
