   %\begin{align} \label{eq:symmetric_cursed_equilibrium_under_F*}
   %    F_l\left(\theta^*\right) = F_h\left(\theta^*\right) + \theta^* -2\theta^*F_h\left(\theta^*\right),
   %\end{align}
   %then $\left(\sigma_1^{\theta^*}, \sigma_2^{\theta^*}\right)$ is a symmetric equilibrium.
