   %It follows that there is a unique $\theta^* \in \left(\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right)$ that satisfies $\theta^*=g\left(\theta^*\right)$, such that $\left(\sigma_1^{\theta^*}, \sigma_2^{\theta^*}\right)$ is the unique symmetric non-trivial cursed Knight-Nash equilibrium under $F^*$.   
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:comparative_statics_max_min_prob_of_trade_under_F*}]
    Remark that the symmetric equilibria $\left(\sigma_1^{\theta_{\mathcal{F}}^*}, \sigma_2^{\theta_{\mathcal{F}}^*}\right)$ and $\left(\sigma_1^{\theta_{\mathcal{G}}^*}, \sigma_2^{\theta_{\mathcal{G}}^*}\right)$ exist because of Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*}.
    As before, we will assume without loss of generality that $F^*(\theta)=\theta$ for all $\theta$.
    We consider the two cases $\theta_{\mathcal{G}}^*\geq \theta_{\F}^*$ and $\theta_{\mathcal{G}}^*\leq \theta_{\F}^*$.

    In the first case, as $F_h$ and $G_h$ are increasing, $G_h\left(\theta^*_{\mathcal{G}}\right) \geq G_h\left(\theta^*_{\mathcal{F}}\right) > F_h\left(\theta^*_{\mathcal{F}}\right)$.
    Using that $1-2\theta^*_{\mathcal{G}}<0$ and $1-2F_h\left(\theta^*_{I}\right)<0$ as well as Equation \eqref{eq:symmetric_cursed_equilibrium_under_F*}, we obtain that
    \begin{align*}
        G_l\left(\theta^*_{\mathcal{G}}\right) &= \left(1-2\theta_{\mathcal{G}}^*\right) G_h\left(\theta^*_{\mathcal{G}}\right) + \theta_{\mathcal{G}}^* \\
        &< \left(1-2\theta_{\mathcal{G}}^*\right) F_h\left(\theta_{\F}^*\right) + \theta_{\mathcal{G}}^* \\
        &= \left(1-2F_h\left(\theta^*_{\F}\right)\right)\theta_{\mathcal{G}}^* + F_h\left(\theta^*_{\F}\right) \\
        &\leq \left(1-2F_h\left(\theta^*_{\F}\right)\right)\theta_{\F}^* + F_h\left(\theta^*_{\F}\right) = F_l\left(\theta_{\F}^*\right).
    \end{align*}
    In the second case, as $F_l$ and $G_l$ are increasing, $G_l\left(\theta^*_{\mathcal{G}}\right) \leq G_l\left(\theta^*_{\mathcal{F}}\right) < F_l\left(\theta^*_{\mathcal{F}}\right)$.
    Again using \eqref{eq:symmetric_cursed_equilibrium_under_F*}, we find that
    \begin{align*}
        G_h\left(\theta_{\mathcal{G}}^*\right)
        = \frac{1}{2} \frac{\theta_{\mathcal{G}}^*-G_l\left(\theta_{\mathcal{G}}^*\right)}{\theta_{\mathcal{G}}^*-\tfrac{1}{2}}
        \geq \frac{1}{2} \frac{\theta_{\F}^*-G_l\left(\theta_{\mathcal{G}}^*\right)}{\theta_{\F}^*-\tfrac{1}{2}}
        > \frac{1}{2} \frac{\theta_{\F}^*-F_l\left(\theta_{\F}^*\right)}{\theta_{\F}^*-\tfrac{1}{2}}
        = F_h\left(\theta_{\F}^*\right),
    \end{align*}
    where in the first inequality, we used that $\theta_{\F}^*>\theta_{\mathcal{G}}^*$ and that for any real numbers $a<b$, the map $x \mapsto \tfrac{x-a}{x-b}$ is strictly decreasing on $(b, \infty)$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:existence_uniqueness_cursed_uncursed_KNE}]
    Let us confirm that the described strategy profile indeed constitutes such an equilibrium.
    Following Equation \eqref{eq:w(tr)_uncertain_uncursed}, the infimal interim expected utilities of the uncursed player 2 against player 1's strategies are
    \begin{align*}
        \ubar w_2 \left( nt \mid \theta_2, \sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}\right) &= F_l(\theta_2), \text{ and} \\
        \ubar w_2 \left( tr \mid \theta_2, \sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}\right) &= 
        \begin{cases}
            \tfrac{1}{2}-F_h(\theta_2) &\text{ for } \theta_2 \leq F_h^{-1}\left(\tfrac{1}{2}\right), \\
            0 &\text{ for } \theta_2 \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right), F_l^{-1}\left(F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)\right) \right], \\
            F_l(\theta_2)-F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right) &\text{ for } \theta_2 \geq F_l^{-1}\left(F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)\right).
        \end{cases}
    \end{align*}
    It is obvious that $\ubar w_2 \left( nt \mid \theta_2, \sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}\right) > \ubar w_2\left( tr \mid \theta_2, \sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}\right)$ for $\theta_2 \geq F_h^{-1}\left(\tfrac{1}{2}\right)$ and that the utility of trading is strictly decreasing on $\left[0, F_h^{-1}\left(\tfrac{1}{2}\right)\right)$, while that of not trading is strictly increasing.
    The unique intersection $\theta_2^*$ is where $F_l(\theta_2^*) = \tfrac{1}{2}-F_h(\theta_2^*)$, that is, $\theta_2^*=\left(F_l + F_h\right)^{-1}\left(\tfrac{1}{2}\right)$.
    Hence, the cut-off strategy with threshold $\left(F_l+F_h \right)^{-1}\left(\tfrac{1}{2}\right)$ is a maxmin best reply for player 2 against player 1 playing the cut-off strategy with threshold $F_l^{-1}\left(\tfrac{1}{2}\right)$.
    As $\left(F_l+F_h \right)^{-1}\left(\tfrac{1}{2}\right) < \tfrac{1}{2}$, Lemma \ref{lem:best_responses_under_F^*} yields that for player 1, $\sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}$ is indeed a maxmin cursed best response under $F^*$.

    Whenever player 2 plays a cut-off strategy with a threshold that is no more than ${F^*}^{-1}\left(\tfrac{1}{2}\right)$, player 1 responds to this with the strategy $\sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}$.
    Hence, in order to show uniqueness, it is sufficient to confirm that there cannot be a cursed-uncursed Knight-Nash equilibrium under $F^*$ in which player 2 plays a cut-off strategy with threshold $\theta_2 > {F^*}^{-1}\left(\tfrac{1}{2}\right)$.
    If this were the case, $F_l(\theta_1)-F_h(\theta_2)=F_l(\theta_2)$ by the same arguments as above.
    Hence, 
    \begin{align*}
        F_l(\theta_1) = F_l(\theta_2)+F_h(\theta_2) > F_l\left({F^*}^{-1}\left(\tfrac{1}{2}\right)\right)+F_h\left({F^*}^{-1}\left(\tfrac{1}{2}\right)\right) = 1
    \end{align*}
    where the last equality follows from Equation \eqref{eq:symmetry_F}.
    The overall inequality is impossible.
\end{proof}



