    and 
    \begin{align*}
        \ubar v_1\left(tr \mid F_l^{-1}\left(\tfrac{1}{2}\right), \sigma_2^{\hat\theta} \right)
        &= \left(1-2F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)\right)F_h(\hat\theta)+F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right) \\
        &< 2\left( F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right) - F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)^2\right) \\
        &\leq \tfrac{1}{2} \\
        &= F_l\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right) \\
        &= \ubar v_1\left(nt \mid F_l^{-1}\left(\tfrac{1}{2}\right), \sigma_2^{\hat\theta} \right)
    \end{align*}
    where the first inequality follows from $1-2F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right) \leq 0$ and $F_h(\hat\theta)>F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)$, and the second one from $2\left(x-x^2\right)\leq \tfrac{1}{2}$ for all $x \in \R$.
    Therefore, as $\ubar v_1\left(tr \mid \cdot, \sigma_2^{\hat\theta}\right)$ is strictly decreasing and $\ubar v_1\left(nt \mid \cdot, \sigma_2^{\hat\theta}\right)$ strictly increasing on $X_2 \cup X_3$, there must be a unique $\theta_1^* \in X_2$ such that $\sigma_1^{\theta_1^*}$ is the ambiguous maxmin cursed best response to $\sigma_2^{\hat\theta}$.

    It follows that the ambiguous maxmin cursed best response to a cut-off strategy with threshold in $X_1 \cup X_3$ is a cut-off strategy with threshold in $X_2$.
    Hence, for any $\theta_1, \theta_2 \in X_1 \cup X_3$, $\left(\sigma_1^{\theta_1}, \sigma_2^{\theta_2}\right)$ cannot be an ambiguous cursed Knight-Nash equilibrium.

    Let us now show that it is not possible that one threshold lies in $X_2$ while the other one lies in $X_1 \cup X_3$.
    Assume that one player---without loss of generality, player 2---plays a cut-off strategy with threshold $\hat\theta\in X_2$.
    For any $\theta_1 \in X_1$, similar arguments as above show that
    \begin{align}
        \ubar v_1\left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right) 
        = \left( 1-2F_l(\theta_1)\right)F_l(\hat\theta)+F_l(\theta_1) > F_l(\theta_1) = \ubar v_1\left(nt \mid \theta_1, \sigma_2^{\hat\theta}\right) \label{eq:v1(tr)>v1(nt)_theta1_in_X1}
    \end{align}
    such that player 1 wants to trade for any $\theta_1 \in X_1$, in particular they will not use a cut-off strategy with some threshold in $X_1$.
    For $\theta_1 \in X_3$,
    \begin{align}
        \ubar v_1\left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right) 
        &= F_h(\theta_1)+F_h(\hat\theta) - 2 F_h(\theta_1)F_h(\hat\theta) \nonumber \\
        &= \left( 1-2F_h(\hat\theta)\right)F_h(\theta_1)+F_h(\hat\theta) \nonumber \\
        &\leq \left( 1-2F_h(\hat\theta)\right)F_l(\theta_1)+F_h(\hat\theta) \nonumber \\
        &= \left( 1-2F_l(\theta_1)\right)F_h(\hat\theta)+F_l(\theta_1) \nonumber \\
        &< F_l(\theta_1) = \ubar v_1\left(nt \mid \theta_1, \sigma_2^{\hat\theta}\right) \label{eq:v1(tr)<v1(nt)_theta1_in_X3}
    \end{align}
    such that player 1 will not want to trade for any $\theta_1 \in X_3$, in particular they will not use a cut-off strategy with threshold in $X_3$ against $\sigma_2^{\hat\theta}$.
\end{proof}

\noindent We can now state and prove an analogue to Corollary \ref{cor:fully_cursed_Knight_Nash_equilibrium_certain_median_under_F*} and show that if there is no uncertainty about the median, both players play the cut-off strategy with this unambiguous median in the cursed equilibrium.
In particular, in this case, the two approaches to incorporate Knightian uncertainty into the cursed equilibrium coincide.

\begin{corollary} \label{cor:ambiguous_fully_cursed_Knight_Nash_equilibrium_certain_median}
    In addition to Assumption \ref{ass:prior_distributions_ambiguous}, let $F_h^{-1}\left(\tfrac{1}{2}\right)= F_l^{-1}\left(\tfrac{1}{2}\right)$. 
    Then, there is an ambiguous cursed Knight-Nash equilibrium in which both players play the cut-off strategy with threshold $F_h^{-1}\left(\tfrac{1}{2}\right)= F_l^{-1}\left(\tfrac{1}{2}\right)$, and this equilibrium is the only non-trivial equilibrium in cut-off strategies.
\end{corollary}

\begin{proof}
    By Proposition \ref{prop:cut-offs_ambiguity_in_middle}, the given strategy profile is the only candidate for such an equilibrium. 
    Indeed, if player 2 plays this strategy, we know from the last paragraph of the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle} that player 1's ambiguous maxmin fully cursed best response involves playing $tr$ for $\theta_1 \in X_1$, i.e., for $\theta_1 < F_h^{-1}\left(\tfrac{1}{2}\right)=F_l^{-1}\left(\tfrac{1}{2}\right)$; and $nt$ for $\theta_1 \in X_3$, i.e., for $\theta_1 > F_h^{-1}\left(\tfrac{1}{2}\right)=F_l^{-1}\left(\tfrac{1}{2}\right)$. 
    Hence, the maxmin cursed best response against a cut-off strategy with threshold $F_h^{-1}\left(\tfrac{1}{2}\right)=F_l^{-1}\left(\tfrac{1}{2}\right)$ is this strategy itself.
\end{proof}

\noindent Before coming to the main result of this appendix, we need two auxiliary lemmas.
The first one characterizes the value of $\ubar v_k\left(tr \mid \theta_k, \sigma_{-k} \right)$ for all ``important'' types $\theta_k$ and strategies $\sigma_{-k}$, therefore providing an analogue to Lemma \ref{lem:v(nt)_and_v(tr)}.
The second lemma shows that in an ambiguous cursed Knight-Nash equilibrium, only symmetric strategies can be played.
This contrasts the equilibrium concept from the main part, where asymmetric equilibria were possible (Remark \ref{rmk:multiple_equilibria}).

\begin{lemma} \label{lem:value_of_minimum_at_cut-off}
    Let Assumption \ref{ass:prior_distributions_ambiguous} be satisfied. 
    For $k \in \{1,2\}$ and $\hat\theta \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$,
    \begin{align} \label{eq:v(tr)_in_X2}
        \ubar v_k\left(tr \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) = 
        \begin{cases}
            F_l(\theta_k)+F_l(\hat\theta) - 2 F_l(\theta_k)F_l(\hat\theta) &\text{ for } \theta_k \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right), 1-\hat\theta \right], \\
            F_h(\theta_k)+F_h(\hat\theta) - 2 F_h(\theta_k)F_h(\hat\theta) &\text{ for } \theta_k \in \left[1-\hat\theta,  F_l^{-1}\left(\tfrac{1}{2}\right) \right],
        \end{cases}
    \end{align}
    and there exists some $b(\hat\theta) \in \left[1-\hat\theta,  F_l^{-1}\left(\tfrac{1}{2}\right) \right]$ such that the unique ambiguous maxmin cursed best response against $\sigma_{-k}^{\hat\theta}$ is $\sigma_k^{b(\hat\theta)}$.
    The function $b$ is continuous and monotonously decreasing in $\hat\theta$.
\end{lemma}

\begin{proof}
    Without loss of generality, let $k=1$.
    We have seen in \eqref{eq:v(tr)_with_G,H_2} that
    \begin{align*}
        \ubar v_1\left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) \geq \min_{G,H \in \left\{ F_l, F_h \right\}} G(\theta_1)+H(\hat\theta) - 2 G(\theta_1)H(\hat\theta)
    \end{align*}
    for all $\theta_1, \hat\theta \in [0,1]$.
    For $\theta_1, \hat\theta \in X_2=\left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$, 
    \begin{align*}
        F_h(\theta_1)+F_l(\hat\theta) - 2 F_h(\theta_1)F_l(\hat\theta) 
        &= \left( 1-2F_l(\hat\theta)\right)F_h(\theta_1)+F_l(\hat\theta) \\
        &\geq \left( 1-2F_l(\hat\theta)\right)F_l(\theta_1)+F_l(\hat\theta) = F_l(\theta_1)+F_l(\hat\theta) - 2 F_l(\theta_1)F_l(\hat\theta)
    \end{align*}
    and a similar calculation shows that
    \begin{align*}
        F_l(\theta_1)+F_h(\hat\theta) - 2 F_l(\theta_1)F_h(\hat\theta) \geq F_h(\theta_1)+F_h(\hat\theta) - 2 F_h(\theta_1)F_h(\hat\theta).
    \end{align*}
    It follows that $\ubar v_1\left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) \geq \min_{F \in \left\{ F_l, F_h \right\}} F(\theta_1)+F(\hat\theta) - 2 F(\theta_1)F(\hat\theta)$ and, as the converse inequality directly follows from Equation \eqref{eq:ubar_v(tr)},
    \begin{align*}
        \ubar v_1\left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) = \min_{F \in \left\{ F_l, F_h \right\}} F(\theta_1)+F(\hat\theta) - 2 F(\theta_1)F(\hat\theta).
    \end{align*}
    As $F_l(\hat\theta)\leq\tfrac{1}{2}$, the function $\theta_1 \mapsto \left( 1-2F_l(\hat\theta)\right)F_l(\theta_1)+F_l(\hat\theta)$ is monotonously increasing in $\theta_1$ and equals $\tfrac{1}{2}$ for $\theta_1=F_l^{-1}\left(\tfrac{1}{2}\right)$.
    As $F_h(\hat\theta)\geq\tfrac{1}{2}$, the function $\theta_1 \mapsto \left( 1-2F_h(\hat\theta)\right)F_h(\theta_1)+F_h(\hat\theta)$ is monotonously decreasing in $\theta_1$ and equals $\tfrac{1}{2}$ for $\theta_1=F_h^{-1}\left(\tfrac{1}{2}\right)$.
    As $F_h^{-1}\left(\tfrac{1}{2}\right)<F_l^{-1}\left(\tfrac{1}{2}\right)$, either $F_l(\hat\theta)<\tfrac{1}{2}$ or $F_h(\hat\theta)>\tfrac{1}{2}$ (or both) such that one of the two functions must be strictly monotonous.
    Hence, they must have a unique intersection in $\left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$.
    It directly follows from Assumption \ref{ass:prior_distributions_ambiguous} that the functions coincide for $\theta_1=1-\hat\theta$, so we obtain Equation \eqref{eq:v(tr)_in_X2}.

    It remains to show the existence and uniqueness of a number $b(\hat\theta) \in \left[1-\hat\theta,  F_l^{-1}\left(\tfrac{1}{2}\right) \right]$ such that $\sigma_1^{b(\hat\theta)}$ is an ambiguous maxmin fully cursed best response against $\sigma_2^{\hat\theta}$.
    While $\ubar v_1 \left(nt \mid \cdot, \sigma_2^{\hat\theta}\right)=F_l$ is strictly increasing, $\ubar v_1 \left(tr \mid \cdot, \sigma_2^{\hat\theta}\right)$ is, by Equation \eqref{eq:v(tr)_in_X2} increasing on $\left[F_h^{-1}\left(\tfrac{1}{2}\right), 1-\hat\theta\right]$ and decreasing on $\left[ 1-\hat\theta, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$.
    Moreover, as $1-2F_h(\hat\theta)\leq 0$,
    \begin{align*}
        \ubar v_1 \left( tr \mid 1-\hat\theta, \sigma_2^{\hat\theta}\right)
        &= \left(1-2F_h(\hat\theta)\right)F_h(1-\hat\theta)+F_h(\hat\theta) \\
        &\geq \left(1-2F_h(\hat\theta)\right)\cdot 1+F_h(\hat\theta) = 1-F_h(\hat\theta) = F_l(1-\hat\theta)= \ubar v_1 \left( nt \mid 1-\hat\theta, \sigma_2^{\hat\theta}\right),
    \end{align*}
    as well as
    \begin{align*}
        \ubar v_1 \left( tr \mid F_l^{-1}\left(\tfrac{1}{2}\right), \sigma_2^{\hat\theta}\right) 
        &= \left(1-2F_h(\hat\theta)\right)F_h\left(F_l^{-1}\left(\tfrac{1}{2}\right)\right)+F_h(\hat\theta) \\
        &\leq \left(1-2F_h(\hat\theta)\right)\tfrac{1}{2}+F_h(\hat\theta) = \tfrac{1}{2} = \ubar v_1 \left( nt \mid F_l^{-1}\left(\tfrac{1}{2}\right), \sigma_2^{\hat\theta}\right).
    \end{align*}
    By continuity, there must be a unique number $b(\hat\theta) \in \left[ 1-\hat\theta, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ such that
    \begin{align*}
        \ubar v_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) &> \ubar v_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta} \right) &&\text{for } \theta_1 \in \left[1-\hat\theta, b(\hat\theta)\right), \\
        \ubar v_1 \left(tr \mid b(\hat\theta), \sigma_2^{\hat\theta} \right) &= \ubar v_1 \left(nt \mid b(\hat\theta), \sigma_2^{\hat\theta} \right), &&\text{and} \\
        \ubar v_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) &< \ubar v_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta} \right) &&\text{for } \theta_1 \in \left(b(\hat\theta), F_l^{-1}\left(\tfrac{1}{2}\right)\right].
    \end{align*}    
    For $\theta_1 \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right), 1-\hat\theta \right)$, we have $F_l(\theta_1)<\tfrac{1}{2}$ and therefore
    \begin{align*}
        \ubar v_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta}\right) 
        =\left(1-2F_l(\theta_1)\right) F_l(\hat\theta)+F_l(\theta_1)
        > F_l(\theta_1)= \ubar v_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta}\right) .
    \end{align*}
    Moreover, we know from Equations \eqref{eq:v1(tr)>v1(nt)_theta1_in_X1} and \eqref{eq:v1(tr)<v1(nt)_theta1_in_X3} that $\ubar v_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) > \ubar v_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta} \right)$ for $\theta_1 \in \left[0, F_h^{-1}\left(\tfrac{1}{2}\right)\right)$ as well as $\ubar v_1 \left(tr \mid \theta_1, \sigma_2^{\hat\theta} \right) < \ubar v_1 \left(nt \mid \theta_1, \sigma_2^{\hat\theta} \right)$ for $\theta_1 \in \left( F_l^{-1}\left(\tfrac{1}{2}\right), 1\right]$. 
    Therefore, $\sigma_1^{b(\hat\theta)}$ is indeed the unique ambiguous maxmin fully cursed best response against $\sigma_2^{\hat\theta}$.

    It remains to show that $b$ is continuous and decreasing in $\hat\theta$.
    To this end, define for each $\hat\theta \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ the auxiliary function $W_{\hat\theta} \colon \left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right] \to \R$ via
    \begin{align}
        W_{\hat\theta}(\theta_1) \colonequals F_h(\theta_1)+F_h(\hat\theta)-2F_h(\theta_1)F_h(\hat\theta) - F_l(\theta_1). \label{eq:definition_W}
    \end{align}
    We observe that $(\hat\theta, \theta_1) \mapsto W_{\hat\theta}(\theta_1)$ is continuous and that for each $\hat\theta$, $W_{\hat\theta}$ is strictly decreasing, hence invertible.
    By definition, $b(\hat\theta)=W^{-1}_{\hat\theta}(0) \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ which is well-defined by the calculations above.
    As all involved functions are continuous, $b$ is continuous.
    Moreover, $\hat\theta \mapsto W_{\hat\theta}(\theta_1)$ is monotonously decreasing for $\theta_1 \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ as $F_h(\theta_1)\geq \tfrac{1}{2}$ for these $\theta_1$.
    Hence, so is $W^{-1}_{\hat\theta}(0)$.
    Now, let $\hat\theta_k \leq \hat\theta_{ii}$ and observe that $W_{\hat\theta_k}(\theta) \geq W_{\hat\theta_{ii}}(\theta)$ for all $\theta$, in particular $0= W_{\hat\theta_k}\left(W^{-1}_{\hat\theta_k}(0)\right) \geq W_{\hat\theta_{ii}}\left(W^{-1}_{\hat\theta_k}(0)\right)$.
    Applying the decreasing function $W^{-1}_{\hat\theta_{ii}}$ to both sides of the inequality yields that $W^{-1}_{\hat\theta_{ii}}(0) \leq W^{-1}_{\hat\theta_{i}}(0)$.
    Therefore, $b(\hat\theta)=W_{\hat\theta}^{-1}(0)$ is decreasing in $\hat\theta$.
\end{proof}

\begin{lemma} \label{lem:ambiguous_cursed_Knight_Nash_equilibrium_symmetric}
    Let Assumption \ref{ass:prior_distributions_ambiguous} be satisfied.
    In every non-trivial ambiguous cursed Knight-Nash equilibrium in cut-off strategies, both players play the same strategy.
\end{lemma}

\begin{proof}
    Let the equilibrium be such that player $k$ plays the cut-off strategy $\sigma_k^{\theta_k}$.
    We have to show that $\theta_1=\theta_2$.
    By Proposition \ref{prop:cut-offs_ambiguity_in_middle}, $\theta_k \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right), F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ for $k \in \{1,2\}$.
    As $\sigma_1^{\theta_1}$ is an ambiguous fully cursed best response to $\sigma_{2}^{\theta_{2}}$ and vice versa, Lemma \ref{lem:value_of_minimum_at_cut-off} yields that $\theta_1\geq1-\theta_2$ and $\theta_2\geq1-\theta_1$ as well as
    \begin{align*}
        F_l(\theta_1) = \ubar v_1\left(nt \mid \theta_1, \sigma_2^{\theta_2}\right) &= \ubar v_1\left(tr \mid \theta_1, \sigma_2^{\theta_2}\right) \\
        &= F_h(\theta_1)+F_h(\theta_2)-2F_h(\theta_1)F_h(\theta_2) \\
        &= \ubar v_2\left( tr \mid \theta_2, \sigma_1^{\theta_1}\right) 
        = \ubar v_2\left( nt \mid \theta_2, \sigma_1^{\theta_1}\right) = F_l(\theta_2).
    \end{align*}
    As $F_l$ is strictly increasing, it follows that $\theta_1=\theta_2$.
\end{proof}

\noindent We turn to the analogue to Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*}.
In the framework from the main part, only existence of equilibria is established, while uniqueness may not hold (Remark \ref{rmk:multiple_equilibria}).
We can now show that the ambiguous cursed Knight-Nash equilibrium is unique within the class of cut-off strategies.
However, unlike in the cursed Knight-Nash equilibrium given some true distribution $F^*$, the ambiguous framework also allows for equilibria that are not in cut-off strategies.

\begin{theorem} \label{thm:existence_uniqueness_ambiguous_cursed_KNE}
    Let Assumption \ref{ass:prior_distributions_ambiguous} be satisfied.
    Then, there exists a unique non-trivial ambiguous cursed Knight-Nash equilibrium in cut-off strategies. 
    In this equilibrium, both players play the same threshold strategy\footnote{
    In this appendix, we denote optimal cut-offs by the ``curly'' $\vartheta^*$, in order to avoid confusion with the $\theta^*$ which denoted the optimal cut-offs in Subsection \ref{subsec:How_Uncertainty_Leads_Cursed_Players_To_Trade_Even_More}.
    We will later compare the two values.
    }
    $\sigma^{\vartheta^*}$.
    The threshold $\vartheta^*$ lies in $\left(\tfrac{1}{2}, F_l^{-1}\left(\tfrac{1}{2}\right)\right]$, and satisfies
    \begin{align} \label{eq:threshold_equation_ambigous_CKNE}
        2\left(F_h\left(\vartheta^*\right)-F_h\left(\vartheta^*\right)^2\right) = F_l\left(\vartheta^*\right).
    \end{align}
    Within the class of cut-off strategies, this equilibrium the only non-trivial one.
\end{theorem}

\begin{proof}
    If such an equilibrium exists, both player's thresholds must lie in $\left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ by Proposition \ref{prop:cut-offs_ambiguity_in_middle}, and by Lemma \ref{lem:ambiguous_cursed_Knight_Nash_equilibrium_symmetric}, they must be identical.
    Now, a symmetric profile of cut-off strategies $\left(\sigma_1^{\vartheta^*}, \sigma_2^{\vartheta^*}\right)$ constitutes an ambiguous cursed Knight-Nash equilibrium if and only if $\vartheta^* \in \left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ is a fixed point of the best reply function function $b$ from Lemma \ref{lem:value_of_minimum_at_cut-off}, that is, if and only if it satisfies \eqref{eq:threshold_equation_ambigous_CKNE}.
    As $b$ continuously maps $\left[ F_h^{-1}\left(\tfrac{1}{2}\right),F_l^{-1}\left(\tfrac{1}{2}\right)\right]$ onto itself, there must be such a fixed point, and as $b$ monotonously decreases, it is unique.
    As $b(\theta)\geq 1-\theta$ for all $\theta$, the fixed point $\vartheta^*$ cannot be smaller than $\tfrac{1}{2}$.
    Assume by means of contradiction that $\vartheta^*=\tfrac{1}{2}$.
    Then, by the definition of $b$, it follows that $W_{\tfrac{1}{2}}\left(\tfrac{1}{2}\right)=0$---with $W$ being defined in \eqref{eq:definition_W}---, so
    \begin{align*}
        F_l\left(\tfrac{1}{2}\right)=2\left(F_h\left(\tfrac{1}{2}\right)-F_h\left(\tfrac{1}{2}\right)^2\right)=2\left(F_l\left(\tfrac{1}{2}\right)-F_l\left(\tfrac{1}{2}\right)^2\right)<F_l\left(\tfrac{1}{2}\right),
    \end{align*}
    where the second equality follows from choosing $\theta_k=\hat\theta=\tfrac{1}{2}$ in \eqref{eq:v(tr)_in_X2} and the inequality from $F_l\left(\tfrac{1}{2}\right)<\tfrac{1}{2}$.
    The overall inequality is impossible, so $\vartheta^*$ must be greater than $\tfrac{1}{2}$.
\end{proof}

\noindent Theorem \ref{thm:existence_uniqueness_ambiguous_cursed_KNE} parallels Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*} in showing that a cursed Knight-Nash equilibrium exists, and that in any such equilibrium, more types are willing to engage in trade than if there is no uncertainty:
In the latter case, the only non-trivial cursed equilibrium is where both use the cut-off strategy with threshold $\frac{1}{2}$; if there is uncertainty, the thresholds must be strictly greater.
The underlying reasoning is the same as the one for Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*}:
while a player who refuses to trade only profits from the opponent having a low type, a cursed agent who engages in trade can seemingly profit from high as well as low types of the opponent, which mitigates the effect of uncertainty.

However, this effect is smaller in the ambiguous cursed Knight-Nash equilibrium than in the cursed Knight-Nash equilibrium given some true distribution $F^*$.

\begin{proposition}
    Let $\theta^*$ and $\vartheta^*$ be the thresholds in the cursed Knight-Nash equilibrium given $Id$ (cf. Theorem \ref{thm:existence_chracterization_fully_cursed_KNE_under_F*}), or the ambiguous cursed Knight-Nash equilibrium (cf. Theorem \ref{thm:existence_uniqueness_ambiguous_cursed_KNE}).
    It then holds that $\theta^*\geq \vartheta^*$, and the inequality is strict if $F_h(\theta)>\theta$ for all $\theta \in (0,1)$.
\end{proposition}

\begin{proof}
    Assume by means of contradiction that $\theta^*< \vartheta^*$.
    Then, as $\vartheta^*$ satisfies \eqref{eq:threshold_equation_ambigous_CKNE}, while $\theta^*$ satisfies \eqref{eq:symmetric_cursed_equilibrium_under_F*}, we obtain that
    \begin{align*}
        F_l\left(\vartheta^*\right) &= 2 \left(F_h\left(\vartheta^*\right) - F_h\left(\vartheta^*\right)^2 \right) \\
        &\leq 2 \left(F_h\left(\theta^*\right) - F_h\left(\theta^*\right)^2 \right) \\
        &= \left(1-2F_h\left(\theta^*\right)\right)F_h\left(\theta^*\right)+F_h\left(\theta^*\right) \\
        &\leq \left(1-2F_h\left(\theta^*\right)\right)\theta^*+F_h\left(\theta^*\right)
        =F_l\left(\theta^*\right).
    \end{align*}
    For the first inequality, we used that $F_h\left(\theta^*\right) < F_h\left(\vartheta^*\right)$ in combination with $x \mapsto 2\left(x-x^2\right)$ being strictly decreasing on $\left(\tfrac{1}{2}, 1\right)$; and for the second inequality, that $1-2F_h\left(\theta^*\right)<0$ and $F_h\left(\theta^*\right)\geq \theta^*$.
    We obtain that $F_l\left(\vartheta^*\right) \leq F_l\left(\theta^*\right)$ which implies $\vartheta^* \leq \theta^*$, thus we arrive at a contradiction.

    The second inequality is strict if we assume that $F_h(\theta)>\theta$ for all $\theta \in (0,1)$, which closes the proof.
\end{proof}

\noindent If the average strategy of the opponent is not derived from a true underlying distribution, but subject to minimization, the expected value of trade becomes smaller, while the expected value of refusing to trade is unaffected.
Therefore, the set of player types that engage in trade is larger in the presence of a true distribution than in the absence of such.

We proceed by revisiting the parametrizations introduced in Example \ref{ex:parametrizations}.

\begin{example}
\label{ex:examples_revisited_II}
