        \vartheta_{\kappa}^* &= \frac{4 \kappa^2 - 7 \kappa +1+\sqrt{- 7 \kappa^2 +10 \kappa+1}}{4 (\kappa^2 - 2 \kappa +1)}, \\
        \vartheta_{a}^* &= \begin{cases}
            \frac{-a^3-2a+4+a \sqrt{a^4+4a^2-4}}{4} &\text{ for } a \leq \sqrt{2}, \\
