\noindent We close this appendix by providing results parallel to Proposition \ref{prop:comparative_statics_max_min_prob_of_trade_under_F*} and Theorem \ref{thm:existence_uniqueness_cursed_uncursed_KNE}:
more uncertainty about the type distribution leads to more uncertainty about the outcome of the game, and the location of the cursed-uncursed equilibrium remains unchanged.

\begin{proposition} \label{prop:comparative_statics_max_min_prob_of_trade_ambiguous}
    Let $\F$ and $\mathcal{G}$ be two uncertainty sets that satisfy Assumption \ref{ass:prior_distributions_ambiguous}, and let $\vartheta^*_{\F}$ and $\vartheta^*_{\mathcal{G}}$ be the thresholds of the cut-off strategies played in the unique symmetric cursed Knight-Nash equilibria.
    If $G_h(\theta)>F_h(\theta)$ and $G_l(\theta)<F_l(\theta)$ for all $\theta \in (0,1)$, then $G_l\left(\vartheta^*_{\mathcal{G}}\right)<F_l\left(\vartheta^*_{\F}\right)$ and $G_h\left(\vartheta^*_{\mathcal{G}}\right)>F_h\left(\vartheta^*_{\F}\right)$.
\end{proposition}

\begin{proof}
    We consider the two cases $\vartheta^*_{\mathcal{G}}\geq \vartheta_{\F}^*$ and $\vartheta^*_{\mathcal{G}}\leq \vartheta_{\F}^*$.\footnote{
    Example \ref{ex:examples_revisited_II} shows that both cases are possible.
    }
    In the first case, as $F_h$ and $G_h$ are increasing, $G_h\left(\vartheta^*_{\mathcal{G}}\right) \geq G_h\left(\vartheta^*_{\F}\right) > F_h\left(\vartheta^*_{\F}\right)$.
    Using that $G_h\left(\vartheta^*_{\mathcal{G}}\right)$ and $F_h\left(\vartheta^*_{\F}\right)$ are both contained in $\left(\frac{1}{2}, 1\right)$ and that the map $x \mapsto 2\left(x-x^2\right)$ is strictly decreasing here, we obtain that
    \begin{align*}
        G_l\left(\vartheta^*_{\mathcal{G}}\right) = 2 \left( G_h\left(\vartheta^*_{\mathcal{G}}\right) - G_h\left(\vartheta^*_{\mathcal{G}}\right)^2\right) 
        < 2 \left( F_h\left(\vartheta^*_{\F}\right) - F_h\left(\vartheta^*_{\F}\right)^2\right) = F_l\left(\vartheta^*_{\F}\right),
    \end{align*}
    where the equalities follow from Equation \eqref{eq:threshold_equation_ambigous_CKNE}.

    In the second case, as $F_l$ and $G_l$ are increasing, $G_l\left(\vartheta^*_{\mathcal{G}}\right) \leq G_l\left(\vartheta^*_{\F}\right) < F_l\left(\vartheta^*_{\F}\right)$.
    Again using \eqref{eq:threshold_equation_ambigous_CKNE}, it holds that
    \begin{align*}
        2 \left( G_h\left(\vartheta^*_{\mathcal{G}}\right) - G_h\left(\vartheta^*_{\mathcal{G}}\right)^2\right) = G_l\left(\vartheta^*_{\mathcal{G}}\right) 
        < F_l\left(\vartheta^*_{\F}\right) = 2 \left( F_h\left(\vartheta^*_{\F}\right) - F_h\left(\vartheta^*_{\F}\right)^2\right),
    \end{align*}
    which, as $x \mapsto 2\left(x-x^2\right)$ is strictly decreasing on $\left(\frac{1}{2}, 1\right)$, completes the proof.
\end{proof}

\begin{theorem}\label{thm:existence_uniqueness_cursed_uncursed_KNE_ambiguous}
    Under Assumption \ref{ass:prior_distributions_ambiguous}, the unique non-trivial ambiguous $\left(\{1\}, \{2\}\right)$-cursed-uncursed Knight-Nash equilibrium in cut-off strategies is $\left(\sigma_1^{F_l^{-1}\left(\frac{1}{2}\right)}, \sigma_2^{\left(F_l+F_h\right)^{-1}\left(\frac{1}{2}\right)}\right)$.
\end{theorem}

\begin{proof}
    From the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle}, recall the sets $X_1 = \left[0, F_h^{-1}\left(\tfrac{1}{2}\right)\right)$, $X_2 = \left[ F_h^{-1}\left(\tfrac{1}{2}\right), F_l^{-1}\left(\tfrac{1}{2}\right) \right]$, and $X_3 = \left( F_l^{-1}\left(\tfrac{1}{2}\right), 1\right]$.
    The very same arguments as in the proof of Theorem \ref{thm:existence_uniqueness_cursed_uncursed_KNE} show that for the uncursed player 2, $\sigma_2^{\left(F_l+F_h\right)^{-1}\left(\frac{1}{2}\right)}$ is a best response against $\sigma_1^{F_l^{-1}\left(\frac{1}{2}\right)}$.
    As $\left(F_l+F_h\right)^{-1}\left(\frac{1}{2}\right) \in X_1$, it follows from the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle} that player 1's strategy is an ambiguous maxmin cursed best response against player 2's strategy.

    We turn to uniqueness.
    Assume by means of contradiction that $\left(\sigma_1^{\theta_1}, \sigma_2^{\theta_2}\right)$ is another non-trivial ambiguous cursed-uncursed Knight-Nash equilibrium in cut-off strategies.
    It is straightforward to confirm that if $\theta_1>0$, then $\theta_2=0$ does not define a maxmin best response of player 2; and if $\theta_2>0$, then $\theta_1=0$ does not define an ambiguous maxmin cursed best response of player 1.
    Hence, let both $\theta_1$ and $\theta_2$ be positive.
    By the shape of player 2's interim infimal expected utility functions, it follows that $\theta_2 < \theta_1$.
    Therefore, it is not possible that $\theta_2 \in X_3$, as in this case, by the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle}, player 1's ambiguous cursed maxmin best reply involves a cut-off in $X_2$.
    For any $\theta_2 \in X_1$, player 1's best reply is the cut-off strategy with threshold $F_l^{-1}\left(\tfrac{1}{2}\right)$, so we arrive at the already established equilibrium $\left(\sigma_1^{F_l^{-1}\left(\tfrac{1}{2}\right)}, \sigma_2^{\left(F_l + F_h\right)^{-1}\left(\tfrac{1}{2}\right)}\right)$.
    The remaining case is where $\theta_2 \in X_2$.
    Again by the proof of Proposition \ref{prop:cut-offs_ambiguity_in_middle}, player 1 will not use a cut-off strategy with threshold in $X_3$, so---as $\theta_1 \in X_1$ is precluded by $\theta_2 < \theta_1$---$\theta_1 \in X_2$ as well. 
    In particular, $\theta_1 \leq F_l^{-1}\left(\tfrac{1}{2}\right)$.
    Using the best reply condition of player 2, $F_h(\theta_2)< F_l(\theta_2)+F_h(\theta_2)=F_l(\theta_1)\leq \tfrac{1}{2}$, so $\theta_2 < F_h^{-1}\left(\tfrac{1}{2}\right)$.
    But this is impossible as $\theta_2 \in X_2$.
\end{proof}




\section{Online Appendix II: Partial Cursedness}
\label{app:Partial_Cursedness}

\citet{eyster_rabin_2005} defined a more general equilibrium concept than the one presented in Definition \ref{def:cursed_equilibrium}, allowing players to be \emph{partially cursed}.
This means that their interim perceived expected utility given their types and their opponent's strategies is a convex combination of the fully rational $w_k$ (Equation \eqref{eq:definition_w}) and the fully cursed $v_k$ (Equation \eqref{eq:definition_v}).

\begin{definition} \label{def:partially_cursed_equilibrium}
    Let  $\Gamma = \left( N, \left(A_k\right)_{k\in N}, \left(\Theta_k\right)_{k\in N}, \left(u_k\right)_{k \in N}, \Prob \right)$ be a Bayesian game as specified at the beginning of Section \ref{sec:Several_Equilibrium_Concepts}, and let $\bar\sigma_k$ be the average strategy of player $k$ as defined in \eqref{eq:average_strategy}.
    For any $\chi \in [0,1]$ and strategy profile $\sigma_{-k}$ of $k$'s opponents, $\sigma_k$ is a \emph{$\chi$-cursed best response} against $\sigma_{-k}$ if for each $\theta_k \in \Theta$, and each $a_k^*$ such that $\sigma_k\left(a_k^* \mid \theta_k\right)>0$,
    \small
    \begin{align}
        a_k^* &\in \argmax_{a_k \in a_k} v_k^{\chi}\left(a_k\mid \theta_k, \sigma_{-k}\right), \text{ where} \nonumber \\
        v_k^{\chi}\left(a_k\mid \theta_k, \sigma_{-k}\right) &\colonequals \int_{\Theta_{-k}}
        \sum_{a_{-k} \in A_{-k}} {\left[ \chi \bar{\sigma}_{-k}\left(a_{-k}\mid \theta_k, \Prob\right) + (1-\chi) \sigma_{-k}\left(a_{-k} \mid \theta_{-k}\right)\right] }
        u_i\left(a_k, a_{-k} ; \theta_k, \theta_{-k}\right) \d\Prob\left(\theta_{-k}\mid \theta_k\right)\label{eq:definition_v^chi}
    \end{align}
    \normalsize
    is the \emph{$\chi$-perceived interim expected utility} of action $a_k$, given the own type $\theta_k$ and the opponents' strategy profile $\sigma_{-k}$.
    A strategy profile $\sigma^*$ is a \emph{$\left(\chi_k\right)_{k \in N}$-cursed equilibrium} if for each $k\in N$, $\sigma^*_k$ is a $\chi_k$-cursed best response against $\sigma^*_{-k}$.
\end{definition}

\noindent It directly follows from the definition that if $\chi_k=0$ for all $k\in N$, we arrive at the Bayesian Nash Equilibrium, and if $\chi_k=1$ for all $k$, the fully cursed equilibrium (Definition \ref{def:cursed_equilibrium}).
Moreover,
\begin{align} \label{eq:partially_cursed_convex_combination}
    v_k^{\chi}\left(a_k \mid \theta_k, \sigma_{-k}\right) &= \chi v_k^1\left(a_k \mid \theta_k, \sigma_{-k}\right) + (1-\chi) v_k^0\left(a_k \mid \theta_k, \sigma_{-k}\right) \nonumber \\
    &= \chi v_k\left(a_k \mid \theta_k, \sigma_{-k}\right) + (1-\chi) w_k\left(a_k \mid \theta_k, \sigma_{-k}\right)
\end{align}
with $v_k$ and $w_k$ having been defined in Equations \eqref{eq:definition_v} and \eqref{eq:definition_w}, respectively.

While the degrees of cursedness can be different among players, they are still fixed. 
This contrasts the concept of \emph{$f$-generalized cursed equilibrium} in \citet{eyster_rabin_2005} where the degrees of cursedness as well as the types of players are drawn from some joint probability distribution $f$.

The partially cursed equilibrium has been found difficult to justify in terms of a learning foundation \citep{eyster_rabin_2005}, but nevertheless used to quantify deviation from full rationality in empirical investigations \citep{eyster_rabin_2005, christensen_2008, szembrot_2018}.

In our two-player game, we have classified $\left(\chi_1, \chi_2\right)$-cursed equilibria for the cases $\left(\chi_1, \chi_2\right)=(0,0)$, $\left(\chi_1, \chi_2\right)=(1,1)$, and $\left(\chi_1, \chi_2\right)=(1,0)$ in the main part (Propositions \ref{prop:BNE_is_nt} and \ref{prop:cNE_is_median_cutoff} and Theorem \ref{thm:existence_uniqueness_cursed_uncursed_KNE}).
In this appendix, we shall find partially cursed equilibria for all other combinations of $\chi_1$ and $\chi_2$.
For tractability, we restrict ourselves to the case where there is no uncertainty about the probability distribution, and follow the assumptions made in Section \ref{sec:The_Trading_Game_Without_Uncertainty}:
types are independent and identically drawn according to some probability distribution $F$ on $[0,1]$ that is strictly increasing and continuous.
As before, we abuse notation by writing $\bar\sigma_{-k}\left(a_{-k}\right)$ instead of $\bar\sigma_{-k}\left(a_{-k} \mid \theta_k, \Prob_F\right)$ 

As a first step to finding the equilibria, we show that we can restrict ourselves to cut-off strategies (Definition \ref{def:cut-off_strategy}).

\begin{lemma}\label{lem:best_response_cut_off}
    Let $k \in \{1,2\}$.
    Whenever $\sigma_{-k}$ is such that player $-k$ sometimes trades ($\Bar{\sigma}_{-k}(tr)>0$) and player $k$ is at least partially cursed ($\chi_k>0$), every $\chi_k$-cursed best response against $\sigma_{-k}$ must be a cut-off strategy.
\end{lemma}
\begin{proof}
    We find that the $\chi_k$-cursed expected difference between not trading and trading at type $\theta_k$, given the opponent's strategy $\sigma_{-k}$, is
    \small
    \begin{align*}
        &d_k^{\chi_k} \left( \theta_k, \sigma_{-k} \right) \\
        \colonequals &v_k^{\chi_k}\left(nt \mid \theta_k, \sigma_{-k}\right) - v_k^{\chi_k}\left(tr \mid \theta_k, \sigma_{-k}\right) \\
        = &\chi_k \Bar{\sigma}_{-k} \left(tr\right) \int_0^1 \mathbbm{1}_{\{\theta_k > \theta_{-k}\}} - \mathbbm{1}_{\{\theta_{-k} > \theta_{k}\}} \d F\left(\theta_{-k}\right) + \left(1-\chi_k\right) \int_0^1 \sigma_{-k}\left(tr \mid \theta_{-k} \right) \left(\mathbbm{1}_{\{\theta_k > \theta_{-k}\}} - \mathbbm{1}_{\{\theta_{-k} > \theta_{k}\}} \right) \d F\left(\theta_{-k}\right) \\
        = &\chi_k \Bar{\sigma}_{-k} \left(tr\right) \left( 2F\left(\theta_k\right)-1\right) + \left(1-\chi_k\right) \int_0^1 \sigma_{-k}\left(tr \mid \theta_{-k} \right) \left(\mathbbm{1}_{\{\theta_k > \theta_{-k}\}} - \mathbbm{1}_{\{\theta_{-k} > \theta_{k}\}} \right) \d F \left(\theta_{-k}\right).
    \end{align*}
    \normalsize
    Both summands are increasing in $\theta_k$, and the first one is strictly increasing. 
    Hence, this also holds for the sum, so there must be a unique threshold $\hat\theta$ such that $d_k^{\chi_k} \left( \theta_k, \sigma_{-k} \right)$ is negative for $\theta \in \left[0,\hat\theta\right)$ and positive for $\theta \in \left(\hat\theta, 1\right]$ (Note that one of these intervals might be empty.), which proves the claim.
\end{proof}

\begin{remark}
    If the opposing player $-k$ (almost surely) never trades, every strategy is a $\chi_k$-cursed best response, as the behavior of player $k$ has no effect on the outcome of the game. 
    If $k$ is not cursed ($\chi_k=0$), then $d_k^0 \left( \theta_k, \sigma_{-k} \right) = \int_0^1 \sigma_{-k}(tr \mid \theta_{-k}) \left(\mathbbm{1}_{\{\theta_k > \theta_{-k}\}} - \mathbbm{1}_{\{\theta_{-k} > \theta_{k}\}} \right) \d F\left(\theta_{-k}\right)$ which, depending on $\sigma_{-k}$, can be constantly 0 on some interval. 
    In this case, there is still a cut-off strategy that is a best response, but also various other strategies.
\end{remark}

\noindent Given that the opponent plays a cut-off strategy with threshold $\hat\theta$, it immediately follows from Lemma \ref{lem:v(nt)_and_v(tr)} in combination with Equation \eqref{eq:partially_cursed_convex_combination} that for any $\chi_k \in [0,1]$, player $k$'s $\chi_k$-perceived interim expected utilities from playing $nt$ or $tr$ are
\begin{align}
    v_k^{\chi_k}\left(nt \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= F(\theta_k) \text{ and}\label{eq:v(nt)_partial} \\
    v_k^{\chi_k}\left(tr \mid \theta_k, \sigma_{-k}^{\hat\theta} \right) &= (1-\chi_k) \LV F\left(\theta_k\right)-F(\hat\theta) \RV + \chi_k \left[ F\left(\theta_1\right) + F(\hat\theta) - 2F\left(\theta_k\right)F(\hat\theta)\right]. \label{eq:v(tr)_partial}
\end{align}

\noindent We can now explicitly derive $\chi$-cursed best responses in this game.

\begin{lemma} \label{lem:formula_best_response}
    For player $k$, the unique $\chi$-cursed best response against a cut-off strategy with threshold $\hat\theta_{-k}>0$ is a cut-off strategy with threshold $b_{\chi}^*(\hat\theta_{-k})$, where
    \begin{align*}
        b_{\chi}^*\left(\theta\right)&= F^{-1}\left(\tfrac{1}{2}F(\theta)\right) &&\text{for } \chi=0, \\
         b_{\chi}^*\left(\theta\right) &= F^{-1} \left( \frac{F(\theta)}{2\left(1-\chi+\chi F(\theta)\right)} \right) &&\text{for } \chi \in \left(0, \tfrac{1}{2}\right], \text{ and}\\
         b_{\chi}^*\left(\theta\right) &= \begin{cases}
            F^{-1}\left(\frac{2\chi-1}{2\chi}\right) &\text{ for } \theta \leq F^{-1}\left(\frac{2\chi-1}{2\chi}\right), \\
            F^{-1} \left( \frac{F(\theta)}{2\left(1-\chi+\chi F(\theta)\right)} \right) &\text{ for } \theta > F^{-1}\left(\frac{2\chi-1}{2\chi}\right)
            \end{cases}
            &&\text{for }\chi \in \left(\tfrac{1}{2}, 1\right].
    \end{align*}
\end{lemma}

\begin{proof}
    Without loss of generality, let $k=1$ such that $-k=2$. 
    Assume that player 2 plays the cut-off strategy $\sigma_2^{\hat\theta_2}$ with threshold $\hat\theta_2>0$. 
    Then, for player 1, 
    \begin{align}
        &d_1^{\chi}\left(\theta_1, \sigma_2^{\hat\theta_2}\right) \nonumber\\
        = &v_1^{\chi}\left(nt \mid \theta_1, \sigma_2^{\hat\theta_2} \right) - v_1^{\chi}\left(tr \mid \theta_1, \sigma_2^{\hat\theta_2} \right) \\
        = &\chi F(\hat\theta_2) \left(2F\left(\theta_1\right) -1 \right) + (1-\chi) \int_0^{\hat\theta_2} \mathbbm{1}_{\{\theta_1>\theta_2\}} - \mathbbm{1}_{\{\theta_1<\theta_2\}} \d F\left(\theta_2\right) \nonumber\\
        = &\begin{cases}
        \chi F(\hat\theta_2) \left(2F\left(\theta_1\right) -1 \right) + (1-\chi) \left[ 2F\left(\theta_1\right)-F(\hat\theta_2) \right] &\text{ if } \theta_1< \hat\theta_2,\\
        \chi F(\hat\theta_2) \left(2F\left(\theta_1\right) -1 \right) + (1-\chi)F(\hat\theta_2) &\text{ if } \theta_1\geq\hat\theta_2.            
        \end{cases} \label{eq:u(nt)-u(tr)_formula_best_response}
    \end{align}
    For $\chi=0$, this expression is positive if and only if $2F\left(\theta_1\right)-F(\hat\theta_2)>0$, that is, if and only if $\theta_1> F^{-1}\left(\frac{1}{2}F(\hat\theta_2)\right)=b_{0}^*(\hat\theta_2)$.

    Assume now that $\chi> \frac{1}{2}$. 
    As $d_1^{\chi}\left(\theta_1, \sigma_2^{\hat\theta_2}\right)$ is negative for $\theta_1=0$, positive for $\theta_1=1$, and strictly increasing in $\theta_1$, there is a unique threshold $b_{\chi}^*(\hat\theta_2)$ such that $d_1^{\chi}\left(\theta_1, \sigma_2^{\hat\theta_2}\right)$ is positive if and only if $\theta_1 > b_{\chi}^*(\hat\theta_2)$.
    It is immediate to verify that the first part of \eqref{eq:u(nt)-u(tr)_formula_best_response} is positive if and only if $\theta_1 > F^{-1} \left( \frac{F(\hat\theta_2)}{2\left(1-\chi+\chi F(\hat\theta_2)\right)} \right)$, while the second part is positive if and only if $\theta_1 > F^{-1}\left(\frac{2\chi-1}{2\chi}\right)$.
    As $d_1^{\chi}\left(\theta_1, \sigma_2^{\hat\theta_2}\right)$ is continuous in $\theta_1$, it depends on the sign of $d_1^{\chi}\left(\hat\theta_2, \sigma_2^{\hat\theta_2}\right)$ which of these two values equals $b_{\chi}^*(\hat\theta_2)$.
    If $\hat\theta_2 \leq F^{-1}\left(\frac{2\chi-1}{2\chi}\right)$, it holds that $d_1^{\chi}\left(\hat\theta_2, \sigma_2^{\hat\theta_2}\right)\leq 0$ such that $b_{\chi}^*(\hat\theta_2)$ must be greater than or equal $\hat\theta_2$; hence, $b_{\chi}^*(\hat\theta_2)=F^{-1}\left(\frac{2\chi-1}{2\chi}\right)$.
    Similarly, $\hat\theta_2 > F^{-1}\left(\frac{2\chi-1}{2\chi}\right)$ implies that $d_1^{\chi}\left(\hat\theta_2, \sigma_2^{\hat\theta_2}\right)> 0$, so $\hat\theta_2$ is smaller than $b_{\chi}^*(\hat\theta_2)$ which therefore equals $F^{-1} \left( \frac{F(\hat\theta_2)}{2\left(1-\chi+\chi F(\hat\theta_2)\right)} \right)$.

    Finally, for $\chi \in \left(0, \frac{1}{2}\right]$, the second part of \eqref{eq:u(nt)-u(tr)_formula_best_response} is always nonnegative. 
    Therefore, the threshold for which the utilities from trading and not trading are equal must be at $F^{-1} \left( \frac{F(\hat\theta_2)}{2\left(1-\chi+\chi F(\hat\theta_2)\right)} \right)=b_{\chi}^*(\hat\theta_2)$.
\end{proof}

\begin{corollary} \label{cor:formula_best_response_monotonicity_properties}
    For every $\chi \in [0,1]$, $b^*_{\chi}$ is increasing on $(0,1]$.
    For $\chi \in \left[0, \frac{1}{2}\right]$, the function is strictly increasing on $[0,1]$, while for $\chi \in \left[\frac{1}{2},1\right)$, it is so for $\theta\geq F^{-1} \left( \frac{2\chi-1}{2\chi} \right)$.
    Moreover, for any fixed $\theta \in (0,1)$, $\chi \mapsto b_{\chi}^*\left(\theta\right)$ is strictly increasing on $[0,1]$.
\end{corollary}

\begin{proof}
    Using the definition of $b^*_{\chi}$, one can take the derivative of $F\left(b^*_{\chi}\left(\theta\right) \right)$ with respect to $F(\theta)$, and use that $F$ and $F^{-1}$ are strictly increasing.
\end{proof}

