\begin{proposition}[Collapse of Latent Reconstruction Loss]
    \label{prop:collapse-of-latent-loss}
    Given $\mathcal{O},\ \mathcal{S},\ \mathcal{A} \subseteq \mathbb{R}^d$ and functions $h: \mathcal{O} \rightarrow \mathcal{S}$, $f: \mathcal{S} \times \mathcal{A} \rightarrow \mathcal{S}$, and latent reconstruction loss: $$\mathcal{L}_{\text{latent}}(h, f) = \mathbb{E}_{(o, a, o') \sim \mathcal{D}} \left[ \left\lVert f(h(o), a) - h(o') \right\rVert \right],$$
    There exists $(h^*, f^*)$ and $c \in \mathcal{S}$, such that $h^*(o) = c$ for all $o \in \mathcal{O}$ and $f^*(c, a) = c$ for all $a \in \mathcal{A}$, such that: $$\mathcal{L}_{\text{latent}}(h^*, f^*) = \min_{h, f} \mathcal{L}_{\text{latent}}(h, f)$$
\end{proposition}
\begin{explanation}
    If you have an encoder and a world model, and you train it using the latent reconstruction loss, there is a cheat configuration for the model to minimize the loss while learning nothing about the true dynamics.
\end{explanation}
\begin{proof}[Proof Sketch]
    If we construct such a degenerate solution $(h^*, f^*)$, this solution satisfies $\mathcal{L}_{\text{latent}}(h^*, f^*) = 0$, which is a global minimum as $\mathcal{L}_{\text{latent}}(h, f) \geq 0$ for all $(h, f)$.
\end{proof}
\begin{proposition}[Non-Collapse of Generative Loss]
    \label{prop:non-collapse-of-gen-loss}
    Given functions $h: \mathcal{O} \rightarrow \mathcal{S}$, $f: \mathcal{S} \times \mathcal{A} \rightarrow \mathcal{S}$, $g: \mathcal{S} \to \mathcal{O}$, and generative loss: $$\mathcal{L}_{\text{gen}}(h, f, g) = \mathbb{E}_{(o, a, o') \sim \mathcal{D}} \left[ \left\lVert g \circ f(h(o), a) - o' \right\rVert \right],$$
    Assuming $\exists (o_1, a_1, o_2),\ (o_3, a_3, o_4) \in \mathcal{D}$ such that $o_2 \neq o_4$, then given $(h', f')$, fixed $g'$ and $c \in \mathcal{S}$ such that $h'(o) = c \ \forall o \in \mathcal{O}$ and $f'(c, a) = c \ \forall a \in \mathcal{A}$, there exists $(\tilde{h}, \tilde{f})$ such that: $$\mathcal{L}_{\text{gen}}(\tilde{h}, \tilde{f}, g') < \mathcal{L}_{\text{gen}}(h', f', g')$$
\end{proposition}
\begin{explanation}
    If you add a decoder to the model and train it with the generative loss, assuming the data contains different next-observation targets, there will always be another set of encoder and world model that gets lower loss than the previous cheat configuration.
\end{explanation}
\begin{proof}[Proof Sketch]
    Given degenerate solution $(h', f')$ and fixed $g'$, construct $(\tilde{h}, \tilde{f})$ to be equal to $(h', f')$ at every point except $(o_1, a_1, o_2)$ and $(o_3, a_3, o_4)$ where $o_2 \neq o_4$ and the constant-valued $(h', f')$ will get non-zero loss. Instead, set $(\tilde{h}, \tilde{f})$ to perfectly fit these two targets, so they will get zero loss. Thus we have:
    $$\mathcal{L}_{\text{gen}}(\tilde{h}, \tilde{f}, g') < \mathcal{L}_{\text{gen}}(h', f', g')$$
\end{proof}
Details of the proofs of both propositions are available in Appendices~\ref{appendix:proof-collapse-of-latent-loss} and \ref{appendix:proof-non-collapse-of-gen-loss}, respectively.

