\begin{theorem}[Latent reconstruction is an upper-bounded surrogate for generative reconstruction]
\label{thm:latent-lower-bound-generative}
    Given sufficiently powerful encoder $h: \mathcal{O} \to \mathcal{S}$ and decoder $g: \mathcal{S} \to \mathcal{O}$, such that for all latent states $\hat{s} \in \mathcal{S}$, the roundtrip reconstruction error satisfies $\left\lVert h \circ g(\hat{s}) - \hat{s} \right\rVert \leq \epsilon$ for some small $\epsilon > 0$. For world model $f: \mathcal{S} \times \mathcal{A} \to \mathcal{S}$ and transition data $(o, a, o') \sim \mathcal{D}$, define the latent-space loss $\mathcal{L}_{\text{latent}}$ and the generative loss $\mathcal{L}_{\text{gen}}$ as below: 
    \[
        \mathcal{L}_{\text{latent}} = \left\lVert f(h(o), a) - h(o') \right\rVert,
        \qquad
        \mathcal{L}_{\text{gen}} = \left\lVert g \circ f(h(o), a) - o' \right\rVert.
    \]
    Assume that encoder $h$, decoder $g$, and world model $f$ induce the following conditional distributions:
    \[
        \hat{s} \mid o \sim \mathcal{N}(h(o), I),
        \quad
        \hat{o} \mid \hat{s} \sim \mathcal{N}(g(\hat{s}), I),
        \quad
        \text{and }
        \hat{s}' \mid \hat{s}, a \sim       \mathcal{N}(f(\hat{s}, a), I).
    \]
    Then, the following inequality holds:
    \[
        \mathcal{L}_{\text{latent}} \leq \mathcal{L}_{\text{gen}} + \epsilon,
    \]
    with $\mathcal{L}_{\text{latent}} = \mathcal{L}_{\text{gen}}$ 
    when $h \circ g(\hat{s}) = \hat{s}$ for all $\hat{s} \in \mathcal{S}$ and $\supp(\mathcal{D}) \subseteq \image(g)$.
    % when $g$ is invertible and $h = g^{-1}$.
\end{theorem}
% \mingkai{TODO: Make sure to show in the detailed proof how this inequality is tight given the condition}
%\mingkai{Updated explanation to emphasize that the losses being equal is unrealistic}
\begin{explanation}
    If your encoder and decoder approximately undo each other, then the JEPA latent reconstruction loss is upper-bounded by the generative loss plus a small reconstruction error. These losses are only equal when the encoder-decoder pair perfectly invert each other, which is unrealistic in practice.  
    % Only in the ideal case do these two losses match. 
    As such, \underline{minimizing the latent loss does not guarantee consistency with observed data}, which is required for minimizing the generative loss (Figure~\ref{fig:latent-gen-proof}).
\end{explanation}
\begin{proof}[Proof Sketch]
Observe that the two losses $\mathcal{L}_{\text{latent}}$ and $\mathcal{L}_{\text{gen}}$ are scaled KL divergences of the Gaussian prediction distributions in the latent and observation spaces, respectively. Apply the encoder $h$ to both the observation prediction and true observation distributions in $\mathcal{L}_{\text{gen}}$, and the \textbf{data processing inequality} states that the augmented KL divergence is upper-bounded by the original $\mathcal{L}_{\text{gen}}$. After that, apply the triangle inequality to show that $\mathcal{L}_{\text{latent}}$ is upper-bounded by the sum of this augmented KL (upper-bounded by $\mathcal{L}_{\text{gen}}$) and the roundtrip reconstruction error (upper-bounded by $\epsilon$), thus completing the proof. (We include the detailed proof in Appendix~\ref{appendix:latent-lower-bound-generative}.)
\end{proof}


