\subsection{Decision-Making}


\begin{figure}
    \centering
    \includegraphics[width=0.5\linewidth]{figures/13-decision-making-figure.pdf}
    \caption{Illustration of PAN-based world model for decision-making in a web agent}
    \label{fig:decision-making-figure}
