\section{Proof for Theorem~\ref{thm:completeness-of-language}}
\label{appendix:proof-completeness-of-language}
\begin{proof}
We will prove the countrapositive that $f_\epsilon(\mathbf{x}) = f_\epsilon(\mathbf{x}') \Rightarrow \| \mathbf{x} - \mathbf{x}' \| \leq \epsilon$.

Based on the conditions, we have it that $\| \mathbf{x} - \mathbf{x}' \| = \sum_{t=1, d=1}^{T, D} (x_{td} - x'_{td})^2 \leq \epsilon = \Tilde{\epsilon}^2$, which is satisfied when $|x_{td} - x'_{td}| \leq \frac{\tilde{\epsilon}}{\sqrt{TD}}$.
% \begin{align*}
% \| \mathbf{x} - \mathbf{x}' \| &\leq \epsilon = \Tilde{\epsilon}^2 \\
% \sum_{t=1}^T \sum_{d=1}^D (x_{td} - x'_{td})^2 &\leq \Tilde{\epsilon}^2
% \end{align*}

Because $\| x_t \| \leq K \vcentcolon= \frac{\Tilde{K}^2}{4}$, we have that $| x_{td} | \leq \frac{\Tilde{K}}{2} \ \forall d \in [1, D]$. Therefore, to satisfy the condition that $\| \mathbf{x} - \mathbf{x}' \| \leq \epsilon$, we need to divide the interval $\left[-\frac{\Tilde{K}}{2}, \frac{\Tilde{K}}{2}\right]$ into subintervals with length at most $\frac{\tilde{\epsilon}}{\sqrt{TD}}$, of which there are $\lceil \sqrt{TD} \Tilde{K} \tilde{\epsilon}^{-1} \rceil$ of them.
Further, because there are $TD$ such intervals to divide, the support of our code should be at least as large as the number of required subintervals as below:
\[ |\mathcal{V}|^M \geq \lceil \sqrt{TD} \Tilde{K} \tilde{\epsilon}^{-1} \rceil^{TD}  \] 

In the two cases below, we will attempt to construct this support by scaling the vocabulary size $|\mathcal{V}|$ and the code length $M$ individually. It is technically also possible to scale both at the same time, but we focus on the existence for this proof, and leave more efficient solutions to future work.

\textbf{Case 1} (Modality Tokenizer): Take $N = T$, and construct a vocabulary $\mathcal{V}$ with size $M_\epsilon = \lceil \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rceil ^D$. We then define the encoding function for $x$ as $f_\epsilon(x) = (c_1, \dots, c_T)$ where $c_t \in \mathcal{V}$. We define the index of $c_t$ as a $D$-digit number of base-$M_\epsilon$
$$(d_1(c_t), d_2(c_t), \dots, d_D(c_t)),$$
where $d_n(c_t) = \lfloor \frac{x_{tn} + \tilde{K} / 2}{\tilde{\epsilon} / \sqrt{TD}} \rfloor$ is the $n$-th digit. Note that this is well defined because $d_n(c_t) \in \left[0, \lfloor \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rfloor \right]$, and thus enables the representation of $\lceil \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rceil^D$ unique values for $c_t$ using $D$ digits.
This way, given $f_\epsilon(x) = f_\epsilon(x')$, since $c_t = c_t'\ \forall t \in [1, T]$, we have $d_n(c_t) = d_n(c_t')\ \forall n \in [1, D]$, which implies that $|x_{tn} - x'_{tn}| \leq \tilde{\epsilon} / \sqrt{TD}$. Thus, we have
\begin{align}
\| x - x' \| = \sum_{t=1,d=1}^{T, D} (x_{td} - x'_{td})^2 \leq \sum_{t=1,d=1}^{T, D} \frac{\tilde{\epsilon}^2}{TD} = \epsilon
\end{align}
\textbf{Case 2} (Finding a Language Expression): Assume that the vocabulary has a fixed size $|\mathcal{V}| = N$ (which applies to a wide range of natural and machine languages). Take sequence length $N_\epsilon = TD \lceil \log_M \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rceil$ and define 
$$f_\epsilon(\mathbf{x}) = (c_1, \dots, c_{N_\epsilon}),\ c_t \in \mathcal{V},$$
We map each $x_{td}$ to a number $u_{td} \in [0, 1]$ represented by $L$ digits of base-$N$, where the $n$-th digit $d_n(u_{td}) = c_{s + n}$. 
In this manner, $x_{td}$ will correspond to subsequence $(c_{s+1}, c_{s+2}, \dots, c_{s+L})$, where $s = (td - 1) \lceil \log_M \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rceil$ and $L = \lceil \log_N \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rceil$.
Thus, we have that
\begin{align}
x_{td} = \left( \sum_{n=1}^L \frac{d_n(u_{td})}{M^n} - \frac{1}{2} \right) \tilde{K}.
\end{align}
Now, given $\mathbf{x}, \mathbf{x}'$ where $f_\epsilon(\mathbf{x}) = f_\epsilon(\mathbf{x}')$, we have $f_\epsilon(\mathbf{x})_{td} = f_\epsilon(\mathbf{x}')_{td}$ and $d_n(u_{td}) = d_n(u_{td})$, so $u_{td}$ and $u'_{td}$ must lie in the same interval formed by numbers for which all digits $d_n$ are identical as below:
\begin{align} 
\left[ u:\ d_n(u) = v_n,\ n = 1, \dots, L \right] = \left[ 
\sum_{n=1}^L \frac{v_n}{M^n}, \sum_{n=1}^L \frac{v_n}{M^n} + \frac{1}{M^L} \right)
\end{align}
Thus we have
\begin{align*}
    |x_{td} - x_{td}'|
    &= \left| \left( \sum_{n=1}^L \frac{d_n(u_{td})}{M^n} - \frac{1}{2} \right) \tilde{K} - \left( \sum_{n=1}^L \frac{d_n(u_{td}')}{M^n} - \frac{1}{2} \right) \tilde{K} \right| 
    = \left| \left( \sum_{n=1}^L \frac{d_n(u_{td})}{M^n} - \sum_{n=1}^L \frac{d_n(u_{td}')}{M^n} \right) \tilde{K} \right| \\
    &\leq \left| M^{-L} \tilde{K} \right| = \left| M^{-\lceil \log_M \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1} \rceil} \tilde{K} \right| 
    \leq \left| M^{-\log_M \sqrt{TD} \tilde{K} \tilde{\epsilon}^{-1}} \tilde{K} \right| \leq \left| \frac{\tilde{\epsilon}}{\sqrt{TD}} \right|
\end{align*}
And by extension
$\| \mathbf{x} - \mathbf{x}' \| \leq \epsilon$
\end{proof}

\section{Proof for Proposition~\ref{prop:collapse-of-latent-loss}}
\label{appendix:proof-collapse-of-latent-loss}
\begin{proof}
    We will prove the proposition by constructing such a $(h^*, f^*)$ pair such that $\mathcal{L}_{\text{latent}}(h^*, f^*) = \min_{h, f} \mathcal{L}_{\text{latent}}(h, f)$. ($(h^*, f^*)$ is the global minimum of $\mathcal{L}_{\text{latent}}$.) \\
    This could be simply done by finding arbitrary $c \in \mathbb{R}^n$ and letting $h^*(o) = c$ for all $o \in \mathcal{O}$ and $f^*(c, a) = c$ for all $a \in \mathcal{A}$. Then, we have that $\mathcal{L}_{\text{latent}}(h^*, f^*) = 0$. Since $\mathcal{L}_{\text{latent}}$ is a distance measurement, we have that $\mathcal{L}_{\text{latent}} \geq 0$, which means that $(h^*, f^*)$ is the global minimum.
\end{proof}

\section{Proof for Proposition~\ref{prop:non-collapse-of-gen-loss}}
\label{appendix:proof-non-collapse-of-gen-loss}
\begin{proof}
We prove the proposition by showing that, with the generative loss $\mathcal{L}_{\text{gen}}$, there is no solution that can be both degenerate and optimal at the same time. More specifically, for any degenerate solution $(h', f')$, and fixed $g$, there must be a way to construct another solution $(\tilde{h}, \tilde{f})$ which yields a lower loss value. \\
More formally, without loss of generality, assume that we have:
\begin{itemize}
    \item Some arbitrary constant $c \in \mathbb{R}^n$;
    \item $h’: \mathcal{O} \rightarrow \mathcal{S}$ such that $h’(o) = c$ for all $o \in \mathcal{O}$;
    \item $f’: \mathcal{S} \times \mathcal{A} \rightarrow \mathcal{S}$ such that $f’(c, a) = c$ for all $a \in \mathcal{A}$;
    \item A fixed decoder $g: \mathcal{S} \rightarrow \mathcal{O}$;
    \item A dataset $\mathcal{D} \subset \mathcal{O} \times \mathcal{A} \times \mathcal{O}$ containing at least two distinct triplets:
    $$(o_1, a_1, o_2),\quad (o_3, a_3, o_4) \in \mathcal{D} \text{ with } o_2 \ne o_4.$$
\end{itemize}
Assuming all the function families are sufficiently expressive. Then, under the degenerate solution $(h’, f’)$, for any $(o, a, o’) \in \mathcal{D}$, we have:
$g \circ f'(h'(o), a) = g(f'(c, a)) = g(c).$
Therefore, the generative loss becomes:
\[
\mathcal{L}_{\text{gen}}(h', f', g) = \mathbb{E}_{(o, a, o') \sim \mathcal{D}} \left[ \left\lVert g(c) - o' \right\rVert \right].
\]
Note that this loss is non-zero if there exists at least one $(o, a, o’) \in \mathcal{D}$ such that $g(c) \ne o’$, which must be the case here because $o_2 \ne o_4$ while $g(c)$ is fixed across all inputs. \\
We now construct an alternative pair $(\tilde{h}, \tilde{f})$ such that:
\begin{itemize}
    \item For all $(o, a, o’) \in \mathcal{D} \setminus \{(o_1, a_1, o_2), (o_3, a_3, o_4)\}$, define $\tilde{h}(o) = c$ and $\tilde{f}(c, a) = c$, i.e., $\tilde{h}, \tilde{f}$ behave identically to the degenerate solution.
    \item For the two special cases, define $s_1, s_2 \in \mathcal{S}$ such that $g’(s_1) = o_2$ and $g’(s_2) = o_4$. (This is possible since $g’$ is fixed and assumed expressive enough to approximate $o_2$ and $o_4$.) \\
    Then, set $\tilde{h}(o_1) = \hat{s}_1$, $\tilde{f}(\hat{s}_1, a_1) = s_1$, and $\tilde{h}(o_3) = \hat{s}_2$, $\tilde{f}(\hat{s}_2, a_3) = s_2$, where $\hat{s}_1, \hat{s}_2 \in \mathcal{S}$ are any distinct intermediate representations to encode $o_1$ and $o_3$.
\end{itemize}
Now, consider the loss under this construction:
\begin{itemize}
    \item At $(o_1, a_1, o_2)$: $\tilde{h}(o_1) = \hat{s}_1$, $\tilde{f}(\hat{s}_1, a_1) = s_1$, $g’(s_1) = o_2$, so loss is $\left\lVert o_2 - o_2 \right\rVert = 0$. 
    \item At $(o_3, a_3, o_4)$: similarly, loss is zero for $\tilde{h}$ and $\tilde{f}$.
    \item While for $h'$ and $f'$, there must be one of $(o_1, a_1, o_2)$ and $(o_3, a_3, o_4)$ at which the loss is strictly positive. In other words, $\left\lVert g(c) - o_2 \right\rVert + \left\lVert g(c) - o_4 \right\rVert > 0$
    \item At all other datapoints, the loss is unchanged (equal to the degenerate solution’s loss) because we did not modify the outputs for those inputs.
\end{itemize}
Hence, the total loss under $(\tilde{h}, \tilde{f})$ is strictly less than under $(h’, f’)$:
\[\mathcal{L}_{\text{gen}}(\tilde{h}, \tilde{f}, g) < \mathcal{L}_{\text{gen}}(h', f', g)\]
This indicates that the degenerate solution must not be optimal, thus proving that it cannot be a global minimizer when $g$ is trained or expressive and when the dataset includes different outputs for different inputs.

\end{proof}

\section{Proof of Theorem~\ref{thm:latent-lower-bound-generative}}
\label{appendix:latent-lower-bound-generative}
\begin{proof}
Because the conditional distributions in the statement are all isotropic Gaussians, we can use them to construct the following transition distributions (assuming $\hat{q}$ is the empirical data distribution):
\begin{align*}
    \text{Latent Prediction } p_{h \circ f}:\ &\hat{s}' \mid o, a \sim \mathcal{N}(f(h(o), a), I) \\
    \text{Latent Target } \hat{q}_h:\ &\hat{s}' \mid o' \sim \mathcal{N}(h(o'), I) \\
    \text{Observation Prediction } p_{h \circ f \circ g}:\ &\hat{o}' \mid o, a \sim \mathcal{N}(g \circ f(h(o), a), I)
\end{align*}
It emerges that the two loss functions described above can be expressed as scaled KL divergences of those distributions, as shown below:
\begin{align*}
    \mathcal{L}_{\text{latent}} &= \| f(h(o), a) - h(o') \| = \sqrt{2 D_{\text{KL}}(\hat{q}_h(\hat{s}' \mid o') \, \Vert \, p_{h \circ f}(\hat{s}' \mid o, a))}, \\
    \mathcal{L}_{\text{gen}} &= \| g \circ f(h(o), a) - o' \| = \sqrt{2 D_{\text{KL}}(\hat{q}(o') \, \Vert \, p_{h \circ f \circ g}(o' \mid o, a))}.
\end{align*}
Consider applying the encoder transition to $\hat{q}$ and $p_{h \circ f \circ g}$. In the former case, we will recover the latent target $\hat{q}_h$, and in the latter case we will have performed a roundtrip from latent to observation, and back to latent, resulting in the following conditional distribution:
\begin{align*}
    \text{Roundtrip Latent Prediction } p_{h \circ f \circ g \circ h}:\ &\hat{s}' \mid o, a \sim \mathcal{N}(h \circ g \circ f(h(o), a), I).
\end{align*}
Applying the \textbf{data processing inequality} gives the following relation:
\[
    D_{\text{KL}}(\hat{q}_h(\hat{s}' \mid o') \, \Vert \, p_{h \circ f \circ g \circ h}(\hat{s}' \mid o, a)) \leq
    D_{\text{KL}}(\hat{q}(o') \, \Vert \, p_{h \circ f \circ g}(o' \mid o, a)),
\]
And because the left-hand side is $\frac{1}{2}\|h \circ g \circ f(h(o),a) - h(o')\|^2 $ and the right-hand side is $\frac{1}{2} \mathcal{L}_{\text{gen}}^2$, we plug them into the inequality above and get:
\begin{equation}
    \|h \circ g \circ f(h(o),a) - h(o')\| \leq \mathcal{L}_{\text{gen}}. 
    \label{ineq:data-processing-inequality}
\end{equation}
Next, because the encoder $h$ and decoder $g$ satisfy the roundtrip consistency of $\| h \circ g(\hat{s}) - \hat{s} \| \leq \epsilon$, plugging in $\hat{s} = f(h(o), a)$ gives:
\begin{equation}
    \| h \circ g \circ f(h(o), a) - f(h(o), a) \| \leq \epsilon.
    \label{ineq:roundtrip-consistency}
\end{equation}
Finally, we apply the triangle inequality to upper-bound the latent loss as below:
\begin{align*}
    \mathcal{L}_{\text{latent}} &= \| f(h(o), a) - h(o') \| \\
    &\leq {\underbrace {\textstyle \| f(h(o), a) - h \circ g \circ f(h(o), a) \|}_{\leq \epsilon \text{ by Inequality~\ref{ineq:roundtrip-consistency}}}} + 
        {\underbrace {\textstyle \| h \circ g \circ f(h(o), a) - h(o') \|}_{\leq \mathcal{L}_{\text{gen}} \text{ by Inequality~\ref{ineq:data-processing-inequality}}} } \\
    &\leq \mathcal{L}_{\text{gen}} + \epsilon
\end{align*}

When $h \circ g(\hat{s}) = \hat{s}$ for all $\hat{s} \in \mathcal{S}$, we have that $g: \mathcal{S} \to \text{Im}(g) \subseteq \mathcal{O}$ is an injective function which maps each point in $\mathcal{S}$ to a unique point in its image $\text{Im}(g)$. On the other hand, $h$ is the left inverse of $g$ on $\text{Im}(g)$, which maps each $\hat{o} \in \text{Im}(g)$ to $\hat{s} \in \mathcal{S}$ s.t. $g(\hat{s}) = \hat{o}$. Thus $h$ is bijective in $\text{Im}(g)$ by mapping each element $o \in \text{Im}(g)$ to exactly one $\hat{s} \in \mathcal{S}$.

This means $h$ defines a parameter transformation $T_h$ where $T_h(o) = h(o)$ for all $o \in \text{Im}(g)$. Because $\hat{q}(o')$ and $p_{h \circ f \circ g}(o' \mid o, a)$ are supported entirely inside $\text{Im}(g)$ and KL divergence is invariant under parameter transformation, we have:
\begin{align*}
    \frac{1}{2} \mathcal{L}_{\text{gen}}^2 &= D_{\text{KL}}(\hat{q}(o') \, \Vert \, p_{h \circ f \circ g}(o' \mid o, a)) \\
    &= D_{\text{KL}}(\hat{q}_h(\hat{s}' \mid o') \, \Vert \, p_{h \circ f \circ g \circ h}(\hat{s}' \mid o, a)) \\
    &= \frac{1}{2} \| h \circ g \circ f(h(o), a) - h(o') \|^2 \\
    &= \frac{1}{2} \| f(h(o), a) - h(o') \|^2 \quad (h \circ g(\hat{s}) = \hat{s}) \\
    &= \frac{1}{2} \mathcal{L}_{\text{latent}}^2.
\end{align*}
Thus we have $\mathcal{L}_{\text{latent}} = \mathcal{L}_{\text{gen}}$.
% With equality when decoder $g$ is invertible, encoder $h$ perfectly preserves information with $h = g^{-1}$, resulting in $h \circ g(\hat{s}) = \hat{s}$.
\end{proof}

