\title[Reduction theorem and applications]
{An extension of Haagerup's reduction theorem with applications to subdiagonal subalgebras of general von Neumann algebras}

\author{Louis Labuschagne}
\address{DSI-NRF CoE in Math. and Stat. Sci,\\ Focus Area for Pure and Applied Analytics,\\ Internal Box 209, School of Math.\& Stat. Sci.\\NWU, PVT. BAG X6001, 2520 Potchefstroom\\ South Africa}
