\title{Connection Matrices in {\em Macaulay2}}
\author{Paul Görlach${}^\sharp$, Joris Koefler${}^\flat$, Anna-Laura Sattelberger${}^\flat$,
 Mahrud Sayrafi${}^{\circ}$, \\Hendrik Schroeder${}^\diamond$,
