\begin{algorithm}[H]
    \caption{(Normal form algorithm in the rational Weyl algebra){\bf .}}\label{alg:normal form algorithm}
    \begin{algorithmic}
    \smallskip
        \Require $P \in R_n$, a Gröbner basis $G$ of a $D_n$-ideal $I$ with respect to $\prec_{(0,v)}$ on $D_n$ for  $v \in \mathbb{R}^n_{>0}$\linebreak \hspace*{9.4mm} and $\prec$ being the lexicographic order on $D_n$.
        \Ensure The {\tt normalForm} of $P$ by $G$ in $R_n$ with respect to $\prec'_{(0,v)}$.
        \smallskip
        \If{$P==0$}
            \State \Return $P$
        \EndIf
        \While{$\exists G_i \in G$ s.t.\ $\init_{\prec'_{(0,v)}}(G_i) \mid \init_{\prec'_{(0,v)}}(P)$}
            \State $P \coloneqq  \operatorname{red}_{\prec'_{(0,v)}}(P,G_i)$
        \EndWhile \smallskip
        \State \Return lt$_{\prec'_{(0,v)}}(P)$ $+$ \texttt{normalForm}($P-\leadTerm_{\prec'_{(0,v)}}(P)$, $G$)
    \end{algorithmic}
\end{algorithm}

Note that \Cref{alg:normal form algorithm} terminates since the leading term becomes successively smaller and $1$ is the smallest monomial of any term order $\prec$ on $D_n$. Note also that \Cref{prop1413} ensures that the normal form of any $P \in R_n I$ is $0$. We point out that, in general, it is not sufficient to carry out the reduction in the {\tt while} loop only once for the elements of the Gröbner basis.

\smallskip
As seen above, the normal form algorithm allows us to compute the connection matrices of an ideal $I \subset D_n$, which we summarize in pseudo-code in the next algorithm.

\begin{algorithm}[H]
    \caption{(Connection matrices with respect to standard monomials){\bf .}} \label{alg:connectionMatrices}
    \begin{algorithmic} 
    \smallskip
        \Require A $D_n$-ideal $I$ of finite holonomic rank $m <\infty$ and a positive vector $v \in \RR_{>0}^n$.
        \Ensure The {\tt connectionMatrices} $A_1,\dots,A_n \in \CC(x)^{m \times m}$ of $I$ with respect to the \linebreak \hspace*{13.4mm} standard monomials for~$\prec'_{(0,v)}$.\smallskip 
        \State $G\coloneqq$  Gröbner basis of the $D_n$-ideal $I$ with respect to $\prec_{(0,v)}$
        \State $\{s_1 \prec'_{(0,v)} s_2 \prec'_{(0,v)} \dots \prec'_{(0,v)} s_m\}\coloneqq \{\partial^\beta \colon \beta \in \NN^n \text{ s.t.\ } \init_{\prec'_{(0,v)}}(P) \nmid \xi^\beta \ \forall P \in G\}$ 
        \For{$i$ from $1$ to $n$}
          \For{$j$ from $1$ to $m$}
            \State $P \coloneqq $ \texttt{normalForm}($\partial_i s_j$,\, $G$) \textcolor{black!60}{\Comment{normal form computation in $R_n$ w.r.t.\ $\prec'_{(0,v)}$}}
            \For{$k$ from $1$ to $m$}
               \State $a_{jk}^{(i)} \coloneqq  $ coefficient of the monomial $s_k$ in $P$
            \EndFor
          \EndFor
          \State $A_i \coloneqq (a_{jk}^{(i)}) \in \CC(x)^{m \times m}$
        \EndFor
        \State \Return $A_1,\dots,A_n$.
    \end{algorithmic}
\end{algorithm}
\vspace*{-2mm}

The following example shows how to compute the connection matrices via this algorithm.
\begin{example} 
    Let $I$ be the $D_2$-ideal from \Cref{leading term dependence on space} and again $v=(2,1)$. We already determined a Gröbner basis $G$ of $I$ and $R_2I$ with respect to $\prec_{(0,v)}$ and $\prec'_{(0,v)}$, respectively. We have $\init_{\prec'_{(0,v)}}(R_2 I) = \langle \xi_x \xi_y , \xi_x, \xi_y^2 \rangle$. The holonomic rank of $I$ is the number of monomials~$\xi^\alpha$ that are not contained in the initial ideal $\init_{\prec'_{(0,v)}}(R_2 I)$.
    Therefore, $\rank(I) = 2$, with $s_1=1$ and $s_2=\partial_y$ being the standard monomials. We hence choose $\{1,\partial_y\}$ as our \mbox{$\mathbb{C}(x,y)$-basis} of~$R_2/R_2 I$. Following the above algorithm, we have $\operatorname{red}_{\prec'_{(0,v)}}(\partial_x, x\partial_x+y\partial_y+1) = \partial_x-\frac{1}{x}(x\partial_x+y\partial_y+1) = -\frac{y}{x}\partial_y-\frac{1}{x}$. Consequently, we get the normal form
    \begin{align*}
        \texttt{normalForm}(\partial_x s_1, G) &\,=\, \texttt{normalForm}(\partial_x, G) \,=\, -\frac{y}{x}\partial_y-\frac{1}{x} \,.
    \end{align*}
    Analogously, we obtain
    \begin{align*}
        \texttt{normalForm}(\partial_x s_2, G) &\,=\, \texttt{normalForm}(\partial_x\partial_y, G) \,=\, -\frac{x+y}{x(x-y)} \partial_y - \frac{1}{x(x-y)} \, , \\
        \texttt{normalForm}(\partial_y s_1, G) &\,=\, \texttt{normalForm}(\partial_y, G) \,=\, \partial_y \, ,\\
        \texttt{normalForm}(\partial_y s_2, G) &\,=\, \texttt{normalForm}(\partial_y^2, G) \,=\, \frac{3y-x}{(x-y)y}\partial_y + \frac{1}{(x-y)y} \, .
    \end{align*}
    From the first and last two normal forms, we obtain the connection matrices of $I$ as
    \renewcommand\arraystretch{1.2}
    \begin{align*}
        A_1 = \begin{pmatrix}
            -\frac{1}{x} & - \frac{y}{x}\\
            - \frac{1}{x(x-y)} & -\frac{x+y}{x(x-y)}
        \end{pmatrix} \quad \text{and} 
        \quad A_2 = \begin{pmatrix}
            0 & 1\\
            \frac{1}{(x-y)y} & \frac{3y-x}{(x-y)y}
        \end{pmatrix},
    \end{align*}
and the corresponding connection matrix as 
    \begin{align*}
        \qquad \qquad
        A \,=\,  A_1 \d x + A_2 \d y \,=\, \begin{pmatrix}
            -\frac{1}{x} \d x & - \frac{y}{x} \d x + \d y\\
            - \frac{1}{x(x-y)} \d x + \frac{1}{(x-y)y} \d y & -\frac{x+y}{x(x-y)}\d x + \frac{3y-x}{(x-y)y} \d y
        \end{pmatrix}. \qquad \qquad \qedhere
    \end{align*}
    \renewcommand\arraystretch{1}
\end{example}

We can now compute the connection matrices in arbitrary $\CC(x)$-bases of $R_n/R_nI$ (not necessarily given by standard monomials) by first computing the connection matrices~$A_i$ using \Cref{alg:connectionMatrices} and then computing the resulting gauge transforms~$\widetilde{A}_i$. 

\begin{algorithm}[H]
    \caption{(Gauge transformation to an arbitrary basis){\bf .}}\label{alg:gaugeTransform}
    \begin{algorithmic} 
        \Require A $D_n$-ideal $I$ of $\rank(I)=m < \infty$, a $\CC(x)$-basis $\{r_1,\dots,r_m\}$ of $R_n/R_n I$,  $v \in \RR_{>0}^n$.
        \Ensure The connection matrices of $I$ in the basis $\{r_1,\dots,r_m\}$. \smallskip
        \State $A\coloneqq {\tt connectionMatrices}(I, v)$ 
        \State $G\coloneqq$  Gröbner basis of the $D_n$-ideal $I$ with respect to $\prec_{(0,v)}$
        \State $\{s_1 \prec'_{(0,v)} s_2 \prec'_{(0,v)} \dots \prec'_{(0,v)} s_m\} \,\coloneqq\, \{\partial^\beta \colon \beta \in \NN^n \text{ s.t.\ } \init_{\prec'_{(0,v)}}(g) \nmid \xi^\beta \ \forall g \in G\}$ %standard monomials of $R_n I$.
        \For{$j$ from $1$ to $m$}
          \State $P \coloneqq $ \texttt{normalForm}($r_j$,\, $v$,\, $G$) \textcolor{black!60}{\Comment{normal form computation in $R_n$ w.r.t.\ $\prec'_{(0,v)}$}}
          \For{$k$ from $1$ to $m$}
            \State $g_{jk} \coloneqq $ coefficient of the monomial $s_k$ in $P$.
          \EndFor
        \EndFor
        \State $g \coloneqq (g_{jk}) \in \CC(x)^{m \times m}$. 
        \smallskip
        \State \Return $\widetilde{A}_i \coloneqq gA_ig^{-1}+(\partial_i\bullet g)g^{-1}$ for  $i=1,\ldots,n$.
    \end{algorithmic}
\end{algorithm}
\vspace*{-1mm}
\noindent Examples for gauge transformations are provided in the documentation of our package.

