As is common in extreme value theory, we further standardise the RMLM $\boldsymbol{X}$ by standardizing the max-linear coefficient matrix $A$. 
This implies that we are working directly with 
$\bar{A}$, i.e., $\boldsymbol{X}=\bar{A}\times_{\max}\boldsymbol{Z}$.
The standardised max-linear coefficient matrix with entries 
$$(\bar{A})_{ij}=\frac{a_{ij}}{\big(\sum_{k=1}^d {a_{ik}^2}\big)^{1/2}}$$ 
has useful properties.
The next lemma shows that the definition entails unit scalings for the components and that the diagonal entries of $\bar{A}$ are the largest in their respective columns, which is important in establishing asymmetries in the scaling methodology in Theorems \ref{p2sourcenodes}  and \ref{consT}.
We summarise these properties of $\bar A$ as follows.

\begin{lemma}\label{p2ineq}
Let $\bsx=\bar A\times_{\max}\boldsymbol{Z}$  be a RMLM, where $\boldsymbol{Z}\in \RV^{d}_+(2)$ has independent and standardised components and with standardised max-linear coefficient matrix $\bar{A}\in \mathbb{R}_+^{d\times d}$. Then\\
(i) [\cite{KK},  Prop. 1] $\sigma_i^2=\sum_{j\in V} \bar a_{ij}^2=1$ for  $i\in V$;\\
(ii) [\cite{GKO}, Lemma A.1]
 $\bar{a}_{jj}>\bar{a}_{ij}$ for $i\neq j$.
\end{lemma}

The following model assumptions are used throughout the rest of the paper.\vspace{2mm}\\
{ \textbf {Assumptions A:}}\label{p2modelassump}
\begin{enumerate}
	\item[(A1)]
	The innovations vector $\boldsymbol{Z}\in {\RV}^{d}_+(2)$ has independent and standardised components.
	\item[(A2)]
	The choice of norm is the Euclidean norm, denoted by $\|\cdot\|$.
	\item[(A3)]
	The components of the RMLM $\bsx=A\times_{\max}\boldsymbol{Z}$ are standardised with scalings $\sigma_i=1$ for all $i\in V$, a consequence of $A$ being standardised.
\end{enumerate}

In what follows we use different scalings between the max-projections of $\bsx$ on some component subset of $V$ and partly rescaled components.
We define for $I\subset V$, $i,j \in I^c=V\setminus I$, and $a\ge 1$,
\begin{align}\label{Mscale}
M_{i,aj, aI} \coloneqq X_i\vee a X_j\vee \bigvee_{k\in I} a X_k
= \bigvee_{\ell\in V} \Big(a_{i\ell}  \vee  a a_{j\ell} \vee \bigvee_{k\in I} a a_{k\ell} \Big) Z_\ell,
%M_{I,aI^c}  := \bigvee_{k\in I} X_k\vee \bigvee_{k\in I^c} a X_k  =\bigvee_{j\in V}\Big(\bigvee_{k\in I} a_{kj}\vee  \bigvee_{k\in I^c}  a a_{kj} \Big)  Z_j.
%M_{ai}  := \bigvee_{k\in V\setminus \{i\}} X_k\vee a X_i =\bigvee_{j\in V}\Big(\bigvee_{k\in V\setminus \{i\}} a_{kj}\vee a a_{ij} \Big)  Z_j.
%M_{I,ai}  := \bigvee_{k\in I\setminus \{i\}} X_k\vee a X_i =\bigvee_{j\in V}\Big(\bigvee_{k\in I\setminus \{i\}} a_{kj}\vee a a_{ij} \Big)  Z_j.
\end{align}
%For simplicity, we write $M:= M_V$ and $M_{ai}:=M_{V\setminus\{i\},ai} $.
giving 
$M_{i,aj} =  \bigvee_{\ell\in V} \big(a_{i\ell}  \vee  a a_{j\ell} \big) Z_\ell $ for $I=\emptyset$ and 
$M_{i,j} =  \bigvee_{\ell\in V} \big(a_{i\ell}  \vee  a_{j\ell} \big) Z_\ell $ for $a=1$.

In preparation for the next section, we summarise some important properties of the scalings of max-projections.
In particular, we make use of maxima over rescaled components of the vector $\boldsymbol{X}$ under Assumptions~A. 
Lemma 6 of \citet{KK} proves formulas (i) and (ii) of Proposition~\ref{p2scalcoll}; we prove~(iii)~below. % to Lemma \ref{p2ineq} using \eqref{eq:e}.

\bpr\label{p2scalcoll} 
Let $\boldsymbol{X}$ be a RMLM satisfying Assumptions~A. 
Then the max-projections in \eqref{Mscale} belong to $\RV_+(2)$ with squared scalings\\
(i) $\sigma_{M_{I}}^2 =\sum_{\ell\in V} \bigvee_{i\in I} a_{i\ell}^2$ for $I\subsetneq V$; \\
(ii) $\sigma_{M}^2 = \sum_{\ell\in V}  a_{\ell\ell}^2$;\\
(iii) $\sigma^2_{M_{i,aj, aI}} = \sum_{\ell\in  I\cup\{j\}}  a^2 a^2_{\ell\ell}
+ \sum_{\ell\in  (I\cup\{j\})^c}\big(a^2_{i\ell}\vee \bigvee_{k\in I\cup\{j\}} a^2 a^2_{k\ell}\big)$ for $a\ge 1$ and $i,j\in I^c, i\neq j$.
%(iv) $\sigma_{M_{ai}}^2 = \sum_{k\in V\setminus \{i\} }  \big( a_{kk}^2\vee a a_{ik}^2\big) +  a^2 a_{ii}^2$ for $a>0$.
\epr

\begin{proof}
(i)  Note that $M_I=\bigvee_{i\in I} X_i=\bigvee_{\ell\in V} \bigvee_{i\in I} a_{i\ell} Z_\ell$  has the same structure as $X_i=\bigvee_{\ell\in V} a_{i\ell} Z_\ell$ with $a_{i\ell}$ replaced by $\bigvee_{i\in I} a_{i\ell}$.
Thus, choosing $f(\omega_1,\dots,\omega_d) = \bigvee_{k\in I} \omega_k^2$ gives \\[2mm]
\centerline{$\sigma_{M_{I}}^2 = \int_{\Theta_+^{d-1}} \bigvee_{i\in I} \omega_i^2 dH_{\bsx}(\boldsymbol\omega)
=  \sum_{\ell\in V} \| \bsa_{\ell}\|^2 \big( \bigvee_{i\in I} \frac{a^2_{i\ell}}{\| \bsa_{\ell}\|^2}\big)
 = \sum_{\ell\in V} \bigvee_{i\in I} a_{i\ell}^2$; }\\
 (ii) is a consequence of Lemma \ref{p2ineq}(ii);\\
 (iii) is proven with 
 $f(\omega_1,\dots,\omega_d)= \omega_i^2 \vee \bigvee_{k\in I\cup\{j\}}a \omega_k^2$. Using (i) gives 
 \begin{align*}
\sigma^2_{M_{i,aj, aI}} &= \sum_{\ell\in V}\Big(a^2_{i\ell}\vee \bigvee_{k\in I\cup\{j\}} a^2 a^2_{k\ell}\Big)\\
&= \sum_{\ell\in  I\cup\{j\}}\Big(a^2_{i\ell}\vee \bigvee_{k\in I\cup\{j\}} a^2 a^2_{k\ell}\Big) 
+ \sum_{\ell\in  (I\cup\{j\})^c}\Big(a^2_{i\ell}\vee \bigvee_{k\in I\cup\{j\}} a^2 a^2_{k\ell}\Big)\\
&=  \sum_{\ell\in  I\cup\{j\}}  a^2 a^2_{\ell\ell}
+ \sum_{\ell\in  (I\cup\{j\})^c}\Big(a^2_{i\ell}\vee \bigvee_{k\in I\cup\{j\}} a^2 a^2_{k\ell}\Big)
 \end{align*}
where we have used  Lemma \ref{p2ineq}(ii) for the last equality.
\end{proof}

The next lemma provides ingredients for the proof of Theorem~\ref{p2sourcenodes} below. 

\begin{lemma}\label{le:order}
Let $\bsx$ be a RMLM on a well-ordered DAG satisfying Assumptions A.
Let $I\subseteq V$ denote a set of nodes satisfying $\An(I)\cap I^c=\emptyset$. 
Then the following hold for $i,j\notin I$, $i\neq j$
\begin{align}
\sigma^2_{M_{i,aj}}-\sigma_{M_{ij}}^2 
&= (a^2-1) a_{jj}^2+ \sum_{\ell\in\an(j)} \big(a_{i\ell}^2\vee a^2 a_{j\ell}^2 -a_{i\ell}^2\vee  a_{j\ell}^2\big),\label{eq:iaj} \\
\sigma^2_{M_{i,aj, aI}} - \sigma^2_{M_{i,j, I}} 
&= (a^2-1)\sum_{\ell\in  I\cup\{j\}}  a^2_{\ell\ell} + \sum_{\ell\in  I^c\cap\an(j)} \big(a^2_ {i\ell}\vee a^2 a^2_{j\ell} - a^2_ {i\ell}\vee  a^2_{j\ell}\big).\label{eq:b}
\end{align}
\end{lemma}

\begin{proof} 
Note that \eqref{eq:iaj} is a special case of \eqref{eq:b} for $I=\emptyset$, hence we only prove \eqref{eq:b}.
We use Proposition~\ref{p2scalcoll}(iii) and obtain, since $a_{k\ell}=0$ for $\ell\notin\an(k)$,
\begin{align*}%\label{eq:b}
&\sigma^2_{M_{i,aj, aI}} - \sigma^2_{M_{i,j, I}} \\
&= (a^2-1)\sum_{\ell\in I\cup\{j\}}  a^2_{\ell\ell}
 + \sum_{\ell\in  (I\cup\{j\})^c}\Big( \big(a^2_{i\ell}\vee \bigvee_{k\in (I\cup\{j\})\cap\des(\ell)} a^2 a^2_{k\ell}\big)
- \big(a^2_{i\ell}\vee \bigvee_{k\in (I\cup\{j\})\cap\des(\ell)} a^2_{k\ell}\big)\Big)\\
&= (a^2-1)\sum_{\ell\in I\cup\{j\}}  a^2_{\ell\ell}
 + \sum_{\ell\in  (I\cup\{j\})^c}\Big( \big(a^2_{i\ell}\vee \bigvee_{k\in \{j\}\cap\des(\ell)} a^2 a^2_{k\ell}\big)
- \big(a^2_{i\ell}\vee \bigvee_{k\in \{j\}\cap\des(\ell)} a^2_{k\ell}\big)\Big)\\
&= (a^2-1)\sum_{\ell\in I\cup\{j\}}  a^2_{\ell\ell}
 + \sum_{\ell\in I^c\cap\an(j)}\Big( \big(a^2_{i\ell}\vee a^2 a^2_{j\ell}\big)
- \big(a^2_{i\ell}\vee  a^2_{j\ell}\big)\Big),
\end{align*}
where we have used that {$I\cap\des(\ell)=\emptyset$ for $\ell\in I^c$} %$I\cap\des(j)=\emptyset$ for $j\in I^c$
in the second equality.
\end{proof}

