We generalise the above recursion for a $d$-dimensional RMLM
\begin{align}\label{eq:Atimes} 
\bsx = A \times_{\max}\boldsymbol{Z}
\quad\mbox{with}\quad
 A 
=\begin{bmatrix}
a_{11}&\hdots &a_{1{d}}\\
\vdots& \ddots & \vdots\\
0&\hdots &a_{{d}{d}}
\end{bmatrix},
\end{align}
which gives rise to Algorithm~\ref{recalg2} below; for a proof we refer to \cite{KK}.

\begin{proposition}[\cite{KK}, Proposition 2]\label{estalg2}
Let $\boldsymbol{X}\in\RV^d_+$ be a RMLM on a well-ordered DAG with representation \eqref{eq:Atimes} satisfying Assumptions A.
Then the following recursion yields the max-linear coefficient matrix $A$:
	\begin{align}
	a_{{d}{d}}^2  &=  \sigma_{d}^2=1 \, \mbox{ and } \, a_{ii}^2 \, =\, \sigma_{M_{i,\dots,{d}}}^2-\sigma_{M_{i+1,\dots,{d}}}^2 \quad	  i=1,\dots,{d}-1,  \label{recformula1}\\
	a_{ij}^2 &= \sigma_{M_{i,j+1,j+2,\dots,{d}}}^2-\sigma_{M_{j+1,j+2,\dots,{d}}}^2-\sum_{k=i}^{j-1}a_{ik}^2 \quad \quad\,
	i=1,\dots,{d}-2,  j =i+1,\dots,{d}-1.
	\label{recformula2}\\
	a_{i{d}}^2 &= \sigma_{i}^2-\sum_{k=i}^{{d}-1}a_{ik}^2 \, = \, 1-\sum_{k=i}^{{d}-1}a_{ik}^2 \quad\quad\quad\quad\quad  i=1,\dots,{d}-1. \label{recformula3}
	\end{align}
\end{proposition}

%The Algorithm corresponding to Proposition~\ref{estalg2} reads as follows.
\begin{algorithm}[ht]
	\caption{Computation of the max-linear coefficient matrix A }\label{recalg2}
	\textbf{Input}:\quad $A = (0)_{{d}\times{d}}$\\
	\textbf{Output}: The max-linear coefficient matrix  $A\in \R_+^{d\times d}$
	\begin{algorithmic}[1]
		\Procedure{}{}
		\State \textbf{for} $i = 1,\dots,{d}-2$ \textbf{do}
		%\State \hspace{5mm}\textbf{Compute} $\sigma_{M_{i,i+1,\dots,{d}}}^2; \sigma_{M_{i+1,\dots,{d}}}^2$
		\State \hspace{5mm}\textbf{Set} $a_{ii}^2=\sigma_{M_{i,i+1,\dots,{d}}}^2-\sigma_{M_{i+1,\dots,{d}}}^2$ \textbf{using} \eqref{recformula1} 
		%\State \hspace{5mm}\textbf{if} $i\in\{1,\dots,{d}-2\}$ \textbf{do}
		\State \hspace{13.4mm}\textbf{for} $j=i+1,\dots,{d}-1$ \textbf{do}
		%\State \hspace{5mm}\textbf{Compute} $\sigma_{M_{i,j+1,\dots,{d}}}^2; \sigma_{M_{j+1,\dots,{d}}}^2$
		\State \hspace{18.4mm}\textbf{Set} $a_{ij}^2=\sigma_{M_{i,j+1,\dots,{d}}}^2-\sigma_{M_{j+1,\dots,{d}}}^2-\sum_{k=i}^{j-1}a_{ik}^2$ \textbf{using} \eqref{recformula2} 
		\State\hspace{13.4mm}\textbf{end for}
		\State\hspace{5mm}\textbf{Set} $a_{i{d}}^2=\sigma_{i}^2-\sum_{k=i}^{{d}-1}a_{ik}^2$ \textbf{using} \eqref{recformula3} 
		\State \textbf{end for}
		%\State \hspace{0mm}\textbf{Compute} $\sigma_{d}^2$
		\State\hspace{0mm}\textbf{Set}
		$a_{{d}-1,{d-1}}^2=\sigma_{M_{d-1,d}}^2-\sigma_{M_d}^2$;
		$a_{{d}-1,{d}}^2=\sigma_{{{d}-1}}^2-a_{{d}-1,{d}-1}^2$; $a_{{d}{d}}^2=\sigma_{{d}}^2.$
		\State \textbf{return} A
		\EndProcedure
	\end{algorithmic}
\end{algorithm}


In Proposition~\ref{estalg2} we have shown that one can compute the diagonal entries of $A$ from the squared scalings $\sigma_{M_{1,2,\dots,{d}}}^2,\sigma_{M_{2,3,\ldots,{d}}}^2,\dots,$ $ \sigma_{M_{{d}-1,{d}}}^2,\sigma_{d}^2$ by a recursion algorithm.
Furthermore, we have identified the non-diagonal entries of the $i$-th row of $A$ from
$$(\sigma_{M_{i,i+1,\dots,{d}}}^2,\sigma_{M_{i,i+2,\dots,{d}}}^2,\dots, \sigma_{M_{i,{d}}}^2 ,\sigma_{i}^2),\quad i=1,\dots,{d}.$$
We summarise all these quantities into one column vector ${S}_{M}\in \mathbb{R}^{{d}({d}+1)/2}_+$, i.e., 
%\begin{small}
    \begin{align}\label{sm}
	{S}_{M}\coloneqq( {\sigma}_{M_{1,2,\dots,{d}}}^2, {\sigma}_{M_{1,3,\dots,{d}}}^2,\dots,  {\sigma}_{M_{1,{d}}}^2 , {\sigma}_{1}^2,  {\sigma}_{M_{2,3,\dots,{d}}}^2, {\sigma}_{M_{2,4,\dots,{d}}}^2,\dots,  {\sigma}_{M_{2,{d}}}^2, {\sigma}_{2}^2,\dots , {\sigma}_{M_{{d}-1,{d}}}^2, {\sigma}_{{d}-1}^2,  {\sigma}_{d}^2).
\end{align}
%\end{small}
Consider the row-wise vectorised version of the squared entries of the upper triangular matrix $A$, where we use $A^2$ for the {matrix with squared entries of $A$} and its vectorised version 
\begin{align}\label{vecA}
{A^2}\coloneqq(a_{11}^2,\dots,a_{1{d}}^2,a_{22}^2,\dots,a_{2{d}}^2,\dots..,a_{{d}-1,{d}-1}^2, a_{{d}-1,{d}}^2,a_{{d}{d}}^2).
\end{align}
Note that both vectors ${A^2}$ and ${S}_{M}$ show a similar structure, built from row vectors with ${d},{d}-1,\ldots,1$ components, respectively; so both have ${d}({d}+1)/2$ components.
By means of Proposition~\ref{estalg2} we show that ${A^2}$ can be written as a linear transformation of $S_M$.

\begin{theorem}[\cite{KK}, Theorem~1]\label{consT}
	Let $S_M$ and ${A^2}$ be as in (\ref{sm}) and (\ref{vecA}), respectively. 	
    Then
\beam \label{Alinear} 
{A^2} &=& T \, S_M,
\eeam
where $T\coloneqq (t_{uv})_{k\times k}\in \mathbb{R}^{k\times k}$ for $k={d}({d}+1)/2$ has non-zero entries in the rows corresponding to the upper triangular components $a^2_{ij}$ in the vector (\ref{vecA}) given by
\begin{enumerate}
\item[]
$a^2_{ii}:\quad t_{\ell_{ii}, \ell_{ii}}=1$, $t_{\ell_{ii}, \ell_{i+1,i+1}}=-1 $ for  $i=1,\dots,{d}-1$;
\item[]
$a^2_{{d}{d}}:\quad t_{\ell_{ii}, \ell_{ii}}=1$ for $i={d}$; 
\item[]
$a^2_{ij}:\quad t_{\ell_{ij},\ell_{ij}}=1,  t_{\ell_{ij},\ell_{j+1,j+1}}=-1, t_{\ell_{ij},\ell_{i,j-1}}=-1, t_{\ell_{ij},\ell_{jj}}=1$ for $i<j\leq {d}-1$; 
\item[]
$a^2_{i{d}}:\quad t_{\ell_{i{d}},\ell_{i{d}}}=1, t_{\ell_{i{d}},\ell_{i,{d}-1}}=-1,  t_{\ell_{i{d}},\ell_{{d}{d}}}=1$ for $i=1,\dots,{d}-1$,
\end{enumerate}
where {$\ell_{ij}=(j-{d})+\sum_{k=0}^{i-1}({d}-k)$ for $i=1,...,d$ and $j\geq i$}. All remaining entries of $T$ are equal to zero.
\end{theorem}

The proof uses the fact that the vector $A^2$ in~\eqref{vecA} can be represented by simple linear combinations of scalings as follows:
\beam
	 a_{ii}^2 & =& \sigma_{M_{i,\dots,{d}}}^2-\sigma_{M_{i+1,\dots,{d}}}^2\quad\mbox{for }  i=1,\dots,{d}-1\quad \mbox{ and } \quad a_{{d}{d}}^2  =  \sigma_{{d}}^2=1\label{Ai}\\
	a_{ij}^2 &=& (\sigma_{M_{i,j+1,j+2,\dots,{d}}}^2-\sigma_{M_{j+1,j+2,\dots,{d}}}^2)-(\sigma_{M_{i,j,\dots,{d}}}^2-\sigma_{M_{j,\dots,{d}}}^2)\label{AS1}\\
	&& \mbox{for }  i=1,\dots,d-2 \mbox{ and } j=i+1,\dots,{d}-1\nonumber\\
	a_{i{d}}^2&=&\sigma_{i}^2-(\sigma_{M_{i,{d}}}^2-\sigma_{{d}}^2)\quad\mbox{for }   i<{d}\quad \mbox{ and } \quad a_{{d}{d}}^2=\sigma_{{d}}^2 \label{ASp}
	\eeam
We construct the matrix $T$ so that the relations~\eqref{Ai}--\eqref{ASp} hold when $T$ is applied to~$S_M$.

