\begin{align}\label{eq:stable}
s_{ij}(r)=\#\{\wh \D^{A}_{\delta}(r): j\to i{\,\,\text{is present in}\,\,}\wh \D^{A}_{\delta}(r)\}, \quad r\in K_k.
