\section{Proof of Proposition \ref{prop:KernelHm2}.}
\label{sec:ProofPropositionKernelHm2}

\begin{definition}
Let $m,k,l\in\mathbb Z_{\geq0}$ be nonnegative integers satisfying $k+l\leq m$, denote
\begin{equation}
\mathfrak P_{m,k,l}:=X_{23}^m\mathcal P_k\left(\frac{X_{12}-X_{13}}{X_{23}}\right)\mathcal P_l\left(\frac{X_{12}+X_{13}}{X_{23}}\right)\qquad\in\quad \mathbb C[X_{12},X_{13},X_{23}],
\label{eq:PmklDefinition}
\end{equation}
where $\mathcal P_k$ and $\mathcal P_l$ stand for Legendre polynomials of degrees $k$ and $l$ respectively.
\end{definition}

\begin{lemma}
The following provides a basis on $\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_m$, the space of homogeneous polynomials of degree $m$ in variables $X_{12},X_{13},X_{23}$:
\begin{equation*}
\mathfrak B=\left\{\mathfrak P_{m,k,l}\;|\;m,k,l\in\mathbb Z_{\geq0},\; k+l\leq m\right\}.
%\label{eq:BasisPmkl}
\end{equation*}
\end{lemma}
\begin{proof}
First, note that $\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_m$ has a basis given by $X_{23}^{m-k-l}(X_{12}-X_{13})^k(X_{12}+X_{13})^l$ with $k+l\leq m$. Next, observe that $\mathfrak B$ is obtained by triangular change of basis from the latter.
\end{proof}

\begin{lemma}
Consider restriction of the operator $\hat H_1^{(-2)}$ on a subspace of homogeneous polynomials of degree $m\in\mathbb Z_{\geq 0}$, it has the following kernel
\begin{equation}
\ker\hat H_1^{(-2)}\big|_{\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_m}=\mathrm{Span}\left\{ \mathfrak P_{m,l,l}\;\left|\;0\leq l\leq\left\lfloor\frac m2\right\rfloor\right.\right\}.
\label{eq:KerH1m2}
\end{equation}
\end{lemma}
\begin{proof}
To this end we make the following change of variables
\begin{equation}
(X_{12},X_{23},X_{13})\leftrightarrow (U,V,X_{23}),\qquad\textrm{where}\qquad U=\frac{X_{12}-X_{13}}{X_{23}},\quad V=\frac{X_{12}+X_{13}}{X_{23}}.
\label{eq:UVXChangeOfVariables}
\end{equation}
In terms of the new variables operator (\ref{eq:H1m2}) multiplied by $X_{12}X_{13}$ on the left acquires especially simple form
\begin{equation}
X_{12}X_{13}\hat H_1^{(-2)}=\left(\left(1-U^2\right)\frac{\partial^2}{\partial U^2}-2U\frac{\partial}{\partial U}\right)-\left(\left(1-V^2\right)\frac{\partial^2}{\partial V^2}-2V\frac{\partial}{\partial V}\right)=\hat{\mathcal D}_U-\hat{\mathcal D}_V,
\label{eq:DifferenceOfLegendreOperators}
\end{equation}
where $\hat{\mathcal D}_U$ and $\hat{\mathcal D}_V$ are nothing but Legendre differential operators in variables $U,V$. Note that the action of the right hand side of (\ref{eq:DifferenceOfLegendreOperators}) on $\mathbb C[U,V]$ is diagonal in the basis of products of Legendre polynomials
\begin{equation*}
\left\{\mathcal P_l(U)\mathcal P_k(V)\;\big|\; k,l\in\mathbb Z_{\geq0}\right\}
\end{equation*}
with eigenvalues $\lambda_{k,l}=k(k+1)-l(l+1)$.

As a corollary, the action of $X_{12}X_{13}\hat H_1^{(-2)}$ on the homogeneous component $\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_m$ of degree $m$ is diagonal in basis $\mathfrak B$
with the same eigenvalues $\lambda_{k,l}=k(k+1)-l(l+1)$. Taking the span of all the eigenvectors corresponding to zero eigenvalue we get precisely (\ref{eq:KerH1m2}).
\end{proof}

\begin{lemma}
Let $m,l\in\mathbb Z_{\geq0}$ be a pair of nonnegative integers satisfying $2l\leq m$. The action of the remaining two operators (\ref{eq:H2m2}) and (\ref{eq:H3m2}) on polynomial $\mathfrak P_{m,l,l}$ is given by
\begin{subequations}
\begin{align}
X_{12}X_{23}\hat H_2^{(-2)}\mathfrak P_{m,l,l}=&(m+1)\left((m+2l+2)X_{12}X_{23}^{-1}\mathfrak P_{m,l,l}-(l+1)\mathfrak P_{m,l+1,l}-(l+1)\mathfrak P_{m,l,l+1}\right),\label{eq:H2m2PmllAction}\\[0.3em]
X_{13}X_{23}\hat H_3^{(-2)}\mathfrak P_{m,l,l}=&(m+1)\left((m+2l+2)X_{13}X_{23}^{-1}\mathfrak P_{m,l,l}+(l+1)\mathfrak P_{m,l+1,l}-(l+1)\mathfrak P_{m,l,l+1}\right).
\label{eq:H3m2PmllAction}
\end{align}
\end{subequations}
\end{lemma}
\begin{proof}
Applying differential operator (\ref{eq:H2m2}) to the right hand side of (\ref{eq:PmklDefinition}) and changing the variables as in (\ref{eq:UVXChangeOfVariables}) we get
\begin{equation}
\begin{aligned}
X_{12}X_{23}^{1-m}\hat H_2^{(-2)}\mathfrak P_{m,l,l}=&\frac12m(m+1)(U+V)\mathcal P_l(U)\mathcal P_l(V)\\
&\quad+(1+m-UV-mV^2)\mathcal P_l(U)\mathcal P_l'(V)+(1+m-mU^2-UV)\mathcal P_l'(U)\mathcal P_l(V)\\
&\quad+\frac12(U-V)(1-V^2)\mathcal P_l(U)\mathcal P_l''(V)-\frac12(U-V)(1-U^2)\mathcal P_l''(U)\mathcal P_l(V)\\
=&(m+1)\left(\frac12m(U+V)\mathcal P_l(U)\mathcal P_l(V)+(1-V^2)\mathcal P_l(U)\mathcal P_l'(V)+(1-U^2)\mathcal P_l'(U)\mathcal P_l(V)\right).
%=&(m+1)\left(\frac12m(U+V)\mathcal P_l(U)\mathcal P_l(V)+(l+1)\mathcal P_l(U)\left(\mathcal P_{l+1}(V)-V\mathcal P_l(V)\right)\right.\\
%&\quad\qquad\left.\phantom{\frac12}+(l+1)\mathcal P_l(V)\left(\mathcal P_{l+1}(U)-U\mathcal P_l(U)\right)\right)\\
\label{eq:H2m2PmllActionStep1}
\end{aligned}
\end{equation}
Here in the second equality we have used Legendre differential equation to eliminate $\mathcal P_l''$. Finally, to eliminate the first derivatives we use the following identity
\begin{equation*}
(1-x^2)\mathcal P_l'(x)+(l+1)\left(\mathcal P_{l+1}(x)-x\mathcal P_l(x)\right)=0\qquad\textrm{for all}\quad l\in\mathbb Z_{\geq0}.
\end{equation*}
The right hand side of (\ref{eq:H2m2PmllActionStep1}) acquires the following form
\begin{equation}
\begin{aligned}
X_{12}X_{23}^{1-m}&\hat H_2^{(-2)}\mathfrak P_{m,l,l}\\[0.5em]
=&(m+1)\left((m+2l+2)\frac{U+V}2\mathcal P_l(U)\mathcal P_l(V)-(l+1)\mathcal P_{l+1}(U)\mathcal P_l(V)-(l+1)\mathcal P_l(U)\mathcal P_{l+1}(V)\right).
\end{aligned}
\label{eq:H2m2ActionPmllUV}
\end{equation}
Changing variables back to $X_{12},X_{13},X_{23}$ we conclude the proof of identity (\ref{eq:H2m2PmllAction}).

Finally, in order to prove the second identity (\ref{eq:H3m2PmllAction}) note that 
\begin{equation*}
\hat H_3^{(-2)}=\sigma_{(X_{12},X_{13})}\circ \hat H_2^{(-2)}\circ\sigma_{(X_{12},X_{13})}
\end{equation*}
where $\sigma_{(X_{12},X_{13})}$ is an order two automorphism of the ring $\mathbb C[X_{12}^{\pm1},X_{13}^{\pm1},X_{23}^{\pm1}]$ of Laurent polynomials which preserves the polynomial subring.
\end{proof}

For the remainder of Appendix \ref{sec:ProofPropositionKernelHm2} we fix lexicographic monomial ordering on Laurent monomials in $X_{12}, X_{13}, X_{23}$. Note that this is a total monomial ordering which respects multiplication, but it is not a well-order. This will be enough for comparing the leading parts of Laurent polynomials involved in our proofs.

\begin{lemma}
Let $m,l\in\mathbb Z_{\geq0}$ be a pair of nonnegative integers satisfying $m\geq 2l$. The action of differential operators $\hat H_2^{(-2)}$ and $\hat H_3^{(-2)}$ on basis element $\mathfrak P_{m,l,l}$ has the following leading term
\begin{subequations}
\begin{equation}
\mathop{\mathrm{LT}}\left(\hat H_2^{(-2)}\mathfrak P_{m,l,l}\right)=\left\{\begin{array}{ll}
\frac{((2l-1)!!)^2}{(l!)^2}(m+1)(m-2l)X_{12}^{2l}X_{23}^{m-2l-2},&m>2l,\\[0.5em]
\frac{((2l+1)!!)^2}{(l!)^2}\frac{2l^2}{4l^2-1}X_{12}^{2l-2},&m=2l>0,\\[0.5em]
\emptyset,&m=l=0,
\end{array}\right.
\label{eq:LeadingTermsH2m2Pmll}
\end{equation}
\begin{equation}
\mathop{\mathrm{LT}}\left(\hat H_3^{(-2)}\mathfrak P_{m,l,l}\right)=
\left\{\begin{array}{ll}
\frac{((2l-1)!!)^2}{(l!)^2}(m+1)(m-2l)X_{12}^{2l}X_{23}^{m-2l-2},&m>2l,\\[0.5em]
-\frac{((2l+1)!!)^2}{(l!)^2}\frac{2l^2}{4l^2-1}X_{12}^{2l-2},&m=2l>0,\\[0.5em]
\emptyset,&m=l=0.
\end{array}\right.
\label{eq:LeadingTermsH3m2Pmll}
\end{equation}
\end{subequations}
\label{lemm:LeadingTermsH2m2H3m2Pmll}
\end{lemma}
\begin{proof}

Using Rodriguez formula \cite{Askey'2005} for Legendre polynomials we get the following expression for the first two leading terms
\begin{equation}
P_l(x)=\frac1{2^l l!}\left(\frac{(2l)!}{l!}x^l-l\frac{(2l-2)!}{(l-2)!}x^{l-2}\right)+\mathbf S(x^{l-3}).
\label{eq:LegendreLeadingTerms}
\end{equation}
Here by $\mathbf S(x^{l-2})$ we denote the linear combination of monomials $x^i$ with $i<l-2$. 

With our choice of monomial ordering on $\mathbb C[X_{12}^{\pm1},X_{13}^{\pm1},X_{23}^{\pm1}]$, formula (\ref{eq:LegendreLeadingTerms}) implies that 
\begin{equation}
\begin{aligned}
&P_l\left(\frac{X_{12}\pm X_{13}}{X_{23}}\right)=\frac1{2^l}\left(\begin{array}{c}2l\\l\end{array}\right)\left(\frac{X_{12}\pm X_{13}}{X_{23}}\right)^l-\frac l{2^l}\left(\begin{array}{c}2l-2\\l\end{array}\right)\left(\frac{X_{12}\pm X_{13}}{X_{23}}\right)^{l-2}+\mathbf S(X_{12}^{l-3})\\[0.5em]
&\qquad\qquad=\frac1{2^l}\left(\begin{array}{c}2l\\l\end{array}\right)\left(X_{12}^lX_{23}^{-l}\pm lX_{12}^{l-1}X_{13}X_{23}^{-l}+\frac{l(l-1)}2X_{12}^{l-2}X_{13}^2X_{23}^{-l}-\frac{l(l-1)(l-2)}6X_{12}^{l-3}X_{13}^3X_{23}^{-l}\right)\\[0.5em]
&\qquad\qquad\quad-\frac l{2^l}\left(\begin{array}{c}2l-2\\l\end{array}\right)\left(X_{12}^{l-2}X_{23}^{2-l}\pm (l-2)X_{12}^{l-3}X_{13}X_{23}^{2-l}\right)+\mathbf S(X_{12}^{l-3}).
\end{aligned}
\label{eq:PlUVLeadingTerms}
\end{equation}
Hereinafter $\mathbf S(X_{12}^k),\; k\in\mathbb Z$ stands for linear combination of monomials $X_{12}^{i_{12}}X_{13}^{i_{13}}X_{23}^{i_{23}}$ with $i_{12}<k$.

As a corollary of (\ref{eq:PlUVLeadingTerms}) we get the following formula for the leading terms of the basis element (\ref{eq:PmklDefinition})
\begin{equation}
\begin{aligned}
\mathfrak P_{m,k,l}=&X_{23}^mP_k\left(\frac{X_{12}-X_{13}}{X_{23}}\right)P_l\left(\frac{X_{12}+X_{13}}{X_{23}}\right)=\frac1{2^{k+l}}X_{12}^{k+l}X_{23}^{m-k-l}\\[0.5em]
&\quad\times\left(\left(\begin{array}{c}2k\\k\end{array}\right)\left(1-kX_{12}^{-1}X_{13}+\frac{k(k-1)}2X_{12}^{-2}X_{13}^2-\frac{k(k-1)(k-2)}6X_{12}^{-3}X_{13}^3\right)\right.\\[0.5em]
&\qquad\quad\left.-k\left(\begin{array}{c}2k-2\\k\end{array}\right)\left(X_{12}^{-2}X_{23}^2-(k-2)X_{12}^{-3}X_{13}X_{23}^2\right)\right)\\[0.5em]
&\quad\times\left(\left(\begin{array}{c}2l\\l\end{array}\right)\left(1+lX_{12}^{-1}X_{13}+\frac{l(l-1)}2X_{12}^{-2}X_{13}^2+\frac{l(l-1)(l-2)}6X_{12}^{-3}X_{13}^3\right)\right.\\[0.5em]
&\qquad\quad\left.-l\left(\begin{array}{c}2l-2\\l\end{array}\right)\left(X_{12}^{-2}X_{23}^2+(l-2)X_{12}^{-3}X_{13}X_{23}^2\right)\right)+\mathbf S(X_{12}^{k+l-3})\\[0.5em]
=&\frac1{2^{k+l}}X_{12}^{k+l}X_{23}^{m-k-l}\left[\left(\begin{array}{c}2k\\k\end{array}\right)\left(\begin{array}{c}2l\\l\end{array}\right)\left(1+\left(l-k\right)X_{12}^{-1}X_{13}+\frac{(k-l)^2-(k+l)}2X_{12}^{-2}X_{13}^2\right)\right.\\[0.5em]
&\quad-\left(l\left(\begin{array}{c}2k\\k\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)+k\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2k-2\\k\end{array}\right)\right)X_{12}^{-2}X_{23}^2\\[0.5em]
&\quad-\left(\begin{array}{c}2k\\k\end{array}\right)\left(\begin{array}{c}2l\\l\end{array}\right)\frac{(k-l)((k-l)^2-3(k+l)+2)}6X_{12}^{-3}X_{13}^3\\[0.5em]
&\quad\left.+\left(\left(\begin{array}{c}2k\\k\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)(-l)(l-k-2)+\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2k-2\\k\end{array}\right)(-k)(l-k+2)\right)X_{12}^{-3}X_{13}X_{23}^2\right]\\[0.5em]
&\quad+\mathbf S(X_{12}^{k+l-3}).
\end{aligned}
\label{eq:PmklLeadingTerms}
\end{equation}
Combining (\ref{eq:H2m2PmllAction}) with (\ref{eq:PmklLeadingTerms}) and dropping all the terms which are subleading to $X_{12}^{2l}$ we get
\begin{align*}
\hat H_2^{(-2)}\mathfrak P_{m,l,l}=&(m+1)(m+2l+2)X_{12}^{2l}X_{23}^{m-2l-2}\\[0.5em]
&\qquad\times\left[\frac1{2^{2l}}\left(\begin{array}{c}2l\\l\end{array}\right)^2\left(1-lX_{12}^{-2}X_{13}^2\right)-\frac{l}{2^{2l-1}}\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)X_{12}^{-2}X_{23}^2\right]\\[0.5em]
&-(m+1)(l+1)X_{12}^{2l}X_{23}^{m-2l-2}\\[0.5em]
&\qquad\times\left[\frac1{2^{2l+1}}\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(\begin{array}{c}2l\\l\end{array}\right)\left(1-X_{12}^{-1}X_{13}-lX_{12}^{-2}X_{13}^2\right)\right.\\[0.5em]
&\qquad-\frac1{2^{2l+1}}\left(l\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)+(l+1)\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l\\l+1\end{array}\right)\right)X_{12}^{-2}X_{23}^2\\[0.5em]
&\qquad+\frac1{2^{2l+1}}\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(1+X_{12}^{-1}X_{13}-lX_{12}^{-2}X_{13}^2\right)\\[0.5em]
&\qquad\left.-\frac1{2^{2l+1}}\left((l+1)\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l\\l+1\end{array}\right)+l\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)\right)X_{12}^{-2}X_{23}^2\right]\\[0.5em]
&+\mathbf S(X_{12}^{2l-2})\\[0.5em]
=&(m+1)X_{12}^{2l}X_{23}^{m-2l-2}\left[(m-2l)\frac{((2l-1)!!)^2}{(l!)^2}\right.\\[0.5em]
&\qquad-\frac{l}{2^{2l}}\left(\begin{array}{c}2l\\l\end{array}\right)\left((m+2l+2)\left(\begin{array}{c}2l\\l\end{array}\right)-(l+1)\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\right)X_{12}^{-2}X_{13}^2\\[0.5em]
&\qquad\left.-\frac1{2^{2l}}\left(\begin{array}{c}2l\\l\end{array}\right)\left((l+1)l\left(\begin{array}{c}2l\\l\end{array}\right)-(m+1)2^l\frac{(2l-3)!!}{(l-2)!}\right)X_{12}^{-2}X_{23}^2\right]+\mathbf S(X_{12}^{2l-2}).
\end{align*}
When $m>2l$, the first term on the right hand side is nonvanishing and coicides with the first case of (\ref{eq:LeadingTermsH2m2Pmll}). When $m=2l$, the first two terms on the right hand side vanish, while the third term simplifies exactly to the second case of (\ref{eq:LeadingTermsH2m2Pmll}). Finally, in the case $m=l=0$, the basis element is constant and thus annihinated by $\hat H_2^{(-2)}$.

Similarly, for the action of $\hat H_3^{(-2)}$ on the basis element we get
\begin{align*}
\hat H_3^{(-2)}\mathfrak P_{m,l,l}=&(m+1)(m+2l+2)X_{12}^{2l}X_{23}^{m-2l-2}\\[0.5em]
&\qquad\quad \times\left[\frac1{2^{2l}}\left(\begin{array}{c}2l\\l\end{array}\right)^2(1-l X_{12}^{-2}X_{13}^2)-\frac l{2^{2l-1}}\left(\begin{array}{c}2l\\ l\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)X_{12}^{-2}X_{23}^2\right]\\[0.5em]
&\quad +(m+1)(l+1)X_{12}^{2l+1}X_{13}^{-1}X_{23}^{m-2l-2}\\[0.5em]
&\qquad\quad\times\left[\frac1{2^{2l+1}}\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(\begin{array}{c}2l\\l\end{array}\right)(1-X_{12}^{-1}X_{13}-lX_{12}^{-2}X_{13}^2+lX_{12}^{-3}X_{13}^3)\right.\\[0.5em]
&\qquad\quad-\frac1{2^{2l+1}}\left(l\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)+(l+1)\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l\\l+1\end{array}\right)\right)X_{12}^{-2}X_{23}^2\\[0.5em]
&\qquad\quad+\frac1{2^{2l+1}}\left(\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(\begin{array}{c}2l-2\\ l\end{array}\right)3l+\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l\\l+1\end{array}\right)(-l-1)\right)X_{12}^{-3}X_{13}X_{23}^2\\[0.5em]
&\qquad\quad-\frac1{2^{2l+1}}\left(\begin{array}{c}2l\\l\end{array}\right)\left(\begin{array}{c}2l+2\\l+1\end{array}\right)\left(1+X_{12}^{-1}X_{13}-lX_{12}^{-2}X_{13}^2+lX_{12}^{-3}X_{13}^3\right)\\[0.5em]
&\qquad\quad +\frac1{2^{2l+1}}\left((l+1)\left(\begin{array}{c}2l\\ l\end{array}\right)\left(\begin{array}{c}2l\\ l+1\end{array}\right)+l\left(\begin{array}{c}2l+2\\ l+1\end{array}\right)\left(\begin{array}{c}2l-2\\ l\end{array}\right)X_{12}^{-2}X_{23}^2\right)\\[0.5em]
&\qquad\quad\left. -\frac1{2^{2l+1}}\left((l+1)\left(\begin{array}{c}2l\\ l\end{array}\right)\left(\begin{array}{c}2l\\ l+1\end{array}\right)-3l\left(\begin{array}{c}2l+2\\ l+1\end{array}\right)\left(\begin{array}{c}2l-2\\ l\end{array}\right)\right)X_{12}^{-3}X_{13}X_{23}^2\right]\\[0.5em]
&\quad+\mathbf S(X_{12}^{l-2})\\[0.5em]
=&(m+1)X_{12}^{2l}X_{23}^{m-2l-2}\left[(m-2l)\frac{((2l-1)!!)^2}{(l!)^2}\right.\\[0.5em]
&\qquad-\frac1{2^{2l}}(m+1)\left(2l(m+2l+2)\left(\begin{array}{c}2l\\ l\end{array}\right)\left(\begin{array}{c}2l-2\\l\end{array}\right)+(l+1)^2\left(\begin{array}{c}2l\\ l\end{array}\right)\left(\begin{array}{c}2l\\ l+1\end{array}\right)\right.\\[0.5em]
&\qquad\quad\left.\left.-3l(l+1)\left(\begin{array}{c}2l-2\\ l\end{array}\right)\left(\begin{array}{c}2l+2\\ l+1\end{array}\right)\right)X_{12}^{-2}X_{23}^2\right]+\mathbf S(X_{12}^{2l-2}).
\end{align*}
As with the previous operator, when $m>2l$ the first therm on the right hand side is nonvanishing and coincides with the first case of (\ref{eq:LeadingTermsH3m2Pmll}). When $m=2l>0$, the first term vanishes, while the coefficient in the second term simplifies exactly to the corresponding case of (\ref{eq:LeadingTermsH3m2Pmll}). Finally, when $m=l=0$, the basis element $\mathfrak P_{0,0,0}=1$ is annihilated by $\hat H_3^{(-2)}$.
\end{proof}

\begin{lemma}
The common kernel of $\hat H_1^{(-2)}$ with either one of the two remaining operators $\hat H_2^{(-2)},\hat H_3^{(-2)}$ is a graded subspace of the polynomial ring. For all $n\in\mathbb Z_{\geq0}$, the homogeneous component of the common kernel of degree $2n+1$ is trivial
\begin{equation}
\ker\hat H_1^{(-2)}\cap\ker\hat H_j^{(-2)}\Big|_{\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_{2n+1}}=\{0\},\qquad 2\leq j\leq3,
\label{eq:OddKernelH1m2Hjm2}
\end{equation}
while the homogeneous component of the common kernel of degree $2n$ is one-dimensional and given by
\begin{subequations}
\begin{align}
\ker\hat H_1^{(-2)}\cap\ker\hat H_2^{(-2)}\Big|_{\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_{2n}}=&\mathbb C\phi_{2n}^{(1,2)},\quad\textrm{where}\quad \phi_{2n}^{(1,2)}:=\sum_{l=0}^n(-1)^{n-l}\frac{2l+1}{n+l+1}\left(\begin{array}{c}2n\\n-l\end{array}\right)\mathfrak P_{2n,l,l},
\label{eq:EvenKernelH1m2H2m2}\\[0.3em]
\ker\hat H_1^{(-2)}\cap\ker\hat H_3^{(-2)}\Big|_{\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_{2n}}=&\mathbb C\phi_{2n}^{(1,3)},\quad\textrm{where}\quad \phi_{2n}^{(1,3)}:=\sum_{l=0}^n\frac{2l+1}{n+l+1}\left(\begin{array}{c}2n\\n-l\end{array}\right)\mathfrak P_{2n,l,l}.
\label{eq:EvenKernelH1m2H3m2}
\end{align}
\label{eq:EvenKernelH1m2Hjm2}
\end{subequations}
\end{lemma}
\begin{proof}
Let $m\in\mathbb Z_{\geq0}$ be a nonnegative integer. From (\ref{eq:KerH1m2}) we know that
\begin{equation}
\left\{\mathfrak P_{m,l,l}:0\leq l\leq\left\lfloor\frac m2\right\rfloor\right\}
\label{eq:KernelH1m2BasisIntersectionTwo}
\end{equation}
forms a basis on the kernel of operator $\hat H_1^{(-2)}$.

When $m\equiv1\bmod2$, it follows by (\ref{eq:LeadingTermsH2m2Pmll}) that the leading terms of the action of $\hat H_2^{(-2)}$ on basis elements (\ref{eq:KernelH1m2BasisIntersectionTwo}) are all distinct. Hence, the homogeneous component of the common kernel of $\hat H_1^{(-2)}$ and $\hat H_2^{(-2)}$ of degree $m$ must be trivial.

Now, assume $m=2n$ for some $n\in\mathbb N$ and let 
\begin{equation}
\psi=\sum_{l=0}^{n}c_l\mathfrak P_{2n,l,l}\quad\in\quad \ker\hat H_1^{(-2)}\cap\ker\hat H_2^{(-2)}\Big|_{\left(\mathbb C[X_{12},X_{13},X_{23}]\right)_{2n}}
\label{eq:PsiElementKernelH1m2H2m2}
\end{equation}
be a nontrivial element of the homonegeous component of the common kernel of degree $2n$. Again, by (\ref{eq:LeadingTermsH2m2Pmll}) it follows that necessarily $c_l\neq 0$. Hence the homogeneous component of the common kernel is at most one-dimensional.

It remains to show that $\phi_{2n}^{(1,2)}$ belongs to the kernel. By (\ref{eq:KerH1m2}) we know that $\phi_{2n}^{(1,2)}$ is annihilated by $\hat H_1^{(-2)}$. As for the action of $\hat H_2^{(-2)}$, consider an arbitrary element of the form (\ref{eq:PsiElementKernelH1m2H2m2}),  we have
\begin{equation*}
\begin{aligned}
\frac{X_{12}X_{23}^{m-1}}{m+1}&\hat H_2^{(-2)}\psi=\frac{X_{12}X_{23}^{m-1}}{m+1}\sum_{l=0}^nc_{l}\hat H_2^{(-2)}\mathfrak P_{2n,l,l}\\[0.5em]
\stackrel{(\ref{eq:H2m2ActionPmllUV})}{=}&\sum_{l=0}^n c_l \left((m+2l+2)\frac{U+V}2\mathcal P_l(U)\mathcal P_l(V)-(l+1)\mathcal P_l(U)\mathcal P_l(V)-(l+1)\mathcal P_l(U)\mathcal P_{l+1}(V)\right)\\[0.5em]
=\;\,&\sum_{l=0}^{n-1} \left( c_{l+1} \dfrac{(n + l + 2)(l+1)}{2l + 3} + c_{l} \dfrac{(n-l)(l+1)}{2l + 1} \right) \big( \mathcal P_l(U)\mathcal P_{l+1}(V) + \mathcal P_{l+1}(U)\mathcal P_{l}(V) \big)  
\end{aligned}
\end{equation*}
The right hand side of the above expression vanishes for $c_l$ as in (\ref{eq:EvenKernelH1m2H2m2}), namely when we specialize to
\begin{equation*}
c_l=(-1)^{n-l}\frac{2l+1}{n+l+1}\left(\begin{array}{c}2n\\ n-l\end{array}\right).
\end{equation*}

The proof of the remaining part (\ref{eq:EvenKernelH1m2H3m2}) is completely analogous to the argument presented above and thus omitted for the sake of brevity.
\end{proof}

\begin{customprop}{\ref{prop:KernelHm2}}
Let $p\in\mathbb C[X_{12},X_{13},X_{23}]$ be a polynomial annihilated by all three of the operators (\ref{eq:Hm2}), then necessarily it is a constant polynomial $p\in\mathbb C$. In other words,
\begin{equation}
\ker\hat H_1^{(-2)}\cap\ker\hat H_2^{(-2)}\cap\ker\hat H_3^{(-2)}=\mathbb C.
\label{eq:CommonKernelHm2}
\end{equation}
\end{customprop}
\begin{proof}
Recall that the three operators $\hat H_i^{(-2)},\;1\leq i\leq3$ are all homogeneous of degree $-2$. As a result, their common kernel is a graded subspace of the polynomial ring. The constant polynomial is annihilated by all three operators, so the homogeneous component of degree zero of the common kernel is $\mathbb C$. To prove (\ref{eq:CommonKernelHm2}) we have thus left to show that all higher homogeneous components of the common kernel are all trivial.

Let $m\in\mathbb N$ be a natural number. When $m\equiv 1\bmod 2$, by (\ref{eq:OddKernelH1m2Hjm2}) the corresponding homogeneous component must be trivial. Next, when $m=2n$ for some $n\in\mathbb N$, it follows by (\ref{eq:EvenKernelH1m2Hjm2}) that every homogeneous element $\psi$ of degree $2n$ in the common kernel must be propostional simultaneously to $\phi_{2n}^{(1,2)}$ and $\phi_{2n}^{(1,3)}$. The latter implies that $\psi=0$ and that completes the proof.
\end{proof}

