%    &\left(\oint \g G_L\right) Z^M=\g\left(\L^\a E_\a{}^M-\psi^{\ua} E_{\ua}{}^M+\frac12\eta^{\a\ab} w_\a E_{\ab}{}^M\right),\cr 
%    &\left(\oint \gb G_R\right) Z^M=\gb\left(\Lb^{\ab}E_{\ab}{}^M-\psib^{\ua}E_{\ua}{}^M-\frac12\eta^{\a\ab}\wb_{\ab}E_\a{}^M\right) .
%\end{align}
