Consider the integrated vertex operator. The most general conformal weight $(1,1)$ has the form
\begin{align}\label{Vads}
    &V=J^\a \Jb^{\ab} A_{\a\ab}+J^{\ua}\Jb^{\ub}A_{\ua\ub}+d_\a\dd_{\ab}P^{\a\ab}+\psi^{\ua}\psi^{\ub}\psib^{\uc}\psib^{\ud}S_{\ua\ub\uc\ud}+\L^\a w_\b\Lb^{\ab}\wb_{\bb}S_{\a\ab}{}^{\b\bb}\cr 
    &+\psi^{\ua}w_\a\psib^{\ub}\wb_{\ab}U_{\ua\ub}{}^{\a\ab}+J^\a\Jb^{\ua}A_{\a\ua}+J^{\ua}\Jb^{\ab}A_{\ua\ab}+J^\a\dd_{\ab}E_\a{}^{\ab}+d_\a\Jb^{\ab}E_{\ab}{}^\a\cr 
&+J^\a\psib^{\ua}\psib^{\ub}\hO_{\a\ua\ub}+\psi^{\ua}\psi^{\ub}\Jb^{\ab} O_{\ab\ua\ub}+J^\a\Lb^{\ab}\wb_{\bb}\hO_{\a\ab}{}^{\bb}+\L^\a w_\b\Jb^{\ab}O_{\ab\a}{}^\b\cr 
    &+J^\a\psib^{\ua}\wb_{\ab} \Ch_{\ua\a}{}^{\ab}+\psi^{\ua}w_\a\Jb^{\ab} C_{\ua\ab}{}^\a+J^{\ua}\dd_{\ab}E_{\ua}{}^{\ab}+d_\a\Jb^{\ua}E_{\ua}{}^\a\cr 
&+J^{\ua}\psib^{\ub}\psib^{\uc}\hO_{\ua\ub\uc}+\psi^{\ub}\psi^{\uc}\Jb^{\ua}O_{\ua\ub\uc}+J^{\ua}\Lb^{\ab}\wb_{\bb}\hO_{\ua\ab}{}^{\bb}+\L^\a w_\b\Jb^{\ua}O_{\ua\a}{}^\b\cr 
    &+J^{\ua}\psib^{\ub}\wb_{\ab}C_{\ua\ub}{}^{\ab}+\psi^{\ub} w_\a\Jb^{\ua}C_{\ua\ub}{}^\a+d_\a\psib^{\ua}\psib^{\ub}\Dh_{\ua\ub}{}^\a+\psi^{\ua}\psi^{\ub}\dd_{\ab}D_{\ua\ub}{}^{\ab} \cr 
    &+d_\a\Lb^{\ab}\wb_{\bb}\Dh_{\ab}{}^{\bb\a}+\L^\a w_\b \dd_{\ab} D_\a{}^{\b\ab}+d_\a\psib^{\ua}\wb_{\ab}V_{\ua}{}^{\a\ab}+\psi^{\ua}w_\a\dd_{\ab}\Vh_{\ua}{}^{\ab\a}\cr 
    &+\psi^{\ua}\psi^{\ub}\Lb^{\ab}\wb_{\bb} S_{\ua\ub\ab}{}^{\bb}+\L^\a w_\b\psib^{\ua}\psib^{\ub}S_{\ua\ub\a}{}^\b+\psi^{\ua}\psi^{\ub}\psib^{\uc}\wb_{\ab}Y_{\ua\ub\uc}{}^{\ab}\cr  
    &+\psi^{\uc}w_\a\psib^{\ua}\psib^{\ub}\Yh_{\ua\ub\uc}{}^\a+\L^\a w_\b\psib^{\ua}\wb_{\ab}Y_{\ua\a}{}^{\b\ab}+\psi^{\ua}w_\a\Lb^{\ab}\wb_{\bb}\Yh_{\ua\ab}{}^{\bb\a}.
\end{align}
We now compute the action of $\g G_L$ and $\gb G_R$ on the integrated vertex $V$ that are defined as
\begin{align}
    \left(\oint \g G_L\right)V=\oint d\s'[\g G_L(\s'),V(\s)],\quad \left(\oint \gb G_R\right)V=\oint d\s'[\gb G_R(\s'),V(\s)],
\end{align}
where we use the commutators shown in the Appendix. 

To compute $\left(\oint \g G_L\right)V$ we proceed as follows. We first note that the integrated vertex operator (\ref{Vads}) can be written as
\begin{align}\label{VL}
    V=\Jb^{\ab}V_{\ab}+\Jb^{\ua}V_{\ua}+\dd_{\ab}V^{\ab}+\psib^{\ua}\psib^{\ub}V_{\ua\ub}+\Lb^{\ab}\wb_{\bb}V_{\ab}{}^{\bb}+\psib^{\ua}\wb_{\ab}V_{\ua}{}^{\ab}, 
\end{align}
where
\begin{align}\label{vertexADS}
    &V_{\ab}=-J^\a A_{\a\ab}+J^{\ua}A_{\ua\ab}-d_\a E_z{\ab}{}^{\a}+\psi^{\ua}\psi^{\ub}O_{\ab\ua\ub}+\L^\a w_\b O_{\ab\a}{}^\b-\psi^{\ua}w_\a C_{\ua\ab}{}^\a,\cr 
    &V_{\ua}=J^\a A_{\a\ua}+J^{\ub}A_{\ub\ua}+d_\a E_{\ua}{}^\a+\psi^{\ub}\psi^{\uc}O_{\ua\ub\uc}+\L^\a w_\b O_{\ua\a}{}^\b+\psi^{\ub} w_\a C_{\ua\ub}{}^\a,\cr
    &V^{\ab}=-J^\a E_\a{}^{\ab}+J^{\ua}E_{\ua}{}^{\ab}-d_\a P^{\a\ab}+\psi^{\ua}\psi^{\ub}D_{\ua\ub}{}^{\ab}+\L^\a w_\b D_\a{}^{\b\ab}-\psi^{\ua}w_\a\Vh_{\ua}{}^{\ab\a} ,\cr
    &V_{\ua\ub}=J^\a \hO_{\a\ua\ub}+J^{\uc}\hO_{\uc\ua\ub}+d_\a\Dh_{\ua\ub}{}^\a+\psi^{\uc}\psi^{\ud}S_{\uc\ud\ua\ub}+\L^\a w_\b S_{\ua\ub\a}{}^\b+\psi^{\uc}w_\a\Yh_{\ua\ub\uc}{}^\a ,\cr &V_{\ab}{}^{\bb}=J^\a\hO_{\a\ab}{}^{\bb}+J^{\ua}\hO_{\ua\ab}{}^{\bb}+d_\a\Dh_{\ab}{}^{\bb\a}+\psi^{\ua}\psi^{\ub}S_{\ua\ub\ab}{}^{\bb}+\L^\a w_\b S_{\a\ab}{}^{\b\bb}+\psi^{\ua}w_\a\Yh_{\ua\ab}{}^{\bb\a} ,\cr 
    &V_{\ua}{}^{\ab}=-J^\a \Ch_{\ua\a}{}^{\ab}+J^{\ub}C_{\ub\ua}{}^{\ab}-d_\a V_{\ua}{}^{\a\ab}+\psi^{\ub}\psi^{\uc}Y_{\ub\uc\ua}{}^{\ab}+\L^\a w_{\b}Y_{\ua\a}{}^{\b\ab}-\psi^{\ub}w_\a U_{\ub\ua}{}^{\a\ab} .
\end{align}
Consider the first term in (\ref{VL}). We obtain
\begin{align}\label{GL1}
    \left(\oint \g G_L\right)\Jb^{\ab}V_{\ab}=\N\left(\g\Jb^{\ab}\left(\L^\a A_{\a\ab}+\psi^{\ua}A_{\ua\ab}-w_\a E_{\ab}{}^\a\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GL2}
    &\N_{(\a}A_{\b)\ab}=-\g^{\ua}_{\a\b}A_{\ua\ab},\cr 
    &\N_\a A_{\ua\ab}+\N_{\ua}A_{\a\ab}=-(\g_{\ua})_{\a\b}E_{\ab}{}^\b,\cr
    &O_{\ab\a}{}^\b=-\frac12(\g^{\ua\ub})_\a{}^\b O_{\ab\ua\ub}=\frac14 (\g^{\ua\ub})_\a{}^\b \N_{[\ua}A_{\ub]\ab}.
\end{align}
In the calculation of (\ref{GL1}) the equations derived from (\ref{GL2}) just as in the flat space case. For example, acting with $\N_\a$ one obtains
\begin{align}
    &\N_\a E_{\ab}{}^\b-\frac12\eta^{\b\gb}\N_{\gb}A_{\a\ab}=-\frac14(\g^{\ua\ub})_\a{}^\b \N_{[\ua}A_{\ub]\ab}.
\end{align}
This equation was derived in \cite{Chandia:2017afc} (see also \cite{Chandia:2018nyh,Chandia:2019paj} for a discussion of the generic background geometry). The background field $C_{\ua\ab}{}^\a$ is given by other background fields as
\begin{align}
    C_{\ua\a}{}^\b=-\N_{\ua}E_{\ab}{}^\a+\frac12\eta^{\a\gb}\N_{\gb}A_{\ua\ab}+\frac14(\g_{\ua})^{\a\b}A_{\b\ab}.
\end{align}

A similar calculation can be done for the remaining terms in (\ref{VL}). For the second term in (\ref{VL}) we obtain
\begin{align}\label{GL3}
    \left(\oint \g G_L\right)\Jb^{\ua}V_{\ua}=\N\left(\g\Jb^{\ua}\left(\L^\a A_{\a\ua}-\psi^{\ub}A_{\ub\ua}-w_\a E_{\ua}{}^\a\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GL4}
    &\N_{(\a}A_{\b)\ua}=\g^{\ub}_{\a\b}A_{\ub\ua},\cr 
    &\N_\a A_{\ub\ua}-\N_{\ub}A_{\a\ua}=(\g_{\ub})_{\a\b}E_{\ua}{}^\b,\cr
    &O_{\ua\a}{}^\b=-\frac12(\g^{\ub\uc})_\a{}^\b O_{\ua\ub\uc}=\frac14 (\g^{\ub\uc})_\a{}^\b \N_{[\ub}A_{\uc]\ua}.
\end{align}
In the calculation of (\ref{GL3}) the equations derived from (\ref{GL4}) just as in the flat space case. For example, acting with $\N_\a$ one obtains
\begin{align}
    &\N_\a E_{\ua}{}^\b-\frac12\eta^{\b\gb}\N_{\gb}A_{\a\ua}=\frac14(\g^{\ub\uc})_\a{}^\b \N_{[\ub}A_{\uc]\ua}.
\end{align}
The background field $C_{\ua\ub}{}^\a$ is given by other background fields as
\begin{align}
    C_{\ua\ub}{}^\a=-\N_{\ub}E_{\ua}{}^\a-\frac12\eta^{\a\gb}\N_{\gb}A_{\ub\ua}+\frac14(\g_{\ub})^{\a\b}A_{\b\ua}.
\end{align}

For the third term in (\ref{VL}) we obtain
\begin{align}\label{GL5}
    \left(\oint \g G_L\right)\dd_{\ab}V^{\ab}=\N\left(\g\dd_{\ab}\left(\L^\a E_{\a}{}^{\ab}+\psi^{\ua}E_{\ua}{}^{\ab}-w_\a P^{\a\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GL6}
    &\N_{(\a}E_{\b)}{}^{\ab}=-\g^{\ua}_{\a\b}E_{\ua}{}^{\ab},\cr 
    &\N_\a E_{\ua}{}^{\ab}+\N_{\ua}E_{\a}{}^{\ab}=-(\g_{\ua})_{\a\b}P^{\b\ab},\cr
    &D_{\a}{}^{\b\ab}=-\frac12(\g^{\ua\ub})_\a{}^\b D_{\ua\ub}{}^{\ab}=\frac14 (\g^{\ua\ub})_\a{}^\b \N_{[\ua}E_{\ub]}{}^{\ab}.
\end{align}
In the calculation of (\ref{GL3}) the equations derived from (\ref{GL4}) just as in the flat space case. For example, acting with $\N_\a$ one obtains
\begin{align}
    &\N_\a P^{\b\ab}-\frac12\eta^{\b\gb}\N_{\gb}E_\a{}^{\ab}=-\frac14(\g^{\ua\ub})_\a{}^\b \N_{[\ua}E_{\ub]}{}^{\ab}.
\end{align}
The background field $\Vh_{\ua}{}^{\ab\a}$ is given by other background fields as
\begin{align}
    \Vh_{\ua}{}^{\ab\a}=-\N_{\ua}P^{\a\ab}+\frac12\eta^{\a\gb}\N_{\gb}E_{\ua}{}^{\ab}+\frac14\g_{\ua}^{\a\b}E_\b{}^{\ab}.
\end{align}

For the fourth term in (\ref{VL}) we obtain
\begin{align}\label{GL7}
    \left(\oint \g G_L\right)\psib^{\ua}\psib^{\ub}V_{\ua\ub}=\N\left(\g\psib^{\ua}\psib^{\ub}\left(\L^\a \hO_{\a\ua\ub}-\psi^{\uc}\hO_{\uc\ua\ub}-w_\a \Dh_{\ua\ub}{}^\a\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GL8}
    &\N_{(\a}\hO_{\b)\ua\ub}=\g^{\uc}_{\a\b}\hO_{\uc\ua\ub},\cr 
    &\N_\a \hO_{\uc\ua\ub}-\N_{\uc}\hO_{\a\ua\ub}=(\g_{\uc})_{\a\b}\Dh_{\ua\ub}{}^\b,\cr
    &S_{\ua\ub\a}{}^\b=-\frac12(\g^{\uc\ud})_\a{}^\b S_{\uc\ud\ua\ub}=\frac14 (\g^{\uc\ud})_\a{}^\b \N_{[\uc}\hO_{\ud]\ua\ub}.
\end{align}
In the calculation of (\ref{GL7}) the equations derived from (\ref{GL8}) just as in the flat space case. For example, acting with $\N_\a$ one obtains
\begin{align}
    &\N_\a \Dh_{\ua\ub}{}^\b-\frac12\eta^{\b\gb}\N_{\gb}\hO_{\a\ua\ub}=\frac14(\g^{\uc\ud})_\a{}^\b \N_{[\uc}\hO_{\ud]\ua\ub}.
\end{align}
The background field $\Yh_{\ua\ub\uc}{}^\a$ is given by other background fields as
\begin{align}
    \Yh_{\ua\ub\uc}{}^\a=-\N_{\uc}\Dh_{\ua\ub}{}^\a
    -\frac12\eta^{\a\gb}\N_{\gb}\hO_{\uc\ua\ub}-\frac14(\g_{\uc})^{\a\b}\hO_{\b\ua\ub}.
\end{align}

For the fifth term in (\ref{VL}) we obtain
\begin{align}\label{GL9}
    \left(\oint \g G_L\right)\Lb^{\ab}\wb_{\bb}V_{\ab}{}^{\bb} =\N\left(\g\Lb^{\ab}\wb_{\bb}\left(\L^\a \hO_{\a\ab}{}^{\bb}-\psi^{\ua}\hO_{\ua\ab}{}^{\bb}-w_\a \Dh_{\ab}{}^{\bb\a}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GL10}
    &\N_{(\a}\hO_{\b)\ab}{}^{\bb}=\g^{\ua}_{\a\b}\hO_{\ua\ab}{}^{\bb},\cr 
    &\N_\a \hO_{\ua\ab}{}^{\bb}-\N_{\ua}\hO_{\a\ab}{}^{\bb}=(\g_{\ua})_{\a\b}\Dh_{\ab}{}^{\bb\b},\cr
    &S_{\a\ab}{}^{\b\bb}=-\frac12(\g^{\ua\ub})_\a{}^\b S_{\ua\ub\ab}{}^{\bb}=\frac14 (\g^{\ua\ub})_\a{}^\b \N_{[\ua}\hO_{\ub]\ab}{}^{\bb}.
\end{align}
In the calculation of (\ref{GL9}) the equations derived from (\ref{GL10}) just as in the flat space case. For example, acting with $\N_\a$ one obtains
\begin{align}
    &\N_\a\Dh_{\ab}{}^{\bb\a}-\frac12\eta^{\b\gb}\N_{\gb}\hO_{\a\ab}{}^{\bb}=\frac14(\g^{\ua\ub})_\a{}^\b \N_{[\ua}\hO_{\ub]\ab}{}^{\bb}.
\end{align}
The background field $\Yh_{\ua\ab}{}^{\bb\a}$ is given by other background fields as
\begin{align}
    \Yh_{\ua\ab}{}^{\bb\a}=-\N_{\ua}\Dh_{\ab}{}^{\bb\a}-\frac12\eta^{\a\gb}\N_{\gb}\hO_{\ua\ab}{}^{\bb}+\frac14(\g_{\ua})^{\a\b}\hO_{\b\ab}{}^{\bb}.
\end{align}


And finally for the sixth term in (\ref{VL}) we obtain
\begin{align}\label{GL11}
    \left(\oint \g G_L\right)\psib^{\ua}\wb_{\ab}V_{\ua}{}^{\ab}=\N\left(\g\psib^{\ua}\wb_{\ab}\left(\L^\a \Ch_{\ua\a}{}^{\ab}+\psi^{\ub}C_{\ub\ua}{}^{\ab}-w_\a V_{\ua}{}^{\a\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GL12}
    &\N_{(\a}\Ch_{\ua\b)}{}^{\ab}=-\g^{\ub}_{\a\b}C_{\ub\ua}{}^{\ab},\cr 
    &\N_\a C_{\ub\ua}{}^{\ab}+\N_{\ub}\Ch_{\ua\a}{}^{\ab}=-(\g_{\ub})_{\a\b}V_{\ua}{}^{\b\ab},\cr
    &Y_{\ua\a}{}^{\b\ab}=-\frac12(\g^{\ub\uc})_\a{}^\b Y_{\ub\uc\ua}{}^{\ab}=\frac14 (\g^{\ub\uc})_\a{}^\b \N_{[\ub}C_{\uc]\ua}{}^{\ab}.
\end{align}
In the calculation of (\ref{GL11}) the equations derived from (\ref{GL12}) just as in the flat space case. For example, acting with $\N_\a$ one obtains
\begin{align}
    &\N_\a V_{\ua}{}^{\b\ab}-\frac12\eta^{\b\gb}\N_{\gb}\Ch_{\ua\a}{}^{\ab}=-\frac14(\g^{\ub\uc})_\a{}^\b \N_{[\ub}C_{\uc]\ua}{}^{\ab}.
\end{align}
The background field $U_{\ub\ua}{}^{\a\ab}$ is given by other background fields as
\begin{align}
    U_{\ub\ua}{}^{\a\ab}=-\N_{\ub}V_{\ua}{}^{\a\ab}+\frac12\eta^{\a\gb}\N_{\gb}C_{\ub\ua}{}^{\ab}+\frac14(\g_{\ub})^{\a\b}\Ch_{\ua\b}{}^{\ab}.
\end{align}

In summary, we have obtained 
\begin{align}
     &\left(\oint \g G_L\right)V=\p (\g w_L),
\end{align}
where
\begin{align}\label{wLis}
    w_L&=\Jb^{\ab}\left(\L^\a A_{\a\ab}+\psi^{\ua}A_{\ua\ab}-w_\a E_{\ab}{}^\a\right)+\Jb^{\ua}\left(\L^\a A_{\a\ua}-\psi^{\ub}A_{\ub\ua}-w_\a E_{\ua}{}^\a\right)\cr
     &+\dd_{\ab}\left(\L^\a E_{\a}{}^{\ab}+\psi^{\ua}E_{\ua\ab}-w_\a P^{\a\ab}\right)+\psib^{\ua}\psib^{\ub}\left(\L^\a \hO_{\a\ua\ub}-\psi^{\uc}\hO_{\uc\ua\ub}-w_\a \Dh_{\ua\ub}{}^\a\right)\cr 
     &+\Lb^{\ab}\wb_{\bb}\left(\L^\a \hO_{\a\ab}{}^{\bb}-\psi^{\ua}\hO_{\ua\ab}{}^{\bb}-w_\a \Dh_{\ab}{}^{\bb\a}\right)+\psib^{\ua}\wb_{\ab}\left(\L^\a \Ch_{\ua\a}{}^{\ab}+\psi^{\ub}C_{\ub\ua}{}^{\ab}-w_\a V_{\ua}{}^{\a\ab}\right),
\end{align}
which resembles the result of the flat space-time background case.

For the calculation of $\left(\oint \g G_R\right)V$, we proceed in a similar way. That is, we recognize that the integrated vertex operator (\ref{Vads}) can be written as
\begin{align}\label{VR}
    V=J^{\a}\Vh_{\a}+J^{\ua}\Vh_{\ua}+d_{\a}\Vh^{\a}+\psi^{\ua}\psi^{\ub}\Vh_{\ua\ub}+\L^{\a}w_{\b}\Vh_{\a}{}^{\b}+\psi^{\ua}w_{\a}\Vh_{\ua}{}^{\a}, 
\end{align}
where
\begin{align}\label{vertexADSP}
    &\Vh_{\a}=\Jb^{\ab} A_{\a\ab}+\Jb^{\ua}A_{\a\ua}+\dd_{\ab} E_{\a}{}^{\ab}+\psib^{\ua}\psib^{\ub}\hO_{\a\ua\ub}+\Lb^{\ab} \wb_{\bb} \hO_{\a\ab}{}^{\bb}+\psib^{\ua}\wb_{\ab} \Ch_{\ua\a}{}^{\ab},\cr 
    &\Vh_{\ua}=\Jb^{\ab} A_{\ua\ab}+\Jb^{\ub}A_{\ua\ub}+\dd_{\ab} E_{\ua}{}^{\ab}+\psib^{\ub}\psib^{\uc}\hO_{\ua\ub\uc}+\Lb^{\ab} \wb_{\bb} \hO_{\ua\ab}{}^{\bb}+\psib^{\ub} \wb_{\ab} C_{\ua\ub}{}^{\ab},\cr
    &\Vh^{\a}=\Jb^{\ab} E_{\ab}{}^{\a}+\Jb^{\ua}E_{\ua}{}^{\a}+\dd_{\ab} P^{\a\ab}+\psib^{\ua}\psib^{\ub}\Dh_{\ua\ub}{}^{\a}+\Lb^{\ab} \wb_{\bb} \Dh_{\ab}{}^{\bb\a}+\psib^{\ua}\wb_{\ab} V_{\ua}{}^{\a\ab} ,\cr
    &\Vh_{\ua\ub}=\Jb^{\ab} O_{\ab\ua\ub}+\Jb^{\uc} O_{\uc\ua\ub}+\dd_{\ab} D_{\ua\ub}{}^{\ab}+\psib^{\uc}\psib^{\ud}S_{\ua\ub\uc\ud}+\Lb^{\ab} \wb_{\bb} S_{\ua\ub\ab}{}^{\bb}+\psib^{\uc}\wb_{\ab} Y_{\ua\ub\uc}{}^{\ab} ,\cr 
    &\Vh_{\a}{}^{\b}=\Jb^{\ab} O_{\ab\a}{}^{\b}+\Jb^{\ua} O_{\ua\a}{}^{\b}+\dd_{\ab} D_{\a}{}^{\b\ab}+\psib^{\ua}\psib^{\ub}S_{\ua\ub\a}{}^{\b}+\Lb^{\ab} \wb_{\bb} S_{\a\ab}{}^{\b\bb}+\psib^{\ua}\wb_{\ab} Y_{\ua\a}{}^{\b\ab} ,\cr 
    &\Vh_{\ua}{}^{\a}=\Jb^{\ab} C_{\ua\ab}{}^{\a}+\Jb^{\ub}C_{\ub\ua}{}^{\a}+\dd_{\ab} \Vh_{\ua}{}^{\ab\a}+\psib^{\ub}\psib^{\uc}\Yh_{\ub\uc\ua}{}^{\a}+\Lb^{\ab} \wb_{\bb}\Yh_{\ua\ab}{}^{\bb\a}+\psib^{\ub}\wb_{\ab} U_{\ua\ub}{}^{\a\ab} .
\end{align}

Consider the first term in (\ref{VR}). We obtain
\begin{align}\label{GR1}
    \left(\oint \gb G_R\right)J^{\a}\Vh_{\a}=\Nb\left(\gb J^{\a}\left(-\Lb^{\b} A_{\a\ab}+\psib^{\ua}A_{\a\ua}+\wb_{\ab} E_{\a}{}^{\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GR2}
    &\N_{(\ab}A_{\a\bb)}=\g^{\ua}_{\ab\bb}A_{\a\ua},\cr 
    &\N_{\ab} A_{\a\ua}-\N_{\ua}A_{\a\ab}=(\g_{\ua})_{\ab\bb}E_{\a}{}^{\bb},\cr
    &\hO_{\a\ab}{}^{\bb}=-\frac12(\g^{\ua\ub})_{\ab}{}^{\bb} \hO_{\a\ua\ub}=\frac14 (\g^{\ua\ub})_{\ab}{}^{\bb} \N_{[\ua}A_{\a\ub]}.
\end{align}
In the calculation of (\ref{GR1}) the equations derived from (\ref{GR2}) just as in the flat space case. For example, acting with $\N_{\ab}$ one obtains
\begin{align}
    &\N_{\ab} E_{\a}{}^{\bb}+\frac12\eta^{\g\bb}\N_{\g}A_{\a\ab}=\frac14(\g^{\ua\ub})_{\ab}{}^{\bb} \N_{[\ua}A_{\a\ub]}.
\end{align}
The background field $\Ch_{\ua\a}{}^{\ab}$ is given by other background fields as
\begin{align}
    \Ch_{\ua\a}{}^{\ab}=\N_{\ua}E_{\a}{}^{\ab}+\frac12\eta^{\g\ab}\N_{\g}A_{\a\ua}+\frac14(\g_{\ua})^{\ab\bb}A_{\a\bb}.
\end{align}

A similar calculation can be done for the remaining terms in (\ref{VR}). For the second term in (\ref{VR}) we obtain
\begin{align}\label{GR3}
    \left(\oint \g G_R\right) J^{\ua}\Vh_{\ua}=\Nb\left(\gb J^{\ua}\left(\Lb^{\ab} A_{\ua\a}-\psib^{\ub}A_{\ua\ub}-\wb_{\ab} E_{\ua}{}^{\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GR4}
    &\N_{(\ab}A_{\ua\bb)}=\g^{\ub}_{\ab\bb}A_{\ua\ub},\cr 
    &\N_{\ab} A_{\ua\ub}-\N_{\ub}A_{\ua\ab}=(\g_{\ub})_{\ab\bb}E_{\ua}{}^{\bb},\cr
    &\hO_{\ua\ab}{}^{\bb}=-\frac12(\g^{\ub\uc})_{\ab}{}^{\bb} \hO_{\ua\ub\uc}=\frac14 (\g^{\ub\uc})_{\ab}{}^{\bb} \N_{[\ub}A_{\ua\uc]}.
\end{align}
In the calculation of (\ref{GR3}) the equations derived from (\ref{GL4}) just as in the flat space case. For example, acting with $\N_{\ab}$ one obtains
\begin{align}
    &\N_{\ab} E_{\ua}{}^{\bb}+\frac12\eta^{\g\bb}\N_{\g}A_{\ua\ab}=\frac14(\g^{\ub\uc})_{\ab}{}^{\bb} \N_{[\ub}A_{\ua\uc]}.
\end{align}
The background field $C_{\ua\ub}{}^{\ab}$ is given by other background fields as
\begin{align}
    C_{\ua\ub}{}^{\ab}=\N_{\ub}E_{\ua}{}^{\ab}+\frac12\eta^{\g\ab}\N_{\g}A_{\ua\ub}+\frac14(\g_{\ub})^{\ab\bb}A_{\ua\bb}.
\end{align}

For the third term in (\ref{VR}) we obtain
\begin{align}\label{GR5}
    \left(\oint \g G_R\right) d_{\a}\Vh^{\a}=\Nb\left(\gb d_{\a}\left(-\Lb^{\ab} E_{\ab}{}^{\a}-\psib^{\ua}E_{\ua}{}^{\a}+\wb_{\ab} P^{\a\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GR6}
    &\N_{(\ab}E_{\bb)}{}^{\a}=\g^{\ua}_{\ab\bb}E_{\ua}{}^{\a},\cr 
    &\N_{\ab} E_{\ua}{}^{\a}-\N_{\ua}E_{\ab}{}^{\a}=(\g_{\ua})_{\ab\bb}P^{\a\bb},\cr
    &\Dh_{\ab}{}^{\bb\a}=-\frac12(\g^{\ua\ub})_{\ab}{}^{\bb} \Dh_{\ua\ub}{}^{\a}=\frac14 (\g^{\ua\ub})_{\ab}{}^{\bb} \N_{[\ua}E_{\ub]}{}^{\a}.
\end{align}
In the calculation of (\ref{GR3}) the equations derived from (\ref{GL4}) just as in the flat space case. For example, acting with $\N_{\ab}$ one obtains
\begin{align}
    &\N_{\ab} P^{\a\bb}+\frac12\eta^{\g\bb}\N_{\g}E_{\ab}{}^{\a}=\frac14(\g^{\ua\ub})_{\ab}{}^{\bb} \N_{[\ua}E_{\ub]}{}^{\a}.
\end{align}
The background field $V_{\ua}{}^{\a\ab}$ is given by other background fields as
\begin{align}
    V_{\ua}{}^{\a\ab}=\N_{\ua}P^{\a\ab}+\frac12\eta^{\g\ab}\N_{\g}E_{\ua}{}^{\a}+\frac14\g_{\ua}^{\ab\bb}E_{\bb}{}^{\a}.
\end{align}

For the fourth term in (\ref{VR}) we obtain
\begin{align}\label{GR7}
    \left(\oint \gb G_R\right)\psi^{\ua}\psi^{\ub}\Vh_{\ua\ub}=\Nb\left(\gb\psi^{\ua}\psi^{\ub}\left(\Lb^{\ab} O_{\ab\ua\ub}-\psib^{\uc} O_{\uc\ua\ub}-\wb_{\ab} D_{\ua\ub}{}^{\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GR8}
    &\N_{(\ab} O_{\bb)\ua\ub}=\g^{\uc}_{\ab\bb} O_{\uc\ua\ub},\cr 
    &\N_{\ab} O_{\uc\ua\ub}-\N_{\uc} O_{\ab\ua\ub}=(\g_{\uc})_{\ab\bb} D_{\ua\ub}{}^{\bb},\cr
    &S_{\ua\ub\ab}{}^{\bb}=-\frac12(\g^{\uc\ud})_{\ab}{}^{\bb} S_{\ua\ub\uc\ud}=\frac14 (\g^{\uc\ud})_{\ab}{}^{\bb} \N_{[\uc} O_{\ud]\ua\ub}.
\end{align}
In the calculation of (\ref{GR7}) the equations derived from (\ref{GR8}) just as in the flat space case. For example, acting with $\N_{\ab}$ one obtains
\begin{align}
    &\N_{\ab} D_{\ua\ub}{}^{\bb}+\frac12\eta^{\g\bb}\N_{\g} O_{\ab\ua\ub}=\frac14(\g^{\uc\ud})_{\ab}{}^{\bb} \N_{[\uc} O_{\ud]\ua\ub}.
\end{align}
The background field $Y_{\ua\ub\uc}{}^{\ab}$ is given by other background fields as
\begin{align}
    Y_{\ua\ub\uc}{}^{\ab}=\N_{\uc} D_{\ua\ub}{}^{\ab}
    +\frac12\eta^{\g\ab}\N_{\g} O_{\uc\ua\ub}+\frac14(\g_{\uc})^{\ab\bb} O_{\bb\ua\ub}.
\end{align}

For the fifth term in (\ref{VR}) we obtain
\begin{align}\label{GR9}
    \left(\oint \gb G_R\right)\L^{\a} w_{\b}\Vh_{\a}{}^{\b} =\Nb\left(\gb\L^{\a} w_{\b}\left(\Lb^{\ab} O_{\ab\a}{}^{\b}-\psib^{\ua} O_{\ua\a}{}^{\b}-\wb_{\ab} D_{\a}{}^{\b\ab}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GR10}
    &\N_{(\ab} O_{\bb)\a}{}^{\b}=\g^{\ua}_{\ab\bb} O_{\ua\a}{}^{\b},\cr 
    &\N_{\ab} O_{\ua\a}{}^{\b}-\N_{\ua} O_{\ab\a}{}^{\b}=(\g_{\ua})_{\ab\bb} D_{\a}{}^{\b\bb},\cr
    &S_{\a\ab}{}^{\b\bb}=-\frac12(\g^{\ua\ub})_{\ab}{}^{\bb} S_{\ua\ub\a}{}^{\b}=\frac14 (\g^{\ua\ub})_{\ab}{}^{\bb} \N_{[\ua} O_{\ub]\a}{}^{\b}.
\end{align}
In the calculation of (\ref{GR9}) the equations derived from (\ref{GR10}) just as in the flat space case. For example, acting with $\N_{\ab}$ one obtains
\begin{align}
    &\N_{\ab} D_{\a}{}^{\b\bb}+\frac12\eta^{\g\bb}\N_{\g} O_{\ab\a}{}^{\b}=\frac14(\g^{\ua\ub})_{\ab}{}^{\bb} \N_{[\ua} O_{\ub]\a}{}^{\b}.
\end{align}
The background field $Y_{\ua\a}{}^{\b\ab}$ is given by other background fields as
\begin{align}
    Y_{\ua\a}{}^{\b\ab}=\N_{\ua}D_{\a}{}^{\b\ab}+\frac12\eta^{\g\ab}\N_{\g}O_{\ua\a}{}^{\b}+\frac14(\g_{\ua})^{\ab\bb}O_{\bb\a}{}^{\b}.
\end{align}


And finally for the sixth term in (\ref{VR}) we obtain
\begin{align}\label{GR11}
    \left(\oint \gb G_R\right)\psi^{\ua} w_{\a}\Vh_{\ua}{}^{\a}=\Nb\left(\gb\psi^{\ua} w_{\a}\left(-\Lb^{\ab} C_{\ua\ab}{}^{\a}+\psib^{\ub}C_{\ub\ua}{}^{\a}+\wb_{\ab} \Vh_{\ua}{}^{\ab\a}\right)\right),
\end{align}
provided that the background fields satisfy the equations
\begin{align}\label{GR12}
    &\N_{(\ab} C_{\ua\bb)}{}^{\a}=\g^{\ub}_{\ab\bb}C_{\ub\ua}{}^{\a},\cr 
    &\N_{\ab} C_{\ub\ua}{}^{\a}-\N_{\ub} C_{\ua\ab}{}^{\a}=(\g_{\ub})_{\ab\bb}\Vh_{\ua}{}^{\bb\a},\cr
    &\Yh_{\ua\ab}{}^{\bb\a}=-\frac12(\g^{\ub\uc})_{\ab}{}^{\bb} \Yh_{\ub\uc\ua}{}^{\a}=\frac14 (\g^{\ub\uc})_{\ab}{}^{\bb} \N_{[\ub}C_{\uc]\ua}{}^{\a}.
\end{align} 
In the calculation of (\ref{GL11}) the equations derived from (\ref{GR12}) just as in the flat space case. For example acting with $\N_{\ab}$ one obtains
\begin{align}
    &\N_{\ab} \Vh_{\ua}{}^{\bb\a}+\frac12\eta^{\g\bb}\N_{\g} C_{\ua\ab}{}^{\a}=\frac14(\g^{\ub\uc})_{\ab}{}^{\bb} \N_{[\ub}C_{\uc]\ua}{}^{\a}.
\end{align}
The background field $U_{\ua\ub}{}^{\a\ab}$ is given by other background fields as
\begin{align}
    U_{\ua\ub}{}^{\a\ab}=\N_{\ub}\Vh_{\ua}{}^{\ab\a}+\frac12\eta^{\g\ab}\N_{\g}C_{\ub\ua}{}^{\a}+\frac14(\g_{\ub})^{\ab\bb} C_{\ua\bb}{}^{\a}.
\end{align}

Then, we have obtained the following
\begin{align}
     &\left(\oint \g G_R\right)V=\pb (\gb w_R), 
\end{align}
where
\begin{align}\label{wRis}
    w_R&=J^{\a}\left(-\Lb^{\ab} A_{\a\ab}+\psib^{\ua}A_{\a\ua}+\wb_{\ab} E_{\a}{}^{\ab}\right)+ J^{\ua}\left(\Lb^{\ab} A_{\ua\ab}-\psib^{\ub}A_{\ua\ub}-\wb_{\ab} E_{\ua}{}^{\ab}\right)\cr
     &+d_{\a}\left(-\Lb^{\ab} E_{\ab}{}^{\a}+\psib^{\ua}E_{\ua}{}^{\a}+\wb_{\ab} P^{\a\ab}\right)+\psi^{\ua}\psi^{\ub}\left(\Lb^{\ab} O_{\ab\ua\ub}-\psib^{\uc} O_{\uc\ua\ub}-\wb_{\ab} D_{\ua\ub}{}^{\ab}\right)\cr 
     &+\L^{\a} w_{\b}\left(\Lb^{\ab} O_{\ab\a}{}^{\b}-\psib^{\ua} O_{\ua\a}{}^{\b}-\wb_{\ab} D_{\a}{}^{\b\ab}\right)+\psi^{\ua} w_{\a}\left(-\Lb^{\ab} C_{\ua\ab}{}^{\a}+\psib^{\ub}C_{\ub\ua}{}^{\a}+\wb_{\ab} \Vh_{\ua}{}^{\ab\a}\right),
\end{align}
which again resembles the result of the flat space-time background case.

We have completed the calculation of $\oint\left(\g G_L+\gb G_R\right)V$ obtaining
\begin{align}\label{res1}
    \oint\left(\g G_L+\gb G_R\right)V=\p(\g w_L)+\pb(\gb w_R),
\end{align}
where $w_L$ is given in (\ref{wLis}) and $w_R$ is given in (\ref{wRis}).

It remains to determine $\oint\left(c T+\overline c \overline T\right)V$. Using the results of \cite{Chandia:2023eel} we check that
\begin{align}
    \left(\oint c T\right)V=\p(cV),\quad \left(\oint \overline c \Tb\right)V=\pb(\overline cV)
\end{align}
to finally obtain
\begin{align}
    QV=\pb W-\p\Wb,
\end{align}
where
\begin{align}
    W=\overline c V+\gb w_R,\quad \Wb=-c V-\g w_L,
\end{align}
just like in the flat space-time case (\ref{Wflat}).

The last step in our construction is to determine the unintegrated vertex operator, $U$, that satisfies
\begin{align}
    QW=\p U,\quad Q\Wb=\pb U. 
\end{align}
Consider $W$. Using Since $T$ and $\Tb$ act on world-sheet fields creating a world-sheet derivative on it, we obtain
\begin{align}\label{QWads}
    &QW=\p\left(c\overline c V+c\gb w_R-\overline c\g w_L \right)+\gb^2 V\cr 
    &+\gb\left(\oint\gb G_R\right)w_R+\gb\left(\oint\g G_L\right)w_R.
\end{align}
It will be shown that $\left(\oint\g G_L\right)w_R=\p \g u$ for some $u$ which will be given below and that $\left(\oint\gb G_R\right)w_R=-\gb V$ so that the term $\gb^2 V$ in (\ref{QWads}) is canceled. 

Consider $\left(\oint\g G_L\right)w_R$. It is useful to write $w_R$ as
\begin{align}
    w_R&=\Lb^{\ab}\left(-J^\a A_{\a\ab}+J^{\ua}A_{\ua\a}-d_\a E_{\ab}{}^\a +\psi^{\ua}\psi^{\ub}O_{\ab\ua\ub}+\L^\a w_\b O_{\ab\a}{}^\b-\psi^{\ua} w_\a C_{\ua\ab}{}^\a\right) \cr 
    &+\psib^{\ua}\left(-J^\a A_{\a\ua}-J^{\ub}A_{\ub\ua}-d_\a E_{\ua}{}^\a-\psi^{\ub}\psi^{\uc}O_{\ua\ub\uc}-\L^\a w_\b O_{\ua\a}{}^\b-\psi^{\ub}w_\a C_{\ua\ub}{}^\aº\right)\cr 
    &+\wb_{\ab}\left(J^\a E_\a{}^{\ab}-J^{\ua}E_{\ua}{}^{\ab}+d_\a P^{\a\ab}-\psi^{\ua}\psi^{\ub} D_{\ua\ub}{}^{\ab}-\L^\a w_\b D_\a{}^{\b\ab}+\psi^{\ua}w_\a\Vh_{\ua}{}^{\ab\a}\right).
\end{align}
Using the equations for the background superfields and the commutators of the appendix one obtains the following
\begin{align}
    \left(\oint\g G_L\right)w_R=\p(\g u),
\end{align}
where
\begin{align}
    u&=-\L^\a\Lb^{\ab} A_{\a\ab}+\L^\a\psib^{\ua}A_{\a\ua}-\psi^{\ua}\Lb^{\ab}A_{\ua\ab}+\L^\a\wb_{\ab} E_\a{}^{\ab}-w_\a\Lb^{\ab}E_{\ab}{}^\a\cr 
    &+\psi^{\ua}\psib^{\ub}A_{\ua\ub}+\psi^{\ua}\wb_{\ab}E_{\ua}{}^{\ab}-w_\a\psib^{\ua}E_{\ua}{}^\a-w_\a\wb_{\ab} P^{\a\ab},
\end{align}
which takes the same form as the flat spacetime background case. 

Consider now $\left(\oint\gb G_R\right)w_R$. Using the form (\ref{wRis}) and using the equations of the backgound fields we obtain
\begin{align}
    \left(\oint\gb G_R\right)w_R=-\gb V.
\end{align}
Therefore, the unintegrated vertex operator $U$ that satisfies $QW=\p U$ is given by
\begin{align}
    U=c\overline c V+c\gb w_R-\overline c\g w_L+\g\gb u,
\end{align}
which has the form of the unintegrated vertex operator in flat spacetime background (\ref{Uflat}).

